/// `len(obj)` — return the length of an object.
/// `len(obj)` — PyPy: operation.py len → space.len_w
fn builtin_len(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // operation.py `len(space, w_obj)`.  The gateway Signature binds the keyword
    // form at the call site, so `args` is positional only and never carries the
    // `__pyre_kw__` marker: a single argument is `obj` (even a dict that holds
    // the marker key), so index it directly.  A wrong positional count carries
    // no single-dict value, so route it through the gateway for the faithful
    // `_match_signature` arity error.
    if let [obj] = args {
        return Ok(w_int_new(crate::baseobjspace::len_w(*obj)?));
    }
    let obj = parse_single_required(args, "obj", "len")?;
    Ok(w_int_new(crate::baseobjspace::len_w(obj)?))
}

/// Manual interp2app gateway for `len`.
///
/// `#[pyre_methods]` emits this same wrapper/descriptor pair automatically:
/// the wrapper reads the arity and each positional slot out of the slice before
/// entering the typed body. The gateway descent walker keys its heap-cache
/// entries for the args array off that element read, so this hand-written
/// wrapper must keep the same shape.
/// Builtins installed by hand must publish the equivalent `BuiltinCode.func`
/// PBC member so source translation can discover and codewrite its graph.
pub fn __majit_wrap_builtin_len(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return builtin_len(args);
    }
    let obj = args[0];
    Ok(w_int_new(crate::baseobjspace::len_w(obj)?))
}

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_len_target, __majit_wrap_builtin_len);

/// `abs(x)` — return the absolute value of a number.
pub fn builtin_abs(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // operation.py `abs(space, w_val)`.  The gateway Signature binds the keyword
    // form at the call site, so a single positional argument is `val` (even a
    // dict holding the marker key); index it directly and route a wrong
    // positional count through the gateway for the `_match_signature` arity error.
    let obj = match args {
        [val] => *val,
        _ => parse_single_required(args, "val", "abs")?,
    };
    builtin_abs_obj(obj)
}
/// Whether the receiver's `__abs__` is still the one its builtin numeric type
/// installs, which is what makes the structural arms below correct for it.
/// `int` covers the bigint representation and `bool`, neither of which
/// registers its own.
///
/// # Safety
/// `obj` must point to a valid object whose header is readable.
pub(crate) unsafe fn abs_uses_builtin(obj: PyObjectRef) -> bool {
    let w_class = unsafe { (*obj).w_class };
    if w_class.is_null() {
        return true;
    }
    // An exact receiver cannot carry a replacement, so the common call spends
    // a pointer compare rather than a lookup.
    for tp in [
        &pyre_object::INT_TYPE,
        &pyre_object::FLOAT_TYPE,
        &pyre_object::COMPLEX_TYPE,
    ] {
        if std::ptr::eq(w_class, pyre_object::get_instantiate(tp)) {
            return true;
        }
    }
    let Some((src, _)) =
        (unsafe { crate::baseobjspace::lookup_where_with_method_cache(w_class, "__abs__") })
    else {
        return true;
    };
    [
        &pyre_object::INT_TYPE,
        &pyre_object::FLOAT_TYPE,
        &pyre_object::COMPLEX_TYPE,
    ]
    .into_iter()
    .any(|tp| std::ptr::eq(src, pyre_object::get_instantiate(tp)))
}

/// `extern "C"` residual bridge for [`abs_uses_builtin`], widening its `bool`
/// result to a word: a raw `-> bool` target defines only the low byte of the
/// result on x86, while the residual dispatcher reads a whole word.
pub(crate) extern "C" fn bh_abs_uses_builtin(obj: PyObjectRef) -> i64 {
    i64::from(unsafe { abs_uses_builtin(obj) })
}

fn builtin_abs_obj(obj: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    // operation.py `abs` → `space.abs` → descroperation `_make_unaryop_impl`
    // (`__abs__`).  The exact-type shortcut is `use_special_method_shortcut`:
    // a receiver whose `w_class` is still the builtin numeric type cannot
    // carry a replacement.  Anything else looks `__abs__` up on the live
    // type (typedef.py user-subclass shortcut reset) and calls it.
    if unsafe { abs_uses_builtin(obj) } {
        return abs_structural(obj);
    }
    unsafe {
        let Some(tp) = crate::typedef::r#type(obj) else {
            return Err(abs_bad_operand(obj));
        };
        // typeobject.py `lookup` = `lookup_where_with_method_cache`.
        match crate::baseobjspace::lookup_where_with_method_cache(tp.as_ptr(), "__abs__") {
            Some((src, method))
                if [
                    &pyre_object::INT_TYPE,
                    &pyre_object::FLOAT_TYPE,
                    &pyre_object::COMPLEX_TYPE,
                ]
                .into_iter()
                .any(|tp| std::ptr::eq(src, pyre_object::get_instantiate(tp))) =>
            {
                abs_structural(obj)
            }
            Some((_, method)) => {
                crate::baseobjspace::get_and_call_function(method, obj, tp.as_ptr(), &[])
            }
            None => Err(abs_bad_operand(obj)),
        }
    }
}

/// `int.__abs__` / `float.__abs__`: the layout arms on their own.  These are
/// what the lookup in `builtin_abs_obj` dispatches to, so they must not repeat
/// it — a subtype whose `__abs__` calls back into one would not terminate.
fn abs_structural(obj: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    unsafe {
        if is_bool(obj) {
            return Ok(w_int_new(w_bool_get_value(obj) as i64));
        }
        if is_int(obj) {
            let v = w_int_get_value(obj);
            // i64::MIN.abs() overflows; promote to long
            return match v.checked_abs() {
                Some(_) => crate::objspace::descroperation::_int_abs(v),
                None => Ok(w_long_new(-BigInt::from(v))),
            };
        }
        if is_long(obj) {
            let val = w_long_get_value(obj);
            // `rbigint.abs` returns `self` for nonnegative values, and
            // longobject.py's `_make_descr_unaryop('abs')` then allocates a
            // fresh W_LongObject around that same rbigint. Preserve both
            // wrapper identity and payload sharing instead of translating
            // `Clone` into another GC payload.
            if val.get_sign() != -1 {
                return Ok(pyre_object::longobject::w_long_from_raw(
                    pyre_object::longobject::w_long_get_raw_value(obj),
                ));
            }
            return Ok(w_long_new(val.neg()));
        }
        if is_float(obj) {
            return crate::objspace::descroperation::_float_abs(w_float_get_value(obj));
        }
        if pyre_object::is_complex(obj) {
            return crate::objspace::descroperation::complex_abs(obj);
        }
    }
    Err(abs_bad_operand(obj))
}

/// `int.__abs__` / `float.__abs__` as gateway functions.
pub fn builtin_abs_dunder(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = match args {
        [val] => *val,
        _ => parse_single_required(args, "self", "__abs__")?,
    };
    abs_structural(obj)
}

/// `int.__neg__` / `float.__neg__` / `complex.__neg__` as gateway functions.
///
/// The body is `neg_inner`, the structural half, not `neg`: an unbound slot
/// must not re-run the `__neg__` override probe that `neg` opens with, or a
/// subtype override wins over the slot it was reached through and an override
/// delegating back to it never terminates.
pub fn builtin_neg_dunder(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = match args {
        [val] => *val,
        _ => parse_single_required(args, "self", "__neg__")?,
    };
    crate::objspace::descroperation::neg_inner(obj)
}

/// `int.__pos__` / `float.__pos__` / `complex.__pos__` as gateway functions.
/// Structural half only, for the reason [`builtin_neg_dunder`] gives.
pub fn builtin_pos_dunder(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = match args {
        [val] => *val,
        _ => parse_single_required(args, "self", "__pos__")?,
    };
    crate::objspace::descroperation::pos_inner(obj)
}

fn abs_bad_operand(obj: PyObjectRef) -> crate::PyError {
    crate::PyError::type_error(format!(
        "bad operand type for abs(): '{}'",
        crate::baseobjspace::object_functionstr_type_name(obj)
    ))
}

#[majit_macros::dont_look_inside]
fn builtin_abs_slow(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_abs(args)
}

/// Exact complex `abs`. Residual, so a trace of an int or a float does not
/// enter `complex_abs`. The complex type slot calls `complex_abs` itself.
#[inline(never)]
#[majit_macros::dont_look_inside]
fn builtin_abs_complex(w_val: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    unsafe { crate::objspace::descroperation::complex_abs(w_val) }
}

/// operation.py `abs` → `space.abs`.
///
/// Exact int follows `intobject.py descr_abs`: `MININT` falls through to
/// the slow path (`descr_neg`), otherwise
/// `newint((x ^ mask) - mask)` with `mask = x >> 63`.  Exact float follows
/// `floatobject.py descr_abs`: `W_FloatObject(abs(floatval))`.  Both boxes
/// are `malloc_typed_managed` in this trace so `fuse_boxing_alloc` can keep
/// them virtual.  An exact complex and every other shape run `builtin_abs`.
pub fn __majit_wrap_builtin_abs(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() == 1 {
        let w_val = args[0];
        unsafe {
            if is_exact_builtin_instance(w_val) && is_int(w_val) {
                let value = w_int_get_value(w_val);
                if value != i64::MIN {
                    let mask = value >> 63;
                    let intval = (value ^ mask).wrapping_sub(mask);
                    return Ok(pyre_object::lltype::malloc_typed_managed(W_IntObject {
                        ob_header: PyObject {
                            ob_type: &INT_TYPE as *const PyType,
                            w_class: get_instantiate(&INT_TYPE),
                        },
                        intval,
                    }) as PyObjectRef);
                }
            } else if is_exact_builtin_instance(w_val) && is_float(w_val) {
                return Ok(pyre_object::lltype::malloc_typed_managed(W_FloatObject {
                    ob_header: PyObject {
                        ob_type: &FLOAT_TYPE as *const PyType,
                        w_class: get_instantiate(&FLOAT_TYPE),
                    },
                    floatval: w_float_get_value(w_val).abs(),
                }) as PyObjectRef);
            } else if is_exact_builtin_instance(w_val) && pyre_object::is_complex(w_val) {
                return builtin_abs_complex(w_val);
            }
        }
    }
    builtin_abs_slow(args)
}

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_abs_target, __majit_wrap_builtin_abs);

/// Strip the trailing `__pyre_kw__` dict that `call_with_kwargs`
/// (`call.rs`) appends for builtin callees and return the positional
/// slice paired with a keyword lookup helper.
///
/// PRE-EXISTING-ADAPTATION (builtin kwargs ABI, consumer side). PyPy's
/// gateway gives each builtin a `Signature` (`gateway.py BuiltinCode`,
/// `:804`) and resolves keywords by name through `args.parse_obj` →
/// `_match_signature` (`argument.py:173`) before the interp-level function
/// runs; the builtin never sees a marker dict. Pyre's flat `BuiltinCodeFn`
/// ABI lacks that Signature surface, so each kwarg-aware builtin reaches into
/// the `__pyre_kw__`-tagged trailing dict via this shared helper. The builtin
/// Signature/unwrap_spec gateway is not yet ported; once it routes builtin
/// kwargs through `Arguments::_match_signature` into named slots, this helper
/// and the `__pyre_kw__` marker can be removed.
pub fn split_builtin_kwargs(args: &[PyObjectRef]) -> (&[PyObjectRef], Option<PyObjectRef>) {
    if !args.is_empty() {
        let last = args[args.len() - 1];
        if builtin_kwargs_marker_tail(last) {
            return (&args[..args.len() - 1], Some(last));
        }
    }
    (args, None)
}

/// Whether `last` is the trailing keyword dict [`split_builtin_kwargs`]
/// strips.
///
/// The marker dict stores an unforgeable sentinel under `__pyre_kw__`
/// (`call_with_kwargs`), so detection is by value identity.  A dict passed
/// positionally that merely contains a `__pyre_kw__` string key
/// (`float({'__pyre_kw__': True})`) carries a different value and is a
/// value, not the marker, so it must not be stripped.
///
/// Scalar so a wrapper that only needs the answer for a known slot can ask
/// it without the sub-slice [`split_builtin_kwargs`] returns: a traced
/// wrapper that builds that sub-slice stops annotating and falls to the
/// legacy walker.
pub fn builtin_kwargs_marker_tail(last: PyObjectRef) -> bool {
    (unsafe { is_dict(last) }) && builtin_kwargs_marker_dict(last)
}

/// Length of the leading non-null run of `args`.
///
/// `bind_kwargs_to_signature` pads the flat argument slice out to the full
/// parameter count with PY_NULL for keyword-only slots and absent optionals,
/// so the true positional count is the prefix before the first PY_NULL.
/// A single named function keeps the count off the annotator's shared
/// iterator-adapter graph: a `take_while` closure inlined per wrapper gives
/// every `__majit_wrap_*` shim its own closure type, and merging those
/// distinct types on one `TakeWhile` graph's input has no common base class.
#[majit_macros::unroll_safe]
pub fn leading_non_null_count(args: &[PyObjectRef]) -> i64 {
    builtin_positional_count(args, false)
}

/// Positional count of a flat builtin argument list.
///
/// `Arguments._match_signature` keeps `num_args` as a Signed and counts the
/// positional prefix in place. A trailing `__pyre_kw__` marker is not a
/// positional: `has_kwargs` stops the scan one slot early, which is the
/// leading non-null run of `split_builtin_kwargs`'s prefix. The wrapper
/// therefore does not build that sub-slice. `interp2app` already passes
/// positionals and keywords separately, so the marker dict is the flat ABI's
/// stand-in and the slice was only there to drop it before counting.
///
/// `Arguments._match_signature` is `@jit.unroll_safe`; the hint belongs
/// on this graph, which owns the positional-prefix loop. A caller hint
/// does not transfer (`look_inside_graph`).
#[majit_macros::unroll_safe]
pub fn builtin_positional_count(args: &[PyObjectRef], has_kwargs: bool) -> i64 {
    // `Arguments._match_signature` keeps `num_args` as a Signed. Rust
    // indexing needs `usize`; that is an adapter, not the gateway count's type.
    // Ordinary Signed subtraction: `saturating_sub` is not in the
    // translator CallRegistry, so the graph never becomes a prepass subject.
    let len = args.len() as i64;
    let limit = if has_kwargs { len - 1 } else { len };
    let mut count = 0i64;
    while count < limit && !args[count as usize].is_null() {
        count += 1;
    }
    count
}

/// Cold dictionary-strategy half of the flat builtin-keyword ABI.
///
/// The caller first proves `last` is a dict.  Keeping the strategy dispatch
/// residual lets the trace-visible non-dict path reject the marker test
/// without entering `w_dict_getitem_str`'s dynamic strategy function.
#[majit_macros::dont_look_inside]
pub fn builtin_kwargs_marker_dict(last: PyObjectRef) -> bool {
    unsafe {
        pyre_object::w_dict_getitem_str(last, "__pyre_kw__")
            .is_some_and(pyre_object::kw_marker::is_kw_marker_sentinel)
    }
}

/// True when the kwargs dict from [`split_builtin_kwargs`] carries a real
/// keyword (any entry other than the `__pyre_kw__` marker).  An empty
/// `**{}` therefore reports `false`.
pub fn has_real_kwargs(kwargs: Option<PyObjectRef>) -> bool {
    real_kwarg_count(kwargs) > 0
}

/// Number of real keyword arguments in the kwargs dict from
/// [`split_builtin_kwargs`] — every entry other than the `__pyre_kw__`
/// marker.  The clinic-style "takes at most N arguments (M given)" builtins
/// (`sum`, `round`, `pow`) count positionals plus this against their limit.
///
/// The marker occupies exactly one entry, so the answer is the dict's length
/// less that entry.  `__pyre_kw__` is one key, so it holds one slot whichever
/// order the writes happen in, and [`split_builtin_kwargs`] hands back a dict
/// only when that slot still holds the sentinel.  `w_dict_len` reads the count
/// off the strategy; enumerating the entries to filter one name out would build
/// a `Vec<(Wtf8Buf, PyObjectRef)>` per arity check.
///
/// A caller keyword spelled `__pyre_kw__` lands in the same slot and
/// `call_with_kwargs` writes the sentinel over it, so that keyword is lost
/// before any arity check sees it: `sum([1, 2], **{'__pyre_kw__': 0})` answers
/// 3 where 3.14.6 and pypy3 both raise, and `dict(**{'__pyre_kw__': 7})`
/// answers `{}` where both give `{'__pyre_kw__': 7}`.  That is the marker
/// scheme's own collision, not this count's: filtering the name out of the
/// entry list reported the same 0.
///
/// The length also needs no key decode, which the entry list does: a key
/// carrying a lone surrogate has no `&str` view, so counting through
/// `w_dict_str_entries` would drop `**{'\udc80': v}` outright and report a
/// keyword-free call.  A non-str key cannot reach here at all —
/// `call_with_kwargs` raises `TypeError("keywords must be strings")` first.
///
/// Not building that `Vec` is also what lets a builtin body be descended.
/// `w_dict_str_entries_wtf8` is un-lowered, and every hand-written
/// `__majit_wrap_*` reaches it through an arity helper into
/// `type_methods::reject_kwargs_of`, so while it was called here the descent
/// declined for `set.add`, `list.append`, `dict.keys` and their siblings.
pub fn real_kwarg_count(kwargs: Option<PyObjectRef>) -> usize {
    let Some(dict) = kwargs else {
        return 0;
    };
    unsafe { pyre_object::w_dict_len(dict) }.saturating_sub(1)
}

/// The real keyword `(name, value)` pairs in the kwargs dict from
/// [`split_builtin_kwargs`] — every entry other than the `__pyre_kw__`
/// marker.  A builtin that has to re-issue its own call as a keyword call
/// (`_thread._local` replays the constructor per thread, `os_local.py`)
/// hands these to `call::call_with_kwargs`.
pub(crate) fn builtin_kwarg_entries(kwargs: Option<PyObjectRef>) -> Vec<(Wtf8Buf, PyObjectRef)> {
    let Some(dict) = kwargs else {
        return Vec::new();
    };
    let marker = Wtf8Buf::from_string("__pyre_kw__".to_string());
    unsafe { pyre_object::w_dict_str_entries_wtf8(dict) }
        .into_iter()
        .filter(|(key, _)| *key != marker)
        .collect()
}

/// Rebuild `Arguments` from a flat builtin rest slice so a consumer can
/// call `Arguments.unpack` the way `descr_new_base_exception` and
/// `W_OSError.descr_new` / `descr_init` do (`args_w, kwds_w = __args__.unpack()`).
///
/// The gateway still packs keywords as a trailing `__pyre_kw__` marker dict
/// (`call.rs` PRE-EXISTING-ADAPTATION); this adapter drops that sentinel and
/// keeps `keyword_names_w` as the original key objects. No real keywords
/// means `positional_only`, so `_jit_few_keywords` stays true and `unpack`'s
/// `look_inside_iff` looks inside.
fn arguments_from_builtin_rest(rest: &[PyObjectRef]) -> crate::argument::Arguments {
    let (pos, kwargs) = split_builtin_kwargs(rest);
    if !has_real_kwargs(kwargs) {
        return crate::argument::Arguments::positional_only(pos);
    }
    let dict = kwargs.expect("has_real_kwargs implies a marker dict");
    let _roots = pyre_object::gc_roots::push_roots();
    let pos_len = pos.len();
    let pos_base = pyre_object::gc_roots::pin_roots(pos);
    let dict_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(dict);
    let items =
        unsafe { pyre_object::w_dict_items(pyre_object::gc_roots::shadow_stack_get(dict_slot)) };
    let items_flat: Vec<PyObjectRef> = items.iter().flat_map(|(k, v)| [*k, *v]).collect();
    let items_base = pyre_object::gc_roots::pin_roots(&items_flat);
    let mut names = Vec::new();
    let mut values = Vec::new();
    for i in 0..items.len() {
        let key = pyre_object::gc_roots::shadow_stack_get(items_base + 2 * i);
        let value = pyre_object::gc_roots::shadow_stack_get(items_base + 2 * i + 1);
        let is_marker = unsafe {
            pyre_object::is_str(key)
                && pyre_object::w_str_get_wtf8(key).as_str() == Ok("__pyre_kw__")
        };
        if is_marker {
            continue;
        }
        names.push(key);
        values.push(value);
    }
    let pos_now: Vec<PyObjectRef> = (0..pos_len)
        .map(|i| pyre_object::gc_roots::shadow_stack_get(pos_base + i))
        .collect();
    if names.is_empty() {
        return crate::argument::Arguments::positional_only(&pos_now);
    }
    let n = names.len();
    let names_base = pyre_object::gc_roots::pin_roots(&names);
    let values_base = pyre_object::gc_roots::pin_roots(&values);
    let names_now: Vec<PyObjectRef> = (0..n)
        .map(|i| pyre_object::gc_roots::shadow_stack_get(names_base + i))
        .collect();
    let values_now: Vec<PyObjectRef> = (0..n)
        .map(|i| pyre_object::gc_roots::shadow_stack_get(values_base + i))
        .collect();
    crate::argument::Arguments::with_kw(&pos_now, &names_now, &values_now)
}

/// Look up a single keyword argument from the kwargs dict produced by
/// `split_builtin_kwargs`. Returns `None` when no kwargs dict is present
/// or the requested key is absent.
pub fn kwarg_get(kwargs: Option<PyObjectRef>, name: &str) -> Option<PyObjectRef> {
    let dict = kwargs?;
    unsafe { pyre_object::w_dict_getitem_str(dict, name) }
}

/// Reject any keyword argument whose name is not in `allowed`.  Mirrors
/// PyPy's `unwrap_spec` strict-keyword behaviour — for example
/// `pypy/module/__builtin__/functional.py min_max` raises
/// `TypeError("min() got unexpected keyword argument")` whenever an
/// unknown kwarg slips in (only `key` and `default` are accepted).
/// pyre's flat builtin ABI has to police this manually because
/// `split_builtin_kwargs` does not enforce a signature.
///
/// `fn_name` is the bare function name used in the error message
/// ("min", "zip_longest", ...).  The `__pyre_kw__` marker entry the
/// gateway appends is filtered out; it is an implementation detail of
/// the kwargs encoding, not a user-visible argument.
pub fn kwarg_reject_unknown(
    kwargs: Option<PyObjectRef>,
    allowed: &[&str],
    fn_name: &str,
) -> Result<(), crate::PyError> {
    let dict = match kwargs {
        Some(d) => d,
        None => return Ok(()),
    };
    let entries = unsafe { pyre_object::w_dict_str_entries_wtf8(dict) };
    for (key, _) in entries.iter() {
        if key.as_str() == Ok("__pyre_kw__") {
            continue;
        }
        if !allowed.iter().any(|name| key.as_str() == Ok(*name)) {
            return Err(unexpected_keyword_error(fn_name, key, allowed));
        }
    }
    Ok(())
}

/// `vgetargskeywords` rejects `nargs + nkwargs > len` before it scans for
/// an unknown key. `NameError_init`, `AttributeError_init`, and
/// `ImportError_init` parse keywords against an empty positional tuple, so
/// `nargs` is 0 and the overflow text is `takes at most N keyword
/// argument(s) (M given)`. A single unknown key that still fits `len`
/// stays on `kwarg_reject_unknown`. `W_NameError.descr_init` has no
/// `@jit` hint; `W_ImportError.descr_init` is `@jit.unroll_safe` for the
/// kwargs loop, not this count.
fn kwarg_reject_parse_keywords(
    kwargs: Option<PyObjectRef>,
    allowed: &[&str],
    fn_name: &str,
) -> Result<(), crate::PyError> {
    let nkwargs = real_kwarg_count(kwargs);
    let len = allowed.len();
    if nkwargs > len {
        let noun = if len == 1 {
            "keyword argument"
        } else {
            "keyword arguments"
        };
        return Err(crate::PyError::type_error(format!(
            "{fn_name}() takes at most {len} {noun} ({nkwargs} given)"
        )));
    }
    kwarg_reject_unknown(kwargs, allowed, fn_name)
}

/// `NAME() got an unexpected keyword argument 'KEY'`, with the
/// `Did you mean` suggestion drawn from `allowed`.
fn unexpected_keyword_error(fn_name: &str, key: &Wtf8, allowed: &[&str]) -> crate::PyError {
    let mut msg = format!("{fn_name}() got an unexpected keyword argument '{key}'");
    if let Ok(wrong) = key.as_str() {
        let candidates: Vec<String> = allowed.iter().map(|s| s.to_string()).collect();
        if let Some(suggestion) = crate::error::best_suggestion(&candidates, wrong) {
            msg.push_str(&format!(". Did you mean '{suggestion}'?"));
        }
    }
    crate::PyError::type_error(msg)
}

/// `_PyArg_UnpackKeywords` for a method whose receiver is its only
/// positional parameter and whose other parameters are all keyword-only
/// (`list.sort($self, /, *, key=None, reverse=False)`): the total count
/// first, then any positional, then the first keyword that names no
/// parameter.  `npos` excludes the receiver.  `None` when the call binds.
pub(crate) fn clinic_keyword_only_error(
    fn_name: &str,
    kwonly: &[&str],
    npos: usize,
    kw_names: &[Wtf8Buf],
) -> Option<crate::PyError> {
    if let Err(err) = clinic_arity(fn_name, npos, kw_names.len(), 0, 0, kwonly.len()) {
        return Some(err);
    }
    kw_names
        .iter()
        .find(|key| !kwonly.iter().any(|name| key.as_str() == Ok(*name)))
        .map(|key| unexpected_keyword_error(fn_name, key, kwonly))
}

/// Bind a positional-or-keyword parameter that follows a positional-only
/// prefix (`eval`/`exec`/`compile` style).  Prefers the positional slot and
/// falls back to the matching keyword.  Raises the argument-clinic
/// "given by name and position" TypeError when the same parameter is supplied
/// both ways.  `pos_index` is the 1-based position used in that message.
pub fn bind_pos_or_kw(
    positional: &[PyObjectRef],
    kwargs: Option<PyObjectRef>,
    slot: usize,
    key: &str,
    fn_name: &str,
    pos_index: usize,
) -> Result<Option<PyObjectRef>, crate::PyError> {
    match (positional.get(slot).copied(), kwarg_get(kwargs, key)) {
        (Some(_), Some(_)) => Err(crate::PyError::type_error(format!(
            "argument for {fn_name}() given by name ('{key}') and position ({pos_index})"
        ))),
        (Some(p), None) => Ok(Some(p)),
        (None, Some(k)) => Ok(Some(k)),
        (None, None) => Ok(None),
    }
}

/// `true` when the last argument is the `__pyre_kw__`-tagged dict the
/// CALL_KW builtin dispatch appends — i.e. the call carried keywords.
pub fn has_builtin_kwargs(args: &[PyObjectRef]) -> bool {
    if args.is_empty() {
        return false;
    }
    let last = args[args.len() - 1];
    (unsafe { is_dict(last) }) && builtin_kwargs_marker_dict(last)
}

/// Resolve a single positional-or-keyword builtin argument: prefer the
/// positional value, fall back to the keyword `name`.  Supplying both
/// raises the `argument.py:_match_keywords` TypeError
/// "argument for X() given by name ('name') and position (N)" (N is the
/// 1-based positional index of the slot).  An absent argument is `None`.
pub fn resolve_pos_or_kw(
    positional: Option<PyObjectRef>,
    kwargs: Option<PyObjectRef>,
    name: &str,
    fn_name: &str,
    position: usize,
) -> Result<Option<PyObjectRef>, crate::PyError> {
    let keyword = kwarg_get(kwargs, name);
    match (positional, keyword) {
        (Some(_), Some(_)) => Err(crate::PyError::type_error(format!(
            "argument for {fn_name}() given by name ('{name}') and position ({position})"
        ))),
        (Some(v), None) | (None, Some(v)) => Ok(Some(v)),
        (None, None) => Ok(None),
    }
}

/// `_PyArg_UnpackKeywords`' two argument-count checks for a callable
/// declaring `maxpos` positional-or-keyword slots followed by `kwonly`
/// keyword-only ones, of which `minargs` are required.
///
/// A call whose positionals and keywords together exceed the declared total
/// is reported against that total ("takes at most 2 arguments (3 given)"),
/// and only a call that stays within it but oversupplies the positional part
/// is reported against `maxpos`.  The order matters: `list.sort` declares no
/// positional slot and two keyword-only ones, so one stray positional is a
/// positional error while three arguments are a total-count error.
///
/// The total-count message says "at most" whatever `minargs` is
/// (`memoryview(b"", 1)` — one required slot — reports "takes at most 1
/// argument (2 given)"); only the positional message names an exact count,
/// and only when every positional slot is required (`itertools.batched([], 1,
/// 2)` reports "takes exactly 2 positional arguments (3 given)").
pub fn clinic_arity(
    fn_name: &str,
    npos: usize,
    nkw: usize,
    minargs: usize,
    maxpos: usize,
    kwonly: usize,
) -> Result<(), crate::PyError> {
    let maxargs = maxpos + kwonly;
    if npos + nkw > maxargs {
        return Err(crate::PyError::type_error(format!(
            "{fn_name}() takes at most {maxargs} {}argument{} ({} given)",
            // bpo-31229: a call that passed only keywords names them, so
            // "takes at most 1 argument (2 given)" cannot read as a claim
            // about positional arguments that were never supplied.
            if npos == 0 { "keyword " } else { "" },
            if maxargs == 1 { "" } else { "s" },
            npos + nkw,
        )));
    }
    if npos > maxpos {
        let limit = if maxpos == 0 {
            "no positional arguments".to_string()
        } else {
            format!(
                "{} {maxpos} positional argument{} ({npos} given)",
                if minargs < maxpos {
                    "at most"
                } else {
                    "exactly"
                },
                if maxpos == 1 { "" } else { "s" },
            )
        };
        return Err(crate::PyError::type_error(format!(
            "{fn_name}() takes {limit}"
        )));
    }
    Ok(())
}

/// Bind positional + `__pyre_kw__` keyword arguments into a resolved
/// scope of length `names.len()`, mirroring the gateway's
/// `Arguments._match_signature` (`pypy/interpreter/argument.py`). Each
/// slot is filled by a positional, then by a keyword of the matching
/// name; an absent optional slot becomes `PY_NULL` (the generated
/// `#[pyre_function]` unwrap reads that as "argument omitted"), and a
/// `PY_NULL` arriving in `args` is read the same way. An absent required
/// slot, an unknown keyword, a keyword duplicating a positional, or too many
/// positionals raises `TypeError`.
///
/// This is the consumer-side counterpart that lets a builtin resolve
/// keywords by parameter name without a per-function `Signature`; the
/// `#[pyre_function]` wrapper supplies the name/required tables it knows
/// at expansion time.
// PyPy: `Arguments._match_signature` (`pypy/interpreter/argument.py`)
// is `@jit.unroll_safe`.  The loops below are bounded by the builtin's static
// signature and argument count in the same way; without the hint the JIT
// policy residualizes this gateway step and cannot descend into the builtin.
#[majit_macros::unroll_safe]
pub fn bind_builtin_kwargs(
    args: &[PyObjectRef],
    names: &[&str],
    required: &[bool],
    fn_name: &str,
) -> Result<Vec<PyObjectRef>, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    // A builtin registered with a `Signature` reaches its body through
    // `bind_kwargs_to_signature`, which lays out every declared slot and
    // leaves an omitted one `PY_NULL`; a positional-only registration hands
    // the body just the arguments the call made. Reading a null slot as an
    // argument that was not passed makes the two registrations bind alike.
    let mut supplied = 0;
    let mut positional_index = 0;
    while positional_index < positional.len() {
        if !positional[positional_index].is_null() {
            supplied += 1;
        }
        positional_index += 1;
    }
    let mut required_count = 0;
    let mut required_index = 0;
    while required_index < required.len() {
        if required[required_index] {
            required_count += 1;
        }
        required_index += 1;
    }
    clinic_arity(
        fn_name,
        supplied,
        real_kwarg_count(kwargs),
        required_count,
        names.len(),
        0,
    )?;
    let mut scope: Vec<PyObjectRef> = vec![PY_NULL; names.len()];
    let mut filled: Vec<bool> = vec![false; names.len()];
    // `argument.py` keys the message off `space.text_w(keyword_names_w[i])`,
    // the keyword's own storage, so a name carrying a lone surrogate reaches
    // `e.args[0]` intact. Keep the WTF-8 rather than a lossy `String`.
    let keyword_entries = kwargs.map(|dict| unsafe { pyre_object::w_dict_str_entries_wtf8(dict) });
    let mut unknown: Option<usize> = None;
    // The slot a keyword named that a positional had already filled, and the
    // entry it came from; reported after the missing-required scan below.
    let mut duplicate: Option<(usize, usize)> = None;
    // PyPy `_match_signature` copies positional values with
    // `take = min(num_args, co_argcount - upfront)` and `for i in range(take)`,
    // so the constant signature bounds let the JIT unroll ordinary indexed
    // reads. Keep that storage shape instead of Rust iterator adapters, whose
    // `Filter`/`Enumerate` state has no RPython counterpart — and keep the
    // `min`: `scope` and `filled` are `names.len()` long, while `clinic_arity`
    // bounds the count of non-null entries rather than the slice itself, so a
    // null-padded `positional` longer than the signature reaches here.
    let take = positional.len().min(names.len());
    let mut positional_index = 0;
    while positional_index < take {
        let value = positional[positional_index];
        scope[positional_index] = value;
        filled[positional_index] = !value.is_null();
        positional_index += 1;
    }
    if let Some(entries) = keyword_entries.as_ref() {
        let mut entry_index = 0;
        while entry_index < entries.len() {
            let (key, val) = &entries[entry_index];
            let key_str = if unsafe { pyre_object::dictmultiobject::wtf8_key_is_utf8(key) } {
                Some(unsafe { pyre_object::dictmultiobject::wtf8_key_as_str_unchecked(key) })
            } else {
                None
            };
            if key_str == Some("__pyre_kw__") {
                entry_index += 1;
                continue;
            }
            let mut matched_index = None;
            let mut name_index = 0;
            while name_index < names.len() {
                if key_str == Some(names[name_index]) {
                    matched_index = Some(name_index);
                    break;
                }
                name_index += 1;
            }
            match matched_index {
                Some(idx) => {
                    if filled[idx] {
                        // Deferred for the reason the unrecognized name below
                        // is: `_PyArg_UnpackKeywords` scans for a name that
                        // duplicates a positional only after every declared
                        // slot has been accounted for, so a call that also
                        // leaves a required slot empty is reported against
                        // that slot.  `function(code, code=code)` names the
                        // missing `globals`, while `function(code, {},
                        // code=code)` — nothing missing — names the duplicate.
                        // The scan runs over the declared slots, not over the
                        // keywords, so two duplicates are reported against the
                        // lower slot rather than the earlier keyword.
                        if duplicate.is_none_or(|(_, filled_idx)| idx < filled_idx) {
                            duplicate = Some((entry_index, idx));
                        }
                    } else {
                        scope[idx] = *val;
                        filled[idx] = true;
                    }
                }
                // `_PyArg_UnpackKeywords` collects the unrecognized names and
                // only reports them once every declared slot has been filled,
                // so a call that misses a required argument is reported
                // against that argument even when it also passed a keyword
                // the function does not know.
                None => unknown = Some(entry_index),
            }
            entry_index += 1;
        }
    }
    let mut name_index = 0;
    while name_index < names.len() {
        if !filled[name_index] && required[name_index] {
            return Err(crate::PyError::type_error(format!(
                "{fn_name}() missing required argument '{}' (pos {})",
                names[name_index],
                name_index + 1,
            )));
        }
        name_index += 1;
    }
    if let Some((entry_index, idx)) = duplicate {
        let entries = keyword_entries
            .as_ref()
            .expect("a duplicate keyword index requires keyword entries");
        return builtin_name_and_position_failure(fn_name, &entries[entry_index].0, idx + 1);
    }
    if let Some(entry_index) = unknown {
        let entries = keyword_entries
            .as_ref()
            .expect("an unknown keyword index requires keyword entries");
        return builtin_unexpected_keyword_failure(fn_name, &entries[entry_index].0);
    }
    Ok(scope)
}

/// Cold `_PyArg_UnpackKeywords` name-and-position formatter.
///
/// The conflict scan runs after the missing-required report, so the hot binder
/// carries only the offending entry index and the slot it names and reaches
/// this residual helper once every declared slot has been accounted for.
#[cold]
#[majit_macros::dont_look_inside]
pub(crate) fn builtin_name_and_position_failure(
    fn_name: &str,
    key: &rustpython_wtf8::Wtf8,
    position: usize,
) -> Result<Vec<PyObjectRef>, crate::PyError> {
    let mut msg = Wtf8Buf::from_string(format!("argument for {fn_name}() given by name ('"));
    msg.push_wtf8(key);
    msg.push_str(&format!("') and position ({position})"));
    Err(crate::PyError::type_error(msg))
}

/// Cold `Arguments._match_signature` unexpected-keyword formatter.
///
/// PyPy retains an `ArgErrUnknownKwds` until the gateway converts it to the
/// final `TypeError`, so accepted calls never trace WTF-8 string assembly.
/// Keep the same boundary here; the hot binder carries only the offending
/// entry index and reaches this residual helper after missing-required checks.
#[cold]
#[majit_macros::dont_look_inside]
pub(crate) fn builtin_unexpected_keyword_failure(
    fn_name: &str,
    key: &rustpython_wtf8::Wtf8,
) -> Result<Vec<PyObjectRef>, crate::PyError> {
    let mut msg = Wtf8Buf::from_string(format!("{fn_name}() got an unexpected keyword argument '"));
    msg.push_wtf8(key);
    msg.push_str("'");
    Err(crate::PyError::type_error(msg))
}

/// Resolve a builtin with a single required positional-or-keyword parameter
/// through the gateway `parse_into_scope`, so the argument binds by name and
/// the trailing `__pyre_kw__` marker dict never leaks as a value. Mirrors an
/// `interp2app` function with `Signature([name])` (e.g. `operation.py`
/// `abs(space, w_val)` / `len(space, w_obj)`): a missing argument, an unknown
/// keyword, or a surplus positional raises the matching `_match_signature`
/// TypeError.
fn parse_single_required(
    args: &[PyObjectRef],
    name: &'static str,
    fn_name: &str,
) -> Result<PyObjectRef, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    // Fast path for the hot fixed-arity call (`len(x)` / `abs(x)`): one
    // positional and no keywords binds directly, skipping the Signature /
    // Arguments / scope allocation the general keyword and arity-error path
    // needs.  Zero or surplus positionals, or any keyword, fall through so the
    // `_match_signature` TypeError is still raised.
    if kwargs.is_none() && positional.len() == 1 {
        return Ok(positional[0]);
    }
    let pos_base = pyre_object::gc_roots::pin_roots(positional);
    let mut keyword_names_w: Vec<PyObjectRef> = Vec::new();
    let mut keywords_w: Vec<PyObjectRef> = Vec::new();
    if let Some(dict) = kwargs {
        let entries: Vec<_> = unsafe { pyre_object::w_dict_str_entries_wtf8(dict) }
            .into_iter()
            .filter(|(key, _)| key.as_str() != Ok("__pyre_kw__"))
            .collect();
        let values: Vec<PyObjectRef> = entries.iter().map(|(_, val)| *val).collect();
        let values_base = pyre_object::gc_roots::pin_roots(&values);
        let mut name_slots = Vec::with_capacity(entries.len());
        for (key, _) in entries {
            let name_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(pyre_object::w_str_from_wtf8_managed(key));
            name_slots.push(name_slot);
        }
        keyword_names_w = name_slots
            .iter()
            .map(|&slot| pyre_object::gc_roots::shadow_stack_get(slot))
            .collect();
        keywords_w = (0..name_slots.len())
            .map(|index| pyre_object::gc_roots::shadow_stack_get(values_base + index))
            .collect();
    }
    let refreshed_pos: Vec<PyObjectRef> = (0..positional.len())
        .map(|index| pyre_object::gc_roots::shadow_stack_get(pos_base + index))
        .collect();
    let signature = crate::gateway::Signature::new(vec![name], None, None, 0, 0);
    let arguments =
        crate::argument::Arguments::with_kw(&refreshed_pos, &keyword_names_w, &keywords_w);
    let mut scope_w = vec![PY_NULL; signature.scope_length()];
    arguments.parse_into_scope(PY_NULL, &mut scope_w, fn_name, &signature, None, PY_NULL)?;
    Ok(scope_w[0])
}

/// Reject `f(x, name=...)` when `name` already arrived positionally.
/// The flat builtin ABI leaves this validation to each kw-aware method.
pub fn kwarg_reject_duplicate(
    kwargs: Option<PyObjectRef>,
    fn_name: &str,
    name: &str,
    positional_present: bool,
) -> Result<(), crate::PyError> {
    if positional_present && kwarg_get(kwargs, name).is_some() {
        return Err(crate::PyError::type_error(format!(
            "{fn_name}() got multiple values for argument '{name}'"
        )));
    }
    Ok(())
}

/// `space.index_w(obj)` parity — `pypy/interpreter/baseobjspace.py
/// space.index_w` returns the int value of an object exposing
/// `__index__`.  Pyre handles the int / long / bool fast paths
/// directly and falls through to looking up `__index__` on the
/// object's type, mirroring PyPy's `lookup_in_type` pass before
/// raising `TypeError`.
pub fn space_index_w(mut obj: PyObjectRef) -> Result<i64, crate::PyError> {
    // Read the machine-word value of a bool / int / long object, raising
    // OverflowError when a bigint does not fit. Returns `None` for anything
    // else so the caller can fall through to the `__index__` lookup / error.
    unsafe fn as_index_value(o: PyObjectRef) -> Option<Result<i64, crate::PyError>> {
        unsafe {
            if pyre_object::is_bool(o) {
                return Some(Ok(pyre_object::w_bool_get_value(o) as i64));
            }
            if pyre_object::is_int(o) {
                return Some(Ok(pyre_object::w_int_get_value(o)));
            }
            if pyre_object::is_long(o) {
                let big = pyre_object::longobject::w_long_get_value(o);
                return Some(
                    if pyre_object::longobject::jit_bigint_to_i64_fits(big) != 0 {
                        Ok(pyre_object::longobject::jit_bigint_to_i64_value(big))
                    } else {
                        Err(crate::PyError::overflow_error(
                            "int too large to convert to int",
                        ))
                    },
                );
            }
        }
        None
    }
    unsafe {
        if let Some(v) = as_index_value(obj) {
            return v;
        }
        if let Some(w_type) = crate::typedef::r#type(obj)
            && let Some(index_fn) =
                crate::baseobjspace::lookup_in_type(w_type.as_ptr(), "__index__")
        {
            let result = pyre_object::with_roots!(obj =>
                crate::call::call_function_impl_result(index_fn, &[obj])
            )?;
            if let Some(v) = as_index_value(result) {
                return v;
            }
        }
    }
    let tp_name = unsafe {
        match crate::typedef::r#type(obj) {
            Some(tp) => pyre_object::w_type_get_name(tp.as_ptr()).to_string(),
            None => "object".to_string(),
        }
    };
    Err(crate::PyError::type_error(format!(
        "'{tp_name}' object cannot be interpreted as an integer"
    )))
}

/// Convert an int or long object to BigInt for comparison.
pub unsafe fn obj_to_bigint(obj: PyObjectRef) -> BigInt {
    unsafe {
        // PyPy's W_BoolObject subclasses W_IntObject and shares `intval`;
        // pyre uses a distinct layout, so preserve that upstream semantic arm
        // with the correct storage projection before testing `is_int`.
        if is_bool(obj) {
            BigInt::from(w_bool_get_value(obj) as i64)
        } else if is_int(obj) {
            BigInt::from(w_int_get_value(obj))
        } else {
            // PyPy's bigint_w/asbigint returns W_LongObject.num itself.
            w_long_get_value(obj).translated_alias()
        }
    }
}

/// `min(*args)` / `min(iterable)` — return the smallest value.
///
/// `pypy/module/__builtin__/functional.py min_max`:
///   - reject any kwargs other than `key` / `default`
///   - reject `default=` paired with multiple positional args
///   - require ≥1 positional arg
pub(crate) fn builtin_min(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    min_max_dispatch(args, /* want_max= */ false, "min")
}

/// `max(a, b)` / `max(iterable)` — return the largest of two values or an iterable.
pub(crate) fn builtin_max(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    min_max_dispatch(args, /* want_max= */ true, "max")
}

/// functional.py `min_max` over two positional arguments that compare without
/// a dunder dispatch: two exact machine ints or two exact floats.  The scan
/// keeps the first argument unless the second compares strictly past it under
/// `$op` (`<` for `min`, `>` for `max`), a NaN included.  A keyword dict rides
/// the same slice and is neither, so it reaches the slow path.
macro_rules! min_max_exact_pair {
    ($args:expr, $op:tt) => {
        if $args.len() == 2 {
            let w_a = $args[0];
            let w_b = $args[1];
            unsafe {
                if is_exact_builtin_instance(w_a)
                    && is_exact_builtin_instance(w_b)
                    && is_int(w_a)
                    && is_int(w_b)
                {
                    let second_wins = w_int_get_value(w_b) $op w_int_get_value(w_a);
                    return Ok(if second_wins { w_b } else { w_a });
                }
                if is_exact_builtin_instance(w_a)
                    && is_exact_builtin_instance(w_b)
                    && is_float(w_a)
                    && is_float(w_b)
                {
                    let second_wins = w_float_get_value(w_b) $op w_float_get_value(w_a);
                    return Ok(if second_wins { w_b } else { w_a });
                }
            }
        }
    };
}

#[majit_macros::dont_look_inside]
fn builtin_min_slow(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_min(args)
}

pub fn __majit_wrap_builtin_min(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    min_max_exact_pair!(args, <);
    builtin_min_slow(args)
}

#[majit_macros::dont_look_inside]
fn builtin_max_slow(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_max(args)
}

pub fn __majit_wrap_builtin_max(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    min_max_exact_pair!(args, >);
    builtin_max_slow(args)
}

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_min_target, __majit_wrap_builtin_min);

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_max_target, __majit_wrap_builtin_max);

fn min_max_dispatch(
    args: &[PyObjectRef],
    want_max: bool,
    fn_name: &str,
) -> Result<PyObjectRef, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    // `min_max` unpacks its positionals before it looks at the keywords, so a
    // keywords-only call is reported against the missing operand.
    if positional.is_empty() {
        return Err(crate::PyError::type_error(format!(
            "{fn_name} expected at least 1 argument, got 0"
        )));
    }
    // functional.py — only `key` and `default` are accepted.
    kwarg_reject_unknown(kwargs, &["key", "default"], fn_name)?;
    let key_fn = kwarg_get(kwargs, "key").filter(|k| unsafe { !pyre_object::is_none(*k) });
    let default = kwarg_get(kwargs, "default");
    // functional.py:206-210 — `default=` is only meaningful for the
    // single-iterable form; combining it with multiple positional args
    // is a user error.
    if positional.len() > 1 && default.is_some() {
        return Err(crate::PyError::type_error(format!(
            "Cannot specify a default for {fn_name}() with multiple positional arguments"
        )));
    }
    if positional.len() == 1 {
        min_max_sequence(positional[0], key_fn, default, want_max, fn_name)
    } else {
        min_max_multiple_args(positional, key_fn, want_max)
    }
}

/// `pypy/module/__builtin__/functional.py min_max_sequence`.
fn min_max_sequence(
    sequence: PyObjectRef,
    key_fn: Option<PyObjectRef>,
    default: Option<PyObjectRef>,
    want_max: bool,
    fn_name: &str,
) -> Result<PyObjectRef, crate::PyError> {
    // `iter` below runs the argument's `__iter__`.  The gateway pins the
    // argument array, but `sequence`, `key` and `default` are copies taken out
    // of it and a minor rewrites the array rather than the copies, so all
    // three take slots of their own before anything can collect.  Publishing a
    // stale word as a root is worse than reading one: the next collection
    // walks it as if it named an object.
    //
    // One `pin_roots` for the three rather than a `pin_root` each: the
    // forwarding query that ends a publication is itself a safepoint, so a
    // value still sitting in a native local while an earlier query runs is
    // published afterwards at the address it had before.
    let _roots = pyre_object::gc_roots::push_roots();
    let sequence_slot = pyre_object::gc_roots::pin_roots(&[
        sequence,
        key_fn.unwrap_or_else(pyre_object::w_none),
        default.unwrap_or_else(pyre_object::w_none),
    ]);
    let key_fn_slot = key_fn.map(|_| sequence_slot + 1);
    let has_default = default.is_some();
    let default_slot = sequence_slot + 2;
    let it = crate::baseobjspace::iter(pyre_object::gc_roots::shadow_stack_get(sequence_slot))?;
    let iterator_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(it);
    // Dict-view iterators are off-GC carriers, so retain their source dict
    // explicitly while the iterator is rooted by this native loop.
    if unsafe {
        pyre_object::dictmultiobject::is_dict_view_iterator(
            pyre_object::gc_roots::shadow_stack_get(iterator_slot),
        )
    } {
        let w_dict = unsafe {
            pyre_object::dictmultiobject::w_dict_view_iterator_get_dict(
                pyre_object::gc_roots::shadow_stack_get(iterator_slot),
            )
        };
        let _ = pyre_object::gc_roots::pin_root(w_dict);
    }
    let best_item_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::gc_roots::shadow_stack_get(default_slot));
    let best_key_slot = if key_fn_slot.is_some() {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::w_none());
        slot
    } else {
        best_item_slot
    };
    let candidate_item_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_none());
    let candidate_key_slot = if key_fn_slot.is_some() {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::w_none());
        slot
    } else {
        candidate_item_slot
    };
    let cmp_op = if want_max {
        crate::baseobjspace::CompareOp::Gt
    } else {
        crate::baseobjspace::CompareOp::Lt
    };
    let mut has_item = false;
    loop {
        let it_now = pyre_object::gc_roots::shadow_stack_get(iterator_slot);
        let item = match crate::baseobjspace::next(it_now) {
            Ok(item) => item,
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    break;
                }
                return Err(e);
            }
        };
        pyre_object::gc_roots::shadow_stack_set(candidate_item_slot, item);
        if let Some(key_fn_slot) = key_fn_slot {
            let candidate_key = crate::call::call_function_impl_result(
                pyre_object::gc_roots::shadow_stack_get(key_fn_slot),
                &[pyre_object::gc_roots::shadow_stack_get(candidate_item_slot)],
            )?;
            pyre_object::gc_roots::shadow_stack_set(candidate_key_slot, candidate_key);
        }
        if !has_item {
            pyre_object::gc_roots::shadow_stack_set(
                best_item_slot,
                pyre_object::gc_roots::shadow_stack_get(candidate_item_slot),
            );
            if key_fn_slot.is_some() {
                pyre_object::gc_roots::shadow_stack_set(
                    best_key_slot,
                    pyre_object::gc_roots::shadow_stack_get(candidate_key_slot),
                );
            }
            has_item = true;
            continue;
        }
        if crate::baseobjspace::is_true(crate::baseobjspace::compare(
            pyre_object::gc_roots::shadow_stack_get(candidate_key_slot),
            pyre_object::gc_roots::shadow_stack_get(best_key_slot),
            cmp_op,
        )?)? {
            pyre_object::gc_roots::shadow_stack_set(
                best_item_slot,
                pyre_object::gc_roots::shadow_stack_get(candidate_item_slot),
            );
            if key_fn_slot.is_some() {
                pyre_object::gc_roots::shadow_stack_set(
                    best_key_slot,
                    pyre_object::gc_roots::shadow_stack_get(candidate_key_slot),
                );
            }
        }
    }
    if !has_item && !has_default {
        return Err(crate::PyError::new(
            crate::PyErrorKind::ValueError,
            format!("{fn_name}() iterable argument is empty"),
        ));
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(best_item_slot))
}

/// `pypy/module/__builtin__/functional.py min_max_multiple_args`:
/// `@jit.look_inside_iff(lambda space, args_w, w_key, implementation_of:
///         jit.loop_unrolling_heuristic(args_w, len(args_w), 3))`.
fn min_max_multiple_args_iff(
    positional: &[PyObjectRef],
    _key_fn: Option<PyObjectRef>,
    _want_max: bool,
) -> bool {
    majit_rlib::jit::loop_unrolling_heuristic(positional, positional.len(), 3)
}

#[majit_macros::look_inside_iff(min_max_multiple_args_iff)]
fn min_max_multiple_args(
    positional: &[PyObjectRef],
    key_fn: Option<PyObjectRef>,
    want_max: bool,
) -> Result<PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let item_base = pyre_object::gc_roots::publish_roots(positional);
    let key_fn_slot = key_fn.map(|key| pyre_object::gc_roots::publish_roots(&[key]));
    pyre_object::gc_roots::normalize_roots(
        item_base,
        positional.len() + usize::from(key_fn_slot.is_some()),
    );
    let cmp_op = if want_max {
        crate::baseobjspace::CompareOp::Gt
    } else {
        crate::baseobjspace::CompareOp::Lt
    };
    let best_item_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::gc_roots::shadow_stack_get(item_base));
    let best_key_slot = if let Some(key_fn_slot) = key_fn_slot {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::w_none());
        let first_key = crate::call::call_function_impl_result(
            pyre_object::gc_roots::shadow_stack_get(key_fn_slot),
            &[pyre_object::gc_roots::shadow_stack_get(best_item_slot)],
        )?;
        pyre_object::gc_roots::shadow_stack_set(slot, first_key);
        slot
    } else {
        best_item_slot
    };
    let candidate_item_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ =
        pyre_object::gc_roots::pin_root(pyre_object::gc_roots::shadow_stack_get(best_item_slot));
    let candidate_key_slot = if key_fn_slot.is_some() {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ =
            pyre_object::gc_roots::pin_root(pyre_object::gc_roots::shadow_stack_get(best_key_slot));
        slot
    } else {
        candidate_item_slot
    };
    for i in 1..positional.len() {
        pyre_object::gc_roots::shadow_stack_set(
            candidate_item_slot,
            pyre_object::gc_roots::shadow_stack_get(item_base + i),
        );
        if let Some(key_fn_slot) = key_fn_slot {
            let candidate_key = crate::call::call_function_impl_result(
                pyre_object::gc_roots::shadow_stack_get(key_fn_slot),
                &[pyre_object::gc_roots::shadow_stack_get(candidate_item_slot)],
            )?;
            pyre_object::gc_roots::shadow_stack_set(candidate_key_slot, candidate_key);
        }
        // `functional.py:139 if space.is_true(space.gt(key, best_key))`
        // — route through the generic comparison dispatch which
        // handles int/long/str/float/tuple natively and falls
        // through to user-defined `__gt__`/`__lt__` for other
        // types.  Errors (TypeError from incomparable types or an
        // exception from the key call, as in functional.py min_max)
        // are propagated to the caller.
        if crate::baseobjspace::is_true(crate::baseobjspace::compare(
            pyre_object::gc_roots::shadow_stack_get(candidate_key_slot),
            pyre_object::gc_roots::shadow_stack_get(best_key_slot),
            cmp_op,
        )?)? {
            pyre_object::gc_roots::shadow_stack_set(
                best_item_slot,
                pyre_object::gc_roots::shadow_stack_get(candidate_item_slot),
            );
            if key_fn_slot.is_some() {
                pyre_object::gc_roots::shadow_stack_set(
                    best_key_slot,
                    pyre_object::gc_roots::shadow_stack_get(candidate_key_slot),
                );
            }
        }
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(best_item_slot))
}

/// CPython 3.14 `type_new` — `type.__new__(metatype, name, bases, dict)`.
///
/// `descr__new__(space, w_typetype, __args__)` takes the metatype as its own
/// gateway parameter and everything behind it as `__args__`, so `pos[0]` is the
/// metatype and `pos[1..]` is `arguments_w`.  A bound `__new__` does not prepend
/// its `__self__`, on the direct path or through `super()`, so the split is the
/// same however the call arrives.
///
/// Nothing may key the `(name, bases, dict)` triple off argument *types* —
/// scanning for the first `str`, say — because that lets a non-type metatype
/// slip past `precheck_for_new` and build a class, and it is why `_ast`'s
/// `register_module` has to name `type` explicitly rather than rely on a scan
/// to default it.
pub fn type_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // The class-definition keywords arrive as a trailing `__pyre_kw__`
    // dict (the builtin kwargs ABI); strip it before the arity check and
    // hand it to __init_subclass__ via `type_create_new_type`.
    let (pos, kwargs) = split_builtin_kwargs(args);
    // `type_new` receives the metatype separately from the tuple parsed by
    // `PyArg_ParseTuple`.  Pyre's flat builtin ABI has to reproduce the
    // descriptor gateway's missing-metatype refusal before splitting it out.
    if pos.is_empty() {
        return Err(crate::PyError::type_error(
            "type.__new__(): not enough arguments",
        ));
    }

    let w_typetype = pos[0];
    let arguments_w = &pos[1..];
    // `type_new` is entered only after `tp_new_wrapper` has established that
    // the first argument is a type.  This check therefore precedes parsing
    // `(name, bases, dict)`, regardless of that tuple's arity.
    precheck_for_new(w_typetype)?;
    if arguments_w.len() != 3 {
        return Err(crate::PyError::type_error(new_arity_message(
            arguments_w.len(),
        )));
    }

    type_create_new_type(arguments_w, w_typetype, kwargs)
}
/// Python 3.14 `type_new`: the inherited slot keeps the defining type's name
/// in its error, even when invoked through a metaclass subclass.  PyPy 3.11's
/// `descr__new__` instead interpolates that subclass (`M.__new__`), but the
/// project's version target is 3.14.
fn new_arity_message(given: usize) -> String {
    format!("type.__new__() takes exactly 3 arguments ({given} given)")
}

/// CPython 3.14 `tp_new_wrapper` — the metatype must be a type before
/// `type_new` parses its three construction arguments.
fn precheck_for_new(w_type: PyObjectRef) -> Result<(), crate::PyError> {
    if unsafe { pyre_object::is_type(w_type) } {
        Ok(())
    } else {
        let type_name = crate::baseobjspace::object_functionstr_type_name(w_type);
        Err(crate::PyError::type_error(format!(
            "type.__new__(X): X is not a type object ({type_name})"
        )))
    }
}

/// typeobject.py `_check_surrogate` — a type name may not contain a
/// lone surrogate.  Validate through the surrogate-aware WTF-8 view (reading
/// the name as `&str` would fail on the surrogate) and raise
/// `UnicodeEncodeError('utf8', name, pos, pos + 1, 'surrogates not allowed')`
/// at the first one, matching `check_utf8(name, allow_surrogates=False)`.
/// Keep the call itself: upstream marks `_check_utf8` `jit.elidable`, so the
/// validator is a load-bearing part of the JIT shape rather than an iterator
/// scan to re-express locally.
///
/// `CheckError.pos` is a BYTE offset — `_check_utf8` walks `s[pos]` — and
/// `_check_surrogate` forwards it unchanged, but `UnicodeEncodeError` is
/// consumed as a code-point index: `descr_str` reads `self.object[self.start]`
/// (`interp_exceptions.py`, `W_UnicodeEncodeError.descr_str`) and `.start` is
/// user-visible. Upstream is inconsistent between the two, and CPython 3.14
/// reports the code-point index, so convert here rather than propagate the
/// byte offset.  Oracle evidence (pinned CPython 3.14.6 versus local PyPy):
/// `type('\u00e9\ud800', (), {})` reports `.start/.end == (1, 2)` on CPython
/// and `(2, 3)` on PyPy.  Those exception attributes are observable, so the
/// CPython 3.14 specification wins while the surrounding PyPy call shape is
/// retained.
pub(crate) fn check_surrogate(w_name: PyObjectRef) -> Result<(), crate::PyError> {
    let wtf8 = unsafe { pyre_object::w_str_get_wtf8(w_name) };
    if let Err(e) = pyre_object::rutf8::check_utf8(wtf8.as_bytes(), false) {
        // RPython's CheckError position, `e.pos + 1`, and the exception's
        // start/end fields are all Signed; keep that type through the call.
        let pos = pyre_object::rutf8::codepoints_in_utf8(wtf8, 0, e.pos as usize) as i64;
        return Err(crate::typedef::unicode_encode_error(
            "utf8",
            w_name,
            pos,
            pos + 1,
            "surrogates not allowed",
        ));
    }
    Ok(())
}

/// `type_new_staticmethod` / `type_new_classmethod` (Objects/typeobject.c):
/// a class body's plain-function `__new__` becomes a `staticmethod` and
/// `__init_subclass__` / `__class_getitem__` become `classmethod`s, so that
/// `cls.__dict__['__new__'].__func__` resolves and the descriptors bind with
/// the right implicit first argument.
pub(crate) fn type_new_wrap_special_methods(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ns);
    if let Some(mut f) = unsafe {
        pyre_object::w_dict_getitem_str(pyre_object::gc_roots::shadow_stack_get(ns_slot), "__new__")
    } && unsafe { crate::function::is_function(f) }
        && !unsafe { pyre_object::function::is_staticmethod(f) }
    {
        pyre_object::with_roots!(f => {
            crate::__pyre_put_new!(
                ns_slot,
                "__new__",
                pyre_object::function::w_staticmethod_new(f)
            )
        });
    }
    for name in ["__init_subclass__", "__class_getitem__"] {
        if let Some(mut f) = unsafe {
            pyre_object::w_dict_getitem_str(pyre_object::gc_roots::shadow_stack_get(ns_slot), name)
        } && unsafe { crate::function::is_function(f) }
            && !unsafe { pyre_object::function::is_classmethod(f) }
        {
            pyre_object::with_roots!(f => {
                crate::__pyre_put_new!(
                    ns_slot,
                    name,
                    pyre_object::function::w_classmethod_new(f)
                )
            });
        }
    }
}

/// A class that supplies equality but no hash is explicitly unhashable.
pub(crate) fn type_new_set_hash_if_eq(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ns);
    if unsafe {
        pyre_object::w_dict_getitem_str(pyre_object::gc_roots::shadow_stack_get(ns_slot), "__eq__")
    }
    .is_some()
        && unsafe {
            pyre_object::w_dict_getitem_str(
                pyre_object::gc_roots::shadow_stack_get(ns_slot),
                "__hash__",
            )
        }
        .is_none()
    {
        unsafe { crate::__pyre_put_new!(ns_slot, "__hash__", pyre_object::w_none()) };
    }
}

/// `type_dict_set_doc` (`type_ready_fill_dict`): every new class owns a
/// `__doc__` entry, using None when its namespace supplied no docstring.
///
/// This runs on the finished type, after the slot descriptors and the
/// `__dict__` / `__weakref__` getsets have been installed, so a defaulted
/// entry lands behind them in `cls.__dict__`.  A `__doc__` declared in
/// `__slots__` therefore already owns the name by the time this looks, and
/// its member descriptor stands.
pub(crate) fn type_dict_set_doc(w_type: PyObjectRef) {
    if crate::type_dict_contains(w_type, "__doc__") {
        return;
    }
    crate::type_dict_store(w_type, "__doc__", pyre_object::w_none());
}

/// PyPy `typeobject.py:223-235 W_TypeObject.__init__`: consume the compiler's
/// `__qualname__` entry before slot setup and retain it on the type object.
/// Keeping it in the namespace changes `cls.__dict__` and makes libraries
/// such as `typing.Protocol` mistake it for a user-declared member.
pub(crate) fn type_new_take_qualname(w_type: PyObjectRef, ns: PyObjectRef) -> crate::PyResult {
    // The lookup and the delete each intern `__qualname__`, so the moving
    // namespace is read back out of a root slot for both.
    let roots = pyre_object::gc_roots::push_roots();
    let base = roots.pin_roots(&[ns, w_type, pyre_object::PY_NULL]);
    let Some(value) = (unsafe { pyre_object::w_dict_getitem_str(roots.get(base), "__qualname__") })
    else {
        return Ok(pyre_object::w_none());
    };
    if !unsafe { pyre_object::is_str(value) } {
        return Err(crate::PyError::type_error(format!(
            "type __qualname__ must be a str, not {}",
            crate::type_methods::arg_type_name(value),
        )));
    }
    roots.set(base + 2, value);
    check_surrogate(value)?;
    unsafe {
        pyre_object::w_type_set_qualname(roots.get(base + 1), roots.get(base + 2));
        pyre_object::w_dict_delitem_str_no_proxy(roots.get(base), "__qualname__");
    }
    Ok(pyre_object::w_none())
}

/// `type_new_set_classcell` / `type_new_set_classdictcell` refuse a namespace
/// entry that is not a cell.  The offending type is spelled with `%.200R`, so
/// a metaclass `__repr__` renders it — and when that repr raises,
/// `_PyErr_FormatV` returns without setting the `TypeError`, leaving the
/// repr's own exception in its place.
pub(crate) fn cell_slot_type_error(key: &str, value: PyObjectRef) -> crate::PyError {
    // `%.200R` clips the rendering at 200 code points.
    const MAX_REPR_CODE_POINTS: usize = 200;
    let rendered = match crate::typedef::r#type(value) {
        Some(w_valtype) => match unsafe { crate::display::py_repr_wtf8(w_valtype.as_ptr()) } {
            Ok(rendered) => rendered,
            Err(error) => return error,
        },
        None => rustpython_wtf8::Wtf8Buf::from_string(format!(
            "<class '{}'>",
            crate::error::type_name_of(value)
        )),
    };
    let mut clipped = rustpython_wtf8::Wtf8Buf::new();
    for point in rendered.code_points().take(MAX_REPR_CODE_POINTS) {
        clipped.push(point);
    }
    crate::PyError::type_error(crate::display::wtf8_format!(
        format!("{key} must be a nonlocal cell, not "),
        clipped
    ))
}

/// typeobject.py `_create_new_type`.
///
/// `descr__new__` looks inside so `type(x)` stays in-trace; this body is a
/// separate function so the 3-arg path is one residual `CALL_MAY_FORCE`.
/// `_create_new_type` has no `@dont_look_inside`; `JitPolicy.look_inside_graph`
/// residualizes it because the body has loops (`contains_loop` /
/// `find_backedges`).  `W_TypeObject.__init__` is `@dont_look_inside`.
/// `#[inline(never)]` keeps the helper a separate graph so rustc does not
/// fold it into `type_descr_new`.
///
/// `ensure_module_attr` reads `caller.get_w_globals()` with no extra force:
/// `w_globals` is frame-invariant (`restore_resume_state_from` leaves it
/// out) so the heap slot is already current.  A hand-placed
/// `jit_force_virtualizable` here aborted compiles that create a type
/// (`ABORT_ESCAPE`) and scrambled virtual locals on loops that still compiled.
#[inline(never)]
fn type_create_new_type(
    args: &[PyObjectRef],
    w_metaclass: PyObjectRef,
    kwargs: Option<PyObjectRef>,
) -> Result<PyObjectRef, crate::PyError> {
    // type(name, bases, dict) — 3-arg form creates a new type
    // PyPy: typeobject.py type.__new__(metatype, name, bases, dict)
    if args.len() == 3 {
        let name_obj = args[0];
        let bases = args[1];
        let w_namespace_dict = args[2];
        // typeobject.py:_check_new_args — validate the three public
        // arguments before attempting to copy or normalise any of them.
        //
        // `type_new` spells the same three checks as a single
        // `PyArg_ParseTuple(args, "UO!O!:type.__new__", ...)`, and it is the
        // `:type.__new__` suffix that names the callable in the messages
        // getargs builds, so they say `type.__new__()` on every entry point —
        // a bare `type(...)` call, `type.__new__` invoked directly, and a
        // metaclass such as `ABCMeta`.  The `O!` checks are `PyObject_
        // TypeCheck`, so a tuple subclass is an accepted `bases` and a dict
        // subclass an accepted namespace; neither is silently coerced.
        if !unsafe { crate::baseobjspace::isinstance_str_w(name_obj) } {
            return Err(crate::PyError::type_error(format!(
                "type.__new__() argument 1 must be str, not {}",
                crate::type_methods::clinic_arg_type_name(name_obj)
            )));
        }
        if !unsafe { is_tuple(bases) } {
            return Err(crate::PyError::type_error(format!(
                "type.__new__() argument 2 must be tuple, not {}",
                crate::type_methods::clinic_arg_type_name(bases)
            )));
        }
        let w_dict_type = crate::typedef::gettypeobject(&pyre_object::pyobject::DICT_TYPE);
        if !unsafe { crate::baseobjspace::isinstance_w(w_namespace_dict, w_dict_type) } {
            return Err(crate::PyError::type_error(format!(
                "type.__new__() argument 3 must be dict, not {}",
                crate::type_methods::clinic_arg_type_name(w_namespace_dict)
            )));
        }
        // name/bases/dict all relocate. Everything from here down
        // dispatches through user code -- the namespace backing's `keys`,
        // the `__mro_entries__` lookups, the namespace copy, `__set_name__`,
        // `__init_subclass__` -- so the three public arguments are
        // published once and re-read at each region below.
        let _roots = pyre_object::gc_roots::push_roots();
        let n_args = args.len();
        let has_kwargs = kwargs.is_some();
        let kwargs_word = kwargs.unwrap_or(pyre_object::PY_NULL);
        // One publish of every live word, then a single normalize, so the
        // argument slice, the keyword dict, and the metaclass are on the
        // root stack before the first forwarding query.
        let name_slot = pyre_object::gc_roots::publish_roots(&[name_obj, bases, w_namespace_dict]);
        let bases_slot = name_slot + 1;
        let namespace_root = name_slot + 2;
        let args_base = pyre_object::gc_roots::publish_roots(args);
        let kwargs_slot = pyre_object::gc_roots::publish_roots(&[kwargs_word]);
        let meta_slot = pyre_object::gc_roots::publish_roots(&[w_metaclass]);
        pyre_object::gc_roots::normalize_roots(name_slot, 3 + n_args + 2);
        let name_obj = || pyre_object::gc_roots::shadow_stack_get(name_slot);
        let meta = || pyre_object::gc_roots::shadow_stack_get(meta_slot);

        // typeobject.py `_create_new_type` — direct three-argument
        // `type()` never performs PEP 560 base rewriting.  A non-type base
        // advertising `__mro_entries__` gets the dedicated diagnostic before
        // metaclass calculation; class statements resolve it earlier in
        // `__build_class__` and therefore never reach this branch.
        let bases = pyre_object::gc_roots::shadow_stack_get(bases_slot);
        let n_bases = unsafe { w_tuple_len(bases) };
        for index in 0..n_bases {
            let Some(base) = (unsafe { pyre_object::w_tuple_getitem(bases, index as i64) }) else {
                continue;
            };
            if !unsafe { pyre_object::is_type(base) }
                && unsafe { crate::baseobjspace::lookup(base, "__mro_entries__") }.is_some()
            {
                return Err(crate::PyError::type_error(
                    "type() doesn't support MRO entry resolution; use types.new_class()",
                ));
            }
        }

        // `_calculate_metaclass` then, when the winner differs, maybe
        // `space.call_obj_args(newfunc, w_winner, __args__)`. Delegation
        // sits before name validation and the namespace copy, matching
        // `_create_new_type` and `type_new_get_bases`. `getattr` and the
        // delegated `__new__` collect, so every live word is a slot.
        let w_winner = crate::call::calculate_metaclass(
            if meta().is_null() {
                crate::typedef::w_type()
            } else {
                meta()
            },
            pyre_object::gc_roots::shadow_stack_get(bases_slot),
        )?;
        let winner_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_winner);
        let default_meta = if meta().is_null() {
            crate::typedef::w_type()
        } else {
            meta()
        };
        if !crate::baseobjspace::is_w(
            pyre_object::gc_roots::shadow_stack_get(winner_slot),
            default_meta,
        ) {
            // Delegate only when the winner's resolved `__new__` is not
            // `type.__new__` itself; otherwise `w_typetype = w_winner`.
            let newfunc = crate::baseobjspace::getattr_str(
                pyre_object::gc_roots::shadow_stack_get(winner_slot),
                "__new__",
            )?;
            let newfunc_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(newfunc);
            let type_new = crate::baseobjspace::getattr_str(crate::typedef::w_type(), "__new__")?;
            let type_new_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(type_new);
            if !crate::baseobjspace::is_w(
                pyre_object::gc_roots::shadow_stack_get(newfunc_slot),
                pyre_object::gc_roots::shadow_stack_get(type_new_slot),
            ) {
                let kw_entries = builtin_kwarg_entries(
                    has_kwargs.then(|| pyre_object::gc_roots::shadow_stack_get(kwargs_slot)),
                );
                let mut new_args = vec![
                    pyre_object::gc_roots::shadow_stack_get(winner_slot),
                    name_obj(),
                    pyre_object::gc_roots::shadow_stack_get(bases_slot),
                    pyre_object::gc_roots::shadow_stack_get(namespace_root),
                ];
                for index in 3..n_args {
                    new_args.push(pyre_object::gc_roots::shadow_stack_get(args_base + index));
                }
                return if kw_entries.is_empty() {
                    crate::call::call_function_impl_result(
                        pyre_object::gc_roots::shadow_stack_get(newfunc_slot),
                        &new_args,
                    )
                } else {
                    crate::call::call_with_kwargs_in_ctx(
                        crate::call::take_last_exec_ctx(),
                        pyre_object::gc_roots::shadow_stack_get(newfunc_slot),
                        &new_args,
                        &kw_entries,
                    )
                };
            }
        }
        let w_metaclass = || pyre_object::gc_roots::shadow_stack_get(winner_slot);

        // Mixed NUL+surrogate is UnicodeEncodeError: `type_new_set_name`
        // encodes with `PyUnicode_AsUTF8AndSize` before the `strlen` NUL
        // test (Objects/typeobject.c, read at v3.14.6 in
        // ~/Projects/cpython-3146). `_create_new_type` does `'\x00' in name`
        // then `_check_surrogate` and answers ValueError. The exception type
        // is observable, so `_check_surrogate` runs first; both checks stay
        // before the namespace copy. `_check_utf8` `@jit.elidable` governs
        // the utf8 scan, not this order. `W_TypeObject.__init__`
        // `@dont_look_inside` and `name?` sit after a successful name.
        // U+0000 is a single 0x00 byte in WTF-8.
        check_surrogate(name_obj())?;
        if unsafe { pyre_object::w_str_get_wtf8(name_obj()) }
            .as_bytes()
            .contains(&0)
        {
            return Err(crate::PyError::value_error(
                "type name must not contain null characters",
            ));
        }
        let name = crate::baseobjspace::str_utf8_w(name_obj())?;
        let backing_root = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(unsafe {
            crate::type_methods::resolve_dict_backing(pyre_object::gc_roots::shadow_stack_get(
                namespace_root,
            ))
        });

        // Copy the namespace into the class-namespace scratch.
        // `w_dict_items` dispatches through `is_module_dict`, so the rare
        // `__build_class__` case where the namespace is a W_ModuleDictObject
        // still walks correctly.
        //
        // `type.__new__` accepts any `dict` subclass as the namespace
        // (the check is `PyDict_Check`, not `PyDict_CheckExact`); resolve
        // the dict backing so e.g. an `enum._EnumDict` class body is
        // walked instead of dropped.
        //
        // `type_new_init` opens with `PyDict_Copy(ctx->orig_dict)` and then
        // mutates that one dict, so the scratch namespace is a clone rather
        // than a per-key refill.  The clone carries each key's cached hash,
        // where a re-store would call `__hash__` again — running a
        // side-effecting one an extra time, and dropping the entry outright
        // once that `__hash__` starts raising, since the store surface cannot
        // report an error.
        // Name/bases/dict/backing already sit on `_roots`; pin the scratch
        // clone onto the same set instead of opening a nested bracket.
        let w_ns_backing = pyre_object::gc_roots::shadow_stack_get(backing_root);
        let class_ns = if w_ns_backing.is_null() {
            pyre_object::w_dict_new()
        } else {
            unsafe {
                pyre_object::w_dict_copy(pyre_object::gc_roots::shadow_stack_get(backing_root))
            }
        };
        let class_ns_root = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(class_ns);
        // type_new_classcell — capture the `__classcell__` cell and keep
        // both explicit class cells out of the new type's `__dict__`
        // (CPython consumes them here rather than storing them).
        let mut classcell_root = None;
        let mut classdictcell_root = None;
        // `_PyDict_HasOnlyStringKeys(type->tp_dict)` decides the
        // `RuntimeWarning` reported once the type is ready.  Only this copy
        // can introduce such a key; every later pass installs descriptors
        // under interned names.
        let mut has_non_string_key = false;
        {
            let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
            let items = unsafe { pyre_object::w_dict_items(class_ns) };
            let mut flat = Vec::with_capacity(items.len() * 2);
            for &(key, value) in &items {
                flat.push(key);
                flat.push(value);
            }
            let item_root = pyre_object::gc_roots::pin_roots(&flat);
            for index in 0..items.len() {
                let key = pyre_object::gc_roots::shadow_stack_get(item_root + index * 2);
                let value = pyre_object::gc_roots::shadow_stack_get(item_root + index * 2 + 1);
                if !unsafe { pyre_object::is_str(key) } {
                    has_non_string_key = true;
                    continue;
                }
                let key_text = unsafe { pyre_object::w_str_get_wtf8(key) };
                let name = match key_text.as_str() {
                    Ok(name @ ("__classcell__" | "__classdictcell__")) => name,
                    _ => continue,
                };
                if !unsafe { pyre_object::is_cell(value) } {
                    return Err(cell_slot_type_error(name, value));
                }
                let root = pyre_object::gc_roots::shadow_stack_len();
                let _ = pyre_object::gc_roots::pin_root(value);
                if name == "__classcell__" {
                    classcell_root = Some(root);
                } else {
                    classdictcell_root = Some(root);
                }
                let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
                unsafe { pyre_object::w_dict_delitem_str_no_proxy(class_ns, name) };
            }
        }
        // typeobject.py ensure_module_attr.  Direct three-argument type()
        // calls do not pass through __build_class__, so fill __module__ from
        // the live caller frame when the namespace did not supply it.
        //
        // `ensure_module_attr` reaches the caller through
        // `getexecutioncontext().gettopframe_nohidden()`, so read it that way
        // rather than through the `CURRENT_FRAME` thread-local.  No force is
        // owed here: the walk only dereferences the vref and follows
        // `f_backref`, and `force_frame` belongs to the consumers that hand a
        // frame to application code.  `w_globals` is a declared virtualizable
        // field, but no walk writes it on the live frame —
        // `restore_resume_state_from` leaves it and `pycode` out of the resume
        // restore as frame-invariant — so its heap slot is already current.
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        if unsafe { pyre_object::w_dict_getitem_str(class_ns, "__module__") }.is_none() {
            let ec = crate::call::getexecutioncontext() as *mut crate::PyExecutionContext;
            let frame = if ec.is_null() {
                std::ptr::null_mut()
            } else {
                unsafe { (*ec).gettopframe_nohidden() }
            };
            if !frame.is_null() {
                let globals = unsafe { (*frame).get_w_globals() };
                if !globals.is_null()
                    && let Some(module) = crate::baseobjspace::finditem_str(globals, "__name__")?
                {
                    let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
                    unsafe {
                        pyre_object::w_dict_setitem_str_no_proxy(class_ns, "__module__", module)
                    };
                }
            }
        }
        // CPython 3.14 rejects lone surrogates in the initial type doc while
        // retaining the historical freedom to assign arbitrary objects later.
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        if let Some(doc) = unsafe { pyre_object::w_dict_getitem_str(class_ns, "__doc__") }
            && unsafe { pyre_object::is_str(doc) }
        {
            check_surrogate(doc)?;
        }
        // W_TypeObject.__init__: pop and validate __qualname__ before slot
        // construction.  Pyre keeps it in the canonical namespace because it
        // has no separate qualname field, but preserves the same validation.
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        if let Some(qualname) = unsafe { pyre_object::w_dict_getitem_str(class_ns, "__qualname__") }
            && !unsafe { crate::baseobjspace::isinstance_str_w(qualname) }
        {
            return Err(crate::PyError::type_error(format!(
                "type __qualname__ must be a str, not {}",
                crate::error::type_name_of(qualname)
            )));
        }
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        type_new_set_hash_if_eq(class_ns);
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        type_new_wrap_special_methods(class_ns);

        // typeobject.py:954 — `W_TypeObject.__init__` is the site that reads
        // the bases as `bases_w or [space.w_object]`, so the `(object,)`
        // default belongs to construction and to nothing that runs before it.
        // On the empty-bases arm this is a `(object,)` tuple minted right here
        // with no other referrer, and it has to survive `validate_c3_mro`,
        // `create_all_slots`, `__set_name__` and `__init_subclass__` before
        // anything else refers to it.  A tuple is nursery-allocated and every
        // one of those collects, so each use below reads the slot back instead
        // of carrying the word. `_calculate_metaclass` already ran on the
        // bases as written; substituting `(object,)` there would weigh an
        // explicit metatype against `type(object)`.
        let _effective_bases_roots = pyre_object::gc_roots::push_roots();
        let bases = pyre_object::gc_roots::shadow_stack_get(bases_slot);
        let w_effective_bases =
            if bases.is_null() || !unsafe { is_tuple(bases) } || unsafe { w_tuple_len(bases) } == 0
            {
                let w_object = crate::typedef::w_object();
                if !w_object.is_null() {
                    pyre_object::w_tuple_new(vec![w_object])
                } else {
                    bases
                }
            } else {
                bases
            };
        let effective_bases_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_effective_bases);

        // `_create_new_type` reaches the instance through
        // `space.allocate_instance(W_TypeObject, w_typetype)`, which runs
        // `W_TypeObject.check_user_subclass` (typeobject.py) on the way
        // in.  That is the only place a metatype which *is* a type but is not a
        // subtype of `type` gets refused — `precheck_for_new` above settles
        // only that it is a type at all — so without it
        // `type.__new__(int, 'A', (), {})` would build a class whose metatype
        // is `int`.  Call the function rather than inline one of its three
        // checks: the layout arm is what refuses a metatype whose instances are
        // not laid out as type objects.
        crate::typedef::check_user_subclass(crate::typedef::w_type(), w_metaclass())?;

        // This is type.__new__'s own construction path. A different winning
        // metaclass above received the original bases without a C3 pre-check.
        unsafe {
            crate::baseobjspace::validate_c3_mro(
                pyre_object::gc_roots::shadow_stack_get(effective_bases_slot),
                false,
            )?
        };

        let _dict_root = pyre_object::gc_roots::push_roots();
        let dict_root = pyre_object::gc_roots::shadow_stack_len();
        let class_ns = pyre_object::gc_roots::shadow_stack_get(class_ns_root);
        // Clone the assembled namespace preserving its cached key hashes,
        // mirroring the final `PyDict_Copy` for the type's `__dict__`.  A
        // per-key reinsert would hash every non-string key again, running a
        // side-effecting `__hash__` an extra time (and dropping any error it
        // raised, since the store cannot propagate one).
        let dict_obj = unsafe { pyre_object::w_dict_copy(class_ns) };
        let dict_obj = pyre_object::gc_roots::pin_root(dict_obj);
        let w_type = pyre_object::w_type_new(
            name,
            pyre_object::gc_roots::shadow_stack_get(effective_bases_slot),
            dict_obj as pyre_object::gc_hook::GCREF,
        );
        // Nothing refers to a class this young — the classcell is optional and
        // `weak_subclasses` is weak — while the passes below allocate, so a
        // major cycle sweeps it out from under `create_all_slots` and the
        // barrier in `tag_subclass_instance` then writes through a freed
        // header.  `allocate_instance` puts the type in the nursery, so each
        // collecting pass below reloads it from the slot.
        let w_type_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_type);
        let w_type = || pyre_object::gc_roots::shadow_stack_get(w_type_slot);
        // The type allocation may have moved the namespace, so the qualname
        // pass receives the forwarded address rather than the word above.
        type_new_take_qualname(w_type(), pyre_object::gc_roots::shadow_stack_get(dict_root))?;
        // typeobject.py create_all_slots parity.
        unsafe {
            crate::call::create_all_slots(
                w_type(),
                pyre_object::gc_roots::shadow_stack_get(effective_bases_slot),
            )?
        };
        // `type_ready_fill_dict` defaults the doc entry once the slot and
        // instance descriptors own their names.
        type_dict_set_doc(w_type());
        // rclass.py:739-743 — set w_class (typeptr) at allocation time.
        // For type objects, w_class is the metaclass (type(C) → Meta).
        // baseobjspace.py getclass() returns the metatype.
        crate::typedef::tag_subclass_instance(w_type(), w_metaclass());

        // type_new_classcell — bind the captured `__classcell__` to the
        // new type so `__class__` / zero-arg `super()` in the methods
        // resolve; the key was already dropped from the namespace above.
        // PyPy `_store_type_in_classcell` runs before W_TypeObject.__init__,
        // whose `ensure_common_attributes` invokes a custom metaclass mro().
        if let Some(classcell_root) = classcell_root {
            let classcell = pyre_object::gc_roots::shadow_stack_get(classcell_root);
            unsafe { pyre_object::w_cell_set(classcell, w_type()) };
        }

        // typeobject.py compute_mro — a custom metaclass `mro`
        // runs after the class cell is bound and before ready().
        unsafe { crate::baseobjspace::compute_and_set_mro(w_type())? };
        // typeobject.py ready() — link self into each base's
        // `weak_subclasses` so `mutated()` and `__subclasses__()`
        // observe this class.
        unsafe { pyre_object::typeobject::w_type_ready(w_type()) };

        // CPython type_new_set_classdict precedes type_new_set_names: lazy
        // annotation thunks invoked by __set_name__ must resolve class-local
        // names through the completed type dictionary.
        if let Some(classdictcell_root) = classdictcell_root {
            let classdictcell = pyre_object::gc_roots::shadow_stack_get(classdictcell_root);
            let type_dict = unsafe { pyre_object::w_type_get_dict_ptr(w_type()) as PyObjectRef };
            if !type_dict.is_null() {
                unsafe { pyre_object::w_cell_set(classdictcell, type_dict) };
            }
        }

        // `type_new_impl` reports a namespace the class body filled with a
        // key that is not a string once the type is ready, and before
        // `type_new_set_names` runs.
        if has_non_string_key {
            crate::warn::warn_category(
                &format!("non-string key in the __dict__ of class {name}"),
                "RuntimeWarning",
                1,
            )?;
        }

        // _set_names (typeobject.py) — call `__set_name__(owner, name)`
        // on each descriptor in the type's FINAL `__dict__` (`w_type.dict_w`),
        // i.e. the filtered namespace with `__classcell__`/`__classdictcell__`
        // already removed, not the original backing.  Collect the entries
        // first so the storage borrow is released before the call, which may
        // re-enter the type's dict.
        let dict_obj = pyre_object::gc_roots::shadow_stack_get(dict_root);
        let set_name_entries = unsafe { pyre_object::w_dict_items(dict_obj) };
        // The pairs sit in a native Vec the collector does not walk and every
        // `__set_name__` runs Python, so a class body's list and dict values
        // move out from under the entries still to come.  Pin them and read
        // each back at the call that consumes it.  The owner goes in the same
        // scope: `allocate_instance` put it in the nursery, and nothing refers
        // to a class this young — the classcell is optional and
        // `weak_subclasses` is weak — so a collection under a hook would
        // move or sweep it.  The scope runs to the end of the branch, which
        // is what keeps the owner alive through `__init_subclass__` as well.
        let _entry_roots = pyre_object::gc_roots::push_roots();
        let mut livevars = Vec::with_capacity(set_name_entries.len() * 2 + 1);
        livevars.push(w_type());
        livevars.extend(
            set_name_entries
                .iter()
                .flat_map(|&(key, value)| [key, value]),
        );
        let owner_slot = pyre_object::gc_roots::pin_roots(&livevars);
        // `PyDict_Next` walks every entry, so a descriptor stored under a
        // non-string key gets its `__set_name__` call too.
        for index in 0..set_name_entries.len() {
            let key = pyre_object::gc_roots::shadow_stack_get(owner_slot + 1 + index * 2);
            let value = pyre_object::gc_roots::shadow_stack_get(owner_slot + 2 + index * 2);
            unsafe {
                crate::baseobjspace::set_name(
                    pyre_object::gc_roots::shadow_stack_get(owner_slot),
                    key,
                    value,
                )
            }?;
        }

        // type_new_init_subclass — fire __init_subclass__ with the
        // keywords that reached type.__new__ (the stripped `__pyre_kw__`
        // dict).  This is the single site for the metaclass path; the
        // default-metaclass `__build_class__` shortcut fires it itself
        // because it bypasses type.__new__.
        let init_subclass_kwargs: Vec<(PyObjectRef, PyObjectRef)> = match has_kwargs
            .then(|| pyre_object::gc_roots::shadow_stack_get(kwargs_slot))
        {
            Some(kw) => unsafe {
                pyre_object::w_dict_items(kw)
                    .into_iter()
                    .filter(|(k, _)| {
                        is_str(*k) && pyre_object::w_str_get_wtf8(*k).as_str() != Ok("__pyre_kw__")
                    })
                    .collect()
            },
            None => Vec::new(),
        };
        crate::call::call_init_subclass_on_bases(
            w_type(),
            pyre_object::gc_roots::shadow_stack_get(effective_bases_slot),
            &init_subclass_kwargs,
        )?;

        return Ok(w_type());
    }

    unreachable!("type.__new__ argument count was checked by type_descr_new")
}

/// CPython 3.14 `type_call` / `type_vectorcall` one-argument fast path.
/// This deliberately does not belong to `type_descr_new`: a direct
/// `type.__new__(type, obj)` must still require `(name, bases, dict)`.
pub(crate) fn type_of_object(obj: PyObjectRef) -> PyObjectRef {
    // `typedef::type()` respects __class__ overrides for all object kinds.
    if let Some(tp) = crate::typedef::r#type(obj) {
        return tp.as_ptr();
    }
    type_of_object_unnamed(obj)
}

#[majit_macros::dont_look_inside]
fn type_of_object_unnamed(obj: PyObjectRef) -> PyObjectRef {
    if obj.is_null() {
        return crate::typedef::gettypeobject(&pyre_object::pyobject::NONE_TYPE);
    }
    let name = unsafe { (*(*obj).ob_type).name };
    box_str_constant(rustpython_wtf8::Wtf8::new(name))
}

/// `isinstance(obj, cls)` — pypy/module/__builtin__/abstractinst.py
/// `app_isinstance` → `abstract_isinstance_w(allow_override=True)`.
fn builtin_isinstance(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `isinstance` is registered with a fixed arity, so `builtin_code_call`
    // rejects a wrong positional count before this body runs and the branch is
    // unreachable today.  It is what `__majit_wrap_builtin_isinstance` falls
    // back to, though, and the walker enters that wrapper directly rather than
    // through `builtin_code_call` -- so the wording has to be the one
    // `arity_mismatch` gives a two-argument builtin, which the hand-rolled
    // message it replaces did not match, and the report has to be cold and
    // residual the way every reporter in `gateway.rs` is.
    if args.len() != 2 {
        return crate::gateway::method_exact_arity_failure("isinstance", 2, args.len());
    }
    Ok(w_bool_from(crate::baseobjspace::isinstance(
        args[0], args[1],
    )?))
}

/// Manual interp2app gateway for `isinstance`.
///
/// `#[pyre_methods]` emits this same wrapper/descriptor pair automatically:
/// the wrapper reads the arity and each positional slot out of the slice before
/// entering the typed body. The gateway descent walker keys its heap-cache
/// entries for the args array off that element read, so this hand-written
/// wrapper must keep the same shape.
/// Builtins installed by hand must publish the equivalent `BuiltinCode.func`
/// PBC member so source translation can discover and codewrite its graph.
pub fn __majit_wrap_builtin_isinstance(
    args: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return builtin_isinstance(args);
    }
    let obj = args[0];
    let cls = args[1];
    Ok(w_bool_from(crate::baseobjspace::isinstance(obj, cls)?))
}

crate::builtin_wrapper_descriptor!(
    __majit_wrap_builtin_isinstance_target,
    __majit_wrap_builtin_isinstance
);

/// isinstance(obj, cls) for JIT fast path.
///
/// Returns Some(bool) if the check can be resolved, None if cls format
/// is not supported for the fast path (e.g. tuple of types).
/// Uses the same MRO-based `issubtype_w` as the full dispatch.
pub fn call_isinstance(obj: PyObjectRef, cls: PyObjectRef) -> Option<bool> {
    unsafe {
        if is_type(cls) {
            return Some(crate::baseobjspace::isinstance_w(obj, cls));
        }
    }
    None
}

/// `issubclass(cls, classinfo)` — pypy/module/__builtin__/abstractinst.py
/// `app_issubclass` → `abstract_issubclass_w(allow_override=True)`.
fn builtin_issubclass(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "issubclass() takes exactly two arguments ({} given)",
            args.len()
        )));
    }
    Ok(w_bool_from(crate::baseobjspace::issubclass(
        args[0], args[1],
    )?))
}

// Descroperation helpers (lookup_type_special, try_dispatch_binary_special,
// try_int_long_pow_with_modulo, binary_builtin_type_error,
// issubtype_w) live in `crate::baseobjspace` because
// they are space-level semantics shared between the builtin module,
// weakproxy wrappers, and any future opcode dispatch.

/// Exception type constructor — called as e.g. `ValueError("msg")`.
///
/// `W_BaseException.descr_init` stores the constructor positional
/// arguments on `self.args_w`. That slot is the fixed-size item array
/// (`ll_fixed_newlist` / `FixedSizeListRepr`). `descr_str` and
/// `descr_repr` format from the same field, and `w_exception_get_args`
/// rebuilds a fresh tuple per read (`descr_getargs`:
/// `return space.newtuple(self.args_w)`).
macro_rules! exc_constructor {
    ($fn_name:ident, $kind:expr) => {
        fn $fn_name(
            cls: Option<PyObjectRef>,
            args: &[PyObjectRef],
        ) -> Result<PyObjectRef, crate::PyError> {
            // `interp_exceptions.py W_BaseException.descr_init`:
            // `self.args_w = args_w`.  The string form of the exception
            // is derived from `args_w` on demand (`descr_str`), so the
            // constructor only captures the args — no eager message copy.
            let _roots = pyre_object::gc_roots::push_roots();
            let args_base = pyre_object::gc_roots::shadow_stack_len();
            for &arg in args {
                let _ = pyre_object::gc_roots::pin_root(arg);
            }
            let cls_slot = cls.map(|cls| {
                let slot = pyre_object::gc_roots::shadow_stack_len();
                let _ = pyre_object::gc_roots::pin_root(cls);
                slot
            });
            let exc = match cls_slot {
                Some(slot) => pyre_object::interp_exceptions::w_exception_new_empty_for_class(
                    $kind,
                    pyre_object::gc_roots::shadow_stack_get(slot),
                ),
                None => pyre_object::interp_exceptions::w_exception_new_empty($kind),
            };
            let exc_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(exc);
            // The allocation above may collect and move the arguments without
            // updating the raw slice, so rebuild them from their rooted slots.
            let mut rooted_args = Vec::with_capacity(args.len());
            for i in 0..args.len() {
                rooted_args.push(pyre_object::gc_roots::shadow_stack_get(args_base + i));
            }
            let args_list = pyre_object::interp_exceptions::w_exception_args_new(rooted_args);
            unsafe {
                pyre_object::interp_exceptions::w_exception_set_args(
                    pyre_object::gc_roots::shadow_stack_get(exc_slot),
                    args_list,
                );
            }
            Ok(pyre_object::gc_roots::shadow_stack_get(exc_slot))
        }
    };
}

