/// `interp_exceptions.py W_BaseException.descr_init` — store the
/// constructor positional arguments on `self.args_w`.  Installed as
/// `BaseException.__init__` so the type-call `__new__` ⇒ `__init__`
/// protocol re-stamps `args` to the values forwarded by a subclass's
/// `super().__init__(*args)`, instead of leaving the full original
/// argument list captured by `__new__`.  `args[0]` is `self`.
///
/// `descr_init(self, space, args_w)` takes `args_w` bound as the positional
/// list, so no tuple stands between the caller and the body: this is the flat
/// slice, with any keywords riding it as the trailing `__pyre_kw__` marker.
/// One positional that is not that marker stores `args` without the general
/// walk.  Any other arity that fits in six words stays in
/// [`exc_base_exception_init_slow`]; a longer slice is passed through whole,
/// and both of those reach [`exc_base_exception_init`], which rejects the
/// keywords.
pub fn __majit_wrap_base_exception_descr_init(
    args: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    if args.len() == 2 && !args[0].is_null() && !builtin_kwargs_marker_tail(args[1]) {
        exc_init_one_positional(args[0], args[1]);
        return Ok(pyre_object::w_none());
    }
    // The six-word residual cannot see a longer tail. Hand the real slice
    // to the initializer instead of shortening it.
    if args.len() > 6 {
        return exc_base_exception_init_long(args);
    }
    // Spelled out rather than read through a closure: a closure here is a
    // graph of its own, annotated without the environment it reads, and it
    // falls to the legacy walker on the captured slice.
    exc_base_exception_init_slow(
        args.first().copied().unwrap_or(pyre_object::PY_NULL),
        args.get(1).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(2).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(3).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(4).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(5).copied().unwrap_or(pyre_object::PY_NULL),
        args.len() as i64,
    )
}

/// Word ABI for the same reason as `dict_get_slow`: the traced wrapper
/// cannot pass the args slice through.
#[majit_macros::dont_look_inside]
fn exc_base_exception_init_slow(
    a0: PyObjectRef,
    a1: PyObjectRef,
    a2: PyObjectRef,
    a3: PyObjectRef,
    a4: PyObjectRef,
    a5: PyObjectRef,
    n: i64,
) -> Result<PyObjectRef, crate::PyError> {
    let buf = [a0, a1, a2, a3, a4, a5];
    // The wrapper forwards a longer flat slice to `exc_base_exception_init`
    // before this residual. A count that does not match the words cannot
    // be reconstructed, so do not pretend the call was shorter.
    if !(0..=buf.len() as i64).contains(&n) {
        return Err(crate::PyError::type_error(
            "exception initializer argument count exceeds the values received",
        ));
    }
    exc_base_exception_init(&buf[..n as usize])
}

/// `BaseException(*args)` takes any number of positional arguments, so an
/// arity the word ABI cannot carry still has to reach the initializer whole.
/// Residual for the same reason as [`exc_base_exception_init_slow`]: a
/// traced wrapper that passes the slice on itself stops annotating.
#[majit_macros::dont_look_inside]
fn exc_base_exception_init_long(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    exc_base_exception_init(args)
}

#[majit_macros::dont_look_inside_cannot_raise]
fn exc_init_one_positional(w_self: PyObjectRef, arg: PyObjectRef) {
    if exception_args_already(w_self, &[arg]) {
        return;
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let self_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_self);
    let arg_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(arg);
    let args_list = pyre_object::interp_exceptions::w_exception_args_new(vec![
        pyre_object::gc_roots::shadow_stack_get(arg_slot),
    ]);
    unsafe {
        pyre_object::interp_exceptions::w_exception_set_args(
            pyre_object::gc_roots::shadow_stack_get(self_slot),
            args_list,
        );
    }
}

crate::builtin_wrapper_descriptor!(
    __majit_wrap_base_exception_descr_init_target,
    __majit_wrap_base_exception_descr_init
);

/// `ValueError(x)` — one positional that is not the trailing `__pyre_kw__`
/// marker.  `descr_new_base_exception(space, w_subtype, __args__)` receives
/// `__args__` unbound: this flat slice, keywords included as that marker
/// dict.  The body does `args_w, kwds_w = __args__.unpack()` and then
/// `# ignore kwds`, so the dict is discarded rather than rejected.
///
/// TODO: the general `exc_value_error_new` graph has no jitcode of its own,
/// so a call that misses this one-arg guard declines with
/// `no jitcode for address`.  Binding `__args__` at the gateway closed that
/// gap and is the wrong fix.  Upstream recovers it by tracing the matcher:
/// `Arguments._match_signature` carries `@jit.unroll_safe` and
/// `Arguments.unpack` carries `@jit.look_inside_iff`.
pub fn __majit_wrap_exc_value_error_descr_new(
    args: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    if args.len() == 2 && !args[0].is_null() && !builtin_kwargs_marker_tail(args[1]) {
        return Ok(value_error_one_arg(args[0], args[1]));
    }
    // The four-word residual cannot see a longer tail, and a bare exception
    // takes any number of positional arguments. Hand the real slice over
    // rather than shortening it.
    if args.len() > 4 {
        return exc_value_error_new_long(args);
    }
    // Spelled out for the reason [`__majit_wrap_base_exception_descr_init`]
    // gives: a closure reading the slice is a graph of its own.
    exc_value_error_new_slow(
        args.first().copied().unwrap_or(pyre_object::PY_NULL),
        args.get(1).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(2).copied().unwrap_or(pyre_object::PY_NULL),
        args.get(3).copied().unwrap_or(pyre_object::PY_NULL),
        args.len() as i64,
    )
}

#[majit_macros::dont_look_inside]
fn exc_value_error_new_slow(
    a0: PyObjectRef,
    a1: PyObjectRef,
    a2: PyObjectRef,
    a3: PyObjectRef,
    n: i64,
) -> Result<PyObjectRef, crate::PyError> {
    let buf = [a0, a1, a2, a3];
    // The wrapper forwards a longer flat slice to `exc_value_error_new`
    // before this residual. A count that does not match the words cannot be
    // reconstructed, so do not pretend the call was shorter.
    if !(0..=buf.len() as i64).contains(&n) {
        return Err(crate::PyError::type_error(
            "exception constructor argument count exceeds the values received",
        ));
    }
    exc_value_error_new(&buf[..n as usize])
}

/// The constructor takes any number of positional arguments, so an arity the
/// word ABI cannot carry still has to reach it whole.  Residual for the same
/// reason as [`exc_value_error_new_slow`]: a traced wrapper that passes the
/// slice on itself stops annotating, and it drags `exc_value_error_new` into
/// the prepass with it.
#[majit_macros::dont_look_inside]
fn exc_value_error_new_long(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    exc_value_error_new(args)
}

#[majit_macros::dont_look_inside_cannot_raise]
fn value_error_one_arg(cls: PyObjectRef, arg: PyObjectRef) -> PyObjectRef {
    let _roots = pyre_object::gc_roots::push_roots();
    let arg_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(arg);
    let cls_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(cls);
    let exc = unsafe {
        pyre_object::interp_exceptions::w_exception_new_empty_for_class(
            pyre_object::interp_exceptions::ExcKind::ValueError,
            pyre_object::gc_roots::shadow_stack_get(cls_slot),
        )
    };
    // `w_exception_args_new` allocates the args list, so the fresh exception
    // has to be rooted and re-read rather than carried in a raw local.
    // `allocate_instance` already stamped `w_class` and, for a user layout,
    // enqueued the finalizer.
    let exc_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(exc);
    let args_list = pyre_object::interp_exceptions::w_exception_args_new(vec![
        pyre_object::gc_roots::shadow_stack_get(arg_slot),
    ]);
    unsafe {
        pyre_object::interp_exceptions::w_exception_set_args(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            args_list,
        );
    }
    pyre_object::gc_roots::shadow_stack_get(exc_slot)
}

crate::builtin_wrapper_descriptor!(
    __majit_wrap_exc_value_error_descr_new_target,
    __majit_wrap_exc_value_error_descr_new
);

fn exc_base_exception_init(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let w_self = *args.first().ok_or_else(|| {
        crate::PyError::type_error("__init__() missing 1 required positional argument: 'self'")
    })?;
    // `descr_init(self, space, args_w)` has `args_w` bound as the positional
    // list, so a keyword never reaches the body and the caller gets a
    // TypeError.  The flat builtin ABI carries keywords in a trailing
    // `__pyre_kw__` marker instead, so reject them here: every arity path
    // reaches this initializer, the single point `descr_init` is upstream.
    let (positional, kwargs) = split_builtin_kwargs(&args[1..]);
    if has_real_kwargs(kwargs) {
        return Err(exc_no_keywords_error(w_self, "BaseException"));
    }
    // `interp_exceptions.py descr_init` and `descr_new_base_exception` both
    // store the `args_w` list they were handed, so `type.__call__` reaches
    // here holding a list that already contains exactly these objects.  Keep
    // it rather than build a second one over the same elements: `args` is read
    // out as a fresh tuple and the storage is never handed out, so its
    // identity is not observable.
    if !exception_args_already(w_self, positional) {
        let _roots = pyre_object::gc_roots::push_roots();
        let self_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_self);
        let args_base = pyre_object::gc_roots::shadow_stack_len();
        for &arg in positional {
            let _ = pyre_object::gc_roots::pin_root(arg);
        }
        let mut rooted_args = Vec::with_capacity(positional.len());
        for i in 0..positional.len() {
            rooted_args.push(pyre_object::gc_roots::shadow_stack_get(args_base + i));
        }
        let args_list = pyre_object::interp_exceptions::w_exception_args_new(rooted_args);
        unsafe {
            pyre_object::interp_exceptions::w_exception_set_args(
                pyre_object::gc_roots::shadow_stack_get(self_slot),
                args_list,
            )
        };
    }
    Ok(pyre_object::w_none())
}

/// `interp_exceptions.py W_StopIteration.descr_init` — initialize
/// `w_value` to the first positional argument (or None) independently of the
/// `args_w` list, then run `W_Exception.descr_init`.
fn exc_stop_iteration_init(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let w_self = *args.first().ok_or_else(|| {
        crate::PyError::type_error("__init__() missing 1 required positional argument: 'self'")
    })?;
    let (positional, kwargs) = split_builtin_kwargs(&args[1..]);
    if has_real_kwargs(kwargs) {
        return Err(exc_no_keywords_error(w_self, "StopIteration"));
    }
    let w_value = positional
        .first()
        .copied()
        .unwrap_or_else(pyre_object::w_none);
    // The reference stores `w_value` before delegating, and the order matters
    // here beyond parity: `descr_init` allocates the replacement `args` list,
    // so a moving collection between the two would leave this raw local — and
    // `w_self` — pointing at vacated memory.
    unsafe { pyre_object::interp_exceptions::w_exception_set_value(w_self, w_value) };
    let mut flat = Vec::with_capacity(positional.len() + 1);
    flat.push(w_self);
    flat.extend_from_slice(positional);
    exc_base_exception_init(&flat)
}

/// `_PyArg_NoKeywords(type_name, kwds)` message for an exception initializer
/// that a subclass inherits: the reported name is the receiver's own type, not
/// the class the initializer was installed on.
fn exc_no_keywords_error(w_self: PyObjectRef, fallback: &str) -> crate::PyError {
    let type_name = unsafe {
        match crate::typedef::r#type(w_self) {
            Some(tp) => pyre_object::w_type_get_name(tp.as_ptr()).to_string(),
            None => fallback.to_string(),
        }
    };
    crate::PyError::type_error(format!("{type_name}() takes no keyword arguments"))
}

/// `SyntaxError_init` stores `args` through `BaseException_init` before it
/// parses the details tuple, then writes `msg` and the location fields.
/// Four, six, or seven fields are accepted. Five fields are stored too —
/// an omitted `end_offset` or `_metadata` becomes None — and only then
/// raises `end_offset must be provided when end_lineno is provided`.
/// Fewer than four or more than seven fields fail after `args` and `msg`
/// have already been replaced; the location slots stay as they were.
/// `W_SyntaxError.descr_init` raises before `W_BaseException.descr_init`,
/// and on five fields it leaves the previous end positions in place.
/// That function has no `@jit` hint. SyntaxError subclasses inherit this
/// initializer.
fn exc_syntax_error_init(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let w_self = *args.first().ok_or_else(|| {
        crate::PyError::type_error("__init__() missing 1 required positional argument: 'self'")
    })?;
    let (positional, kwargs) = split_builtin_kwargs(&args[1..]);
    if has_real_kwargs(kwargs) {
        return Err(exc_no_keywords_error(w_self, "SyntaxError"));
    }
    // `fixedview` runs the details object's own iteration protocol and can
    // reach a collection safepoint, but the positional arguments live in a
    // native slice the gateway copied off the shadow stack, which a collection
    // does not rewrite.  Publish the receiver and the arguments first, then
    // read each one back from its slot.
    let _roots = pyre_object::gc_roots::push_roots();
    let mut flat = Vec::with_capacity(positional.len() + 1);
    flat.push(w_self);
    flat.extend_from_slice(positional);
    let base = pyre_object::gc_roots::pin_roots(&flat);
    // `SyntaxError_init` calls `BaseException_init` before `PyArg_ParseTuple`.
    // `W_SyntaxError.descr_init` validates first and only then calls
    // `W_BaseException.descr_init`, so a rejected details tuple leaves
    // `args_w` alone there. The rejected call still exposes the new `args`.
    // `fixedview` can move the receiver, so the arguments are the shadow
    // stack slots rather than the slice from entry.
    let mut call = Vec::with_capacity(positional.len() + 1);
    call.push(pyre_object::gc_roots::shadow_stack_get(base));
    for index in 0..positional.len() {
        call.push(pyre_object::gc_roots::shadow_stack_get(base + 1 + index));
    }
    exc_base_exception_init(&call)?;
    if !positional.is_empty() {
        unsafe {
            pyre_object::interp_exceptions::w_exception_set_syntax_msg(
                pyre_object::gc_roots::shadow_stack_get(base),
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            );
        }
    }
    if positional.len() == 2 {
        let details =
            crate::baseobjspace::fixedview(pyre_object::gc_roots::shadow_stack_get(base + 2), -1)?;
        let n = details.len();
        match n {
            // `descr_init` stops at six. `"OOOO|OOO"` accepts seven: the last
            // optional is `_metadata`, which `traceback.py` reads back as
            // `(line, offset, source)`. Five fields parse as well. The
            // `end_offset` check runs after the stores.
            4 | 5 | 6 | 7 => {
                let w_self = pyre_object::gc_roots::shadow_stack_get(base);
                unsafe {
                    pyre_object::interp_exceptions::w_exception_set_syntax_filename(
                        w_self, details[0],
                    );
                    pyre_object::interp_exceptions::w_exception_set_syntax_lineno(
                        w_self, details[1],
                    );
                    pyre_object::interp_exceptions::w_exception_set_syntax_offset(
                        w_self, details[2],
                    );
                    pyre_object::interp_exceptions::w_exception_set_syntax_text(w_self, details[3]);
                    // `Py_XSETREF` of an omitted `|OOO` slot clears it. A
                    // repeated `__init__` with a shorter details form clears
                    // both end positions and `_metadata`. A call that supplies
                    // no details form at all does not reach here and keeps
                    // all three.
                    let optional = |index: usize| {
                        details
                            .get(index)
                            .copied()
                            .unwrap_or_else(pyre_object::w_none)
                    };
                    pyre_object::interp_exceptions::w_exception_set_syntax_end_lineno(
                        w_self,
                        optional(4),
                    );
                    pyre_object::interp_exceptions::w_exception_set_syntax_end_offset(
                        w_self,
                        optional(5),
                    );
                    pyre_object::interp_exceptions::w_exception_set_syntax_metadata(
                        w_self,
                        optional(6),
                    );
                }
                if n == 5 {
                    return Err(crate::PyError::type_error(
                        "end_offset must be provided when end_lineno is provided",
                    ));
                }
            }
            n if n < 4 => {
                return Err(crate::PyError::type_error(format!(
                    "function takes at least 4 arguments ({n} given)"
                )));
            }
            n => {
                return Err(crate::PyError::type_error(format!(
                    "function takes at most 7 arguments ({n} given)"
                )));
            }
        }
    }
    // `W_SyntaxError.descr_init` ends by calling `_report_missing_parentheses`,
    // which reads `w_text` back and rewrites `w_msg` into a "Did you mean
    // print(...)?" suggestion.  That belongs to a parser which cannot produce
    // the diagnostic itself; this tree's grammar does, so the rewrite is
    // deliberately absent.  Measured against the pinned 3.14.6:
    // `SyntaxError("Missing parentheses in call to 'print' ", (f, 1, 1,
    // "print 1")).msg` comes back unchanged, and the suggestion the compiler
    // itself emits reads `print(...)`, not the reconstructed `print(1)`.
    // Rewriting here would miss on both counts.
    Ok(pyre_object::w_none())
}

/// Whether `w_self`'s `args_w` storage already holds exactly `positional`,
/// element for element by identity.
fn exception_args_already(w_self: PyObjectRef, positional: &[PyObjectRef]) -> bool {
    unsafe {
        let stored = pyre_object::interp_exceptions::w_exception_get_args_storage(w_self);
        if stored.is_null() {
            return positional.is_empty();
        }
        if pyre_object::interp_exceptions::rlist_len(stored) != positional.len() {
            return false;
        }
        positional.iter().enumerate().all(|(i, &item)| {
            std::ptr::eq(
                pyre_object::interp_exceptions::rlist_getitem(stored, i),
                item,
            )
        })
    }
}

/// `interp_exceptions.py W_OSError._parse_init_args` + `_init_error`.
/// A 2..=5 positional-argument call fills the `errno` / `strerror` /
/// `filename` / `filename2` slots; when a filename is present it is
/// dropped from `args_w` (`self.args_w = [w_errno, w_strerror]`, line
/// 652) for pickle / repr compatibility.  `kind` is `OSError` for the base type and
/// `FileNotFoundError` for that dedicated kind. `cls` selects the layout
/// kind; `stamp` is the class `allocate_instance` compares with the realbase
/// (`W_OSError.descr_new` may already have retargeted it through `ERRNO_MAP`).
fn os_error_build(
    kind: pyre_object::interp_exceptions::ExcKind,
    cls: Option<PyObjectRef>,
    stamp: Option<PyObjectRef>,
    args: &[PyObjectRef],
) -> PyObjectRef {
    use pyre_object::interp_exceptions;
    // Published before the first `__repr__` runs.  `args` is the stack copy
    // the gateway built, and a minor rewrites the shadow slots rather than
    // that copy, so an element formatted early is a pre-move address by the
    // time the run below is stored — every element of it, since the store
    // reads the whole slice after the last dispatch.
    let _roots = pyre_object::gc_roots::push_roots();
    let args_base = pyre_object::gc_roots::pin_roots(args);
    let cls_slot = cls.map(|cls| {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(cls);
        slot
    });
    let stamp_slot = stamp.map(|stamp| {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(stamp);
        slot
    });
    let kind = match cls_slot {
        Some(slot) => interp_exceptions::exception_layout_kind_for_class(
            kind,
            pyre_object::gc_roots::shadow_stack_get(slot),
        ),
        None => kind,
    };
    // `py_str_wtf8` / `py_repr_wtf8` collect.  `stamp` is already in a slot;
    // a copy held across those calls is a short bracket.
    let stamp_now = || match stamp_slot.or(cls_slot) {
        Some(slot) => pyre_object::gc_roots::shadow_stack_get(slot),
        None => pyre_object::PY_NULL,
    };
    let arg = |index: usize| pyre_object::gc_roots::shadow_stack_get(args_base + index);
    let exc = if args.len() == 1 && unsafe { pyre_object::is_str(arg(0)) } {
        let w = unsafe { pyre_object::w_str_get_wtf8(arg(0)) };
        interp_exceptions::w_exception_new_wtf8_for_class(kind, w, stamp_now())
    } else {
        let msg: rustpython_wtf8::Wtf8Buf = if args.is_empty() {
            rustpython_wtf8::Wtf8Buf::new()
        } else if args.len() == 1 {
            // exception construction is non-raising machinery, per the F7
            // display policy; a raising __str__/__repr__ on the args degrades
            // to the empty string rather than propagating.
            unsafe { crate::display::py_str_wtf8(arg(0)) }.unwrap_or_default()
        } else {
            let mut parts = rustpython_wtf8::Wtf8Buf::from_string("(".to_string());
            for index in 0..args.len() {
                if index > 0 {
                    parts.push_str(", ");
                }
                parts.push_wtf8(
                    &unsafe { crate::display::py_repr_wtf8(arg(index)) }.unwrap_or_default(),
                );
            }
            parts.push_str(")");
            parts
        };
        interp_exceptions::w_exception_new_wtf8_for_class(kind, &msg, stamp_now())
    };
    // Seed `args_w` so a deferred-init instance (`_use_init`, no `__new__`
    // slot fill) still reports the empty tuple until `__init__` runs.
    // The instance is a nursery object (`alloc_exception_nursery`), and
    // `w_exception_args_new` collects, so the pin is re-read before the
    // store and before the return.
    let exc_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(exc);
    let args_list =
        pyre_object::interp_exceptions::w_exception_args_new((0..args.len()).map(arg).collect());
    let exc = pyre_object::gc_roots::shadow_stack_get(exc_slot);
    unsafe { interp_exceptions::w_exception_set_args(exc, args_list) };
    pyre_object::gc_roots::shadow_stack_get(exc_slot)
}

/// `Py_IS_TYPE(self, BlockingIOError)` — the exact-type test `_init_error`
/// uses to read a numeric third argument as `characters_written` rather than
/// a filename.
fn exc_is_blocking_io_error(exc: PyObjectRef) -> bool {
    matches!(
        (crate::typedef::r#type(exc), lookup_exc_class("BlockingIOError")),
        (Some(c), Some(b)) if std::ptr::eq(c.as_ptr(), b)
    )
}

