struct ExcGetsetRow {
    name: &'static str,
    fget: std::sync::atomic::AtomicUsize,
    fset: std::sync::atomic::AtomicUsize,
    fdel: std::sync::atomic::AtomicUsize,
}

type ExcGetsetSpec = (
    &'static str,
    crate::gateway::BuiltinCodeFn,
    crate::gateway::BuiltinCodeFn,
    crate::gateway::BuiltinCodeFn,
);

const EXC_GETSET_SPECS: [ExcGetsetSpec; 8] = [
    (
        "__dict__",
        exc_gs_get_dict,
        exc_gs_set_dict,
        exc_gs_del_dict,
    ),
    ("args", exc_gs_get_args, exc_gs_set_args, exc_gs_del_args),
    (
        "__cause__",
        exc_gs_get_cause,
        exc_gs_set_cause,
        exc_gs_del_cause,
    ),
    (
        "__context__",
        exc_gs_get_context,
        exc_gs_set_context,
        exc_gs_del_context,
    ),
    (
        "__traceback__",
        exc_gs_get_traceback,
        exc_gs_set_traceback,
        exc_gs_del_traceback,
    ),
    (
        "characters_written",
        exc_gs_get_written,
        exc_gs_set_written,
        exc_gs_del_written,
    ),
    (
        "message",
        exc_gs_get_message,
        exc_gs_set_message,
        exc_gs_del_message,
    ),
    (
        "exceptions",
        exc_gs_get_exceptions,
        exc_gs_set_exceptions,
        exc_gs_del_exceptions,
    ),
];

static EXC_GETSET_ROWS: std::sync::OnceLock<Vec<ExcGetsetRow>> = std::sync::OnceLock::new();

/// One builtin function object per accessor.  `exception_attr_slot_fold`
/// recognises a canonical descriptor by membership of its `fget` in this
/// table (`interp_exceptions.py` `GetSetProperty` / `readwrite_attrproperty_w`).
///
/// Each accessor is pinned while the rest are built, and the published table
/// is a root ([`walk_exception_getset_roots`]): an accessor whose class has
/// not installed it yet is reachable from nothing else.
fn exception_getset_rows() -> &'static [ExcGetsetRow] {
    EXC_GETSET_ROWS.get_or_init(|| {
        let _roots = pyre_object::gc_roots::push_roots();
        let first_slot = pyre_object::gc_roots::shadow_stack_len();
        for (_, get, set, del) in EXC_GETSET_SPECS {
            let _ = pyre_object::gc_roots::pin_root(make_builtin_function_with_arity(
                "__get__", get, 2,
            ));
            let _ = pyre_object::gc_roots::pin_root(make_builtin_function_with_arity(
                "__set__", set, 3,
            ));
            let _ = pyre_object::gc_roots::pin_root(make_builtin_function_with_arity(
                "__delete__",
                del,
                2,
            ));
        }
        let slot = |i: usize| {
            std::sync::atomic::AtomicUsize::new(pyre_object::gc_roots::shadow_stack_get(
                first_slot + i,
            ) as usize)
        };
        EXC_GETSET_SPECS
            .iter()
            .enumerate()
            .map(|(i, &(name, ..))| ExcGetsetRow {
                name,
                fget: slot(3 * i),
                fset: slot(3 * i + 1),
                fdel: slot(3 * i + 2),
            })
            .collect()
    })
}

/// Forward the exception accessor table's function slots.
pub(crate) fn walk_exception_getset_roots(visitor: &mut dyn FnMut(&mut PyObjectRef)) {
    let Some(rows) = EXC_GETSET_ROWS.get() else {
        return;
    };
    for row in rows {
        for cell in [&row.fget, &row.fset, &row.fdel] {
            unsafe { visitor(&mut *(cell.as_ptr() as *mut PyObjectRef)) };
        }
    }
}

fn exception_getset_for(attr: &str) -> (PyObjectRef, PyObjectRef, PyObjectRef) {
    let row = exception_getset_rows()
        .iter()
        .find(|row| row.name == attr)
        .unwrap_or_else(|| panic!("exception getset {attr}"));
    let load = |cell: &std::sync::atomic::AtomicUsize| {
        cell.load(std::sync::atomic::Ordering::Relaxed) as PyObjectRef
    };
    (load(&row.fget), load(&row.fset), load(&row.fdel))
}

/// True when `fget` is one of the canonical exception-typedef getters.
pub(crate) fn is_exception_canonical_fget(fget: PyObjectRef) -> bool {
    exception_getset_rows()
        .iter()
        .any(|row| row.fget.load(std::sync::atomic::Ordering::Relaxed) == fget as usize)
}

/// Store `value` under `key` in the type namespace dict rooted at shadow-stack
/// slot `ns_slot`.
///
/// A `dict` header moves, and the store allocates on its own account: the key
/// string it interns, and the dict's storage when it grows.  The namespace word
/// is therefore read back out of the slot instead of being carried in a Rust
/// local across the descriptors a namespace is filled with.  Taking the value
/// already built is what makes that read safe — call arguments evaluate left to
/// right, so spelling it inline with an allocating value expression would hand
/// the store a pre-move address.  The value is pinned for the length of the
/// store because nothing references it yet.
fn type_ns_store(ns_slot: usize, key: &str, value: PyObjectRef) {
    let _roots = pyre_object::gc_roots::push_roots();
    let value_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(value);
    // `pop_roots` reloads the value before setitem; the pin's return is not
    // that writeback once setitem allocates.
    unsafe {
        pyre_object::w_dict_setitem_str_no_proxy(
            pyre_object::gc_roots::shadow_stack_get(ns_slot),
            key,
            pyre_object::gc_roots::shadow_stack_get(value_slot),
        )
    };
}

/// Install the class's `interp_exceptions.py` typedef getsets into `ns`.
fn install_exception_getsets(ns: PyObjectRef, class_name: &str) {
    let _roots = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ns);
    for attr in exception_typedef_attrs(class_name) {
        let (fget, fset, fdel) = exception_getset_for(attr);
        type_ns_store(
            ns_slot,
            attr,
            crate::typedef::make_getset_property_named(fget, fset, fdel, attr),
        );
    }
}

/// Build a builtin exception type with the given name, base, and __new__ wrapper.
pub fn make_exc_type(
    name: &'static str,
    new_fn: crate::gateway::BuiltinCodeFn,
    base: PyObjectRef,
) -> PyObjectRef {
    make_exc_type_with_init(name, None, new_fn, None, base)
}

/// `new_exception_class` — a module's own exception class, as
/// `PyErr_NewException` builds one.
///
/// Both spellings construct the class by calling `type(name, (base,), {})`:
/// PyPy through `space.call_function(space.w_type, ...)`, `PyErr_NewException`
/// through `PyObject_CallFunction((PyObject *)&PyType_Type, ...)`.  What that
/// gives a class and a statically defined exception does not is a weakref
/// slot, which is why `weakref.ref(_queue.Empty())` works where
/// `weakref.ref(Exception())` is a `TypeError`.  Every exception here already
/// carries the storage; this is the flag that makes it reachable.
///
/// Three module exception classes are built another way upstream and carry no
/// slot: `ssl.SSLError`, `_csv.Error` and `_ctypes.COMError` come from a type
/// spec that names its own `basicsize`, and a spec that does adds no managed
/// weakref.  Those three keep [`make_exc_type`] / [`make_exc_type_with_init`].
pub fn new_exception_class(
    name: &'static str,
    new_fn: crate::gateway::BuiltinCodeFn,
    mut base: PyObjectRef,
) -> PyObjectRef {
    let cls = pyre_object::with_roots!(base => make_exc_type(name, new_fn, base));
    add_weakref_slot(cls, base);
    cls
}

/// The weakref half of `type_new_descriptors`: the class gets its own
/// `__weakref__` descriptor only when the base it takes its layout from has no
/// slot to inherit, which is why `_pickle.PickleError.__dict__` carries one and
/// `_pickle.PicklingError.__dict__` does not.  The flag is set either way --
/// it is what `getweakref` / `setweakref` read.
fn add_weakref_slot(cls: PyObjectRef, base: PyObjectRef) {
    if !unsafe { pyre_object::w_type_get_weakrefable(base) } {
        let _roots = pyre_object::gc_roots::push_roots();
        let save = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(cls);
        let cls = pyre_object::gc_roots::shadow_stack_get(save);
        let descr = crate::typedef::copy_descriptor_for_type(crate::typedef::weakref_descr(), cls);
        let _ = pyre_object::gc_roots::pin_root(descr);
        let cls = pyre_object::gc_roots::shadow_stack_get(save);
        let descr = pyre_object::gc_roots::shadow_stack_get(save + 1);
        crate::type_dict_store(cls, "__weakref__", descr);
    }
    unsafe { pyre_object::w_type_set_weakrefable(cls, true) };
}

/// PyPy's `_new_exception` stores the supplied docstring directly in each
/// builtin exception's TypeDef namespace.
fn make_exc_type_with_doc(
    name: &'static str,
    doc: &'static str,
    new_fn: crate::gateway::BuiltinCodeFn,
    base: PyObjectRef,
) -> PyObjectRef {
    make_exc_type_with_init(name, Some(doc), new_fn, None, base)
}

/// The interpreter class that owns an exception TypeDef's instance layout.
///
/// `interp_exceptions.py` uses `_new_exception` for fieldless classes; those
/// keep their base interpreter class and therefore reuse its Layout.  The
/// concrete `class W_*` definitions below introduce fields and each owns a
/// child Layout: `W_BaseException`, `W_ImportError`,
/// `W_UnicodeTranslateError`, `W_StopIteration`, `W_OSError`, `W_NameError`,
/// `W_SyntaxError`, `W_SystemExit`, `W_UnicodeDecodeError`,
/// `W_AttributeError`, `W_UnicodeEncodeError`, and
/// `interp_group.W_BaseExceptionGroup`.
fn exception_layout_pytype(name: &str, base: PyObjectRef) -> *const pyre_object::PyType {
    use pyre_object::interp_exceptions as exc;
    match name {
        "BaseException" => &exc::EXCEPTION_TYPE,
        "ImportError" => &exc::EXC_IMPORT_ERROR_TYPE,
        "UnicodeTranslateError" => &exc::EXC_UNICODE_TRANSLATE_ERROR_TYPE,
        "StopIteration" => &exc::EXC_STOP_ITERATION_TYPE,
        "OSError" => &exc::EXC_OS_ERROR_TYPE,
        "NameError" => &exc::EXC_NAME_ERROR_TYPE,
        "SyntaxError" => &exc::EXC_SYNTAX_ERROR_TYPE,
        "SystemExit" => &exc::EXC_SYSTEM_EXIT_TYPE,
        "UnicodeDecodeError" => &exc::EXC_UNICODE_DECODE_ERROR_TYPE,
        "AttributeError" => &exc::EXC_ATTRIBUTE_ERROR_TYPE,
        "UnicodeEncodeError" => &exc::EXC_UNICODE_ENCODE_ERROR_TYPE,
        "BaseExceptionGroup" => &exc::EXC_BASE_EXCEPTION_GROUP_LAYOUT_TYPE,
        _ => unsafe {
            let parent = pyre_object::w_type_get_layout_ptr(base);
            if parent.is_null() {
                &exc::EXCEPTION_TYPE
            } else {
                (*(*parent).typedef).instance_type
            }
        },
    }
}

/// PyPy `TypeCache.build`: `_new_exception` assigns
/// `typedef.applevel_subclasses_base`, and the cache passes that real base's
/// TypeDef as `overridetypedef`.  Concrete `W_*` exception classes instead
/// retain their own TypeDef even when the Python-level base is related.
fn exception_overridetypedef(
    layout_pytype: *const pyre_object::PyType,
    base: PyObjectRef,
) -> *const pyre_object::typedef::TypeDef {
    unsafe {
        let parent = pyre_object::w_type_get_layout_ptr(base);
        if parent.is_null() || !std::ptr::eq((*(*parent).typedef).instance_type, layout_pytype) {
            std::ptr::null()
        } else {
            (*parent).typedef
        }
    }
}

/// Variant of `make_exc_type` that also installs a per-class `__init__`
/// descriptor.  Used for the three Unicode*Error subclasses whose PyPy
/// `descr_init` does typed slot stamping after `__new__`'s raw
/// `args_w` capture (`interp_exceptions.py`, `:1041-1059`,
/// `:1159-1173`).  Without this split, every direct
/// `UnicodeDecodeError.__new__(cls, *args)` call would inherit the
/// typechecking that PyPy keeps confined to `descr_init` — see
/// `_new` at `:274-284` (no per-arg validation).
pub fn make_exc_type_with_init(
    name: &'static str,
    doc: Option<&'static str>,
    new_fn: crate::gateway::BuiltinCodeFn,
    init_fn: Option<crate::gateway::BuiltinCodeFn>,
    base: PyObjectRef,
) -> PyObjectRef {
    if let Some(cls) = lookup_exc_class(name) {
        return cls;
    }
    // `setup_builtin_type` reuses the parent's Layout for `_new_exception`
    // aliases and creates a child for each concrete `W_*` interpreter class.
    // That graph is what makes e.g. `(ValueError, OSError)` compatible while
    // rejecting the sibling layouts `(UnicodeTranslateError,
    // UnicodeEncodeError)`.
    let layout_pytype = exception_layout_pytype(name, base);
    let overridetypedef = exception_overridetypedef(layout_pytype, base);
    let cls = crate::typedef::make_builtin_type_with_layout_owner(
        name,
        move |ns| {
            // The producer's own root slot tracks its copy of the namespace,
            // not this by-value parameter, so the word is pinned again here for
            // the run of allocating insertions below.
            let _roots = pyre_object::gc_roots::push_roots();
            let ns_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(ns);
            if let Some(doc) = doc {
                type_ns_store(ns_slot, "__doc__", pyre_object::w_str_new(doc));
            }
            // `descr_new_base_exception(space, w_subtype, __args__)` takes
            // `__args__` unbound.  No Signature: keywords stay on the flat
            // slice as the trailing `__pyre_kw__` marker, and the body
            // ignores them (`# ignore kwds`).  `descr_init(self, space,
            // args_w)` is the side that rejects keywords, and only
            // BaseException's `__init__` carries that Signature.
            let new_sig = None;
            type_ns_store(
                ns_slot,
                "__new__",
                crate::typedef::make_new_descr_maybe_sig(new_fn, new_sig),
            );
            if let Some(init_fn) = init_fn {
                // `descr_init(self, space, args_w)` binds `args_w` as the
                // positional list.  No Signature: a `*args` one would pack
                // those positionals into a fresh tuple on every exception
                // construction, where `descr_init` only stores the list it was
                // handed (`space.newtuple(self.args_w)` runs in
                // `descr_getargs`, when `args` is read).  Keywords stay on the
                // flat slice as the trailing marker and
                // `exc_base_exception_init` rejects them.
                let init_sig = None;
                type_ns_store(
                    ns_slot,
                    "__init__",
                    crate::gateway::make_builtin_function_maybe_sig("__init__", init_fn, init_sig),
                );
            }
            // `interp_exceptions.py` declares each class's typed attributes
            // as `GetSetProperty` entries on its own `TypeDef`.
            install_exception_getsets(pyre_object::gc_roots::shadow_stack_get(ns_slot), name);
            if name == "SyntaxError" {
                for (member_name, kind, doc) in [
                    ("msg", pyre_object::MEMBER_SYNTAX_ERROR_MSG, "exception msg"),
                    (
                        "filename",
                        pyre_object::MEMBER_SYNTAX_ERROR_FILENAME,
                        "exception filename",
                    ),
                    (
                        "lineno",
                        pyre_object::MEMBER_SYNTAX_ERROR_LINENO,
                        "exception lineno",
                    ),
                    (
                        "offset",
                        pyre_object::MEMBER_SYNTAX_ERROR_OFFSET,
                        "exception offset",
                    ),
                    (
                        "text",
                        pyre_object::MEMBER_SYNTAX_ERROR_TEXT,
                        "exception text",
                    ),
                    (
                        "end_lineno",
                        pyre_object::MEMBER_SYNTAX_ERROR_END_LINENO,
                        "exception end lineno",
                    ),
                    (
                        "end_offset",
                        pyre_object::MEMBER_SYNTAX_ERROR_END_OFFSET,
                        "exception end offset",
                    ),
                    (
                        "print_file_and_line",
                        pyre_object::MEMBER_SYNTAX_ERROR_PRINT_FILE_AND_LINE,
                        "exception print_file_and_line",
                    ),
                    (
                        "_metadata",
                        pyre_object::MEMBER_SYNTAX_ERROR_METADATA,
                        "exception private metadata",
                    ),
                ] {
                    type_ns_store(
                        ns_slot,
                        member_name,
                        pyre_object::w_member_new_direct_with_doc(
                            kind,
                            member_name.to_owned(),
                            doc.to_owned(),
                            pyre_object::PY_NULL,
                        ),
                    );
                }
            }
            if name == "StopIteration" {
                type_ns_store(
                    ns_slot,
                    "value",
                    pyre_object::w_member_new_direct_with_doc(
                        pyre_object::MEMBER_STOP_ITERATION_VALUE,
                        "value".to_owned(),
                        "generator return value".to_owned(),
                        pyre_object::PY_NULL,
                    ),
                );
            }
            if name == "BaseException" {
                type_ns_store(
                    ns_slot,
                    "__suppress_context__",
                    pyre_object::w_member_new_direct(
                        pyre_object::MEMBER_EXCEPTION_SUPPRESS_CONTEXT,
                        "__suppress_context__".to_owned(),
                        pyre_object::PY_NULL,
                    ),
                );
            }
            if name == "AttributeError" {
                for (member_name, kind, doc) in [
                    (
                        "name",
                        pyre_object::MEMBER_ATTRIBUTE_ERROR_NAME,
                        "attribute name",
                    ),
                    ("obj", pyre_object::MEMBER_ATTRIBUTE_ERROR_OBJ, "object"),
                ] {
                    type_ns_store(
                        ns_slot,
                        member_name,
                        pyre_object::w_member_new_direct_with_doc(
                            kind,
                            member_name.to_owned(),
                            doc.to_owned(),
                            pyre_object::PY_NULL,
                        ),
                    );
                }
            }
            if name == "NameError" {
                type_ns_store(
                    ns_slot,
                    "name",
                    pyre_object::w_member_new_direct_with_doc(
                        pyre_object::MEMBER_NAME_ERROR_NAME,
                        "name".to_owned(),
                        "name".to_owned(),
                        pyre_object::PY_NULL,
                    ),
                );
            }
            if name == "ImportError" {
                for (member_name, kind, doc) in [
                    (
                        "msg",
                        pyre_object::MEMBER_IMPORT_ERROR_MSG,
                        "exception message",
                    ),
                    ("name", pyre_object::MEMBER_IMPORT_ERROR_NAME, "module name"),
                    (
                        "name_from",
                        pyre_object::MEMBER_IMPORT_ERROR_NAME_FROM,
                        "name imported from module",
                    ),
                    ("path", pyre_object::MEMBER_IMPORT_ERROR_PATH, "module path"),
                ] {
                    type_ns_store(
                        ns_slot,
                        member_name,
                        pyre_object::w_member_new_direct_with_doc(
                            kind,
                            member_name.to_owned(),
                            doc.to_owned(),
                            pyre_object::PY_NULL,
                        ),
                    );
                }
            }
            if name == "OSError" {
                const OS_ERROR_MEMBERS: &[(&str, u32, &str)] = &[
                    (
                        "errno",
                        pyre_object::MEMBER_OS_ERROR_ERRNO,
                        "POSIX exception code",
                    ),
                    (
                        "strerror",
                        pyre_object::MEMBER_OS_ERROR_STRERROR,
                        "exception strerror",
                    ),
                    (
                        "filename",
                        pyre_object::MEMBER_OS_ERROR_FILENAME,
                        "exception filename",
                    ),
                    (
                        "filename2",
                        pyre_object::MEMBER_OS_ERROR_FILENAME2,
                        "second exception filename",
                    ),
                ];
                // `interp_exceptions.py:723-728` installs this one only where
                // the platform has a Windows error code to hold.
                #[cfg(windows)]
                const WINERROR_MEMBER: &[(&str, u32, &str)] = &[(
                    "winerror",
                    pyre_object::MEMBER_OS_ERROR_WINERROR,
                    "Win32 exception code",
                )];
                #[cfg(not(windows))]
                const WINERROR_MEMBER: &[(&str, u32, &str)] = &[];
                for &(member_name, kind, doc) in OS_ERROR_MEMBERS.iter().chain(WINERROR_MEMBER) {
                    type_ns_store(
                        ns_slot,
                        member_name,
                        pyre_object::w_member_new_direct_with_doc(
                            kind,
                            member_name.to_owned(),
                            doc.to_owned(),
                            pyre_object::PY_NULL,
                        ),
                    );
                }
            }
            if name == "SystemExit" {
                type_ns_store(
                    ns_slot,
                    "code",
                    pyre_object::w_member_new_direct_with_doc(
                        pyre_object::MEMBER_SYSTEM_EXIT_CODE,
                        "code".to_owned(),
                        "exception code".to_owned(),
                        pyre_object::PY_NULL,
                    ),
                );
            }
            if matches!(
                name,
                "UnicodeDecodeError" | "UnicodeEncodeError" | "UnicodeTranslateError"
            ) {
                for (member_name, kind, doc) in [
                    (
                        "encoding",
                        pyre_object::MEMBER_UNICODE_ERROR_ENCODING,
                        "exception encoding",
                    ),
                    (
                        "object",
                        pyre_object::MEMBER_UNICODE_ERROR_OBJECT,
                        "exception object",
                    ),
                    (
                        "start",
                        pyre_object::MEMBER_UNICODE_ERROR_START,
                        "exception start",
                    ),
                    (
                        "end",
                        pyre_object::MEMBER_UNICODE_ERROR_END,
                        "exception end",
                    ),
                    (
                        "reason",
                        pyre_object::MEMBER_UNICODE_ERROR_REASON,
                        "exception reason",
                    ),
                ] {
                    type_ns_store(
                        ns_slot,
                        member_name,
                        pyre_object::w_member_new_direct_with_doc(
                            kind,
                            member_name.to_owned(),
                            doc.to_owned(),
                            pyre_object::PY_NULL,
                        ),
                    );
                }
            }
            // `interp_exceptions.py:291-292` registers `__str__` /
            // `__repr__` on `BaseException`'s typedef, and each of the
            // classes below registers a `descr_str` of its own on top.  A
            // class that inherits both stays out of this list, so
            // `LookupError.__str__` resolves up the MRO to
            // `BaseException`'s the way `KeyError.__str__` does not.
            if name == "BaseException" {
                type_ns_store(
                    ns_slot,
                    "__repr__",
                    make_builtin_function_with_arity("__repr__", exception_repr_method, 1),
                );
                type_ns_store(
                    ns_slot,
                    "__str__",
                    make_builtin_function_with_arity("__str__", base_exception_str_method, 1),
                );
            } else if matches!(
                name,
                "KeyError"
                    | "OSError"
                    | "ImportError"
                    | "SyntaxError"
                    | "UnicodeDecodeError"
                    | "UnicodeEncodeError"
                    | "UnicodeTranslateError"
            ) {
                type_ns_store(
                    ns_slot,
                    "__str__",
                    make_builtin_function_with_arity("__str__", exception_str_method, 1),
                );
            }
            // `pypy/module/exceptions/interp_exceptions.py:225-235`
            // `BaseException.with_traceback` — installed on every
            // builtin exception class so MRO lookup from a subclass
            // (`MyError.with_traceback`) hits the canonical method
            // even before user-level `class MyError(BaseException):`
            // metaclass walks BaseException's namespace.  PyPy adds
            // this to BaseException only; pyre's `make_exc_type`
            // wires it into every class because Pyre doesn't run
            // `BaseException.__init_subclass__` at builtin-bootstrap
            // time, so without per-class install `subclass.with_traceback`
            // raises AttributeError.
            if name == "BaseException" {
                type_ns_store(
                    ns_slot,
                    "with_traceback",
                    make_builtin_function_with_arity(
                        "with_traceback",
                        |args| {
                            let w_self = *args.first().ok_or_else(|| {
                                crate::PyError::type_error(
                                    "with_traceback() missing 1 required positional argument: 'self'",
                                )
                            })?;
                            let w_tb = args.get(1).copied().unwrap_or(pyre_object::PY_NULL);
                            if !w_self.is_null() && unsafe { pyre_object::is_exception(w_self) } {
                                // `interp_exceptions.py:213-219
                                // descr_settraceback` — only None or
                                // PyTraceback is accepted.
                                let value =
                                    if w_tb.is_null() || unsafe { pyre_object::is_none(w_tb) } {
                                        pyre_object::PY_NULL
                                    } else if unsafe { crate::pytraceback::is_pytraceback(w_tb) } {
                                        w_tb
                                    } else {
                                        return Err(crate::PyError::type_error(
                                            "__traceback__ must be a traceback or None",
                                        ));
                                    };
                                unsafe {
                                    pyre_object::interp_exceptions::w_exception_set_traceback(
                                        w_self, value,
                                    );
                                }
                            }
                            Ok(w_self)
                        },
                        2,
                    ),
                );
                // `BaseException.add_note` / `descr_add_note`. The body is
                // `BaseException_add_note_impl`: attribute lookup of
                // `__notes__`, then `PyList_Append`.
                type_ns_store(
                    ns_slot,
                    "add_note",
                    make_builtin_function_with_arity(
                        "add_note",
                        |args| {
                            let w_self = *args.first().ok_or_else(|| {
                                crate::PyError::type_error(
                                    "add_note() missing 1 required positional argument: 'self'",
                                )
                            })?;
                            let w_note = *args.get(1).ok_or_else(|| {
                                crate::PyError::type_error(
                                    "add_note() missing 1 required positional argument: 'note'",
                                )
                            })?;
                            // `descr_add_note` accepts `str` and any `str`
                            // subclass (`isinstance_w(w_note, space.w_unicode)`).
                            // The rejection wording is `_PyArg_BadArgument`,
                            // which names the method and renders `None` as
                            // `None` rather than as its type. `descr_add_note`
                            // says "note must be a str, not %T".
                            if !unsafe { crate::baseobjspace::isinstance_str_w(w_note) } {
                                let got = if w_note == pyre_object::w_none() {
                                    "None".to_string()
                                } else {
                                    crate::baseobjspace::object_functionstr_type_name(w_note)
                                };
                                return Err(crate::PyError::type_error(format!(
                                    "add_note() argument must be str, not {got}"
                                )));
                            }
                            crate::baseobjspace::base_exception_add_note(w_self, w_note)?;
                            Ok(pyre_object::w_none())
                        },
                        2,
                    ),
                );
                // `interp_exceptions.py` — `descr_reduce` /
                // `descr_setstate`, installed on `BaseException` so every
                // subclass inherits them through the MRO.
                type_ns_store(
                    ns_slot,
                    "__reduce__",
                    make_builtin_function_with_arity("__reduce__", base_exception_reduce, 1),
                );
                type_ns_store(
                    ns_slot,
                    "__setstate__",
                    make_builtin_function_with_arity("__setstate__", base_exception_setstate, 2),
                );
            }
            // `interp_exceptions.py descr_reduce` — ImportError overrides
            // reduce to copy the `name`/`path`/`name_from` slots into state.
            // There is no ImportError `tp_setstate`; `BaseException___setstate___impl`
            // setattr's each present key and leaves the others. PyPy's
            // `W_ImportError.descr_setstate` pops those three names with a
            // None default, so an omitted path becomes None and the caller's
            // state dict loses the keys. `descr_setstate` has no `@jit` hint.
            // ModuleNotFoundError (built via `make_exc_type`) inherits reduce
            // through the MRO and setstate from BaseException.
            if name == "ImportError" {
                type_ns_store(
                    ns_slot,
                    "__reduce__",
                    make_builtin_function_with_arity("__reduce__", import_error_reduce, 1),
                );
            }
            // CPython 3.14 gives AttributeError a producer-specific pickle
            // state: preserve `name` and `args`, but deliberately omit `obj`.
            if name == "AttributeError" {
                type_ns_store(
                    ns_slot,
                    "__getstate__",
                    make_builtin_function_with_arity("__getstate__", attribute_error_getstate, 1),
                );
                type_ns_store(
                    ns_slot,
                    "__reduce__",
                    make_builtin_function_with_arity("__reduce__", attribute_error_reduce, 1),
                );
            }
            // `interp_exceptions.py descr_reduce` — OSError overrides reduce to
            // re-append the filename(s); its subclasses inherit it.
            if name == "OSError" {
                type_ns_store(
                    ns_slot,
                    "__reduce__",
                    make_builtin_function_with_arity("__reduce__", os_error_reduce, 1),
                );
            }
        },
        base,
        layout_pytype,
        overridetypedef,
    );
    if name == "SyntaxError" {
        for member_name in [
            "msg",
            "filename",
            "lineno",
            "offset",
            "text",
            "end_lineno",
            "end_offset",
            "print_file_and_line",
            "_metadata",
        ] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    }
    if name == "StopIteration"
        && let Some(member) = crate::type_dict_lookup(cls, "value")
    {
        unsafe { pyre_object::w_member_set_cls(member, cls) };
    }
    if name == "BaseException"
        && let Some(member) = crate::type_dict_lookup(cls, "__suppress_context__")
    {
        unsafe { pyre_object::w_member_set_cls(member, cls) };
    }
    if name == "AttributeError" {
        for member_name in ["name", "obj"] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    }
    if name == "NameError"
        && let Some(member) = crate::type_dict_lookup(cls, "name")
    {
        unsafe { pyre_object::w_member_set_cls(member, cls) };
    }
    if name == "ImportError" {
        for member_name in ["msg", "name", "name_from", "path"] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    }
    if name == "OSError" {
        for member_name in ["errno", "strerror", "filename", "filename2"] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    }
    if name == "SystemExit"
        && let Some(member) = crate::type_dict_lookup(cls, "code")
    {
        unsafe { pyre_object::w_member_set_cls(member, cls) };
    }
    if matches!(
        name,
        "UnicodeDecodeError" | "UnicodeEncodeError" | "UnicodeTranslateError"
    ) {
        for member_name in ["encoding", "object", "start", "end", "reason"] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    }
    // Record the class so typedef::r#type can map a raised exception
    // back to its specific builtin class (TypeError, ValueError, ...).
    register_exc_class(name, cls)
}

/// Build a builtin exception class with more than one base, e.g.
/// `class UnsupportedOperation(OSError, ValueError)`
/// (`Modules/_io/_iomodule.c`).  The MRO is the C3 linearization over
/// `bases`; the first base drives instance layout.  `with_traceback` /
/// `add_note` are inherited through the MRO from `BaseException`, so
/// only `__new__` is installed here.
///
/// Both classes built this way — `io.UnsupportedOperation` and
/// `ssl.SSLCertVerificationError` — come from `PyErr_NewException*`, so both
/// are weak-referenceable for the reason [`new_exception_class`] gives.
pub fn make_exc_type_multi(
    name: &'static str,
    new_fn: crate::gateway::BuiltinCodeFn,
    bases: &[PyObjectRef],
) -> PyObjectRef {
    if let Some(cls) = lookup_exc_class(name) {
        return cls;
    }
    let mut w_base0 = bases[0];
    let cls = pyre_object::with_roots!(w_base0 =>
        crate::typedef::make_builtin_type_with_bases_and_overridetypedef(
            name,
            move |ns| {
                let _roots = pyre_object::gc_roots::push_roots();
                let ns_slot = pyre_object::gc_roots::shadow_stack_len();
                let _ = pyre_object::gc_roots::pin_root(ns);
                type_ns_store(ns_slot, "__new__", crate::typedef::make_new_descr(new_fn));
            },
            bases,
        )
    );
    add_weakref_slot(cls, w_base0);
    register_exc_class(name, cls)
}

/// `interp_group.py:71-72` `message` / `exceptions` — the two
/// `interp_attrproperty_w` slots `descr_new` stamps onto the instance.  They
/// live in dedicated `W_BaseException` fields, not in `w_dict`, so the group's
/// public `__dict__` stays empty and user code cannot rewrite them.
pub(crate) fn exception_group_fields(
    w_self: PyObjectRef,
) -> Result<(PyObjectRef, PyObjectRef), crate::PyError> {
    let message = unsafe { pyre_object::interp_exceptions::w_exception_get_group_message(w_self) };
    if message.is_null() {
        return Err(crate::PyError::attribute_error(
            "exception group has no message",
        ));
    }
    let exceptions =
        unsafe { pyre_object::interp_exceptions::w_exception_get_group_exceptions(w_self) };
    if exceptions.is_null() {
        return Err(crate::PyError::attribute_error(
            "exception group has no exceptions",
        ));
    }
    Ok((message, exceptions))
}

/// `interp_group.py descr_new`, whose validation upstream is one applevel
/// helper, `app_group.py check_new_args`, ending `return cls, tuple(exceptions)`.
///
/// It stays inline here because the constructor-time `exceptions` repr
/// (gh-141732) has to be taken between two of that helper's own steps: after
/// the sequence check, so a non-sequence still raises `TypeError` first, and
/// before `tuple(exceptions)`, so the repr is the source sequence's and not the
/// converted tuple's.  Extracting the helper puts the capture on one side or
/// the other and loses one of those two orderings.
fn exception_group_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `descr_new(space, w_subtype, w_message, w_exceptions)` counts only the
    // positional arguments it was bound to. Keywords ride the same flat slice
    // here, so strip them before the arity check and leave the rejection to
    // `descr_init`, which names the type the instance ended up with.
    let positional = if args.is_empty() {
        args
    } else {
        split_builtin_kwargs(&args[1..]).0
    };
    if positional.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "BaseExceptionGroup.__new__() takes exactly 2 arguments ({} given)",
            positional.len()
        )));
    }
    // `py_repr`, `fixedview` and the `isinstance`/`issubclass` checks below all
    // run Python, so the three operands cannot stay in untraced Rust locals
    // across them.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[args[0], positional[0], positional[1]]);
    let message = pyre_object::gc_roots::shadow_stack_get(base + 1);
    let w_exceptions = pyre_object::gc_roots::shadow_stack_get(base + 2);
    if !unsafe { crate::baseobjspace::isinstance_str_w(message) } {
        let type_name = crate::type_methods::clinic_arg_type_name(message);
        return Err(crate::PyError::type_error(format!(
            "BaseExceptionGroup.__new__() argument 1 must be str, not {type_name}"
        )));
    }
    let is_list_or_tuple = unsafe {
        crate::baseobjspace::isinstance_list_w(w_exceptions) || pyre_object::is_tuple(w_exceptions)
    };
    if !is_list_or_tuple {
        let has_len = crate::baseobjspace::getattr_str(
            pyre_object::gc_roots::shadow_stack_get(base + 2),
            "__len__",
        )
        .is_ok();
        let has_getitem = crate::baseobjspace::getattr_str(
            pyre_object::gc_roots::shadow_stack_get(base + 2),
            "__getitem__",
        )
        .is_ok();
        if !has_len || !has_getitem {
            return Err(crate::PyError::type_error(
                "second argument (exceptions) must be a sequence",
            ));
        }
    }
    // CPython 3.14 Objects/exceptions.c BaseExceptionGroup_new (gh-141732):
    // preserve the initial representation of a non-list/tuple sequence before
    // converting it to the immutable `exceptions` tuple.  Besides keeping the
    // repr stable when the source sequence is later mutated, doing this here
    // deliberately propagates a raising or non-string custom `__repr__` from
    // the constructor.
    let repr_slot = if is_list_or_tuple {
        None
    } else {
        let rendered = pyre_object::w_str_from_wtf8_managed(unsafe {
            crate::display::py_repr_wtf8(pyre_object::gc_roots::shadow_stack_get(base + 2))?
        });
        let _ = pyre_object::gc_roots::pin_root(rendered);
        Some(pyre_object::gc_roots::shadow_stack_len() - 1)
    };
    let exceptions =
        crate::baseobjspace::fixedview(pyre_object::gc_roots::shadow_stack_get(base + 2), -1)?;
    // `fixedview` returns an untraced Vec and the membership checks below run
    // Python, so publish every element before walking them.
    let items = pyre_object::gc_roots::pin_roots(&exceptions);
    let exception_count = exceptions.len();
    if exception_count == 0 {
        return Err(crate::PyError::value_error(
            "second argument (exceptions) must be a non-empty sequence",
        ));
    }
    for index in 0..exception_count {
        let exc = pyre_object::gc_roots::shadow_stack_get(items + index);
        if !unsafe { pyre_object::is_exception(exc) } {
            return Err(crate::PyError::value_error(format!(
                "Item {index} of second argument (exceptions) is not an exception"
            )));
        }
    }
    let base_group = lookup_exc_class("BaseExceptionGroup").unwrap();
    let base_group = pyre_object::gc_roots::pin_root(base_group);
    let mut exception_group = lookup_exc_class("ExceptionGroup").unwrap();
    let exception = lookup_exc_class("Exception").unwrap();
    // `isinstance` / `issubclass` collect.  `base_group` is still read after
    // those calls for the layout test, so it sits in this pin with the others.
    // Reload `cls` from `base`: `getattr` / `py_repr` / `fixedview` already
    // ran, so a Rust local taken before those calls is a pre-move address.
    let live_base = pyre_object::gc_roots::pin_roots(&[
        pyre_object::gc_roots::shadow_stack_get(base),
        exception,
        exception_group,
        base_group,
    ]);
    let cls_now = || pyre_object::gc_roots::shadow_stack_get(live_base);
    let exception_now = || pyre_object::gc_roots::shadow_stack_get(live_base + 1);
    let group_now = || pyre_object::gc_roots::shadow_stack_get(live_base + 2);
    let base_group_now = || pyre_object::gc_roots::shadow_stack_get(live_base + 3);
    // Each `isinstance` collects, so re-read `items + index` immediately
    // before the call instead of walking a copied Vec of pre-move words.
    let all_exceptions = (0..exception_count).all(|index| {
        crate::baseobjspace::isinstance(
            pyre_object::gc_roots::shadow_stack_get(items + index),
            exception_now(),
        )
        .unwrap_or(false)
    });
    if std::ptr::eq(cls_now(), base_group_now()) && all_exceptions {
        pyre_object::gc_roots::shadow_stack_set(live_base, group_now());
    }
    if crate::baseobjspace::issubclass(cls_now(), exception_now())? && !all_exceptions {
        let name = unsafe { pyre_object::w_type_get_name(cls_now()) };
        let msg = if std::ptr::eq(cls_now(), group_now()) {
            "Cannot nest BaseExceptions in an ExceptionGroup".to_string()
        } else {
            format!("Cannot nest BaseExceptions in '{name}'")
        };
        return Err(crate::PyError::type_error(msg));
    }

    let kind = if crate::baseobjspace::issubclass(cls_now(), exception_now())? {
        pyre_object::interp_exceptions::ExcKind::Exception
    } else {
        pyre_object::interp_exceptions::ExcKind::BaseException
    };
    // `cls` may have been retargeted to `ExceptionGroup` above; publish
    // whichever class the instance is about to be tagged with.
    let _ = pyre_object::gc_roots::pin_root(cls_now());
    let cls_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    // Exact `BaseExceptionGroup` is the plain extended layout. `ExceptionGroup`
    // (including the promotion above) and app subclasses are `_getusercls`.
    let user_layout = !std::ptr::eq(
        pyre_object::gc_roots::shadow_stack_get(cls_slot),
        base_group_now(),
    );
    // Each allocation below is a safepoint, so the nascent group and the tuple
    // it stores both go on the shadow stack before the next one runs.
    let exc = pyre_object::interp_exceptions::w_exception_new_empty_extended_for_class(
        kind,
        pyre_object::gc_roots::shadow_stack_get(cls_slot),
        user_layout,
    );
    let _ = pyre_object::gc_roots::pin_root(exc);
    let exc_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    unsafe {
        // `isinstance` / `issubclass` above can collect.  Read the source
        // sequence back from its slot. `app_group.check_new_args` finishes
        // with `tuple(exceptions)`, and `W_TupleObject.descr_new` returns an
        // exact tuple unchanged, so that object is `w_exceptions`. A list or
        // a tuple subclass is copied from the pinned items.
        // `args_w` keeps the sequence the caller passed. An exact tuple is
        // therefore the same object as `args[1]`. A list stays a list there:
        // `BaseException_new` holds the call args, while
        // `W_BaseExceptionGroup.descr_new` would store the converted tuple
        // and drop the list.
        let source = pyre_object::gc_roots::shadow_stack_get(base + 2);
        let tuple = if pyre_object::is_exact_tuple(source) {
            source
        } else {
            pyre_object::w_tuple_new(
                (0..exception_count)
                    .map(|i| pyre_object::gc_roots::shadow_stack_get(items + i))
                    .collect(),
            )
        };
        let _ = pyre_object::gc_roots::pin_root(tuple);
        let tuple_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
        // `interp_group.py:19-20` — the two attrproperty slots, plus the
        // constructor-time sequence repr.  None of these writes allocates, so
        // the shadow-stack reads below stay valid across all three.
        pyre_object::interp_exceptions::w_exception_set_group_message(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            pyre_object::gc_roots::shadow_stack_get(base + 1),
        );
        pyre_object::interp_exceptions::w_exception_set_group_exceptions(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            pyre_object::gc_roots::shadow_stack_get(tuple_slot),
        );
        if let Some(repr_slot) = repr_slot {
            pyre_object::interp_exceptions::w_exception_set_group_exceptions_repr(
                pyre_object::gc_roots::shadow_stack_get(exc_slot),
                pyre_object::gc_roots::shadow_stack_get(repr_slot),
            );
        }
        let stored_args = pyre_object::interp_exceptions::w_exception_args_new(vec![
            pyre_object::gc_roots::shadow_stack_get(base + 1),
            pyre_object::gc_roots::shadow_stack_get(base + 2),
        ]);
        pyre_object::interp_exceptions::w_exception_set_args(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            stored_args,
        );
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(exc_slot))
}

/// `interp_group.py W_BaseExceptionGroup.descr_init` — retain the first
/// positional value in the shared exception value slot, then delegate the
/// public `args` tuple update and keyword rejection to BaseException.
fn exception_group_init(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let w_self = *args.first().ok_or_else(|| {
        crate::PyError::type_error("__init__() missing 1 required positional argument: 'self'")
    })?;
    let (positional, kwargs) = split_builtin_kwargs(&args[1..]);
    if has_real_kwargs(kwargs) {
        return Err(exc_no_keywords_error(w_self, "BaseExceptionGroup"));
    }
    if let Some(value) = positional.first().copied() {
        unsafe { pyre_object::interp_exceptions::w_exception_set_value(w_self, value) };
    }
    let mut flat = Vec::with_capacity(positional.len() + 1);
    flat.push(w_self);
    flat.extend_from_slice(positional);
    exc_base_exception_init(&flat)
}

enum ExceptionGroupCondition {
    Class(PyObjectRef),
    Callable(PyObjectRef),
    /// `app_group.py _exception_group_projection`'s `resultset`, which upstream
    /// keeps as an `identity_dict` of the leaf objects. A list is the same
    /// single heap object: `collect_leaves` appends through `w_list_append`
    /// (write-barriered) and a nested `isinstance` / `derive` collection
    /// forwards the list rather than a `RootedItems` index run. Nested
    /// `RootedItems` brackets steal those slots (`RootedItems` one-set rule)
    /// so `matches` would read the original group and `split` would keep every
    /// leaf. `except_star_projection_gc_roots` is the guard.
    Identity(PyObjectRef),
}

impl ExceptionGroupCondition {
    fn matches(&self, exc: PyObjectRef) -> Result<bool, crate::PyError> {
        match *self {
            // Match on the exception's type (`exception_match`), not
            // `isinstance`, so a matcher class with a custom metaclass
            // `__instancecheck__` cannot pull unrelated leaves into a subgroup.
            Self::Class(classinfo) => Ok(crate::eval::check_exc_match_against(exc, classinfo)),
            Self::Callable(callable) => {
                let result = crate::call::call_function_impl_result(callable, &[exc])?;
                crate::baseobjspace::is_true(result)
            }
            Self::Identity(leaves) => Ok(exception_group_list_contains_ptr(leaves, exc)),
        }
    }
}

fn exception_group_list_contains_ptr(w_list: PyObjectRef, item: PyObjectRef) -> bool {
    let n = unsafe { pyre_object::w_list_len(w_list) };
    (0..n).any(|i| {
        unsafe { pyre_object::w_list_getitem(w_list, i as i64) }
            .is_some_and(|elt| std::ptr::eq(elt, item))
    })
}

fn exception_group_get_condition_filter(
    mut w_condition: PyObjectRef,
) -> Result<ExceptionGroupCondition, crate::PyError> {
    let mut base_exc = lookup_exc_class("BaseException").unwrap();
    let valid_type = unsafe { pyre_object::is_type(w_condition) }
        && pyre_object::with_roots!(w_condition, base_exc =>
            crate::baseobjspace::issubclass(w_condition, base_exc)
        )
        .unwrap_or(false);
    let valid_tuple = unsafe { pyre_object::is_tuple(w_condition) }
        && (0..unsafe { pyre_object::w_tuple_len(w_condition) }).all(|i| {
            let item = unsafe { pyre_object::w_tuple_getitem(w_condition, i as i64) }.unwrap();
            (unsafe { pyre_object::is_type(item) })
                && crate::baseobjspace::issubclass(item, base_exc).unwrap_or(false)
        });
    if valid_type || valid_tuple {
        return Ok(ExceptionGroupCondition::Class(w_condition));
    }
    // `get_condition_filter` takes any `callable(condition)` as the
    // predicate.  3.14's `get_matcher_type` requires
    // `PyCallable_Check(value) && !PyType_Check(value)`, so a class that is
    // not an exception type is rejected rather than called once per leaf and
    // read back through its instance: `eg.subgroup(C)` for a one-argument
    // `class C` answers a group upstream and raises at 3.14, which the pinned
    // `test_basics_subgroup_split__bad_arg_type` lists among its `bad_args`.
    if crate::baseobjspace::callable_w(w_condition) && !unsafe { pyre_object::is_type(w_condition) }
    {
        return Ok(ExceptionGroupCondition::Callable(w_condition));
    }
    Err(crate::PyError::type_error(
        "expected an exception type, a tuple of exception types, or a callable \
         (other than a class)",
    ))
}

fn exception_group_derive_and_copy_attrs(
    w_self: PyObjectRef,
    exceptions: Vec<PyObjectRef>,
) -> Result<PyObjectRef, crate::PyError> {
    // _derive_and_copy_attrs: construct the sub-result through the overridable
    // `derive` method so a subclass can control reconstruction (e.g. thread
    // extra constructor args), then copy the metadata attrs onto it.
    //
    // `derive` is a fresh bound method that has to survive building the
    // argument list, and the group it answers has to survive the attribute
    // copy, which allocates in turn.
    let _roots = pyre_object::gc_roots::push_roots();
    let self_slot = pyre_object::gc_roots::publish_roots(&[w_self]);
    let items_base = pyre_object::gc_roots::publish_roots(&exceptions);
    pyre_object::gc_roots::normalize_roots(self_slot, 1 + exceptions.len());
    let derive = crate::baseobjspace::getattr_str(
        pyre_object::gc_roots::shadow_stack_get(self_slot),
        "derive",
    )?;
    let derive_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(derive);
    // Reload after `getattr`, which can collect; `take()` copies do not
    // stay live across a later alloc.
    let reloaded: Vec<_> = (0..exceptions.len())
        .map(|i| pyre_object::gc_roots::shadow_stack_get(items_base + i))
        .collect();
    let list_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_list_new(reloaded));
    let group = crate::call::call_function_impl_result(
        pyre_object::gc_roots::shadow_stack_get(derive_slot),
        &[pyre_object::gc_roots::shadow_stack_get(list_slot)],
    )?;
    let group_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(group);
    let base_group = lookup_exc_class("BaseExceptionGroup").unwrap();
    if !crate::baseobjspace::isinstance(
        pyre_object::gc_roots::shadow_stack_get(group_slot),
        base_group,
    )? {
        return Err(crate::PyError::type_error(
            "derive must return an instance of BaseExceptionGroup",
        ));
    }
    // `__notes__` is supposed to be a list, and `split()` is not a good place
    // to report earlier user errors. `findattr` (`PyObject_GetOptionalAttr`)
    // propagates anything but a missing attribute. Present and `issequence_w`
    // (`PySequence_Check`): copy through `fixedview` and `w_list_new`.
    // Present and not a sequence: skip.
    let notes = crate::baseobjspace::findattr(
        pyre_object::gc_roots::shadow_stack_get(self_slot),
        "__notes__",
    )?;
    if let Some(notes) = notes {
        let notes_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(notes);
        if crate::baseobjspace::issequence_w(pyre_object::gc_roots::shadow_stack_get(notes_slot)) {
            let items = crate::baseobjspace::fixedview(
                pyre_object::gc_roots::shadow_stack_get(notes_slot),
                -1,
            )?;
            // `fixedview` returns an untraced Vec and `w_list_new` allocates,
            // so publish every element and build the list from those slots.
            let items_base = pyre_object::gc_roots::pin_roots(&items);
            let items: Vec<_> = (0..items.len())
                .map(|i| pyre_object::gc_roots::shadow_stack_get(items_base + i))
                .collect();
            let notes_list_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(pyre_object::w_list_new(items));
            crate::baseobjspace::setattr_str(
                pyre_object::gc_roots::shadow_stack_get(group_slot),
                "__notes__",
                pyre_object::gc_roots::shadow_stack_get(notes_list_slot),
            )?;
        }
    }
    for name in ["__cause__", "__context__", "__traceback__"] {
        let value = crate::baseobjspace::getattr_str(
            pyre_object::gc_roots::shadow_stack_get(self_slot),
            name,
        )?;
        let value_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(value);
        crate::baseobjspace::setattr_str(
            pyre_object::gc_roots::shadow_stack_get(group_slot),
            name,
            pyre_object::gc_roots::shadow_stack_get(value_slot),
        )?;
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(group_slot))
}

fn exception_group_condition_obj(condition: &ExceptionGroupCondition) -> Option<PyObjectRef> {
    match *condition {
        ExceptionGroupCondition::Class(obj)
        | ExceptionGroupCondition::Callable(obj)
        | ExceptionGroupCondition::Identity(obj) => Some(obj),
    }
}

fn pin_exception_group_children(exceptions: PyObjectRef) -> (usize, usize) {
    let items = unsafe { pyre_object::w_tuple_items_copy_as_vec(exceptions) };
    let n = items.len();
    let base = pyre_object::gc_roots::pin_roots(&items);
    (base, n)
}

fn pin_exception_group_walk(
    w_self: PyObjectRef,
    condition: &ExceptionGroupCondition,
) -> (usize, Option<usize>) {
    match exception_group_condition_obj(condition) {
        Some(obj) => {
            let base = pyre_object::gc_roots::pin_roots(&[w_self, obj]);
            (base, Some(base + 1))
        }
        None => (pyre_object::gc_roots::pin_roots(&[w_self]), None),
    }
}

fn live_exception_group_condition(
    condition: &ExceptionGroupCondition,
    cond_slot: Option<usize>,
) -> ExceptionGroupCondition {
    match *condition {
        ExceptionGroupCondition::Class(_) => ExceptionGroupCondition::Class(
            pyre_object::gc_roots::shadow_stack_get(cond_slot.expect("class condition is pinned")),
        ),
        ExceptionGroupCondition::Callable(_) => {
            ExceptionGroupCondition::Callable(pyre_object::gc_roots::shadow_stack_get(
                cond_slot.expect("callable condition is pinned"),
            ))
        }
        ExceptionGroupCondition::Identity(_) => ExceptionGroupCondition::Identity(
            pyre_object::gc_roots::shadow_stack_get(cond_slot.expect("identity set is pinned")),
        ),
    }
}

/// `app_group.py subgroup`.
///
/// Upstream returns `self` twice: once when the condition matches the group
/// itself, and once at the end when no child was filtered out — the arm its own
/// comment marks as "this is the difference to split!".  3.14's
/// `exceptiongroup_subgroup` keeps only the first: an unfiltered subgroup is
/// still rebuilt through `derive`, so `eg.subgroup(cond) is eg` is False and a
/// `BaseExceptionGroup` subclass answers `ExceptionGroup` rather than itself.
/// Identity is observable, so the second arm is not taken here.  `split` never
/// had it on either side.
fn exception_group_subgroup_inner(
    w_self: PyObjectRef,
    condition: &ExceptionGroupCondition,
) -> Result<PyObjectRef, crate::PyError> {
    let _self_roots = pyre_object::gc_roots::push_roots();
    let (self_slot, cond_slot) = pin_exception_group_walk(w_self, condition);
    let w_self = || pyre_object::gc_roots::shadow_stack_get(self_slot);
    let live_condition = || live_exception_group_condition(condition, cond_slot);
    if live_condition().matches(w_self())? {
        return Ok(w_self());
    }
    let (_, exceptions) = exception_group_fields(w_self())?;
    // `isinstance`, the recursive walk and `matches` all collect. The class
    // is reloaded from this slot at each test.
    let base_group_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(lookup_exc_class("BaseExceptionGroup").unwrap());
    let base_group = || pyre_object::gc_roots::shadow_stack_get(base_group_slot);
    // Children are nursery-allocated exceptions.  `derive` (and isinstance)
    // can collect, so the walk pins the tuple items and reloads each child
    // after every allocating call.  An unrooted `Vec` copy would keep the
    // pre-collect address of a later sibling.
    let (children_base, n_children) = pin_exception_group_children(exceptions);
    let child = |i| pyre_object::gc_roots::shadow_stack_get(children_base + i);
    let mut selected = pyre_object::gc_roots::RootedItems::new();
    for i in 0..n_children {
        let exc = child(i);
        if crate::baseobjspace::isinstance(exc, base_group())? {
            let exc = child(i);
            let subgroup = exception_group_subgroup_inner(exc, &live_condition())?;
            if !unsafe { pyre_object::is_none(subgroup) } {
                selected.push(subgroup);
            }
        } else if live_condition().matches(child(i))? {
            selected.push(child(i));
        }
    }
    // Upstream tracks whether the walk dropped anything and hands back `self`
    // when it did not.  `exceptiongroup_subgroup` derives either way, which is
    // what the identity and the answered class are measured against, so the
    // `modified` flag has no reader here.
    if selected.is_empty() {
        Ok(pyre_object::w_none())
    } else {
        exception_group_derive_and_copy_attrs(w_self(), selected.take())
    }
}

fn exception_group_split_inner(
    w_self: PyObjectRef,
    condition: &ExceptionGroupCondition,
) -> Result<(PyObjectRef, PyObjectRef), crate::PyError> {
    let _self_roots = pyre_object::gc_roots::push_roots();
    let (self_slot, cond_slot) = pin_exception_group_walk(w_self, condition);
    let w_self = || pyre_object::gc_roots::shadow_stack_get(self_slot);
    let live_condition = || live_exception_group_condition(condition, cond_slot);
    if live_condition().matches(w_self())? {
        return Ok((w_self(), pyre_object::w_none()));
    }
    let (_, exceptions) = exception_group_fields(w_self())?;
    let base_group_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(lookup_exc_class("BaseExceptionGroup").unwrap());
    let base_group = || pyre_object::gc_roots::shadow_stack_get(base_group_slot);
    // Either side can hold a freshly derived subgroup while a later child is
    // still recursing and allocating, so every kept child is pinned as it
    // arrives; both sides share one bracket, because two open brackets pin onto
    // the same shadow stack and would read each other's slots back
    // (`build_list_storage`).  The source children are pinned too: `derive`
    // collects, and a bare tuple-copy would leave the next sibling's address
    // stale.
    let (children_base, n_children) = pin_exception_group_children(exceptions);
    let child = |i| pyre_object::gc_roots::shadow_stack_get(children_base + i);
    let mut kept = pyre_object::gc_roots::RootedItems::new();
    let mut matching_at = Vec::new();
    let mut nonmatching_at = Vec::new();
    for i in 0..n_children {
        let exc = child(i);
        if crate::baseobjspace::isinstance(exc, base_group())? {
            let exc = child(i);
            let (yes, no) = exception_group_split_inner(exc, &live_condition())?;
            if !unsafe { pyre_object::is_none(yes) } {
                matching_at.push(kept.len());
                kept.push(yes);
            }
            if !unsafe { pyre_object::is_none(no) } {
                nonmatching_at.push(kept.len());
                kept.push(no);
            }
        } else if live_condition().matches(child(i))? {
            matching_at.push(kept.len());
            kept.push(child(i));
        } else {
            nonmatching_at.push(kept.len());
            kept.push(child(i));
        }
    }
    // `app_group.py` `split` walks `self.exceptions` and derives each
    // side from the live list. Do not `take()` the rooted items: the
    // first `derive` can collect, and a snapshot Vec would then be stale.
    let mut derived = pyre_object::gc_roots::RootedItems::new();
    let yes = if matching_at.is_empty() {
        pyre_object::w_none()
    } else {
        let items: Vec<PyObjectRef> = matching_at.iter().map(|&i| kept.get(i)).collect();
        exception_group_derive_and_copy_attrs(w_self(), items)?
    };
    derived.push(yes);
    let no = if nonmatching_at.is_empty() {
        pyre_object::w_none()
    } else {
        let items: Vec<PyObjectRef> = nonmatching_at.iter().map(|&i| kept.get(i)).collect();
        exception_group_derive_and_copy_attrs(w_self(), items)?
    };
    derived.push(no);
    Ok((derived.get(0), derived.get(1)))
}

/// `ceval.c _PyEval_ExceptionGroupMatch`, answering `CHECK_EG_MATCH`.
///
/// The third element is true exactly when `matching` is a group this call built
/// around a non-group exception.  Such a wrapper is born here with an empty
/// traceback and upstream gives it an entry for the frame running the opcode,
/// which is the frame a later re-raise reports the group as passing through;
/// only the caller holds that frame, so the decision travels out instead of the
/// record.
pub(crate) fn exception_group_match(
    w_exc: PyObjectRef,
    w_type: PyObjectRef,
) -> Result<(PyObjectRef, PyObjectRef, bool), crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[
        w_exc,
        w_type,
        lookup_exc_class("BaseExceptionGroup").unwrap(),
    ]);
    let w_exc = || pyre_object::gc_roots::shadow_stack_get(base);
    let w_type = || pyre_object::gc_roots::shadow_stack_get(base + 1);
    let base_group = || pyre_object::gc_roots::shadow_stack_get(base + 2);
    if crate::eval::check_exc_match_against(w_exc(), w_type()) {
        if crate::baseobjspace::isinstance(w_exc(), base_group())? {
            return Ok((w_exc(), pyre_object::w_none(), false));
        }
        let message = unsafe { pyre_object::w_str_new("") };
        let message_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(message);
        let exceptions = pyre_object::w_tuple_new(vec![w_exc()]);
        let exceptions_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(exceptions);
        let group = exception_group_new(&[
            base_group(),
            pyre_object::gc_roots::shadow_stack_get(message_slot),
            pyre_object::gc_roots::shadow_stack_get(exceptions_slot),
        ])?;
        return Ok((group, pyre_object::w_none(), true));
    }
    if crate::baseobjspace::isinstance(w_exc(), base_group())? {
        // Partial match: call the (overridable) `split` method and validate it
        // returns a 2-tuple of (match, rest).
        let split = crate::baseobjspace::getattr_str(w_exc(), "split")?;
        let split_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(split);
        let pair = crate::call::call_function_impl_result(
            pyre_object::gc_roots::shadow_stack_get(split_slot),
            &[w_type()],
        )?;
        let pair_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pair);
        if !unsafe { pyre_object::is_tuple(pyre_object::gc_roots::shadow_stack_get(pair_slot)) } {
            let name = crate::baseobjspace::object_functionstr_type_name(
                pyre_object::gc_roots::shadow_stack_get(pair_slot),
            );
            return Err(crate::PyError::type_error(format!(
                "split must return a tuple, not {name}"
            )));
        }
        let pair = pyre_object::gc_roots::shadow_stack_get(pair_slot);
        let n = unsafe { pyre_object::w_tuple_len(pair) };
        if n < 2 {
            return Err(crate::PyError::type_error(format!(
                "split must return a 2-tuple, got tuple of size {n}"
            )));
        }
        // Tuples longer than 2 are accepted for backwards compatibility; only
        // the first two elements (match, rest) are used.
        let matching = unsafe { pyre_object::w_tuple_getitem(pair, 0) }.unwrap();
        let rest = unsafe { pyre_object::w_tuple_getitem(pair, 1) }.unwrap();
        return Ok((matching, rest, false));
    }
    Ok((pyre_object::w_none(), w_exc(), false))
}

fn exception_group_notes(w_exc: PyObjectRef) -> Result<Option<PyObjectRef>, crate::PyError> {
    match crate::baseobjspace::getattr_str(w_exc, "__notes__") {
        Ok(notes) => Ok(Some(notes)),
        Err(err) if err.kind == crate::PyErrorKind::AttributeError => Ok(None),
        Err(err) => Err(err),
    }
}

/// Identity comparison of a `__traceback__`/`__cause__`/`__context__` slot,
/// treating an unset (raw NULL) slot and the `None` singleton as the same
/// Python-level value.  `_is_same_exception_metadata` reads these through the
/// attribute layer, which normalizes an unset slot to `None`; the raw slot
/// accessors do not, so a copy made via getattr/setattr (holding `None`) would
/// otherwise not compare equal to a source whose slot was never materialized.
fn exception_group_meta_ref_eq(w_left: PyObjectRef, w_right: PyObjectRef) -> bool {
    let left_none = w_left.is_null() || unsafe { pyre_object::is_none(w_left) };
    let right_none = w_right.is_null() || unsafe { pyre_object::is_none(w_right) };
    if left_none || right_none {
        left_none && right_none
    } else {
        std::ptr::eq(w_left, w_right)
    }
}

fn exception_group_is_same_exception_metadata(
    w_left: PyObjectRef,
    w_right: PyObjectRef,
) -> Result<bool, crate::PyError> {
    // `_is_same_exception_metadata` reads `__notes__` through getattr, which
    // can collect; both operands stay on the shadow stack so the later raw
    // traceback/cause/context slot compares still name the same objects.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[w_left, w_right]);
    let left_notes = exception_group_notes(pyre_object::gc_roots::shadow_stack_get(base))?;
    let has_left_notes = left_notes.is_some();
    let left_notes_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(left_notes.unwrap_or(pyre_object::PY_NULL));
    let right_notes = exception_group_notes(pyre_object::gc_roots::shadow_stack_get(base + 1))?;
    let left_notes =
        has_left_notes.then(|| pyre_object::gc_roots::shadow_stack_get(left_notes_slot));
    if !match (left_notes, right_notes) {
        (Some(left), Some(right)) => std::ptr::eq(left, right),
        (None, None) => true,
        _ => false,
    } {
        return Ok(false);
    }
    Ok(unsafe {
        exception_group_meta_ref_eq(
            pyre_object::interp_exceptions::w_exception_get_traceback(
                pyre_object::gc_roots::shadow_stack_get(base),
            ),
            pyre_object::interp_exceptions::w_exception_get_traceback(
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            ),
        ) && exception_group_meta_ref_eq(
            pyre_object::interp_exceptions::w_exception_get_cause(
                pyre_object::gc_roots::shadow_stack_get(base),
            ),
            pyre_object::interp_exceptions::w_exception_get_cause(
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            ),
        ) && exception_group_meta_ref_eq(
            pyre_object::interp_exceptions::w_exception_get_context(
                pyre_object::gc_roots::shadow_stack_get(base),
            ),
            pyre_object::interp_exceptions::w_exception_get_context(
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            ),
        )
    })
}

fn exception_group_collect_eg_leafs(
    w_exc: PyObjectRef,
    w_leaves: PyObjectRef,
) -> Result<(), crate::PyError> {
    if unsafe { pyre_object::is_none(w_exc) } {
        return Ok(());
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[w_exc, w_leaves]);
    let w_exc = || pyre_object::gc_roots::shadow_stack_get(base);
    let w_leaves = || pyre_object::gc_roots::shadow_stack_get(base + 1);
    let base_group = lookup_exc_class("BaseExceptionGroup").unwrap();
    if crate::baseobjspace::isinstance(w_exc(), base_group)? {
        let (_, exceptions) = exception_group_fields(w_exc())?;
        let children = unsafe { pyre_object::w_tuple_items_copy_as_vec(exceptions) };
        let kids = pyre_object::gc_roots::pin_roots(&children);
        for i in 0..children.len() {
            exception_group_collect_eg_leafs(
                pyre_object::gc_roots::shadow_stack_get(kids + i),
                w_leaves(),
            )?;
        }
    } else if unsafe { pyre_object::is_exception(w_exc()) } {
        if !exception_group_list_contains_ptr(w_leaves(), w_exc()) {
            unsafe { pyre_object::w_list_append(w_leaves(), w_exc()) };
        }
    } else {
        let name = crate::baseobjspace::object_functionstr_type_name(w_exc());
        return Err(crate::PyError::type_error(format!(
            "expected BaseException, got {name}"
        )));
    }
    Ok(())
}

fn exception_group_projection(
    w_group: PyObjectRef,
    keep: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    // The group is a nursery exception. Leaf collection and the list
    // malloc both collect, so the group is re-read from this slot
    // before `exception_group_split_inner`.
    let group_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_group);
    let keep_base = pyre_object::gc_roots::pin_roots(keep);
    let leaves_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_list_new(Vec::new()));
    for i in 0..keep.len() {
        exception_group_collect_eg_leafs(
            pyre_object::gc_roots::shadow_stack_get(keep_base + i),
            pyre_object::gc_roots::shadow_stack_get(leaves_slot),
        )?;
    }
    let (matching, _) = exception_group_split_inner(
        pyre_object::gc_roots::shadow_stack_get(group_slot),
        &ExceptionGroupCondition::Identity(pyre_object::gc_roots::shadow_stack_get(leaves_slot)),
    )?;
    Ok(matching)
}

pub(crate) fn exception_group_prep_reraise_star(
    w_orig: PyObjectRef,
    w_exc_list: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    // Both arguments are nursery exceptions (`alloc_exception_nursery`).
    // `fixedview` and the metadata / projection calls collect, and these
    // locals are not roots, so each use re-reads the shadow-stack slot.
    let _roots = pyre_object::gc_roots::push_roots();
    let orig_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_orig);
    let list_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_exc_list);
    let exceptions =
        crate::baseobjspace::fixedview(pyre_object::gc_roots::shadow_stack_get(list_slot), -1)?;
    if exceptions.is_empty() {
        return Ok(pyre_object::w_none());
    }
    let exc_base = pyre_object::gc_roots::shadow_stack_len();
    for &w_exc in &exceptions {
        let _ = pyre_object::gc_roots::pin_root(w_exc);
    }
    let n = exceptions.len();
    let exc_at = |i: usize| pyre_object::gc_roots::shadow_stack_get(exc_base + i);
    let base_group = lookup_exc_class("BaseExceptionGroup").unwrap();
    if !crate::baseobjspace::isinstance(
        pyre_object::gc_roots::shadow_stack_get(orig_slot),
        base_group,
    )? {
        return Ok(exc_at(0));
    }

    let mut raised_slots = Vec::new();
    let mut reraised_slots = Vec::new();
    for i in 0..n {
        let w_exc = exc_at(i);
        if !unsafe { pyre_object::is_none(w_exc) } {
            if exception_group_is_same_exception_metadata(
                w_exc,
                pyre_object::gc_roots::shadow_stack_get(orig_slot),
            )? {
                reraised_slots.push(exc_base + i);
            } else {
                raised_slots.push(exc_base + i);
            }
        }
    }
    let reraised: Vec<PyObjectRef> = reraised_slots
        .iter()
        .copied()
        .map(pyre_object::gc_roots::shadow_stack_get)
        .collect();
    let reraised_group = exception_group_projection(
        pyre_object::gc_roots::shadow_stack_get(orig_slot),
        &reraised,
    )?;
    if raised_slots.is_empty() {
        return Ok(reraised_group);
    }
    let mut raised: Vec<PyObjectRef> = raised_slots
        .iter()
        .copied()
        .map(pyre_object::gc_roots::shadow_stack_get)
        .collect();
    if !unsafe { pyre_object::is_none(reraised_group) } {
        raised.push(reraised_group);
    }
    if raised.len() == 1 {
        return Ok(raised[0]);
    }
    // Construct through BaseExceptionGroup so a merged result that carries a
    // bare BaseException (e.g. a reraised KeyboardInterrupt alongside a freshly
    // raised Exception) stays a BaseExceptionGroup; the constructor promotes to
    // ExceptionGroup only when every leaf is an Exception.
    let raised_base = pyre_object::gc_roots::shadow_stack_len();
    for &item in &raised {
        let _ = pyre_object::gc_roots::pin_root(item);
    }
    let raised_n = raised.len();
    let base_group_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(lookup_exc_class("BaseExceptionGroup").unwrap());
    let list = pyre_object::w_list_new(
        (0..raised_n)
            .map(|i| pyre_object::gc_roots::shadow_stack_get(raised_base + i))
            .collect(),
    );
    // `w_list_new` collects; the message is allocated after it so no
    // unrooted local crosses that collection.
    let message = unsafe { pyre_object::w_str_new("") };
    exception_group_new(&[
        pyre_object::gc_roots::shadow_stack_get(base_group_slot),
        message,
        list,
    ])
}

fn exception_group_subgroup(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(
            "subgroup() takes exactly one argument",
        ));
    }
    let mut w_self = args[0];
    let condition =
        pyre_object::with_roots!(w_self => exception_group_get_condition_filter(args[1]))?;
    exception_group_subgroup_inner(w_self, &condition)
}

fn exception_group_split(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(
            "split() takes exactly one argument",
        ));
    }
    let mut w_self = args[0];
    let condition =
        pyre_object::with_roots!(w_self => exception_group_get_condition_filter(args[1]))?;
    let (yes, no) = exception_group_split_inner(w_self, &condition)?;
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[yes, no]);
    Ok(pyre_object::w_tuple_new(vec![
        pyre_object::gc_roots::shadow_stack_get(base),
        pyre_object::gc_roots::shadow_stack_get(base + 1),
    ]))
}

fn exception_group_derive(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(
            "derive() takes exactly one argument",
        ));
    }
    // The default derive constructs a BaseExceptionGroup (promoted to
    // ExceptionGroup when every leaf is an Exception), NOT `type(self)`: a
    // subclass that adds constructor args must override `derive` to preserve
    // its type, otherwise split/subgroup fall back to the base class.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[args[0], args[1]]);
    let (message, _) = exception_group_fields(pyre_object::gc_roots::shadow_stack_get(base))?;
    let message_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(message);
    let base_group = lookup_exc_class("BaseExceptionGroup").unwrap();
    crate::call::call_function_impl_result(
        base_group,
        &[
            pyre_object::gc_roots::shadow_stack_get(message_slot),
            pyre_object::gc_roots::shadow_stack_get(base + 1),
        ],
    )
}

fn exception_group_str(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (message, exceptions) = exception_group_fields(args[0])?;
    let message = unsafe { pyre_object::w_str_get_wtf8(message) }.to_wtf8_buf();
    let count = unsafe { pyre_object::w_tuple_len(exceptions) };
    let suffix = if count == 1 { "" } else { "s" };
    // `app_group.py __str__` interpolates `self.message` into the result, and a
    // `str` carrying an unpaired surrogate interpolates as itself.  Building
    // the result through `to_string_lossy` instead turned that surrogate into
    // U+FFFD, so `str(group)` answered a different string than `group.message`
    // held -- a loss visible from Python, not only on the way to stderr.
    let mut rendered = Wtf8Buf::with_capacity(message.len() + 32);
    rendered.push_wtf8(&message);
    rendered.push_str(&format!(" ({count} sub-exception{suffix})"));
    Ok(pyre_object::w_str_from_wtf8_managed(rendered))
}

fn exception_group_repr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let self_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    let w_self = || pyre_object::gc_roots::shadow_stack_get(self_slot);
    let (message, exceptions) = exception_group_fields(w_self())?;
    let fields = pyre_object::gc_roots::pin_roots(&[message, exceptions]);
    let message = || pyre_object::gc_roots::shadow_stack_get(fields);
    let exceptions = || pyre_object::gc_roots::shadow_stack_get(fields + 1);
    let cls = crate::typedef::r#type(w_self()).unwrap();
    let name = unsafe { pyre_object::w_type_get_name(cls.as_ptr()) };
    let message_repr = unsafe { crate::display::py_repr_wtf8(message())? };
    let saved =
        unsafe { pyre_object::interp_exceptions::w_exception_get_group_exceptions_repr(w_self()) };
    // `app_group.py __repr__` interpolates the two `!r` results into the result
    // verbatim, so a `__repr__` that answers a lone surrogate carries it
    // through.  Every piece here is WTF-8 for that reason: `w_str_get_value`
    // on the saved spelling would panic outright on such a surrogate, and the
    // `py_repr` spelling of the fallbacks would fold it to U+FFFD.
    let exceptions_repr = if !saved.is_null() {
        unsafe { pyre_object::w_str_get_wtf8(saved) }.to_wtf8_buf()
    } else {
        // Fallback for a group whose constructor never recorded the spelling:
        // render the immutable internal tuple, but as a list when `args` shows
        // the caller supplied one.  The contents come from the internal tuple,
        // so a later mutation of the caller's list is not reflected — matching
        // PyPy rather than CPython 3.14, which re-renders `args[1]` live.
        let w_args = unsafe { pyre_object::interp_exceptions::w_exception_get_args(w_self()) };
        let original_was_list = unsafe {
            pyre_object::is_tuple(w_args)
                && pyre_object::w_tuple_len(w_args) >= 2
                && pyre_object::is_list(
                    pyre_object::w_tuple_getitem(w_args, 1).unwrap_or(pyre_object::PY_NULL),
                )
        };
        if original_was_list {
            let items = unsafe { pyre_object::w_tuple_items_copy_as_vec(exceptions()) };
            unsafe { crate::display::py_repr_wtf8(pyre_object::w_list_new(items))? }
        } else {
            unsafe { crate::display::py_repr_wtf8(exceptions())? }
        }
    };
    let mut rendered =
        Wtf8Buf::with_capacity(name.len() + message_repr.len() + exceptions_repr.len() + 4);
    rendered.push_str(name);
    rendered.push_str("(");
    rendered.push_wtf8(&message_repr);
    rendered.push_str(", ");
    rendered.push_wtf8(&exceptions_repr);
    rendered.push_str(")");
    Ok(pyre_object::w_str_from_wtf8_managed(rendered))
}

fn make_exception_group_type(
    name: &'static str,
    doc: Option<&'static str>,
    bases: &[PyObjectRef],
) -> PyObjectRef {
    if let Some(cls) = lookup_exc_class(name) {
        return cls;
    }
    let layout_pytype = exception_layout_pytype(name, bases[0]);
    let overridetypedef = exception_overridetypedef(layout_pytype, bases[0]);
    let cls = crate::typedef::make_builtin_type_with_bases_and_layout_owner(
        name,
        move |ns| {
            let _roots = pyre_object::gc_roots::push_roots();
            let ns_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(ns);
            if let Some(doc) = doc {
                type_ns_store(ns_slot, "__doc__", pyre_object::w_str_new(doc));
            }
            if name == "ExceptionGroup" {
                // CPython 3.14 creates ExceptionGroup as the heap type over
                // BaseExceptionGroup + Exception.  Its own namespace therefore
                // carries `__module__ = "builtins"` and `__doc__ = None`;
                // BaseExceptionGroup is a static builtin and has no own module
                // entry.
                type_ns_store(ns_slot, "__module__", pyre_object::w_str_new("builtins"));
                type_ns_store(ns_slot, "__doc__", pyre_object::w_none());
            }
            if name != "BaseExceptionGroup" {
                return;
            }
            for (method_name, function, arity) in [
                (
                    "subgroup",
                    exception_group_subgroup as crate::gateway::BuiltinCodeFn,
                    2,
                ),
                (
                    "split",
                    exception_group_split as crate::gateway::BuiltinCodeFn,
                    2,
                ),
                (
                    "derive",
                    exception_group_derive as crate::gateway::BuiltinCodeFn,
                    2,
                ),
                (
                    "__str__",
                    exception_group_str as crate::gateway::BuiltinCodeFn,
                    1,
                ),
                (
                    "__repr__",
                    exception_group_repr as crate::gateway::BuiltinCodeFn,
                    1,
                ),
            ] {
                type_ns_store(
                    ns_slot,
                    method_name,
                    make_builtin_function_with_arity(method_name, function, arity),
                );
            }
            type_ns_store(
                ns_slot,
                "__new__",
                crate::typedef::make_new_descr(exception_group_new),
            );
            type_ns_store(
                ns_slot,
                "__init__",
                make_builtin_function("__init__", exception_group_init),
            );
            type_ns_store(
                ns_slot,
                "__class_getitem__",
                pyre_object::function::w_classmethod_new(make_builtin_function(
                    "__class_getitem__",
                    crate::_pypy_generic_alias::generic_alias_class_getitem,
                )),
            );
            for (member_name, kind, doc) in [
                (
                    "message",
                    pyre_object::MEMBER_EXCEPTION_GROUP_MESSAGE,
                    "exception message",
                ),
                (
                    "exceptions",
                    pyre_object::MEMBER_EXCEPTION_GROUP_EXCEPTIONS,
                    "nested exceptions",
                ),
            ] {
                type_ns_store(
                    ns_slot,
                    member_name,
                    pyre_object::w_member_new_direct_with_doc(
                        kind,
                        member_name.to_owned(),
                        doc.to_owned(),
                        pyre_object::PY_NULL,
                    ),
                );
            }
        },
        bases,
        layout_pytype,
        overridetypedef,
    );
    if name == "BaseExceptionGroup" {
        for member_name in ["message", "exceptions"] {
            if let Some(member) = crate::type_dict_lookup(cls, member_name) {
                unsafe { pyre_object::w_member_set_cls(member, cls) };
            }
        }
    } else if name == "ExceptionGroup" {
        // `moduledef.py` names `interp_group.W_ExceptionGroup` under
        // `interpleveldefs`, so this multiple-inheritance type is a static
        // builtin exactly like `BaseExceptionGroup` beside it — immutable, and
        // carrying none of the heap-type flag bits. Its instances still take
        // the ordinary weakref slot; pyre constructs the type directly, so
        // install the copied descriptor and flag explicitly.
        let _roots = pyre_object::gc_roots::push_roots();
        let save = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(cls);
        let cls = pyre_object::gc_roots::shadow_stack_get(save);
        let descr = crate::typedef::copy_descriptor_for_type(crate::typedef::weakref_descr(), cls);
        let _ = pyre_object::gc_roots::pin_root(descr);
        let cls = pyre_object::gc_roots::shadow_stack_get(save);
        let descr = pyre_object::gc_roots::shadow_stack_get(save + 1);
        crate::type_dict_store(cls, "__weakref__", descr);
        unsafe { pyre_object::w_type_set_weakrefable(cls, true) };
    }
    register_exc_class(name, cls)
}

/// Process-global registry from exception class name (as used by
/// `ExcKind → exc_kind_name`) to the W_TypeObject exposed in the builtins
/// namespace. Populated at init-builtins time via `make_exc_type`. Entries are
/// first-writer-wins so every execution context installs the same canonical
/// class hierarchy in its builtins dictionary.
///
/// Also propagates into `pyre_object::interp_exceptions`'s kind-indexed
/// registry so `w_exception_new(kind, ...)` populates
/// `ob_header.w_class` with the registered class — every
/// builtin-raised exception then satisfies
/// `space.type(w_exc) == registered class` per `baseobjspace.py
/// exception_getclass`.
fn register_exc_class(name: &'static str, cls: PyObjectRef) -> PyObjectRef {
    let registry = EXC_CLASS_REGISTRY
        .get_or_init(|| parking_lot::Mutex::new(std::collections::HashMap::new()));
    // The map lookup is all this lock covers.  Everything below reaches the
    // object heap, whose dict locks are striped -- two unrelated dictionaries
    // can share one -- so a thread holding a dict lock and waiting for this
    // registry closes a cycle against the thread that holds the registry and
    // wants a dict.  A plain mutex is invisible to the collector's
    // stop-the-world handshake as well, so nothing breaks that wait.
    let canonical = {
        let mut registry = registry.lock();
        *registry.entry(name).or_insert(cls as usize) as PyObjectRef
    };
    // Both of these are first-writer-wins on their own, so a second thread
    // arriving at the same class repeats them rather than racing them.
    crate::typedef::stamp_exception_method_owners(canonical, name);
    crate::baseobjspace::object_space().export_builtin_exception(name, canonical);
    if let Some(kind) = pyre_object::interp_exceptions::exc_kind_from_name(name) {
        let by_kind = pyre_object::interp_exceptions::register_exc_class_for_kind(kind, canonical);
        debug_assert_eq!(by_kind, canonical);
    }
    canonical
}

/// Look up a builtin exception class by its `ExcKind` name. Returns
/// `None` if the registry hasn't been populated yet (e.g. before
/// install_default_builtins).
///
/// `dont_look_inside` because the body reads `EXC_CLASS_REGISTRY`, a
/// runtime-populated `static` of a host type rather than a build-time constant,
/// so the front-end cannot lift it. Reaching it from a lifted body fails that
/// callee's lift and, transitively, every caller's — which is how
/// `warn::warn_category_w` lost its jitcode and made every interpreter-level
/// warning an opaque residual. Hiding the registry behind the opaque call keeps
/// the callers liftable, exactly as `w_dict_new` does for its host `IndexMap`,
/// and the scalar `Option<PyObjectRef>` result is the same residual boundary
/// shape as `baseobjspace::lookup_in_type_where_uncached`.
#[majit_macros::dont_look_inside]
pub fn lookup_exc_class(name: &str) -> Option<PyObjectRef> {
    let registry = EXC_CLASS_REGISTRY.get()?;
    let registry = registry.lock();
    registry.get(name).copied().map(|cls| cls as PyObjectRef)
}

/// The `PythonFinalizationError` for an operation refused at interpreter
/// shutdown, carrying `message` as its argument when one is given.
///
/// Every caller reaches this only while `thread::is_finalizing()` holds, which
/// is exactly when the registry [`lookup_exc_class`] reads may already be torn
/// down. Naming the class with `expect` there ends the process instead of
/// refusing the operation, so a missing class falls back to the base the
/// registration gives it — `PythonFinalizationError` is made on
/// `runtime_error` — and the `except RuntimeError` that would have caught it
/// still does.
pub fn finalization_error(message: Option<&str>) -> crate::PyError {
    let Some(cls) = lookup_exc_class("PythonFinalizationError") else {
        return crate::PyError::runtime_error(
            message.unwrap_or("Operation blocked during Python finalization."),
        );
    };
    let _roots = pyre_object::gc_roots::push_roots();
    let cls_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(cls);
    let w_value = match message {
        Some(message) => pyre_object::w_str_new_managed(message),
        None => pyre_object::PY_NULL,
    };
    crate::PyError::from_type_and_value(pyre_object::gc_roots::shadow_stack_get(cls_slot), w_value)
}

/// Look up the reusable prebuilt instance for a builtin exception
/// class, addressed by `ExcKind` name.  Mirrors RPython's
/// `rpython/rtyper/exceptiondata.py get_standard_ll_exc_instance`
/// — the JIT's `_ovf` direct-raise rewrite
/// (`rpython/jit/codewriter/flatten.py:165-170`) emits
/// `raise <Constant(ll_ovf)>` with the prebuilt instance pointer (NOT
/// the class pointer).  The instance lives forever; callers can stamp
/// its pointer into a JIT constant pool.
///
/// Returns `None` when `name` is not one of the recognised `ExcKind`
/// names (`exc_kind_from_name` returns `None`); standard exceptions
/// listed by `pyre_jit::jit::exceptiondata::STANDARD_EXCEPTIONS` all
/// map through.
pub fn lookup_exc_instance(name: &str) -> Option<PyObjectRef> {
    let kind = pyre_object::interp_exceptions::exc_kind_from_name(name)?;
    Some(pyre_object::interp_exceptions::standard_exc_instance(kind))
}

static EXC_CLASS_REGISTRY: std::sync::OnceLock<
    parking_lot::Mutex<std::collections::HashMap<&'static str, usize>>,
> = std::sync::OnceLock::new();

/// `__build_class__(body, name, *bases)` — class creation.
///
/// PyPy equivalent: pyopcode.py BUILD_CLASS
/// Direct call to call::real_build_class (no callback needed —
/// interpreter and runtime are in the same crate).
fn builtin_build_class(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    crate::call::real_build_class(args)
}

/// Get a reference to the `__build_class__` builtin function.
pub fn get_build_class_func() -> PyObjectRef {
    make_builtin_function("__build_class__", builtin_build_class)
}

/// Is `obj` the `__build_class__` builtin?
///
/// Every producer wraps the same `BuiltinCode.func`, so the function address
/// recognizes both the copy in the builtins namespace and any fresh one
/// [`get_build_class_func`] hands out.
pub fn is_build_class_builtin(obj: PyObjectRef) -> bool {
    if obj.is_null() || !unsafe { crate::function::is_function(obj) } {
        return false;
    }
    let code = unsafe { crate::function::function_get_code(obj) } as PyObjectRef;
    if code.is_null() || !unsafe { crate::gateway::is_builtin_code(code) } {
        return false;
    }
    let func = unsafe { crate::gateway::builtin_code_get(code) };
    crate::gateway::builtin_code_fn_eq(func, builtin_build_class as crate::gateway::BuiltinCodeFn)
}

/// `str(obj)` → convert to string
pub fn builtin_str(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (pos, kwargs) = split_builtin_kwargs(args);
    kwarg_reject_unknown(kwargs, &["object", "encoding", "errors"], "str")?;
    let kw_count = kwargs
        .map(|dict| unsafe {
            pyre_object::w_dict_str_entries_wtf8(dict)
                .iter()
                .filter(|(key, _)| key.as_str() != Ok("__pyre_kw__"))
                .count()
        })
        .unwrap_or(0);
    let arg_count = pos.len() + kw_count;
    if pos.len() > 3 {
        return Err(crate::PyError::type_error(format!(
            "str expected at most 3 arguments, got {}",
            pos.len()
        )));
    }
    if arg_count > 3 {
        return Err(crate::PyError::type_error(format!(
            "str() takes at most 3 arguments ({} given)",
            arg_count
        )));
    }
    // `str(object='', encoding='utf-8', errors='strict')` — every parameter
    // is positional-or-keyword (unicodeobject.py:descr_new).  An absent
    // `object` yields the empty string; an encoding/errors of None counts as
    // "not given".
    let mut obj = match resolve_pos_or_kw(pos.first().copied(), kwargs, "object", "str", 1)? {
        Some(o) => o,
        None => return Ok(w_str_new("")),
    };
    let w_encoding = resolve_pos_or_kw(pos.get(1).copied(), kwargs, "encoding", "str", 2)?;
    let w_errors = resolve_pos_or_kw(pos.get(2).copied(), kwargs, "errors", "str", 3)?;
    // `_get_encoding_and_errors` — a *supplied* encoding/errors must be a
    // str; an explicit `None` is supplied (not "omitted") and so is
    // rejected.  Encoding is validated before errors.
    if let Some(w) = w_encoding
        && !unsafe { is_str(w) }
    {
        let tn = crate::error::type_name_of(w);
        return Err(crate::PyError::type_error(format!(
            "str() argument 'encoding' must be str, not {tn}"
        )));
    }
    if let Some(w) = w_errors
        && !unsafe { is_str(w) }
    {
        let tn = crate::error::type_name_of(w);
        return Err(crate::PyError::type_error(format!(
            "str() argument 'errors' must be str, not {tn}"
        )));
    }
    let has_encoding = w_encoding.is_some();
    let has_errors = w_errors.is_some();
    if has_encoding || has_errors {
        if unsafe { is_str(obj) } {
            return Err(crate::PyError::type_error("decoding str is not supported"));
        }
        let Some(src) = crate::typedef::buffer_as_bytes_like(obj)? else {
            let tn = crate::error::type_name_of(obj);
            return Err(crate::PyError::type_error(format!(
                "decoding to str: need a bytes-like object, {tn} found"
            )));
        };
        // `descr_decode` reads an omitted encoding as utf-8
        // (stringmethods.py).  This positional shape cannot skip the
        // slot when `errors` follows it, so spell the default out: `decode`
        // refuses a literal `None` there like any other non-str.  The default
        // is a prebuilt: `w_str_new` is immortal, so wrapping it per call
        // would leak one string for every `str(b, errors=...)`.
        static DEFAULT_ENCODING: crate::warn::PrebuiltText = crate::warn::PrebuiltText::new();
        let mut decode_args = vec![
            src,
            w_encoding.unwrap_or_else(|| DEFAULT_ENCODING.get("utf-8")),
        ];
        if let Some(e) = w_errors {
            decode_args.push(e);
        }
        return crate::typedef::descr_decode(&decode_args);
    }
    // A tagged `int` immediate stringifies to its decimal value; format it
    // before `is_str` / `ob_type` touch it as a pointer.
    // Mirrors `py_str_wtf8` / `py_repr_obj`. Gated on `CAN_BE_TAGGED`.
    if pyre_object::tagged_int::CAN_BE_TAGGED && pyre_object::tagged_int::is_tagged_int(obj) {
        return Ok(pyre_object::w_str_new_managed(&format!(
            "{}",
            pyre_object::tagged_int::untag_int(obj)
        )));
    }
    unsafe {
        if is_str(obj) {
            // A `str` subclass keeps `ob_type` at STR_TYPE but carries the
            // Python class in `w_class`; honor its `__str__` override before
            // returning the raw value.
            let tp = (*obj).ob_type;
            // WTF-8-preserving so a `__str__` override returning a lone
            // surrogate yields that str rather than panicking.
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::builtin_subclass_dunder_obj(obj, tp, "__str__")
            )? {
                return Ok(r);
            }
            // `str(s) is s` only for an exact `str`; a subclass with no
            // `__str__` override is copied to a fresh base `str`.
            if is_exact_type(obj, &STR_TYPE) {
                return Ok(obj);
            }
            return Ok(pyre_object::w_str_from_wtf8_managed(
                pyre_object::w_str_get_wtf8(obj).to_owned(),
            ));
        }
    }
    unsafe {
        // A class object is an instance of its metaclass, so `space.str`
        // resolves `__str__` there before the `<class ...>` representation.
        if let Some(r) = pyre_object::with_roots!(obj =>
            crate::display::type_metaclass_dunder_obj(obj, "__str__")
        )? {
            return Ok(r);
        }
        if pyre_object::is_instance(obj) {
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::try_call_dunder_obj_above_object(obj, "__str__")
            )? {
                return Ok(r);
            }
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::try_call_dunder_obj(obj, "__repr__")
            )? {
                return Ok(r);
            }
        }
        // `space.str` returns an app-level `__str__` result object directly;
        // a str subclass is valid and retains its Python class. The WTF-8
        // conversion below is for builtin formatting, where a fresh base str
        // is the appropriate result object.
        if !obj.is_null() && pyre_object::is_exception(obj) {
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::exc_user_dunder_obj(obj, "__str__")
            )? {
                return Ok(r);
            }
            // `space.str(w_exc)` invokes the resolved exception descriptor
            // and returns its object result.  The diagnostic WTF-8 path below
            // is intentionally value-only; routing builtin `str()` through it
            // would copy `BaseException.args_w[0]` and break the upstream
            // `str(ValueError(s)) is s` identity rule.
            return exception_str_method(&[obj]);
        }
    }
    // Exact machine int: `intobject.py descr_str`.  A look-inside
    // call from this graph is what gives `descr_str` its own jitcode
    // so the walker can descend it.  A subclass keeps `ob_type` at
    // `INT_TYPE` and may override `__str__`; `is_int` is too wide.
    if unsafe {
        pyre_object::py_type_check(obj, &pyre_object::INT_TYPE)
            && pyre_object::is_exact_builtin_instance(obj)
    } {
        return Ok(unsafe { pyre_object::descr_str(obj) });
    }
    let w = unsafe { crate::py_str_wtf8(obj)? };
    // `StdObjSpace.str` returns the ordinary movable `space.newtext` result.
    // The input is fully consumed above, so only the newly built WTF-8 value
    // must be rooted across this terminal collecting header allocation.
    Ok(unsafe { pyre_object::w_str_from_wtf8_managed_collecting(w) })
}

unsafe fn py_repr_obj(mut obj: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    unsafe {
        if pyre_object::tagged_int::CAN_BE_TAGGED && pyre_object::tagged_int::is_tagged_int(obj) {
            return Ok(pyre_object::w_str_new_managed(&format!(
                "{}",
                pyre_object::tagged_int::untag_int(obj)
            )));
        }
        if !obj.is_null() {
            let tp = (*obj).ob_type;
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::builtin_subclass_dunder_obj(obj, tp, "__repr__")
            )? {
                return Ok(r);
            }
            if let Some(r) = pyre_object::with_roots!(obj =>
                crate::display::type_metaclass_dunder_obj(obj, "__repr__")
            )? {
                return Ok(r);
            }
            if pyre_object::is_instance(obj)
                && let Some(r) = pyre_object::with_roots!(obj =>
                    crate::display::try_call_dunder_obj(obj, "__repr__")
                )?
            {
                return Ok(r);
            }
        }
        Ok(pyre_object::w_str_from_wtf8_managed(
            crate::display::py_repr_wtf8(obj)?,
        ))
    }
}

/// `repr(obj)` → string representation
pub fn builtin_repr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "repr() takes exactly one argument ({} given)",
            args.len()
        )));
    }
    // WTF-8-preserving so a `__repr__` override returning a lone surrogate
    // yields that str rather than panicking in the `String` path.
    unsafe { py_repr_obj(args[0]) }
}

/// `unicodeobject.c:unicode_repr` post-pass — take the repr of `obj`
/// and escape every non-ASCII code point as `\xXX` / `\uXXXX` /
/// `\UXXXXXXXX`.  Shared by the `ascii()` builtin and the `!a`
/// `str.format` conversion.
fn ascii_escape_wtf8(s: &Wtf8) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.code_points() {
        let cp = ch.to_u32();
        if cp < 0x80 {
            out.push(char::from_u32(cp).unwrap());
        } else if cp <= 0xFF {
            out.push_str(&format!("\\x{cp:02x}"));
        } else if cp <= 0xFFFF {
            out.push_str(&format!("\\u{cp:04x}"));
        } else {
            out.push_str(&format!("\\U{cp:08x}"));
        }
    }
    out
}

pub(crate) fn py_ascii(obj: PyObjectRef) -> Result<String, crate::PyError> {
    let s = unsafe { crate::display::py_repr_wtf8(obj)? };
    Ok(ascii_escape_wtf8(&s))
}

pub(crate) fn py_ascii_obj(obj: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    let r = unsafe { py_repr_obj(obj)? };
    let r_wtf8 = unsafe { pyre_object::w_str_get_wtf8(r) };
    let out = ascii_escape_wtf8(r_wtf8);
    let changed = r_wtf8.as_str().map(|s| s != out).unwrap_or(true);
    if unsafe { is_exact_type(r, &STR_TYPE) } || changed {
        return Ok(w_str_new_managed(&out));
    }
    let Some(tp) = (unsafe { crate::typedef::r#type(r) }) else {
        return Ok(w_str_new_managed(&out));
    };
    let Some(new_fn) = (unsafe { crate::baseobjspace::lookup_in_type(tp.as_ptr(), "__new__") })
    else {
        return Ok(w_str_new_managed(&out));
    };
    crate::builtins::call_and_check(new_fn, &[tp.as_ptr(), w_str_new_managed(&out)])
}

/// `bltinmodule.c:builtin_ascii` — like `repr`, but escape every
/// non-ASCII code point in the repr as `\xXX` / `\uXXXX` / `\UXXXXXXXX`.
fn builtin_ascii(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "ascii() takes exactly one argument ({} given)",
            args.len()
        )));
    }
    py_ascii_obj(args[0])
}

/// `int(obj)` → convert to int
/// call_function with exception propagation.
/// PyPy's space.get_and_call_function returns normally or raises;
/// pyre's call_function stashes errors as PY_NULL. This helper
/// recovers stashed errors as Result.
pub fn call_and_check(
    method: PyObjectRef,
    args: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    let result = crate::call_function(method, args);
    if result == pyre_object::PY_NULL {
        if let Some(err) = crate::call::take_call_error() {
            return Err(err);
        }
        return Err(crate::PyError::type_error("call returned NULL"));
    }
    Ok(result)
}

/// intobject.py _new_baseint
pub fn builtin_int(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `int(x=0, base=10)` — `x` is positional-only (a `base` keyword is the
    // only one accepted), `base` is positional-or-keyword at position 2
    // (intobject.py descr_new).
    let (pos, kwargs) = split_builtin_kwargs(args);
    // `descr_new(space, w_inttype, w_x, __posonly__, w_base=None)` has two
    // user-visible slots.  PyPy's gateway rejects surplus positionals while
    // binding that signature, before `_new_int` runs; pyre's flat builtin
    // ABI must perform the same gateway check explicitly.
    if pos.len() > 2 {
        return Err(crate::PyError::type_error(format!(
            "int expected at most 2 arguments, got {}",
            pos.len()
        )));
    }
    kwarg_reject_unknown(kwargs, &["base"], "int")?;
    let w_base = resolve_pos_or_kw(pos.get(1).copied(), kwargs, "base", "int", 2)?;
    let mut obj = match pos.first().copied() {
        Some(o) => o,
        None => {
            // intobject.py:986 — a base without a value is a missing source.
            if w_base.is_some() {
                return Err(crate::PyError::type_error("int() missing string argument"));
            }
            return Ok(w_int_new(0));
        }
    };

    if w_base.is_none() {
        // intobject.py: space.is_w(space.type(w_value), space.w_int)
        let w_type = crate::typedef::r#type(obj);
        let w_int = crate::typedef::gettypefor(&INT_TYPE);
        if w_type.is_some() && w_type == w_int {
            return Ok(obj);
        }
        // intobject.py:994: space.lookup(w_value, '__int__')
        if unsafe { crate::baseobjspace::lookup(obj, "__int__") }.is_some() {
            // intobject.py: w_intvalue = space.int(w_value)
            let w_intvalue = pyre_object::with_roots!(obj => crate::baseobjspace::space_int(obj))?;
            return ensure_baseint_result(w_intvalue, obj);
        }
        // Python 3.14 difference: the deprecated `__trunc__` delegation in
        // this PyPy source was removed from `int()` after Python 3.11.  Our
        // language target is 3.14, so proceed directly to `__index__`.
        // intobject.py: space.lookup(w_value, '__index__')
        if unsafe { crate::baseobjspace::lookup(obj, "__index__") }.is_some() {
            // intobject.py:1016: w_obj = space.index(w_value)
            let w_obj = pyre_object::with_roots!(obj => crate::baseobjspace::space_index(obj))?;
            return ensure_baseint_result(w_obj, obj);
        }
        // intobject.py:1047 — unicode is normalized through
        // `unicode_to_decimal_w` so non-ASCII decimal digits parse.
        if unsafe { is_str(obj) } {
            let normalized = pyre_object::with_roots!(obj => unicode_to_decimal_w(obj))
                .map_err(|_| invalid_int_literal(obj, 10))?;
            return parse_int_from_str(obj, &normalized, 10);
        }
        // intobject.py:1056-1070 — bytes / bytearray, then any object
        // exposing a readable buffer (`space.charbuf_w`).
        if let Some(src) = crate::typedef::buffer_as_bytes_like(obj)? {
            let data = unsafe { pyre_object::bytesobject::bytes_like_data(src) }.to_vec();
            let s = String::from_utf8_lossy(&data);
            return parse_int_from_str(obj, &s, 10);
        }
        return Err(crate::PyError::type_error(format!(
            "int() argument must be a string, a bytes-like object or a real number, not '{}'",
            crate::type_methods::arg_type_name(obj)
        )));
    }

    // intobject.py:1051-1072: w_base is not None — parse with base
    let base = pyre_object::with_roots!(obj => getindex_w_for_base(w_base.unwrap()))?;
    unsafe {
        // intobject.py:1079 — unicode normalized through `unicode_to_decimal_w`.
        if is_str(obj) {
            let normalized = pyre_object::with_roots!(obj => unicode_to_decimal_w(obj))
                .map_err(|_| invalid_int_literal(obj, base))?;
            return parse_int_from_str(obj, &normalized, base);
        }
        // With an explicit base only str / bytes / bytearray are accepted.
        if pyre_object::bytesobject::is_bytes_like(obj) {
            let data = pyre_object::bytesobject::bytes_like_data(obj).to_vec();
            let s = String::from_utf8_lossy(&data);
            return parse_int_from_str(obj, &s, base);
        }
    }
    Err(crate::PyError::type_error(
        "int() can't convert non-string with explicit base",
    ))
}

/// intobject.py _ensure_baseint
fn ensure_baseint_result(
    obj: PyObjectRef,
    _original: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    unsafe {
        if is_int(obj) {
            // intobject.py: W_IntObject (or subclass) → wrapint
            return Ok(w_int_new(w_int_get_value(obj)));
        }
        if pyre_object::pyobject::is_long(obj) {
            // intobject.py:1100-1102: W_AbstractLongObject → newlong
            return Ok(pyre_object::longobject::w_long_from_raw(
                pyre_object::longobject::w_long_get_raw_value(obj),
            ));
        }
    }
    // intobject.py:1104-1107: shouldn't happen
    Err(crate::PyError::new(
        crate::PyErrorKind::RuntimeError,
        "internal error in int.__new__()".to_string(),
    ))
}

/// baseobjspace.py space.getindex_w(w_base, None)
///
/// Calls __index__() on w_base and converts to i64.
/// On OverflowError (long that doesn't fit i64), returns 37 sentinel
/// (intobject.py:1057: causes ValueError in string_to_bigint).
fn getindex_w_for_base(w_base: PyObjectRef) -> Result<u32, crate::PyError> {
    let value = getindex_w(w_base)?;
    if value < 0 || value == 1 || value > 36 {
        return Err(crate::PyError::new(
            crate::PyErrorKind::ValueError,
            "int() base must be >= 2 and <= 36, or 0".to_string(),
        ));
    }
    Ok(value as u32)
}

/// baseobjspace.py space.getindex_w(w_obj, None)
///
/// Return w_obj.__index__() as i64. On overflow, clamp to i64::MAX
/// (w_exception=None path).
pub fn getindex_w(mut w_obj: PyObjectRef) -> Result<i64, crate::PyError> {
    unsafe {
        if is_int(w_obj) {
            return Ok(w_int_get_value(w_obj));
        }
        if pyre_object::pyobject::is_long(w_obj) {
            // baseobjspace.py: try int_w, on overflow clamp to
            // -sys.maxint-1 for a negative value, sys.maxint otherwise.
            let big = pyre_object::longobject::w_long_get_value(w_obj);
            return Ok(
                if pyre_object::longobject::jit_bigint_to_i64_fits(big) != 0 {
                    pyre_object::longobject::jit_bigint_to_i64_value(big)
                } else if pyre_object::longobject::jit_bigint_sign_i64(big) < 0 {
                    i64::MIN
                } else {
                    i64::MAX
                },
            );
        }
        // baseobjspace.py: w_index = self.index(w_obj)
        if let Some(method) = crate::baseobjspace::lookup(w_obj, "__index__") {
            let w_index = pyre_object::with_roots!(w_obj => call_and_check(method, &[w_obj]))?;
            if is_int(w_index) {
                return Ok(w_int_get_value(w_index));
            }
            if pyre_object::pyobject::is_long(w_index) {
                let big = pyre_object::longobject::w_long_get_value(w_index);
                return Ok(
                    if pyre_object::longobject::jit_bigint_to_i64_fits(big) != 0 {
                        pyre_object::longobject::jit_bigint_to_i64_value(big)
                    } else if pyre_object::longobject::jit_bigint_sign_i64(big) < 0 {
                        i64::MIN
                    } else {
                        i64::MAX
                    },
                );
            }
        }
    }
    Err(crate::PyError::type_error(format!(
        "'{}' object cannot be interpreted as an integer",
        unsafe { (*(*w_obj).ob_type).name }
    )))
}

/// `unicodeobject.py unicode_to_decimal_w` — normalize a unicode string for
/// numeric parsing: a non-ASCII decimal digit (`Numeric_Type=Decimal`)
/// becomes its ASCII digit and non-ASCII whitespace becomes a space, so
/// `int("４２")` and `float("١٫٥")`-style inputs parse.  An all-ASCII string
/// is returned untouched.
fn unicode_to_decimal_w(w_unistr: PyObjectRef) -> Result<String, crate::PyError> {
    let utf8 = unsafe { w_str_get_wtf8(w_unistr) };
    if let Ok(s) = utf8.as_str()
        && s.is_ascii()
    {
        // Copy off the nursery unicode buffer. A borrowed `&str` is not
        // forwarded when a later digit allocation collects.
        return Ok(s.to_string());
    }

    // unicodeobject.py `_unicode_to_decimal_w`: iterate the internal UTF-8
    // representation by code point, translate Unicode decimal digits and
    // whitespace, then encode each result as strict UTF-8.  WTF-8 exposes the
    // same surrogate-bearing representation as RPython's rutf8 iterator.
    let ucd = rustpython_unicode::Ucd::new(true);
    let mut out = String::with_capacity(utf8.len());
    for (pos, cp) in utf8.code_points().enumerate() {
        let mut c = cp;
        if c.to_u32() > 127 {
            let Some(ch) = c.to_char() else {
                return Err(crate::typedef::unicode_encode_error(
                    "utf-8",
                    w_unistr,
                    pos as i64,
                    (pos + 1) as i64,
                    "surrogates not allowed",
                ));
            };
            if ch.is_whitespace() {
                out.push(' ');
                continue;
            }
            if let Some(v) = ucd.decimal(c) {
                c = CodePoint::from((b'0' + v as u8) as char);
            }
        }
        let Some(ch) = c.to_char() else {
            return Err(crate::typedef::unicode_encode_error(
                "utf-8",
                w_unistr,
                pos as i64,
                (pos + 1) as i64,
                "surrogates not allowed",
            ));
        };
        out.push(ch);
    }
    Ok(out)
}

/// `wrap_parsestringerror(space, e, w_source)` — report the original Python
/// source object, not the whitespace-trimmed or Unicode-normalized buffer the
/// number parser consumes internally.
fn invalid_int_literal(w_source: PyObjectRef, base: u32) -> crate::PyError {
    // `%.200R` clips the rendering at 200 code points, closing quote included
    // — a long literal is reported unterminated.
    const MAX_REPR_CODE_POINTS: usize = 200;
    // `_PyLong_FromBytes` renders the buffer it was handed through a fresh
    // `PyBytes_FromStringAndSize`, so a `bytearray` — or a subclass of either
    // — reports its contents as `b'-'` rather than its own repr.
    let rendered = if unsafe { pyre_object::bytesobject::is_bytes_like(w_source) } {
        // Copy the contents out before allocating: the source is free to move
        // while the new object is built.
        let clipped = unsafe {
            let data = pyre_object::bytesobject::bytes_like_data(w_source);
            data[..data.len().min(MAX_REPR_CODE_POINTS)].to_vec()
        };
        pyre_object::bytesobject::w_bytes_from_bytes(&clipped)
    } else {
        w_source
    };
    let source_repr = unsafe { crate::display::py_repr_wtf8(rendered) }
        .unwrap_or_else(|_| rustpython_wtf8::Wtf8Buf::from_string("<unprintable>".to_string()));
    let mut clipped = rustpython_wtf8::Wtf8Buf::new();
    for point in source_repr.code_points().take(MAX_REPR_CODE_POINTS) {
        clipped.push(point);
    }
    crate::PyError::value_error(crate::display::wtf8_format!(
        format!("invalid literal for int() with base {base}: "),
        clipped
    ))
}

/// Parse an integer from a string with the given base.
pub fn parse_int_from_str(
    w_source: PyObjectRef,
    s: &str,
    base: u32,
) -> Result<PyObjectRef, crate::PyError> {
    let _source_roots = pyre_object::gc_roots::push_roots();
    let source_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_source);
    let w_source = || pyre_object::gc_roots::shadow_stack_get(source_slot);
    // NumberStringParser stores an interior `&str`. Digit allocation can
    // collect and move a nursery unicode buffer; parse from a Rust copy.
    let owned = s.to_string();
    let s = owned.as_str();
    // rarithmetic.py `string_to_int` first handles short, plain
    // decimal strings without constructing a NumberStringParser.
    const OVF_DIGITS: usize = 19; // len(str(sys.maxint)) on pyre's i64 target
    if base == 10 && !s.is_empty() && s.len() < OVF_DIGITS {
        let bytes = s.as_bytes();
        let (start, sign) = match bytes[0] {
            b'-' => (1, -1_i64),
            b'+' => (1, 1_i64),
            _ => (0, 1_i64),
        };
        if start != bytes.len() {
            let mut result = 0_i64;
            let mut all_decimal = true;
            for &byte in &bytes[start..] {
                if !byte.is_ascii_digit() {
                    all_decimal = false;
                    break;
                }
                result = result * 10 + (byte - b'0') as i64;
            }
            if all_decimal {
                return Ok(w_int_new(result * sign));
            }
        }
    }

    // intobject.py `_string_to_int_or_long` constructs the one
    // NumberStringParser used by both the machine-int attempt and the
    // rbigint overflow retry.  Do not maintain a second parser here: it
    // diverges on prefix/underscore ordering and erases rbigint allocation
    // failures into an "invalid literal" error.
    let maxdigits = if base == 0 || base.is_power_of_two() {
        0
    } else {
        crate::module::sys::state::int_max_str_digits()
    };
    let mut parser =
        majit_rlib::rbigint::NumberStringParser::new(s, base as i64, true, true, 0, None, 0, true)
            .map_err(|error| match error {
                majit_rlib::rbigint::RBigIntError::Memory => crate::PyError::memory_error(""),
                _ => invalid_int_literal(w_source(), base),
            })?;

    // NumberStringParser performs this check immediately after its structural
    // initialization.  Constructing it with a zero limit lets us retain
    // PyPy's `MaxDigitsError.digits` value in the application-level message.
    if maxdigits != 0 {
        let digit_count =
            parser.end - parser.start - s.bytes().filter(|&c| c == b'_').count() as i64;
        if digit_count > maxdigits as i64 {
            return Err(crate::PyError::value_error(format!(
                "Exceeds the limit ({maxdigits} digits) for integer string conversion: value has {digit_count} digits; use sys.set_int_max_str_digits() to increase the limit"
            )));
        }
    }

    // rarithmetic.py:962-977 accumulates a signed machine word and hands the
    // same rewound parser to rbigint only after `ovfcheck` fails.
    let parsed_base = parser.base;
    let parsed_sign = parser.sign;
    let mut machine_value = 0_i64;
    loop {
        let digit = parser.next_digit().map_err(|error| match error {
            majit_rlib::rbigint::RBigIntError::Memory => crate::PyError::memory_error(""),
            _ => invalid_int_literal(w_source(), base),
        })?;
        if digit < 0 {
            return Ok(w_int_new(machine_value));
        }
        let signed_digit = if parsed_sign < 0 { -digit } else { digit };
        let Some(value) = machine_value
            .checked_mul(parsed_base)
            .and_then(|value| value.checked_add(signed_digit))
        else {
            parser.rewind();
            break;
        };
        machine_value = value;
    }

    let value = BigInt::_from_numberstring_parser(&mut parser).map_err(|error| match error {
        majit_rlib::rbigint::RBigIntError::Memory => crate::PyError::memory_error(""),
        majit_rlib::rbigint::RBigIntError::MaxStrDigits => unreachable!("limit checked above"),
        _ => invalid_int_literal(w_source(), base),
    })?;
    Ok(w_long_new(value))
}

/// The error every decimal `int` conversion raises once the result would
/// exceed `sys.get_int_max_str_digits()` digits.
pub(crate) fn int_max_str_digits_error(maxdigits: i32) -> crate::PyError {
    crate::PyError::value_error(format!(
        "Exceeds the limit ({maxdigits} digits) for integer string conversion; use sys.set_int_max_str_digits() to increase the limit"
    ))
}

/// PyPy `W_AbstractLongObject.descr_str` / Python 3.14 integer-to-decimal
/// conversion guard. The bit-length lower bound rejects enormous values
/// before the quadratic decimal conversion; the resulting string supplies
/// the exact boundary check.
pub unsafe fn int_to_decimal_string(obj: PyObjectRef) -> Result<String, crate::PyError> {
    let owned;
    let value = if pyre_object::is_bool(obj) {
        owned = BigInt::from(pyre_object::w_bool_get_value(obj) as i64);
        &owned
    } else if pyre_object::is_int(obj) {
        owned = BigInt::from(pyre_object::w_int_get_value(obj));
        &owned
    } else {
        debug_assert!(pyre_object::is_long(obj));
        pyre_object::w_long_get_value(obj)
    };
    let maxdigits = crate::module::sys::state::int_max_str_digits();
    let too_long = int_max_str_digits_error;
    if maxdigits != 0 {
        let bits = value.bits();
        let decimal_digits_lower_bound = if bits == 0 {
            1u64
        } else {
            ((bits - 1).saturating_mul(30_103u64) / 100_000u64) + 1u64
        };
        if decimal_digits_lower_bound > maxdigits as u64 {
            return Err(too_long(maxdigits));
        }
    }
    // longobject.py calls `self.asbigint().str(max_str_digits=...)`.
    // Going through Rust's Display/ToString adapter erases rbigint's
    // MaxIntError and MemoryError edges (and can turn either into a formatting
    // panic), so preserve the direct consumer contract.
    match value.str(maxdigits as i64) {
        Ok(text) => Ok(text),
        Err(majit_rlib::rbigint::RBigIntError::MaxStrDigits) => Err(too_long(maxdigits)),
        Err(majit_rlib::rbigint::RBigIntError::Memory) => Err(crate::PyError::memory_error("")),
        Err(_) => unreachable!("rbigint.str returned an unrelated error"),
    }
}

/// Remove PEP 515 underscore digit separators, rejecting any underscore
/// that is not flanked by two ASCII digits — `_Py_string_to_number_with_
/// underscores`. Returns `None` for an invalid placement (leading,
/// trailing, doubled, or adjacent to `.`/`e`/sign).
fn strip_numeric_underscores(s: &str) -> Option<String> {
    if !s.contains('_') {
        return Some(s.to_string());
    }
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(chars.len());
    for i in 0..chars.len() {
        let c = chars[i];
        if c == '_' {
            let prev_digit = i > 0 && chars[i - 1].is_ascii_digit();
            let next_digit = i + 1 < chars.len() && chars[i + 1].is_ascii_digit();
            if prev_digit && next_digit {
                continue;
            }
            return None;
        }
        out.push(c);
    }
    Some(out)
}

/// `float.__float__(self)` — floatobject.py descr___float__: an exact float
/// is returned as-is; a strict subclass is down-converted to a fresh base
/// `float`.  Kept separate from the `float()` constructor so `float()` can look
/// `__float__` up on a subclass (honoring an override) without recursing.
pub(crate) fn builtin_float_dunder(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = args[0];
    unsafe {
        if is_exact_type(obj, &FLOAT_TYPE) {
            return Ok(obj);
        }
        if is_float(obj) {
            return Ok(floatobject::w_float_new(w_float_get_value(obj)));
        }
    }
    // interp2app(W_FloatObject.descr_float) requires a float `self`.
    Err(crate::PyError::type_error(format!(
        "descriptor '__float__' requires a 'float' object but received a '{}'",
        crate::type_methods::arg_type_name(obj)
    )))
}

/// The `int` payload as a double, or `None` when `obj` is not an int by layout.
///
/// Reads the payload of a strict subclass too.  `PyLong_AsDouble` is a layout
/// read, and an inherited `int.__float__` has to reproduce it: the exactness
/// gates on the coercion entry points send a subclass to a `__float__` lookup,
/// and this is what that lookup resolves to.
pub fn int_payload_as_f64(obj: PyObjectRef) -> Option<Result<f64, crate::PyError>> {
    unsafe {
        // `is_int` is true for a bool (`BOOL_TYPE`), so test `is_bool` first.
        if is_bool(obj) {
            return Some(Ok(if w_bool_get_value(obj) { 1.0 } else { 0.0 }));
        }
        if is_int(obj) {
            return Some(Ok(w_int_get_value(obj) as f64));
        }
        if pyre_object::is_long(obj) {
            // `rbigint.tofloat()` raises when the value does not fit a double.
            let v = pyre_object::jit_bigint_to_f64_or_nan(pyre_object::w_long_get_value(obj));
            if !v.is_finite() {
                return Some(Err(crate::PyError::overflow_error(
                    "int too large to convert to float",
                )));
            }
            return Some(Ok(v));
        }
    }
    None
}

/// `int.__float__(self)` — longobject.py `descr___float__`, which converts the
/// receiver's payload and never re-dispatches.  `bool` inherits it.
///
/// Kept separate from the `float()` constructor for the reason
/// [`builtin_float_dunder`] gives: the constructor looks `__float__` up on a
/// strict subclass so an override is honored, so binding this name to the
/// constructor makes a subclass that does *not* override it re-enter the very
/// lookup that reached here.
pub(crate) fn builtin_int_float_dunder(
    args: &[PyObjectRef],
) -> Result<PyObjectRef, crate::PyError> {
    let mut obj = args[0];
    match pyre_object::with_roots!(obj => int_payload_as_f64(obj)) {
        Some(value) => Ok(floatobject::w_float_new(value?)),
        None => Err(crate::PyError::type_error(format!(
            "descriptor '__float__' requires a 'int' object but received a '{}'",
            crate::type_methods::arg_type_name(obj)
        ))),
    }
}

/// `float(obj)` → convert to float
pub fn builtin_float(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(floatobject::w_float_new(0.0));
    }
    // Skip `cls` if called via `float.__new__(cls, value)`.
    let value_idx = if args.len() >= 2 && unsafe { pyre_object::is_type(args[0]) } {
        1
    } else {
        0
    };
    if value_idx >= args.len() {
        return Ok(floatobject::w_float_new(0.0));
    }
    let mut obj = args[value_idx];
    unsafe {
        if is_float(obj) {
            // `float(f) is f` for an exact `float`. A subclass falls through
            // to the `__float__` lookup below so an overridden `__float__` is
            // honored; a subclass that does not override it resolves to
            // `float.__float__`, which returns a fresh base `float`.
            if is_exact_type(obj, &FLOAT_TYPE) {
                return Ok(obj);
            }
        } else if is_int(obj) && is_exact_type(obj, &INT_TYPE) {
            // Exact only, for the reason the `float` arm above gives: an `int`
            // subtype falls through to the `__float__` lookup so an override
            // is honored, and resolves to `int.__float__` when there is none.
            // `is_exact_type` answers on `w_class`, which a bigint shares with
            // `int`, so `is_int` (which reads `ob_type`) is what separates the
            // two layouts here.
            return Ok(floatobject::w_float_new(w_int_get_value(obj) as f64));
        }
        if is_bool(obj) {
            return Ok(floatobject::w_float_new(if w_bool_get_value(obj) {
                1.0
            } else {
                0.0
            }));
        }
        if pyre_object::is_long(obj) && is_exact_type(obj, &INT_TYPE) {
            // A Python int is finite, so a non-finite conversion means the
            // magnitude exceeds f64 range.
            let v = pyre_object::jit_bigint_to_f64_or_nan(pyre_object::w_long_get_value(obj));
            if !v.is_finite() {
                return Err(crate::PyError::overflow_error(
                    "int too large to convert to float",
                ));
            }
            return Ok(floatobject::w_float_new(v));
        }
    }
    // descroperation.py float — type-MRO __float__ then __index__
    if let Some(tp) = crate::typedef::r#type(obj) {
        if let Some((_, method)) =
            unsafe { crate::baseobjspace::lookup_where_with_method_cache(tp.as_ptr(), "__float__") }
        {
            let mut result = unsafe {
                pyre_object::with_roots!(obj =>
                    crate::baseobjspace::get_and_call_function(method, obj, tp.as_ptr(), &[])
                )?
            };
            unsafe {
                if is_float(result) {
                    // floatobject.py:228-238 — an exact float is returned as-is;
                    // a strict subclass warns (deprecated) and is converted to a
                    // base float value.
                    if is_exact_type(result, &FLOAT_TYPE) {
                        return Ok(result);
                    }
                    let value_type = crate::type_methods::arg_type_name(obj);
                    let result_type = crate::type_methods::arg_type_name(result);
                    pyre_object::with_roots!(result => crate::warn::warn_deprecation(&format!(
                        "{value_type}.__float__ returned non-float (type {result_type}).  \
                         The ability to return an instance of a strict subclass of \
                         float is deprecated, and may be removed in a future version \
                         of Python."
                    )))?;
                    return Ok(floatobject::w_float_new(w_float_get_value(result)));
                }
            }
            // `_PyNumber_Float` names the receiver's class as well, and neither
            // name is quoted; the deprecation above already reads that way.
            // `descroperation.py float_w` names only the result, in quotes.
            let value_type = crate::type_methods::arg_type_name(obj);
            let result_type = crate::type_methods::arg_type_name(result);
            return Err(crate::PyError::type_error(format!(
                "{value_type}.__float__ returned non-float (type {result_type})",
            )));
        }
        if let Some((_, method)) =
            unsafe { crate::baseobjspace::lookup_where_with_method_cache(tp.as_ptr(), "__index__") }
        {
            let r = unsafe {
                crate::baseobjspace::get_and_call_function(method, obj, tp.as_ptr(), &[])?
            };
            // descroperation.py `space.index` returns an arbitrary-size
            // Python int.  Accept both the machine-word and W_LongObject
            // layouts, then reuse the integer float conversion so an
            // out-of-range bigint raises `OverflowError`.
            unsafe {
                if is_int(r) || is_bool(r) || pyre_object::is_long(r) {
                    return builtin_float(&[r]);
                }
            }
            let result_type = unsafe { (*(*r).ob_type).name };
            return Err(crate::PyError::type_error(format!(
                "__index__ returned non-int (type '{result_type}')",
            )));
        }
    }
    // floatobject.py — only after the `__float__` / `__index__` lookup,
    // unicode (including subclasses without a numeric override) is normalized
    // through `unicode_to_decimal_w` before `_string_to_float`.
    if unsafe { is_str(obj) } {
        let s = unsafe { pyre_object::with_roots!(obj => unicode_to_decimal_w(obj))? };
        // `float_from_string` strips PEP 515 underscore separators (between
        // digits only) before parsing the Python-literal float grammar.
        if let Some(cleaned) = strip_numeric_underscores(s.trim())
            && let Some(v) = rustpython_literal::float::parse_str(&cleaned)
        {
            return Ok(floatobject::w_float_new(v));
        }
        // floatobject.py `_string_to_float`: `%R` uses the original source's
        // repr, preserving quotes and escaping controls/NUL/non-ASCII text.
        let source_repr = unsafe { crate::display::py_repr_wtf8(obj)? };
        return Err(crate::PyError::value_error(crate::display::wtf8_format!(
            "could not convert string to float: ",
            source_repr
        )));
    }
    // floatobject.py:247-255 — a readable buffer (`charbuf_w`: bytes /
    // bytearray / array / memoryview) is decoded and parsed like a str; an
    // unparseable value reprs as `b'...'` in the error (space.repr / `%R`).
    if let Some(src) = crate::typedef::buffer_as_bytes_like(obj)? {
        let data = unsafe { pyre_object::bytesobject::bytes_like_data(src) };
        let decoded = String::from_utf8_lossy(data);
        if let Some(cleaned) = strip_numeric_underscores(decoded.trim())
            && let Ok(v) = cleaned.parse::<f64>()
        {
            return Ok(floatobject::w_float_new(v));
        }
        let r = unsafe { crate::display::py_repr_wtf8(obj)? };
        return Err(crate::PyError::value_error(crate::display::wtf8_format!(
            "could not convert string to float: ",
            r
        )));
    }
    // The message uses the modern "real number" wording (3.14) rather than
    // the older "a number" phrasing.
    Err(crate::PyError::type_error(format!(
        "float() argument must be a string or a real number, not '{}'",
        crate::type_methods::arg_type_name(obj)
    )))
}

/// The attribute-name check mirroring `operation.py checkattrname`
/// (accept `str` and any `str` subclass via `isinstance_w`), raising
/// `"attribute name must be string, not '<type>'"`. getattr/hasattr/
/// setattr/delattr all route through it, matching `operation.py` (and the
/// unified 3.12+ message).
fn checkattrname(w_name: PyObjectRef) -> Result<(), crate::PyError> {
    if !unsafe { crate::baseobjspace::isinstance_str_w(w_name) } {
        let name_type = crate::error::type_name_of(w_name);
        return Err(crate::PyError::type_error(format!(
            "attribute name must be string, not '{name_type}'",
        )));
    }
    Ok(())
}

/// `operation.py hasattr(obj, name)` → bool: `checkattrname`, then
/// (unlike Py2) only an `AttributeError` yields `False`; any other error
/// propagates.
fn builtin_hasattr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "hasattr() takes exactly two arguments ({} given)",
            args.len()
        )));
    }
    let obj = args[0];
    checkattrname(args[1])?;
    match crate::baseobjspace::lookup_attr(obj, args[1]) {
        Ok(_) => Ok(w_bool_from(true)),
        Err(e) if e.kind == crate::PyErrorKind::AttributeError => Ok(w_bool_from(false)),
        Err(e) => Err(e),
    }
}

/// `getattr(obj, name[, default])` → value — direct call
fn builtin_getattr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "getattr() takes no keyword arguments",
        ));
    }
    // `getattr(object, name[, default])`: two or three app-level arguments.
    if args.len() < 2 {
        return Err(crate::PyError::type_error(format!(
            "getattr expected at least 2 arguments, got {}",
            args.len()
        )));
    }
    if args.len() > 3 {
        return Err(crate::PyError::type_error(format!(
            "getattr expected at most 3 arguments, got {}",
            args.len()
        )));
    }
    let obj = args[0];
    checkattrname(args[1])?;
    // operation.py:58-64: the default replaces the error ONLY when a default
    // was supplied AND the error is an AttributeError; other errors (and the
    // no-default case) propagate.  With a default the error never surfaces,
    // so that arm runs suppressed (`_PyObject_LookupAttr`).
    if args.len() > 2 {
        // `args` is a native slice the gateway copied out of its own root
        // slots: the pin keeps the default alive, but nothing rewrites this
        // copy, and `lookup_attr` runs Python (`__getattr__`,
        // `__getattribute__`, a property getter).  A list or dict default
        // moves, so returning `args[2]` after the lookup hands back a pre-move
        // address.  Scope the slot to the three-argument form: `pin_root` and
        // `RootScope::get` are `dont_look_inside`, and the two-argument shape
        // is the one the tracer folds.
        let default_root = pyre_object::gc_roots::push_roots();
        let base = default_root.pin_roots(&[obj, args[1], args[2]]);
        return match crate::baseobjspace::lookup_attr(
            default_root.get(base),
            default_root.get(base + 1),
        ) {
            Ok(val) => Ok(val),
            Err(e) if e.kind == crate::PyErrorKind::AttributeError => {
                Ok(default_root.get(base + 2))
            }
            Err(e) => Err(e),
        };
    }
    crate::baseobjspace::getattr(obj, args[1])
}

/// `pypy/module/__builtin__/operation.py setattr`:
///
/// ```python
/// def setattr(space, w_object, w_name, w_val):
///     w_name = checkattrname(space, w_name)
///     space.setattr(w_object, w_name, w_val)
///     return space.w_None
/// ```
///
/// The space-level `setattr` may raise (AttributeError on read-only
/// descriptors, TypeError on wrong-type values, etc.) and PyPy
/// propagates those errors — they are NOT swallowed here.
fn builtin_setattr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 3 {
        return Err(crate::PyError::type_error(format!(
            "setattr() takes exactly three arguments ({} given)",
            args.len()
        )));
    }
    let obj = args[0];
    checkattrname(args[1])?;
    crate::baseobjspace::setattr(obj, args[1], args[2])?;
    Ok(w_none())
}

/// `delattr(obj, name)` — PyPy: baseobjspace.py delattr
fn builtin_delattr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "delattr() takes exactly 2 arguments ({} given)",
            args.len()
        )));
    }
    let obj = args[0];
    checkattrname(args[1])?;
    crate::baseobjspace::delattr(obj, args[1])?;
    Ok(w_none())
}

pub(crate) fn builtin_tuple(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `tuple.__new__` is positional-only, so any keyword is a TypeError
    // (an empty `**{}` is not a keyword and is allowed).
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "tuple() takes no keyword arguments",
        ));
    }
    if args.is_empty() {
        return Ok(w_tuple_new(vec![]));
    }
    let obj = args[0];
    unsafe {
        // `tuple(t)` returns `t` unchanged only for an EXACT tuple
        // (`PyTuple_CheckExact`); a tuple subclass must be re-iterated
        // through its (possibly overridden) `__iter__`, and the raw
        // storage fast paths below likewise apply only to exact
        // tuple/list instances.
        if is_exact_tuple(obj) {
            return Ok(obj);
        }
        if is_exact_list(obj) {
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(obj);
            let n = w_list_len(pyre_object::gc_roots::shadow_stack_get(obj_slot));
            let mut items = pyre_object::gc_roots::RootedItems::new();
            for i in 0..n {
                if let Some(item) =
                    w_list_getitem(pyre_object::gc_roots::shadow_stack_get(obj_slot), i as i64)
                {
                    items.push(item);
                }
            }
            return Ok(w_tuple_new(items.take()));
        }
    }
    let items = collect_iterable(obj)?;
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&items);
    Ok(w_tuple_new(
        (0..items.len())
            .map(|i| pyre_object::gc_roots::shadow_stack_get(base + i))
            .collect(),
    ))
}

pub fn builtin_list_ctor(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `list.__new__` is positional-only, so any keyword is a TypeError
    // (an empty `**{}` is not a keyword and is allowed).
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "list() takes no keyword arguments",
        ));
    }
    if args.is_empty() {
        return Ok(w_list_new(vec![]));
    }
    // CPython `list_vectorcall_impl` allocates an empty list then delegates to
    // the same `list_extend` machinery as `list.__init__`. Keep both the source
    // and result rooted across that allocation and the iterator callbacks.
    let _roots = pyre_object::gc_roots::push_roots();
    let root_base = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    let list = w_list_new(vec![]);
    let _ = pyre_object::gc_roots::pin_root(list);
    crate::type_methods::list_method_extend(&[
        pyre_object::gc_roots::shadow_stack_get(root_base + 1),
        pyre_object::gc_roots::shadow_stack_get(root_base),
    ])?;
    Ok(pyre_object::gc_roots::shadow_stack_get(root_base + 1))
}

/// The message-less `MemoryError` an unsatisfiable reservation raises.
pub fn reservation_failed() -> crate::PyError {
    crate::PyError::memory_error("")
}

/// `_PY_READ_MAX` — the largest count one raw read is asked for.
///
/// `read(2)`'s count is an `int` on Windows, and a count above `INT_MAX` fails
/// with `EINVAL` on macOS, so both clamp there; elsewhere the whole
/// `Py_ssize_t` range goes through untouched.
#[cfg(any(windows, target_os = "macos"))]
pub const PY_READ_MAX: i64 = i32::MAX as i64;
#[cfg(not(any(windows, target_os = "macos")))]
pub const PY_READ_MAX: i64 = isize::MAX as i64;

/// An empty `Vec` with room for `count` elements, reserved fallibly.
///
/// A builtin that sizes its storage from a Python-supplied count —
/// `itertools.combinations([], sys.maxsize)`, `b'a'.rjust(sys.maxsize)` and
/// their neighbours — cannot use `Vec::with_capacity`: an oversized request
/// aborts the process instead of unwinding, so ordinary Python code
/// terminates the interpreter. PyPy answers those calls with `MemoryError`.
pub fn try_vec_with_capacity<T>(count: usize) -> Result<Vec<T>, crate::PyError> {
    let mut out = Vec::new();
    out.try_reserve_exact(count)
        .map_err(|_| reservation_failed())?;
    Ok(out)
}

/// A zero-filled `Vec<u8>` of `count` bytes, for a `count` that came from
/// Python.
///
/// `vec![0u8; count]` reaches Rust's infallible allocator, which ends the
/// process where `PyBytes_FromStringAndSize(NULL, count)` answers
/// `MemoryError`.
pub fn try_vec_zeroed(count: usize) -> Result<Vec<u8>, crate::PyError> {
    let mut out = try_vec_with_capacity::<u8>(count)?;
    out.resize(count, 0);
    Ok(out)
}

/// `objectmodel.newlist_hint` for a `PyObjectRef` item list.
///
/// RPython handles `newlist_hint` through an ExtRegistry specialization:
/// translation does not inspect the helper body, but emits
/// `LIST.ll_newlist_hint` directly.  Rust generic calls are monomorphized into
/// their caller before the LLBC front end sees them, so this non-generic seam
/// carries the equivalent translation boundary. `flowspace_adapter` replaces
/// the call with `newlist_hint`; generated JitCode never residualizes it.
#[majit_macros::dont_look_inside]
pub fn try_pyobject_vec_with_capacity(count: usize) -> Result<Vec<PyObjectRef>, crate::PyError> {
    try_vec_with_capacity(count)
}

/// The `Wtf8Buf` counterpart of [`try_vec_with_capacity`], for the str
/// methods that size their buffer from a caller-supplied `width`.
pub fn try_wtf8_with_capacity(
    byte_count: usize,
) -> Result<rustpython_wtf8::Wtf8Buf, crate::PyError> {
    let mut out = rustpython_wtf8::Wtf8Buf::new();
    out.try_reserve_exact(byte_count)
        .map_err(|_| reservation_failed())?;
    Ok(out)
}

pub fn collect_iterable(obj: PyObjectRef) -> Result<Vec<PyObjectRef>, crate::PyError> {
    // `iter(obj)` itself can execute arbitrary allocating Python code.  Root
    // the input before that first collection point, matching the root that
    // RPython's shadowstack transform emits around `space.iter`.
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let it = crate::baseobjspace::iter(pyre_object::gc_roots::shadow_stack_get(obj_slot))?;
    collect_iterator(it)
}

/// `PySequence_Fast(seq, msg)` — materialise `seq`, replacing only the
/// `TypeError` raised while obtaining the iterator with `msg`.  A `TypeError`
/// the iterator raises later keeps its own message, and every other error
/// propagates unchanged.
pub(crate) fn sequence_fast(
    obj: PyObjectRef,
    msg: &str,
) -> Result<Vec<PyObjectRef>, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let it = match crate::baseobjspace::iter(pyre_object::gc_roots::shadow_stack_get(obj_slot)) {
        Ok(it) => it,
        Err(e) if e.kind == crate::PyErrorKind::TypeError => {
            return Err(crate::PyError::type_error(msg));
        }
        Err(e) => return Err(e),
    };
    collect_iterator(it)
}

/// Consume an iterator that has already been obtained.  Kept separate from
/// [`collect_iterable`] for CPython `PySequence_Fast` parity: callers such as
/// dict sequence-pair conversion must distinguish an error from `iter(obj)`
/// from an error raised later by `next()`.
pub(crate) fn collect_iterator(it: PyObjectRef) -> Result<Vec<PyObjectRef>, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    // Each `next` runs arbitrary allocating code (a generator body, a JIT
    // callee that boxes a fresh int) which can trigger a moving minor
    // collection. A raw `Vec<PyObjectRef>` on the malloc heap is invisible to
    // the collector, so already-collected nursery elements would be stranded /
    // not forwarded. Pin the iterator and each yielded element onto the shadow
    // stack (a real GC root the collector walks and updates on relocation),
    // then read the forwarded slots back out — the manual equivalent of the
    // translator's shadowstack save/restore around a collecting call
    // (framework.py:853-856).
    let base = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(it);
    // `pin_root` itself queries the collector, so read the iterator back from
    // its slot instead of reusing the caller's copy: a foreign collection that
    // ran inside the pin forwarded the object and rewrote the slot, not the
    // local.
    let it = pyre_object::gc_roots::shadow_stack_get(base);
    // Dict-view iterators are currently off-GC RPython-style carriers.  Their
    // registered raw-field walker covers frame/value-stack reachability, but
    // this helper keeps the iterator on the shadow stack directly; retain its
    // source dict explicitly for the duration of the native loop.
    if unsafe { pyre_object::dictmultiobject::is_dict_view_iterator(it) } {
        let w_dict = unsafe { pyre_object::dictmultiobject::w_dict_view_iterator_get_dict(it) };
        let _ = pyre_object::gc_roots::pin_root(w_dict);
    }
    let item_base = pyre_object::gc_roots::shadow_stack_len();
    let mut count = 0usize;
    loop {
        // The iterator may itself have moved during a prior `next`; reload it
        // from its (post-relocation) shadow-stack slot before each call.
        let it_now = pyre_object::gc_roots::shadow_stack_get(base);
        match crate::baseobjspace::next(it_now) {
            Ok(v) => {
                let _ = pyre_object::gc_roots::pin_root(v);
                count += 1;
            }
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    break;
                }
                return Err(e);
            }
        }
    }
    // Read the forwarded element slots back out. `item_base` follows the
    // iterator and any carrier-specific backing roots above.
    let mut items = Vec::with_capacity(count);
    for i in 0..count {
        items.push(pyre_object::gc_roots::shadow_stack_get(item_base + i));
    }
    Ok(items)
}

/// Create a `set` from a slice of elements.
///
/// PyPy: `setobject.py` W_SetObject.descr_init → `_initialize_set`.
/// Each `add` hashes the element through `space.hash_w`, so an unhashable
/// one (or a raising / `None` / non-int `__hash__`) raises. Build the set
/// element-by-element so the first such element surfaces in left-to-right
/// order before it is stored; `w_set_add` keeps the `dict_keys_equal`
/// dedup, and the hash itself is not used for storage.
pub fn builtin_set_from_items(items: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `w_set_new` can collect before `builtin_set_add_items` pins `items`.
    builtin_set_add_items_impl(None, items, true)
}

/// Add each of `items` to `set`, hashing it as it enters.
///
/// `setobject.py descr_union` adds a non-set operand's elements one by
/// one, each hashed on the way in — unlike a set operand, whose elements
/// already carry the digest they were stored under.
pub fn builtin_set_add_items(
    set: PyObjectRef,
    items: &[PyObjectRef],
) -> Result<(), crate::PyError> {
    builtin_set_add_items_impl(Some(set), items, true).map(|_| ())
}

/// Intersection materializes an operand through PyPy's internal `_newobj`
/// path.  Unlike the public set constructor/mutators, CPython 3.14 and PyPy
/// let the original `unhashable type` escape from this path unchanged.
pub(crate) fn builtin_set_add_items_intersection(
    set: PyObjectRef,
    items: &[PyObjectRef],
) -> Result<(), crate::PyError> {
    builtin_set_add_items_impl(Some(set), items, false).map(|_| ())
}

fn builtin_set_add_items_impl(
    set: Option<PyObjectRef>,
    items: &[PyObjectRef],
    wrap_hash_error: bool,
) -> Result<PyObjectRef, crate::PyError> {
    unsafe {
        // `try_hash_value` may run a user `__hash__` that allocates and
        // triggers a moving minor collection; `set` and every not-yet-added
        // item are rooted for the whole loop and reloaded after each hash,
        // matching `set_update_value`. Mint the empty set only after the
        // items are published, so `w_set_new` cannot move them first.
        let _roots = pyre_object::gc_roots::push_roots();
        let item_base = pyre_object::gc_roots::pin_roots(items);
        let set = match set {
            Some(set) => pyre_object::gc_roots::pin_root(set),
            None => pyre_object::gc_roots::pin_root(pyre_object::w_set_new()),
        };
        let set_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
        for i in 0..items.len() {
            let item = pyre_object::gc_roots::shadow_stack_get(item_base + i);
            let hash = try_hash_value(item).map_err(|err| {
                if wrap_hash_error {
                    crate::baseobjspace::wrap_set_element_hash_error(
                        pyre_object::gc_roots::shadow_stack_get(item_base + i),
                        err,
                    )
                } else {
                    err
                }
            })?;
            let set = pyre_object::gc_roots::shadow_stack_get(set_slot);
            let item = pyre_object::gc_roots::shadow_stack_get(item_base + i);
            pyre_object::w_set_add_hashed_checked(set, item, hash)
                .map_err(crate::baseobjspace::map_set_update_error)?;
        }
        Ok(pyre_object::gc_roots::shadow_stack_get(set_slot))
    }
}

/// `super()` — PyPy: descriptor.py W_Super
/// `super(cls, obj)` — PyPy: pypy/module/__builtin__/descriptor.py W_Super
///
/// Returns a proxy that looks up methods in cls's MRO starting after cls.
/// `getattr` handles the super proxy via `is_super` check.
///
/// Zero-arg super() finds __class__ and self from the calling frame.
/// CPython: Objects/typeobject.c super_init
pub(crate) fn builtin_super(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let args = super_init_args(args)?;
    let _roots = pyre_object::gc_roots::push_roots();
    let save_point = pyre_object::gc_roots::shadow_stack_len();
    for &arg in args {
        let _ = pyre_object::gc_roots::pin_root(arg);
    }
    let w_self = pyre_object::descriptor::w_super_new(PY_NULL, PY_NULL, PY_NULL, PY_NULL);
    let w_self = pyre_object::gc_roots::pin_root(w_self);
    let mut args_w = [PY_NULL; 2];
    for (i, arg) in args_w[..args.len()].iter_mut().enumerate() {
        *arg = unsafe { pyre_object::gc_roots::shadow_stack_get(save_point + i) };
    }
    descr_init(w_self, &args_w[..args.len()])?;
    Ok(unsafe { pyre_object::gc_roots::shadow_stack_get(save_point + args.len()) })
}

fn super_init_args(args: &[PyObjectRef]) -> Result<&[PyObjectRef], crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "super() takes no keyword arguments",
        ));
    }
    if args.len() > 2 {
        return Err(crate::PyError::type_error(format!(
            "super() expected at most 2 arguments, got {}",
            args.len()
        )));
    }
    Ok(args)
}

/// `descriptor.py W_Super.descr_init`: validate before replacing self's fields.
pub(crate) fn descr_init(w_self: PyObjectRef, args: &[PyObjectRef]) -> Result<(), crate::PyError> {
    let args = super_init_args(args)?;
    let _roots = pyre_object::gc_roots::push_roots();
    let save_point = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_self);
    let (w_starttype, w_obj_or_type) = if !args.is_empty() {
        let w_starttype = args[0];
        if !unsafe { pyre_object::is_type(w_starttype) } {
            return Err(crate::PyError::type_error(format!(
                "super() argument 1 must be a type, not {}",
                crate::baseobjspace::object_functionstr_type_name(w_starttype)
            )));
        }
        (w_starttype, args.get(1).copied().unwrap_or(PY_NULL))
    } else {
        // `_super_from_frame` reads the live EC chain, including inlined frames.
        let execution_context =
            crate::call::getexecutioncontext() as *mut crate::PyExecutionContext;
        if execution_context.is_null() {
            return Err(crate::PyError::runtime_error("super(): no current frame"));
        }
        let frame_ptr = unsafe { (*execution_context).gettopframe() };
        if frame_ptr.is_null() {
            return Err(crate::PyError::runtime_error("super(): no current frame"));
        }
        let (self_is_cell, class_slot) =
            bare_super_frame_layout_words(unsafe { (*frame_ptr).code() });
        super_operands_from_frame_layout(frame_ptr, self_is_cell, class_slot)?
    };
    let w_obj_or_type = if w_obj_or_type.is_null() || unsafe { pyre_object::is_none(w_obj_or_type) }
    {
        PY_NULL
    } else {
        w_obj_or_type
    };
    let operands = pyre_object::gc_roots::pin_roots(&[w_starttype, w_obj_or_type]);
    let w_starttype = pyre_object::gc_roots::shadow_stack_get(operands);
    let w_obj_or_type = pyre_object::gc_roots::shadow_stack_get(operands + 1);
    let w_type = if w_obj_or_type.is_null() {
        PY_NULL
    } else {
        super_check(w_starttype, w_obj_or_type)?
    };
    unsafe {
        pyre_object::descriptor::w_super_set_fields(
            pyre_object::gc_roots::shadow_stack_get(save_point),
            pyre_object::gc_roots::shadow_stack_get(save_point + 1),
            w_type,
            pyre_object::gc_roots::shadow_stack_get(save_point + 2),
        );
    }
    Ok(())
}

/// `descriptor.py:_super_from_frame(space, frame)` — the frame-explicit half
/// of zero-argument `super()`.
///
/// The interpreter obtains `frame_ptr` from the live execution-context chain.
/// The meta-tracer passes the active MIFrame's red frame directly when it
/// looks through this helper, which forces the correct inlined frame rather
/// than rediscovering an outer portal frame through an opaque residual call.
pub fn builtin_super_from_frame(
    frame_ptr: *mut crate::pyframe::PyFrame,
) -> Result<PyObjectRef, crate::PyError> {
    if frame_ptr.is_null() {
        return Err(crate::PyError::runtime_error("super(): no current frame"));
    }
    let frame = unsafe { &*frame_ptr };
    let (self_is_cell, class_slot) = bare_super_frame_layout_words(frame.code());
    builtin_super_from_frame_layout(frame_ptr, self_is_cell, class_slot)
}

/// Frame-red / pycode-green half of [`builtin_super_from_frame`].
///
/// PyPy computes `_get_self_location(frame.pycode)` from the green code object
/// and reads only `frame.locals_cells_stack_w` from the red frame.  The
/// generated opcode helper receives those two green layout words explicitly,
/// so it never interprets the host Rust `CodeObject` layout as translated GC
/// fields.
pub fn builtin_super_from_frame_layout(
    frame_ptr: *mut crate::pyframe::PyFrame,
    self_is_cell: bool,
    class_slot: isize,
) -> Result<PyObjectRef, crate::PyError> {
    let (w_class, w_self) = super_operands_from_frame_layout(frame_ptr, self_is_cell, class_slot)?;
    builtin_super(&[w_class, w_self])
}

/// Where zero-argument `super()` finds its two operands in `code`'s slots.
///
/// `descriptor.py _get_self_location`, minus the raising.  3.11+ localsplus
/// lets an argument cellvar share slot zero, so upstream's two branches
/// (`locals_cells_stack_w[0]` against `_getcell(self_cell)`) become one slot
/// read and [`self_is_cell`](Self::self_is_cell).
///
/// Both answers are functions of the code object alone -- `@jit.elidable`
/// upstream -- which is what lets the tracer bake them into a recorded body.
pub struct BareSuperFrameLayout {
    /// `localsplus[0]` holds the `Cell` an inner scope shares, not the
    /// receiver itself.
    pub self_is_cell: bool,
    /// The `__class__` freevar's slot, or `None` when `code` closes over no
    /// such cell — `super(): __class__ cell not found`.
    pub class_slot: Option<usize>,
}

/// [`BareSuperFrameLayout`] for `code`, or `None` for the arity `super()`
/// rejects outright (`super(): no arguments`).
///
/// Shared with the tracer's `walker_bare_super_frame_slots`, which resolves the
/// same two slots as SSA values: a second copy of this arithmetic would let the
/// recorded body read a different slot than the walk executed, and that is a
/// wrong receiver rather than a declined fold.
///
/// Neither failure is spelled as an error here, because the two raise in the
/// opposite order to the one they are computed in: a deleted `arg[0]` is
/// reported ahead of a missing `__class__` cell.
pub fn bare_super_frame_layout(code: &crate::CodeObject) -> Option<BareSuperFrameLayout> {
    if code.arg_count == 0 {
        return None;
    }
    Some(BareSuperFrameLayout {
        self_is_cell: code
            .varnames
            .first()
            .is_some_and(|first| code.cellvars.iter().any(|cell| cell == first)),
        class_slot: code
            .freevars
            .iter()
            .position(|name| name == "__class__")
            .map(|class_freevar| {
                code.varnames.len() + crate::pyframe::npure_cellvars(code) + class_freevar
            }),
    })
}

/// Word ABI for the green result of [`bare_super_frame_layout`].
///
/// `-2` preserves the distinct no-arguments arm; `-1` is a missing
/// `__class__` cell; non-negative values are locals-plus indices.
pub fn bare_super_frame_layout_words(code: &crate::CodeObject) -> (bool, isize) {
    match bare_super_frame_layout(code) {
        None => (false, -2),
        Some(layout) => (
            layout.self_is_cell,
            layout.class_slot.map(|slot| slot as isize).unwrap_or(-1),
        ),
    }
}

/// The `(__class__ cell, arg[0])` pair zero-argument `super()` is built from.
///
/// Every raising arm here reads frame state and runs no Python, so a caller
/// may take the `Err` and walk away without having changed anything.
fn super_operands_from_frame_layout(
    frame_ptr: *mut crate::pyframe::PyFrame,
    self_is_cell: bool,
    class_slot: isize,
) -> Result<(PyObjectRef, PyObjectRef), crate::PyError> {
    if frame_ptr.is_null() {
        return Err(crate::PyError::runtime_error("super(): no current frame"));
    }
    let frame = unsafe { &*frame_ptr };
    if class_slot == -2 {
        return Err(crate::PyError::runtime_error("super(): no arguments"));
    }

    let self_slot = locals_w!(frame)[0];
    let w_self =
        if self_is_cell && !self_slot.is_null() && unsafe { pyre_object::is_cell(self_slot) } {
            unsafe { pyre_object::w_cell_get(self_slot) }
        } else {
            self_slot
        };
    if w_self.is_null() {
        return Err(crate::PyError::runtime_error("super(): arg[0] deleted"));
    }

    if class_slot < 0 {
        return Err(crate::PyError::runtime_error(
            "super(): __class__ cell not found",
        ));
    }
    let class_slot = class_slot as usize;
    // Keep the virtualizable array access immediate, as PyPy's
    // `_super_from_frame` does with `frame.locals_cells_stack_w[index]`.
    // Passing the array through `slice::get` makes the array object itself an
    // SSA link argument, which `jtransform.py` correctly rejects as a
    // virtualizable-array escape.
    let class_cell = if class_slot < locals_w!(frame).len() {
        locals_w!(frame)[class_slot]
    } else {
        PY_NULL
    };
    let w_class = if !class_cell.is_null() && unsafe { pyre_object::is_cell(class_cell) } {
        unsafe { pyre_object::w_cell_get(class_cell) }
    } else {
        class_cell
    };
    if w_class.is_null() {
        return Err(crate::PyError::runtime_error(
            "super(): empty __class__ cell",
        ));
    }

    Ok((w_class, w_self))
}

/// Exact builtins-namespace `super` type identity used by the meta-tracer's
/// zero-argument specialization.
pub fn is_builtin_super_type(obj: PyObjectRef) -> bool {
    std::ptr::eq(
        obj,
        crate::typedef::gettypeobject(&pyre_object::descriptor::SUPER_TYPE),
    )
}

/// `descriptor.py _super_check` — validate the explicit `(type, obj)` pair
/// and return the class whose MRO a bound super proxy walks.
/// The arms of [`super_check`] that settle by walking installed MROs, before
/// it consults `__class__`.
///
/// Split out because the third arm runs `getattr_str`, and a `__class__`
/// property answers it with arbitrary Python.  A caller that must not run
/// Python asks for this half alone; `super_check` itself keeps the full
/// sequence by starting here.
pub fn super_check_python_free(
    start_type: PyObjectRef,
    obj_or_type: PyObjectRef,
) -> Option<PyObjectRef> {
    unsafe {
        if pyre_object::is_type(obj_or_type)
            && crate::baseobjspace::issubtype_w(obj_or_type, start_type)
        {
            return Some(obj_or_type);
        }
        if let Some(obj_type) = crate::typedef::r#type(obj_or_type)
            && crate::baseobjspace::issubtype_w(obj_type.as_ptr(), start_type)
        {
            return Some(obj_type.as_ptr());
        }
    }
    None
}

pub(crate) fn super_check(
    start_type: PyObjectRef,
    obj_or_type: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    if let Some(obj_type) = super_check_python_free(start_type, obj_or_type) {
        return Ok(obj_type);
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let save_point = pyre_object::gc_roots::pin_roots(&[start_type, obj_or_type]);
    unsafe {
        match crate::baseobjspace::getattr_str(
            pyre_object::gc_roots::shadow_stack_get(save_point + 1),
            "__class__",
        ) {
            Ok(apparent_type) => {
                let start_type = pyre_object::gc_roots::shadow_stack_get(save_point);
                if pyre_object::is_type(apparent_type)
                    && crate::baseobjspace::issubtype_w(apparent_type, start_type)
                {
                    return Ok(apparent_type);
                }
            }
            // descriptor.py:139-143 — only AttributeError falls back to
            // type(obj) (the normal case already rejected it above); any
            // other exception from a `__class__` property propagates.
            Err(e) if e.kind == crate::PyErrorKind::AttributeError => {}
            Err(e) => return Err(e),
        }
    }
    let start_type = unsafe { pyre_object::gc_roots::shadow_stack_get(save_point) };
    let obj_or_type = unsafe { pyre_object::gc_roots::shadow_stack_get(save_point + 1) };
    // typeobject.c super_init: a type obj names its own class ("type str"),
    // otherwise the message names the instance's class ("instance of str").
    let obj_desc = if unsafe { pyre_object::is_type(obj_or_type) } {
        format!("type {}", unsafe {
            pyre_object::w_type_get_name(obj_or_type)
        })
    } else {
        let obj_type_name = crate::typedef::r#type(obj_or_type)
            .map(|t| unsafe { pyre_object::w_type_get_name(t.as_ptr()) })
            .unwrap_or("object");
        format!("instance of {obj_type_name}")
    };
    let start_type_name = unsafe { pyre_object::w_type_get_name(start_type) };
    Err(crate::PyError::type_error(format!(
        "super(type, obj): obj ({obj_desc}) is not an instance \
         or subtype of type ({start_type_name})."
    )))
}

/// `operation.py iter`. An omitted sentinel (`w_sentinel is None` — the
/// unwrapped default, not an explicit `None`) is `space.iter`. Two arguments
/// are `iter_sentinel`: a non-callable raises, otherwise
/// `_CallableIterator(callable_, sentinel)`. Keywords are rejected by the
/// same binding `builtin_iter` runs (`iter()` takes no keyword arguments);
/// an empty `**{}` is not a sentinel.
pub fn __majit_wrap_builtin_iter(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_iter(args)
}

#[cfg(not(target_arch = "wasm32"))]
#[linkme::distributed_slice(crate::gateway::BUILTIN_WRAPPER_DESCRIPTORS)]
#[allow(non_upper_case_globals)]
static __majit_wrap_builtin_iter_target: crate::gateway::BuiltinWrapperDescriptor =
    crate::gateway::BuiltinWrapperDescriptor {
        path: concat!(module_path!(), "::", "__majit_wrap_builtin_iter"),
        func: __majit_wrap_builtin_iter,
    };

/// `operation.py _CallableIterator.__iter__` — return self. A keyword or a
/// surplus positional is the positional-only binding's TypeError, not a
/// second body.
pub fn __majit_wrap_iter_self(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        crate::gateway::check_declared_positional_arity("__iter__", 1, args)?;
    }
    Ok(args[0])
}

#[cfg(not(target_arch = "wasm32"))]
#[linkme::distributed_slice(crate::gateway::BUILTIN_WRAPPER_DESCRIPTORS)]
#[allow(non_upper_case_globals)]
static __majit_wrap_iter_self_target: crate::gateway::BuiltinWrapperDescriptor =
    crate::gateway::BuiltinWrapperDescriptor {
        path: concat!(module_path!(), "::", "__majit_wrap_iter_self"),
        func: __majit_wrap_iter_self,
    };

/// `iter(obj)` / `iter(callable, sentinel)` — PyPy:
/// `module/__builtin__/operation.py` iter
fn builtin_iter(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `iter` is a keyword-rejecting builtin; a `sentinel` is only ever
    // positional (`iter(callable, sentinel)`).  Strip the kwargs marker so a
    // keyword call raises instead of consuming the marker dict as an argument.
    let (positional, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "iter() takes no keyword arguments",
        ));
    }
    match positional.len() {
        0 => Err(crate::PyError::type_error(
            "iter expected at least 1 argument, got 0",
        )),
        1 => crate::baseobjspace::iter(positional[0]),
        2 => {
            if !crate::baseobjspace::callable_w(positional[0]) {
                return Err(crate::PyError::type_error("iter(v, w): v must be callable"));
            }
            Ok(pyre_object::operation::w_callable_iterator_new(
                positional[0],
                positional[1],
            ))
        }
        n => Err(crate::PyError::type_error(format!(
            "iter expected at most 2 arguments, got {n}"
        ))),
    }
}

/// `next(iterator[, default])` — PyPy: baseobjspace.py next
fn builtin_next(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "next() takes no keyword arguments",
        ));
    }
    if args.is_empty() {
        return Err(crate::PyError::type_error(
            "next expected at least 1 argument, got 0",
        ));
    }
    if args.len() > 2 {
        return Err(crate::PyError::type_error(format!(
            "next expected at most 2 arguments, got {}",
            args.len()
        )));
    }
    if args.len() > 1 {
        // The iterator body runs Python between the gateway's pin and this
        // return, and `args` is a native copy nothing rewrites when a list or
        // dict default is moved -- see `builtin_getattr`.  Keep the
        // one-argument form free of the slot.
        let default_root = pyre_object::gc_roots::push_roots();
        let base = default_root.pin_roots(&[args[0], args[1]]);
        return match crate::baseobjspace::next(default_root.get(base)) {
            Ok(v) => Ok(v),
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    Ok(default_root.get(base + 1))
                } else {
                    Err(e)
                }
            }
        };
    }
    crate::baseobjspace::next(args[0])
}

/// `callable(obj)` — PyPy: baseobjspace.py callable
fn builtin_callable(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = args[0];
    // `PyCallable_Check` — true when `type(obj)` has `tp_call`.  The builtin
    // callable kinds (function / builtin function, bound method,
    // staticmethod, type) are dispatched through dedicated slots in `call.rs`
    // rather than a `__call__` dict entry, so each is recognised directly;
    // any other object is callable iff its type defines `__call__`.
    let is_callable = unsafe {
        crate::is_function(obj)
            || pyre_object::is_type(obj)
            || pyre_object::is_method(obj)
            || pyre_object::function::is_staticmethod(obj)
            || crate::typedef::r#type(obj)
                .and_then(|t| crate::baseobjspace::lookup_in_type(t.as_ptr(), "__call__"))
                .is_some()
    };
    Ok(w_bool_from(is_callable))
}

/// `compile(source, filename, mode, ...)` — compiling.py `compile`.
///
/// Compiles a Python string to a code object.  `flags` carries the
/// `__future__` compiler-feature bits (and the `PyCF_*` compilation
/// bits), `dont_inherit` controls whether the caller's `__future__`
/// flags are inherited, and `optimize` selects the -1/0/1/2 optimisation
/// level (assert / `__debug__` / docstring stripping).
/// Map a compiler failure to a Python `SyntaxError`, matching where
/// `compile`/`exec`/`eval`/`ast.parse` raise `SyntaxError` (not
/// `ValueError`) for malformed source.  The error's `python_location` /
/// `python_end_location` / `source_path` populate `e.lineno` / `e.offset`
/// / `e.end_lineno` / `e.end_offset` / `e.filename`.  Parser errors carry
/// the offending line sliced from `source`; compiler errors such as
/// ``return`` outside a function retain their location but expose `e.text`
/// as `None` for synthetic ``<string>`` input, matching CPython's
/// `PyErr_SyntaxLocationObject` path.  File compilation retains the decoded
/// line for error display.  A location-less codegen error (line 0) falls back
/// to a bare, message-only SyntaxError.
pub fn compile_err_to_syntax_error(
    e: crate::compile::CompileError,
    source: &str,
    mode: crate::compile::Mode,
) -> crate::PyError {
    compile_err_to_syntax_error_maybe_incomplete(e, source, mode, false)
}

/// Convert Ruff/RustPython's one-based UTF-8 byte column to the one-based
/// Unicode character column exposed by ``SyntaxError.offset``.
///
/// CPython's tokenizer keeps byte offsets internally too, but
/// ``_PyPegen_byte_offset_to_character_offset`` converts them before the
/// exception is materialised.  This is that conversion, for the spans this
/// module locates itself by scanning `source`; a location the compiler reports
/// for a parser diagnostic already counts characters and must not be passed
/// through here.  The line and the span are the caller's to choose.
pub(crate) fn syntax_error_character_offset(
    source: &str,
    lineno: usize,
    byte_offset: usize,
) -> usize {
    if lineno == 0 || byte_offset == 0 {
        return byte_offset;
    }
    let Some(line) = source.split('\n').nth(lineno - 1) else {
        return byte_offset;
    };
    let byte_index = byte_offset.saturating_sub(1).min(line.len());
    let boundary = (0..=byte_index)
        .rev()
        .find(|&index| line.is_char_boundary(index))
        .unwrap_or(0);
    line[..boundary].chars().count() + 1
}

fn source_byte_location(source: &str, byte_index: usize) -> (usize, usize) {
    let byte_index = byte_index.min(source.len());
    let byte_index = (0..=byte_index)
        .rev()
        .find(|&index| source.is_char_boundary(index))
        .unwrap_or(0);
    let line_start = source[..byte_index]
        .rfind('\n')
        .map_or(0, |index| index + 1);
    let lineno = source[..line_start]
        .bytes()
        .filter(|byte| *byte == b'\n')
        .count()
        + 1;
    (lineno, byte_index - line_start + 1)
}

/// Build the located parser error for a diagnostic whose grammar reduction
/// has already selected both its message and source range.
///
/// This deliberately bypasses RustPython's `CompileError::from_ruff_parse_error`:
/// that constructor is for raw Ruff failures and runs source-wide recovery
/// rules.  PyPy `BaseParser.check_version`, like CPython's `CHECK_VERSION`, is
/// already the final parser reduction and must not be reclassified by them.
pub(crate) fn syntax_error_from_source_range(
    message: &str,
    source: &str,
    range: ruff_text_size::TextRange,
) -> crate::PyError {
    let (lineno, byte_offset) = source_byte_location(source, range.start().to_usize());
    let (end_lineno, end_byte_offset) = source_byte_location(source, range.end().to_usize());
    let offset = syntax_error_character_offset(source, lineno, byte_offset);
    let end_offset = syntax_error_character_offset(source, end_lineno, end_byte_offset);
    let text = source.split_inclusive('\n').nth(lineno - 1);
    let mut error = crate::PyError::syntax_error_located(
        message,
        Wtf8::new("<unknown>"),
        lineno as i64,
        offset as i64,
        end_lineno as i64,
        end_offset as i64,
        text,
    );
    stamp_parser_syntax_metadata(&mut error, source);
    error
}

/// `pegen.c _PyPegen_set_syntax_error_metadata` for an error emitted by a
/// parser reduction rather than by later code generation.
fn stamp_parser_syntax_metadata(error: &mut crate::PyError, source: &str) {
    // The exception is materialised and pinned before the tuple elements are
    // built: until it is stamped it lives only in this Rust `PyError`, which
    // the collector does not scan.  Each element is likewise pinned as it is
    // made and reloaded at the end.
    let _roots = pyre_object::gc_roots::push_roots();
    let exc_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(error.to_exc_object());
    let source_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_str_new_managed(source));
    let zero_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_int_new(0));
    let zero = pyre_object::gc_roots::shadow_stack_get(zero_slot);
    let metadata = pyre_object::w_tuple_new(vec![
        zero,
        zero,
        pyre_object::gc_roots::shadow_stack_get(source_slot),
    ]);
    unsafe {
        pyre_object::interp_exceptions::w_exception_set_syntax_metadata(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            metadata,
        );
    }
}

/// Byte index of the one-based character column a parser diagnostic reports,
/// which is what indexes back into the source it was parsed from.  A column
/// past the end of its line lands on the line's end.
fn source_character_index(source: &str, lineno: usize, char_offset: usize) -> Option<usize> {
    let line_start = source
        .split_inclusive('\n')
        .take(lineno.checked_sub(1)?)
        .map(str::len)
        .sum::<usize>();
    let line = source.get(line_start..)?.split('\n').next()?;
    let column = char_offset.checked_sub(1)?;
    let index = line
        .char_indices()
        .nth(column)
        .map_or(line.len(), |(index, _)| index);
    Some(line_start + index)
}

fn source_byte_index(source: &str, lineno: usize, byte_offset: usize) -> Option<usize> {
    let line_start = source
        .split_inclusive('\n')
        .take(lineno.checked_sub(1)?)
        .map(str::len)
        .sum::<usize>();
    let index = line_start.checked_add(byte_offset.checked_sub(1)?)?;
    (index <= source.len() && source.is_char_boundary(index)).then_some(index)
}

/// `pypy/interpreter/pyparser/python.gram:invalid_expression` is also run by
/// the recursive parser used for an f-string replacement field.  Ruff finds
/// the outer f-string error first, so repeat that recursive parse and map its
/// known range back onto the original source.
fn fstring_missing_comma_span(source: &str, raw_index: usize) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    let raw_index = raw_index.min(bytes.len());
    let open = bytes[..raw_index].iter().rposition(|byte| *byte == b'{')?;
    let mut cursor = open + 1;
    let mut delimiters = Vec::new();
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\'' | b'"' => {
                let quote = bytes[cursor];
                let triple = bytes[cursor..].starts_with(&[quote, quote, quote]);
                let quote_len = if triple { 3 } else { 1 };
                cursor += quote_len;
                while cursor < bytes.len() {
                    if bytes[cursor] == b'\\' {
                        cursor = (cursor + 2).min(bytes.len());
                    } else if triple && bytes[cursor..].starts_with(&[quote, quote, quote]) {
                        cursor += 3;
                        break;
                    } else if !triple && bytes[cursor] == quote {
                        cursor += 1;
                        break;
                    } else {
                        cursor += 1;
                    }
                }
            }
            b'(' | b'[' | b'{' => {
                delimiters.push(bytes[cursor]);
                cursor += 1;
            }
            b')' | b']' | b'}' if !delimiters.is_empty() => {
                delimiters.pop();
                cursor += 1;
            }
            b'}' | b'!' | b':' | b'=' if delimiters.is_empty() => break,
            _ => cursor += 1,
        }
    }
    let expression = source.get(open + 1..cursor)?;
    let wrapped = format!("({expression})");
    let inner_error = crate::compile::compile_source(&wrapped, crate::compile::Mode::Eval).err()?;
    if inner_error.to_string() != "invalid syntax. Perhaps you forgot a comma?" {
        return None;
    }
    let (start_line, start_offset) = inner_error.python_location();
    let (end_line, end_offset) = inner_error.python_end_location()?;
    let start = source_character_index(&wrapped, start_line, start_offset)?.checked_sub(1)?;
    let end = source_character_index(&wrapped, end_line, end_offset)?.checked_sub(1)?;
    Some((open + 1 + start, open + 1 + end))
}

/// CPython 3.14's symtable reports a `global`/`nonlocal` conflict at the first
/// declaration in the lexical scope.  RustPython misses the conflict while it
/// scans and later reports an unbound nonlocal at the second declaration.
fn global_nonlocal_conflict_span(
    error: &crate::compile::CompileError,
    source: &str,
) -> Option<(String, usize, usize)> {
    use rustpython_compiler::ast::{self, visitor::Visitor};

    let message = error.to_string();
    let name = message
        .strip_prefix("no binding for nonlocal '")
        .and_then(|rest| rest.strip_suffix("' found"))
        .or_else(|| {
            message
                .strip_prefix("name '")
                .and_then(|rest| rest.strip_suffix("' is nonlocal and global"))
        })?;
    let (lineno, offset) = error.python_location();
    let error_index = source_byte_index(source, lineno, offset)?;
    let parsed = crate::compile::parser::parse_module(source).ok()?;

    fn innermost_scope(body: &[ast::Stmt], index: usize) -> Option<&[ast::Stmt]> {
        for statement in body {
            let range = statement.range();
            if !(range.start().to_usize() <= index && index <= range.end().to_usize()) {
                continue;
            }
            let child = match statement {
                ast::Stmt::FunctionDef(node) => Some(node.body.as_slice()),
                ast::Stmt::ClassDef(node) => Some(node.body.as_slice()),
                _ => None,
            };
            if let Some(child) = child {
                return innermost_scope(child, index).or(Some(child));
            }
        }
        None
    }

    struct DeclarationVisitor<'a> {
        name: &'a str,
        first: Option<(usize, usize)>,
        global: bool,
        nonlocal: bool,
    }

    impl Visitor<'_> for DeclarationVisitor<'_> {
        fn visit_stmt(&mut self, statement: &ast::Stmt) {
            let names = match statement {
                ast::Stmt::Global(node) => Some((true, node.names.as_slice())),
                ast::Stmt::Nonlocal(node) => Some((false, node.names.as_slice())),
                // These bodies are distinct lexical scopes.  Their decorators,
                // defaults, and annotations cannot contain declarations.
                ast::Stmt::FunctionDef(_) | ast::Stmt::ClassDef(_) => return,
                _ => None,
            };
            if let Some((is_global, names)) = names
                && names
                    .iter()
                    .any(|identifier| identifier.as_str() == self.name)
            {
                self.global |= is_global;
                self.nonlocal |= !is_global;
                let range = statement.range();
                let range = (range.start().to_usize(), range.end().to_usize());
                if self.first.is_none_or(|first| range.0 < first.0) {
                    self.first = Some(range);
                }
            }
            ast::visitor::walk_stmt(self, statement);
        }
    }

    let module_body = parsed.syntax().body.as_slice();
    let scope = innermost_scope(module_body, error_index).unwrap_or(module_body);
    let mut visitor = DeclarationVisitor {
        name,
        first: None,
        global: false,
        nonlocal: false,
    };
    for statement in scope {
        visitor.visit_stmt(statement);
    }
    let (start, end) = visitor
        .first
        .filter(|_| visitor.global && visitor.nonlocal)?;
    Some((format!("name '{name}' is nonlocal and global"), start, end))
}

/// `python.gram:invalid_expression` wins over `invalid_arguments` when an
/// unparenthesized generator call is the right operand of a binary expression.
/// CPython 3.14 selects the `for` token in that form rather than the complete
/// generator range selected by Ruff.
fn binary_call_generator_error_span(source: &str) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    'for_index: for for_index in 0..bytes.len().saturating_sub(2) {
        if &bytes[for_index..for_index + 3] != b"for"
            || bytes
                .get(for_index.wrapping_sub(1))
                .is_some_and(|byte| byte.is_ascii_alphanumeric() || *byte == b'_')
            || bytes
                .get(for_index + 3)
                .is_some_and(|byte| byte.is_ascii_alphanumeric() || *byte == b'_')
        {
            continue;
        }
        let Some(open) = bytes[..for_index].iter().rposition(|byte| *byte == b'(') else {
            continue;
        };
        let mut cursor = open;
        while cursor > 0 && bytes[cursor - 1].is_ascii_whitespace() {
            cursor -= 1;
        }
        let name_end = cursor;
        while cursor > 0 && (bytes[cursor - 1].is_ascii_alphanumeric() || bytes[cursor - 1] == b'_')
        {
            cursor -= 1;
        }
        if cursor == name_end {
            continue;
        }
        while cursor > 0 && bytes[cursor - 1].is_ascii_whitespace() {
            cursor -= 1;
        }
        if !matches!(
            bytes.get(cursor.wrapping_sub(1)),
            Some(b'+' | b'-' | b'*' | b'/' | b'%' | b'@' | b'|' | b'&' | b'^')
        ) {
            continue 'for_index;
        }
        return Some((for_index, for_index + 3));
    }
    None
}

/// `python-in-rpython.gram` `invalid_arguments` / `invalid_kwarg` select the
/// keyword name through its `=` when a bare comprehension follows a keyword
/// value: `f(name = value for value in iterable)`. Ruff rejects the same input
/// before retaining that invalid-rule choice, so recover the literal grammar
/// shape from its unchecked token stream.
fn keyword_generator_assignment_span(source: &str) -> Option<(usize, usize)> {
    use rustpython_compiler::ast::token::TokenKind;

    let parsed = crate::compile::parser::parse_unchecked_source(
        source,
        rustpython_compiler::ast::PySourceType::Python,
    );
    let significant: Vec<_> = parsed
        .tokens()
        .iter()
        .filter_map(|token| {
            let (kind, range) = token.as_tuple();
            (!matches!(
                kind,
                TokenKind::Comment
                    | TokenKind::Newline
                    | TokenKind::NonLogicalNewline
                    | TokenKind::EndOfFile
                    | TokenKind::Indent
                    | TokenKind::Dedent
            ))
            .then_some((kind, range))
        })
        .collect();

    let mut stack = Vec::new();
    let mut depths = Vec::with_capacity(significant.len());
    for &(kind, _) in &significant {
        depths.push(stack.len());
        match kind {
            TokenKind::Lpar | TokenKind::Lsqb | TokenKind::Lbrace => stack.push(kind),
            TokenKind::Rpar | TokenKind::Rsqb | TokenKind::Rbrace => {
                stack.pop();
            }
            _ => {}
        }
    }

    for (for_index, &(kind, _)) in significant.iter().enumerate() {
        if kind != TokenKind::For || depths[for_index] == 0 {
            continue;
        }
        let depth = depths[for_index];
        let Some(open_index) = (0..for_index)
            .rev()
            .find(|&index| significant[index].0 == TokenKind::Lpar && depths[index] + 1 == depth)
        else {
            continue;
        };
        let plain_function_parameters = open_index >= 2
            && significant[open_index - 1].0 == TokenKind::Name
            && significant[open_index - 2].0 == TokenKind::Def;
        let typed_function_parameters = (open_index >= 1
            && significant[open_index - 1].0 == TokenKind::Rsqb)
            .then(|| {
                (0..open_index).rev().find(|&index| {
                    significant[index].0 == TokenKind::Lsqb && depths[index] == depths[open_index]
                })
            })
            .flatten()
            .is_some_and(|bracket| {
                bracket >= 2
                    && significant[bracket - 1].0 == TokenKind::Name
                    && significant[bracket - 2].0 == TokenKind::Def
            });
        if plain_function_parameters || typed_function_parameters {
            continue;
        }

        // These parentheses must belong to a call. Parenthesized invalid
        // comprehensions are owned by `invalid_named_expression`, whose span
        // includes the value rather than stopping at `=`.
        let open_start = significant[open_index].1.start().to_usize();
        let Some(previous) = source[..open_start]
            .bytes()
            .rev()
            .find(|byte| !byte.is_ascii_whitespace())
        else {
            continue;
        };
        if !(previous.is_ascii_alphanumeric()
            || previous == b'_'
            || matches!(previous, b')' | b']' | b'}' | b'\'' | b'"'))
        {
            continue;
        }

        let argument_start = (open_index + 1..for_index)
            .rev()
            .find(|&index| significant[index].0 == TokenKind::Comma && depths[index] == depth)
            .map_or(open_index + 1, |index| index + 1);
        let argument = &significant[argument_start..for_index];
        if argument.len() < 3
            || argument[0].0 != TokenKind::Name
            || argument[1].0 != TokenKind::Equal
        {
            continue;
        }
        return Some((
            argument[0].1.start().to_usize(),
            argument[1].1.end().to_usize(),
        ));
    }
    None
}

/// `action_helpers.c _PyPegen_get_expr_name`: the noun `python.gram`'s
/// assignment diagnostics print for a target expression.
fn assignment_expr_name(expr: &rustpython_compiler::ast::Expr) -> Option<&'static str> {
    use rustpython_compiler::ast::Expr;
    Some(match expr {
        Expr::Attribute(_) => "attribute",
        Expr::Subscript(_) => "subscript",
        Expr::Starred(_) => "starred",
        Expr::Name(_) => "name",
        Expr::List(_) => "list",
        Expr::Tuple(_) => "tuple",
        Expr::Lambda(_) => "lambda",
        Expr::Call(_) => "function call",
        Expr::BoolOp(_) | Expr::BinOp(_) | Expr::UnaryOp(_) => "expression",
        Expr::Generator(_) => "generator expression",
        Expr::Yield(_) | Expr::YieldFrom(_) => "yield expression",
        Expr::Await(_) => "await expression",
        Expr::ListComp(_) => "list comprehension",
        Expr::SetComp(_) => "set comprehension",
        Expr::DictComp(_) => "dict comprehension",
        Expr::Dict(_) => "dict literal",
        Expr::Set(_) => "set display",
        Expr::FString(_) => "f-string expression",
        Expr::TString(_) => "t-string expression",
        Expr::NoneLiteral(_) => "None",
        Expr::BooleanLiteral(node) => {
            if node.value {
                "True"
            } else {
                "False"
            }
        }
        Expr::EllipsisLiteral(_) => "ellipsis",
        Expr::StringLiteral(_) | Expr::BytesLiteral(_) | Expr::NumberLiteral(_) => "literal",
        Expr::Compare(_) => "comparison",
        Expr::If(_) => "conditional expression",
        Expr::Named(_) => "named expression",
        // `_PyPegen_get_expr_name` raises SystemError for anything else, which
        // means no assignment diagnostic names it; leave the parser's own.
        _ => return None,
    })
}

/// `action_helpers.c _PyPegen_get_invalid_target` for `STAR_TARGETS`: the
/// innermost element of a target that cannot be assigned to, or `None` when
/// every element can.  Only a list and a tuple are descended, because those are
/// the only targets whose elements are themselves targets.
fn invalid_assignment_target(
    expr: &rustpython_compiler::ast::Expr,
) -> Option<&rustpython_compiler::ast::Expr> {
    use rustpython_compiler::ast::Expr;
    match expr {
        Expr::List(node) => node.elts.iter().find_map(invalid_assignment_target),
        Expr::Tuple(node) => node.elts.iter().find_map(invalid_assignment_target),
        Expr::Starred(node) => invalid_assignment_target(&node.value),
        Expr::Name(_) | Expr::Subscript(_) | Expr::Attribute(_) => None,
        _ => Some(expr),
    }
}

/// Whether `expr` is wrapped in parentheses the expression itself does not own.
///
/// A parenthesized expression reaches the grammar as an `atom`, so the
/// precedence tests below see it as one whatever it contains — `(a or b) = 1`
/// is named the way `f() = 1` is and `a or b = 1` is not.  Ruff's range for a
/// generator expression and for a parenthesized tuple already covers the
/// parentheses those two forms own, so both answer false here, which is what
/// the `!(list|tuple|genexp|...)` guard wants.
fn parenthesized_expr(source: &str, expr: &rustpython_compiler::ast::Expr) -> bool {
    source
        .get(..expr.range().start().to_usize())
        .is_some_and(|before| before.trim_end().ends_with('('))
}

/// The starred element of a target that `expressions` cannot parse, if it has
/// one.  A display keeps its own brackets and unpacks inside them, so only an
/// unparenthesized tuple hands its elements to the expression grammar one by
/// one.
fn first_starred_target(
    target: &rustpython_compiler::ast::Expr,
) -> Option<&rustpython_compiler::ast::Expr> {
    use rustpython_compiler::ast::Expr;
    match target {
        Expr::Starred(_) => Some(target),
        Expr::Tuple(tuple) if !tuple.parenthesized => tuple
            .elts
            .iter()
            .find(|element| matches!(element, Expr::Starred(_))),
        _ => None,
    }
}

/// The index recovery recorded for an expression it could not parse, if
/// `expr` holds one.
///
/// A missing operand reaches the tree as an `ExprName` carrying an empty name
/// over the empty range `missing_node_range` puts at the end of the last token
/// that was read, so `x ===` arrives as a comparison whose right operand is
/// that node.  `star_targets` matches no such target: the parse stopped at the
/// token after it, which is the failure reported, so the diagnostics below must
/// not name a target holding one.  The smallest index wins, because a target
/// can hold more than one and the earliest is where the parse stopped.
fn missing_expression_index(expr: &rustpython_compiler::ast::Expr) -> Option<usize> {
    use rustpython_compiler::ast::{
        Expr,
        visitor::{self, Visitor},
    };

    struct MissingFinder {
        index: Option<usize>,
    }

    impl<'a> Visitor<'a> for MissingFinder {
        fn visit_expr(&mut self, expr: &'a Expr) {
            if let Expr::Name(name) = expr
                && name.id.as_str().is_empty()
            {
                let index = expr.range().start().to_usize();
                self.index = Some(self.index.map_or(index, |first| first.min(index)));
            }
            visitor::walk_expr(self, expr);
        }
    }

    let mut finder = MissingFinder { index: None };
    finder.visit_expr(expr);
    finder.index
}

/// The span of the token the parse stopped on, given the index recovery
/// recorded for the expression that is missing.
///
/// `missing_node_range` sits at the end of the last token that was read, so the
/// token that failed opens at the next character that is neither a space nor a
/// tab.  A newline is that token when the expression ran off the end of the
/// line -- `x ==` is reported at the newline's own column, one past the source
/// text -- so only spaces and tabs are skipped.
fn stopped_token_span(source: &str, missing_index: usize) -> (usize, usize) {
    let start = source.get(missing_index..).map_or(missing_index, |rest| {
        missing_index
            + rest
                .char_indices()
                .find(|(_, character)| !matches!(character, ' ' | '\t'))
                .map_or(rest.len(), |(index, _)| index)
    });
    (start, start + 1)
}

/// The span of the token a statement opens with.
///
/// Every compound statement opens with a keyword, and a decorated one with
/// `@`, so this is the token the expression grammar rejects outright.
fn leading_token_span(source: &str, statement: &rustpython_compiler::ast::Stmt) -> (usize, usize) {
    let start = statement.range().start().to_usize();
    let rest = source.get(start..).unwrap_or_default();
    let length = rest
        .find(|character: char| !character.is_alphanumeric() && character != '_')
        .unwrap_or(rest.len())
        .max(1);
    (start, start + length)
}

/// Whether the target reaches `python.gram:invalid_named_expression`'s third
/// alternative, which is what prints the `Maybe you meant '=='` form.
///
/// That alternative reads `!(list|tuple|genexp|'True'|'None'|'False')
/// a=bitwise_or '=' bitwise_or !('='|':=')`, so a target above `bitwise_or` in
/// the precedence chain — a disjunction, an inversion, a comparison, a
/// conditional expression, a lambda, an unparenthesized named or yield
/// expression, a starred or an unparenthesized tuple — never matches it, and
/// the six spelled-out forms are refused outright.
fn named_expression_assignment_target(source: &str, expr: &rustpython_compiler::ast::Expr) -> bool {
    use rustpython_compiler::ast::{Expr, UnaryOp};
    if parenthesized_expr(source, expr) {
        return true;
    }
    !matches!(
        expr,
        Expr::List(_)
            | Expr::Tuple(_)
            | Expr::Generator(_)
            | Expr::NoneLiteral(_)
            | Expr::BooleanLiteral(_)
            | Expr::BoolOp(_)
            | Expr::Compare(_)
            | Expr::If(_)
            | Expr::Lambda(_)
            | Expr::Named(_)
            | Expr::Yield(_)
            | Expr::YieldFrom(_)
            | Expr::Starred(_)
    ) && !matches!(
        expr,
        Expr::UnaryOp(node) if node.op == UnaryOp::Not
    )
}

/// Whether the assigned value begins with a `bitwise_or`, which is the second
/// half of that same alternative.
///
/// The alternative consumes only a `bitwise_or` prefix of the value and then
/// refuses a following `=` or `:=`, so `f() = a if b else c` matches on `a`
/// while `f() = yield x`, `f() = *a,` and `f() = a := 1` do not.
fn value_opens_with_bitwise_or(source: &str, expr: &rustpython_compiler::ast::Expr) -> bool {
    use rustpython_compiler::ast::{Expr, UnaryOp};
    if expr.range().is_empty() {
        return false;
    }
    if parenthesized_expr(source, expr) {
        return true;
    }
    match expr {
        Expr::Yield(_) | Expr::YieldFrom(_) | Expr::Starred(_) | Expr::Lambda(_) => false,
        Expr::Named(_) => false,
        Expr::UnaryOp(node) if node.op == UnaryOp::Not => false,
        Expr::BoolOp(node) => node
            .values
            .first()
            .is_some_and(|value| value_opens_with_bitwise_or(source, value)),
        Expr::BinOp(node) => value_opens_with_bitwise_or(source, &node.left),
        Expr::Compare(node) => value_opens_with_bitwise_or(source, &node.left),
        Expr::If(node) => value_opens_with_bitwise_or(source, &node.body),
        Expr::Tuple(node) => node
            .elts
            .first()
            .is_some_and(|value| value_opens_with_bitwise_or(source, value)),
        _ => true,
    }
}

/// The `!('='|':=')` half of that alternative, read off the text: a recovering
/// parse ends the statement at the operator it could not use, so what follows
/// the value is what the lookahead would have seen.
fn value_followed_by_assignment(source: &str, value_end: usize) -> bool {
    let rest = source.get(value_end..).unwrap_or_default().trim_start();
    rest.starts_with(":=") || (rest.starts_with('=') && !rest.starts_with("=="))
}

/// The span of the assignment operator standing between a target and whatever
/// follows it -- the value, or the next target of a chain.
///
/// A parenthesized target ends inside its own parentheses, so the gap can open
/// with a run of closing ones: `(a) = 1` hands this `) = `.  Read the operator
/// out from its `=` rather than by trimming the gap, and the brackets stay out
/// of the span.
fn assignment_operator_span(
    source: &str,
    target_end: usize,
    next_start: usize,
) -> Option<(usize, usize)> {
    let gap = source.get(target_end..next_start)?;
    let equals = gap.find('=')?;
    let start = gap[..equals]
        .char_indices()
        .rev()
        .take_while(|(_, character)| {
            !character.is_whitespace() && !matches!(character, ')' | ']' | '}')
        })
        .last()
        .map_or(equals, |(index, _)| index);
    Some((target_end + start, target_end + equals + 1))
}

/// `python.gram:invalid_assignment` / `invalid_named_expression` name the
/// assignment target with `_PyPegen_get_expr_name` and choose between three
/// messages by the shape of the statement.  Ruff reaches only some of them, and
/// for the rest reports either a generic parse failure or the target's source
/// text, so rebuild the diagnostic from the statement the recovering parse
/// produced.
///
/// The recovered tree is what makes this decidable: the alternatives turn on
/// the number of targets, on the precedence of the target and of the value, and
/// on whether either was parenthesized — none of which a scan of the text
/// answers.  A statement whose target is assignable is left alone, which is how
/// an error elsewhere in it keeps the parser's own message.
fn assignment_target_error(
    error: &crate::compile::CompileError,
    source: &str,
    mode: crate::compile::Mode,
) -> Option<(String, usize, usize)> {
    use rustpython_compiler::ast::{self, Expr, Stmt, visitor::Visitor};

    // Both statements this reads are spelled with one, and the recovering parse
    // below is a second parse of the whole source: skip it for the failures that
    // cannot be an assignment at all.
    if !source.contains('=') {
        return None;
    }

    // A bracket left open swallows the rest of the file, so the statements the
    // recovering parse hands back are not the ones the grammar saw and the
    // tokenizer's own complaint is about the whole source rather than any one
    // of them.
    if let crate::compile::CompileError::Parse(parse_error) = error
        && parse_error.is_unclosed_bracket
    {
        return None;
    }

    // The location the diagnostic is being REPORTED at, not the range the parser
    // stopped on: the CPython-shaped override already moved some diagnostics off
    // the token that failed, and it is the reported one that has to belong to
    // the statement named below.  A parser diagnostic counts that column in
    // characters and a compiler one in UTF-8 bytes, the same split the caller
    // makes when it converts back.
    let (lineno, offset) = error.python_location();
    let error_index = match error {
        crate::compile::CompileError::Parse(_) => source_character_index(source, lineno, offset)?,
        crate::compile::CompileError::Codegen(_) => source_byte_index(source, lineno, offset)?,
    };

    struct AssignmentFinder<'a> {
        index: usize,
        found: Option<&'a Stmt>,
    }

    impl<'a> Visitor<'a> for AssignmentFinder<'a> {
        fn visit_stmt(&mut self, statement: &'a Stmt) {
            let range = statement.range();
            if !(range.start().to_usize() <= self.index && self.index <= range.end().to_usize()) {
                return;
            }
            if matches!(statement, Stmt::Assign(_) | Stmt::AugAssign(_)) {
                self.found = Some(statement);
            }
            ast::visitor::walk_stmt(self, statement);
        }
    }

    let parsed = crate::compile::parser::parse_unchecked_source(source, ast::PySourceType::Python);
    let mut finder = AssignmentFinder {
        index: error_index,
        found: None,
    };
    for statement in &parsed.syntax().body {
        finder.visit_stmt(statement);
    }
    let span = |expr: &Expr| {
        (
            expr.range().start().to_usize(),
            expr.range().end().to_usize(),
        )
    };

    let found = finder.found?;

    // `eval` is `expressions NEWLINE* ENDMARKER`, which has no assignment rule
    // at all: the parse stops at the operator and reports the plain failure
    // rather than any of the messages below.  Two target shapes fail before it
    // and name their own first token instead -- a starred element of an
    // unparenthesized tuple, at its `*`, and an unparenthesized `yield`, at the
    // keyword.  A display keeps its own brackets and unpacks inside them, so
    // `[*a, b] = 1` and `(a, *b) = 1` still report at the operator.
    if matches!(mode, crate::compile::Mode::Eval) {
        // `expressions` reaches an assignment operator only when the assignment
        // is the whole source.  A nested one stands behind the keyword that
        // opens the statement holding it, which is where the parse stopped, so
        // report there instead -- `def f(): (yield a) = 1` is named at `def`.
        let top_level = parsed.syntax().body.iter().find(|statement| {
            let range = statement.range();
            range.start().to_usize() <= error_index && error_index <= range.end().to_usize()
        })?;
        if !std::ptr::eq(top_level, found) {
            let (start, end) = leading_token_span(source, top_level);
            return Some(("invalid syntax".to_owned(), start, end));
        }
        let (target, next) = match found {
            Stmt::AugAssign(node) => (node.target.as_ref(), node.value.as_ref()),
            Stmt::Assign(node) => (
                node.targets.first()?,
                node.targets.get(1).unwrap_or(node.value.as_ref()),
            ),
            _ => return None,
        };
        if let Some(starred) = first_starred_target(target) {
            let start = starred.range().start().to_usize();
            return Some(("invalid syntax".to_owned(), start, start + 1));
        }
        if matches!(target, Expr::Yield(_) | Expr::YieldFrom(_))
            && !parenthesized_expr(source, target)
        {
            let start = target.range().start().to_usize();
            return Some(("invalid syntax".to_owned(), start, start + "yield".len()));
        }
        let (start, end) = assignment_operator_span(
            source,
            target.range().end().to_usize(),
            next.range().start().to_usize(),
        )?;
        return Some(("invalid syntax".to_owned(), start, end));
    }

    match found {
        Stmt::AugAssign(node) => {
            let target = node.target.as_ref();
            // `single_target` is the only augmented target the grammar accepts,
            // so anything else reaches `invalid_assignment`'s last alternative.
            if matches!(
                target,
                Expr::Name(_) | Expr::Attribute(_) | Expr::Subscript(_)
            ) {
                return None;
            }
            // A target the parse never finished reaches no alternative at all:
            // `x == += 1` stops at the augmented operator and is reported there,
            // over the operator's own two columns, rather than named.
            if let Some(index) = missing_expression_index(target) {
                let (start, end) =
                    assignment_operator_span(source, index, node.value.range().start().to_usize())?;
                return Some(("invalid syntax".to_owned(), start, end));
            }
            // That alternative reads `star_expressions augassign`, and an
            // unparenthesized yield is not one: the parse stops at the operator.
            if matches!(target, Expr::Yield(_) | Expr::YieldFrom(_))
                && !parenthesized_expr(source, target)
            {
                let (start, end) = assignment_operator_span(
                    source,
                    target.range().end().to_usize(),
                    node.value.range().start().to_usize(),
                )?;
                return Some(("invalid syntax".to_owned(), start, end));
            }
            let name = assignment_expr_name(target)?;
            let (start, end) = span(target);
            Some((
                format!("'{name}' is an illegal expression for augmented assignment"),
                start,
                end,
            ))
        }
        Stmt::Assign(node) => {
            // `(star_targets '=')* a=yield_expr '='` carries its own message.
            if let Some(target) = node.targets.iter().find(|target| {
                matches!(target, Expr::Yield(_) | Expr::YieldFrom(_))
                    && !parenthesized_expr(source, target)
            }) {
                let (start, end) = span(target);
                return Some((
                    "assignment to yield expression not possible".to_owned(),
                    start,
                    end,
                ));
            }
            // A target the parse never finished is named by none of the
            // alternatives: `x ===` and `[x ==] = 1` stop at the token after the
            // missing operand -- the third `=` and the `]` -- and report the
            // plain failure there instead of calling the target a comparison.
            if let Some(index) = node
                .targets
                .iter()
                .filter_map(missing_expression_index)
                .min()
            {
                let (start, end) = stopped_token_span(source, index);
                return Some(("invalid syntax".to_owned(), start, end));
            }
            // `(star_targets '=')*` consumes the assignable targets ahead of the
            // one that fails, which is why a chain reports its second target.
            let invalid = node.targets.iter().find_map(invalid_assignment_target)?;
            if let [target] = node.targets.as_slice()
                && named_expression_assignment_target(source, target)
                && value_opens_with_bitwise_or(source, &node.value)
                && !value_followed_by_assignment(source, node.value.range().end().to_usize())
            {
                let name = assignment_expr_name(target)?;
                let (start, end) = span(target);
                return Some((
                    format!("cannot assign to {name} here. Maybe you meant '==' instead of '='?"),
                    start,
                    end,
                ));
            }
            let name = assignment_expr_name(invalid)?;
            let (start, end) = span(invalid);
            Some((format!("cannot assign to {name}"), start, end))
        }
        _ => None,
    }
}

/// `Parser/string_parser.c parse_string_literal` raises the non-ASCII bytes
/// error at the token (`RAISE_SYNTAX_ERROR_KNOWN_LOCATION(t)`), not at the
/// offending code point.  Ruff's diagnostic instead selects that code point;
/// recover the containing literal token while retaining its parser message.
fn nonascii_bytes_literal_span(source: &str, raw_index: usize) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    let raw_index = raw_index.min(bytes.len());
    let line_start = bytes[..raw_index]
        .iter()
        .rposition(|byte| *byte == b'\n')
        .map_or(0, |index| index + 1);
    let mut quote_start = bytes[line_start..raw_index]
        .iter()
        .rposition(|byte| matches!(*byte, b'\'' | b'"'))?
        + line_start;
    let quote = bytes[quote_start];
    let triple = quote_start >= line_start + 2
        && bytes[quote_start - 1] == quote
        && bytes[quote_start - 2] == quote;
    if triple {
        quote_start -= 2;
    }
    let mut token_start = quote_start;
    while token_start > line_start && bytes[token_start - 1].is_ascii_alphabetic() {
        token_start -= 1;
    }
    let prefix = &bytes[token_start..quote_start];
    if !prefix.iter().any(|byte| matches!(*byte, b'b' | b'B'))
        || !prefix
            .iter()
            .all(|byte| matches!(*byte, b'b' | b'B' | b'r' | b'R'))
    {
        return None;
    }

    let quote_len = if triple { 3 } else { 1 };
    let mut cursor = quote_start + quote_len;
    while cursor < bytes.len() {
        if bytes[cursor] == b'\\' {
            cursor = (cursor + 2).min(bytes.len());
            continue;
        }
        if triple {
            if bytes[cursor..].starts_with(&[quote, quote, quote]) {
                return Some((token_start, cursor + 3));
            }
        } else if bytes[cursor] == quote {
            return Some((token_start, cursor + 1));
        } else if bytes[cursor] == b'\n' {
            return None;
        }
        cursor += 1;
    }
    None
}

/// `Parser/lexer/lexer.c` `maybe_raise_syntax_error_for_string_prefixes`.
/// Ruff tokenizes an incompatible prefix as a NAME followed by a STRING and
/// reports whatever grammar alternative that breaks, so the literal is
/// recovered from the source text and given the ordered prefix checks.
///
/// The check runs in the tokenizer, ahead of every grammar alternative, so the
/// literal can stand anywhere in the source -- after the reported token as
/// well as before it -- and the token stream alone decides which one is
/// reported: `f() = 'ok'; bu'x'` names the prefix, not the assignment.
fn incompatible_string_prefix_error(
    source: &str,
    raw_index: usize,
    tokenizer_stop: Option<usize>,
) -> Option<(String, usize, usize)> {
    let bytes = source.as_bytes();
    first_string_prefix_pair_error(
        bytes,
        raw_index.min(bytes.len()),
        tokenizer_stop.map(|stop| stop.min(bytes.len())),
    )
}

/// The first string token in `bytes` whose prefix is an incompatible pair.
///
/// The tokenizer reads neither a comment nor the text of a literal, so neither
/// does this walk: a quote it stops on opens a token, and a literal's own text
/// is skipped.  An f-string's replacement fields are tokenized, so a literal
/// written inside one is a token in its own right -- `f'{ub"y"}'` names its
/// prefix, and `f'{d['k']}'` is one f-string rather than a literal ending at
/// the quote before `k`.  An unterminated literal ends the walk: the tokenizer
/// raises its own error there and never reaches a prefix written after it.
///
/// A literal inside a replacement field is diagnosed by the parser reading
/// that field rather than by the tokenizer, so it only stands where it
/// precedes the error already reported at `anchor`: `s = f'{ub"y"}'; f() = 1`
/// names the prefix and `f() = 1; s = f'{ub"y"}'` names the assignment.
fn first_string_prefix_pair_error(
    bytes: &[u8],
    anchor: usize,
    tokenizer_stop: Option<usize>,
) -> Option<(String, usize, usize)> {
    /// One replacement field inside an interpolated literal.  Delimiters are
    /// the expression's own displays/calls/subscripts; an empty stack is what
    /// makes `:` enter the format specification rather than a slice or dict.
    struct ReplacementField {
        delimiters: Vec<u8>,
        format_spec: bool,
    }

    /// One literal the walk is inside, plus the nested replacement fields the
    /// tokenizer has entered.  A format specification is literal text until
    /// another `{` opens its own replacement field.
    struct OpenLiteral {
        delimiter: u8,
        triple: bool,
        interpolated: bool,
        fields: Vec<ReplacementField>,
    }

    let mut open: Vec<OpenLiteral> = Vec::new();
    let mut cursor = 0;
    while cursor < bytes.len() {
        if tokenizer_stop.is_some_and(|stop| cursor > stop) {
            return None;
        }
        let byte = bytes[cursor];
        // The innermost literal's own text, or the literal format-spec text of
        // its current field.  A nested replacement field switches back to
        // token mode until its own `}`.
        if let Some(literal) = open
            .last_mut()
            .filter(|literal| literal.fields.last().is_none_or(|field| field.format_spec))
        {
            let in_format_spec = !literal.fields.is_empty();
            match byte {
                // A backslash closes no literal, raw included: `r'\''` keeps
                // the escape in its text and the quote after it in the token.
                // In an interpolated literal it does not hide a following
                // brace: PyPy's `fstring_find_literal` consumes the escape and
                // then still applies its brace branch to that character.
                b'\\'
                    if literal.interpolated
                        && matches!(bytes.get(cursor + 1), Some(b'{' | b'}')) =>
                {
                    cursor += 1
                }
                b'\\' => cursor += 2,
                b'\n' if !literal.triple => return None,
                // `{{` in the outer literal writes one brace.  In a format
                // specification every `{` starts the nested replacement field
                // that makes its contents tokenized expression text.
                b'{' if literal.interpolated => {
                    let doubled = !in_format_spec && bytes.get(cursor + 1) == Some(&b'{');
                    cursor += 1 + usize::from(doubled);
                    if !doubled {
                        literal.fields.push(ReplacementField {
                            delimiters: Vec::new(),
                            format_spec: false,
                        });
                    }
                }
                b'}' if literal.interpolated => {
                    if in_format_spec {
                        literal.fields.pop();
                        cursor += 1;
                    } else {
                        cursor += 1 + usize::from(bytes.get(cursor + 1) == Some(&b'}'));
                    }
                }
                _ if byte == literal.delimiter => {
                    if literal.triple && !bytes[cursor..].starts_with(&[byte; 3]) {
                        cursor += 1;
                    } else {
                        cursor += if literal.triple { 3 } else { 1 };
                        open.pop();
                    }
                }
                _ => cursor += 1,
            }
            continue;
        }
        match byte {
            // A comment runs to the end of its line both at module level and
            // in a replacement expression.  Literal and format-spec text took
            // the branch above and never reaches this token-mode arm.
            b'#' => {
                cursor = bytes[cursor..]
                    .iter()
                    .position(|byte| *byte == b'\n')
                    .map_or(bytes.len(), |newline| cursor + newline + 1);
            }
            b'(' | b'[' | b'{' => {
                if let Some(field) = open
                    .last_mut()
                    .and_then(|literal| literal.fields.last_mut())
                {
                    field.delimiters.push(byte);
                }
                cursor += 1;
            }
            b')' | b']' | b'}' => {
                if let Some(literal) = open.last_mut()
                    && let Some(field) = literal.fields.last_mut()
                {
                    let opening = match byte {
                        b')' => b'(',
                        b']' => b'[',
                        _ => b'{',
                    };
                    if field.delimiters.last() == Some(&opening) {
                        field.delimiters.pop();
                    } else if byte == b'}' && field.delimiters.is_empty() {
                        literal.fields.pop();
                    }
                }
                cursor += 1;
            }
            b':' => {
                if let Some(field) = open
                    .last_mut()
                    .and_then(|literal| literal.fields.last_mut())
                    && field.delimiters.is_empty()
                {
                    field.format_spec = true;
                }
                cursor += 1;
            }
            b'\'' | b'"' => {
                if let Some(error) = string_prefix_pair_error(bytes, cursor)
                    && (open.is_empty() || error.1 <= anchor)
                {
                    return Some(error);
                }
                let triple = bytes[cursor + 1..].starts_with(&[byte, byte]);
                let interpolated = string_prefix_span(bytes, cursor).is_some_and(|prefix| {
                    bytes[prefix]
                        .iter()
                        .any(|byte| matches!(byte.to_ascii_lowercase(), b'f' | b't'))
                });
                open.push(OpenLiteral {
                    delimiter: byte,
                    triple,
                    interpolated,
                    fields: Vec::new(),
                });
                cursor += if triple { 3 } else { 1 };
            }
            _ => cursor += 1,
        }
    }
    None
}

/// The letters written immediately before `quote`, or `None` when what stands
/// there cannot open a token.
fn string_prefix_span(bytes: &[u8], quote: usize) -> Option<std::ops::Range<usize>> {
    let mut start = quote;
    while start > 0
        && matches!(
            bytes[start - 1].to_ascii_lowercase(),
            b'b' | b'r' | b'u' | b'f' | b't'
        )
    {
        start -= 1;
    }
    // A prefix opens a token, so what stands before it has to close one.  An
    // identifier running into the letters makes them part of that name, and a
    // name carries bytes past ASCII too -- which is also what sits behind the
    // closing quote of a literal whose text ends in those letters.
    let closes_a_token = !bytes
        .get(start.wrapping_sub(1))
        .is_some_and(|byte| !byte.is_ascii() || byte.is_ascii_alphanumeric() || *byte == b'_');
    closes_a_token.then_some(start..quote)
}

/// The ordered prefix-pair checks applied to the letters written immediately
/// before `quote`.
fn string_prefix_pair_error(bytes: &[u8], quote: usize) -> Option<(String, usize, usize)> {
    let prefix = string_prefix_span(bytes, quote)?;
    let start = prefix.start;
    let mut seen = [false; 5];
    for byte in &bytes[prefix] {
        let index = match byte.to_ascii_lowercase() {
            b'b' => 0,
            b'r' => 1,
            b'u' => 2,
            b'f' => 3,
            b't' => 4,
            _ => return None,
        };
        if seen[index] {
            return None;
        }
        seen[index] = true;
    }
    let pair = if seen[2] && seen[0] {
        ("u", "b")
    } else if seen[2] && seen[1] {
        ("u", "r")
    } else if seen[2] && seen[3] {
        ("u", "f")
    } else if seen[2] && seen[4] {
        ("u", "t")
    } else if seen[0] && seen[3] {
        ("b", "f")
    } else if seen[0] && seen[4] {
        ("b", "t")
    } else if seen[3] && seen[4] {
        ("f", "t")
    } else {
        return None;
    };
    Some((
        format!("'{}' and '{}' prefixes are incompatible", pair.0, pair.1),
        start,
        quote,
    ))
}

/// A string literal's escape-decode failure.
struct EscapeError {
    /// What the decoder would have said.
    message: String,
    /// Byte offset of the literal, its prefix included.  The caller needs it
    /// because [`string_escape_error`] walks the whole source: the escape is
    /// only what gets reported when nothing earlier in the file already
    /// failed.
    literal_start: usize,
    /// Byte range the diagnostic points at.
    span: (usize, usize),
}

/// The escape-decode failure a string literal in `source` carries, if any.
///
/// `decode_unicode_with_escapes` runs a non-raw literal through the
/// `unicode_escape` decoder, and `decode_bytes_with_escapes` runs a bytes
/// literal through its own, both before the parser interprets anything inside
/// the literal.  The parser pyre delegates to reports every one of those
/// failures as a single `Got unexpected unicode`, so the literal is re-scanned
/// here to recover which escape failed and what the decoder would have said.
///
/// The positions the message carries are byte offsets into the literal's
/// contents, spanning the backslash through the last character the decoder
/// consumed.
fn string_escape_error(source: &str) -> Option<EscapeError> {
    let bytes = source.as_bytes();
    let mut cursor = 0;
    while cursor < bytes.len() {
        if bytes[cursor] == b'#' {
            cursor = bytes[cursor..]
                .iter()
                .position(|byte| *byte == b'\n')
                .map_or(bytes.len(), |newline| cursor + newline + 1);
            continue;
        }
        if !matches!(bytes[cursor], b'\'' | b'"') {
            cursor += 1;
            continue;
        }

        let quote_start = cursor;
        let mut token_start = quote_start;
        while token_start > 0 && bytes[token_start - 1].is_ascii_alphabetic() {
            token_start -= 1;
        }
        if bytes
            .get(token_start.wrapping_sub(1))
            .is_some_and(|byte| byte.is_ascii_alphanumeric() || *byte == b'_')
        {
            cursor += 1;
            continue;
        }
        let prefix = &bytes[token_start..quote_start];
        if !prefix
            .iter()
            .all(|byte| matches!(byte.to_ascii_lowercase(), b'b' | b'f' | b'r' | b't' | b'u'))
        {
            cursor += 1;
            continue;
        }
        let has = |wanted: u8| {
            prefix
                .iter()
                .any(|byte| byte.to_ascii_lowercase() == wanted)
        };
        // A raw literal keeps its backslashes, so no decoder runs over it.
        if has(b'r') {
            cursor += 1;
            continue;
        }
        let bytes_literal = has(b'b');
        let replacement_fields = has(b'f') || has(b't');

        let quote = bytes[quote_start];
        let triple = bytes[quote_start..].starts_with(&[quote, quote, quote]);
        let quote_len = if triple { 3 } else { 1 };
        let content_start = quote_start + quote_len;
        let mut content_end = content_start;
        while content_end < bytes.len() {
            if triple && bytes[content_end..].starts_with(&[quote, quote, quote]) {
                break;
            }
            if !triple && bytes[content_end] == quote {
                break;
            }
            if bytes[content_end] == b'\\' {
                content_end = (content_end + 2).min(bytes.len());
            } else {
                content_end += 1;
            }
        }

        let token_end = (content_end + quote_len).min(bytes.len());
        if let Some(message) = escape_decode_error(
            &bytes[content_start..content_end],
            bytes_literal,
            replacement_fields,
        ) {
            // A literal that holds replacement fields is several tokens, and
            // the one the report points at is the closing quote; a literal
            // that is one token is pointed at whole.
            let span = if replacement_fields {
                (token_end.saturating_sub(quote_len), token_end)
            } else {
                (token_start, token_end)
            };
            return Some(EscapeError {
                message,
                literal_start: token_start,
                span,
            });
        }
        cursor = token_end;
    }
    None
}

/// The decoder's complaint about a literal's `contents`.
///
/// A literal holding replacement fields reaches the decoder one piece at a
/// time -- the run of text between two fields -- and the positions the message
/// carries are relative to the piece the escape sits in.
fn escape_decode_error(
    contents: &[u8],
    bytes_literal: bool,
    replacement_fields: bool,
) -> Option<String> {
    /// `'unicodeescape' codec can't decode bytes in position ...`, whose range
    /// runs from the backslash through the last character consumed.
    fn unicode_error(start: usize, end: usize, reason: &str) -> String {
        format!(
            "(unicode error) 'unicodeescape' codec can't decode bytes in position {start}-{end}: {reason}"
        )
    }

    let mut piece_start = 0;
    let mut cursor = 0;
    while cursor < contents.len() {
        // A replacement field is not text the decoder ever sees, and the piece
        // after it starts over at position 0.  A doubled brace is not one: it
        // stays in the piece it is written in.
        if replacement_fields && contents[cursor] == b'{' && contents.get(cursor + 1) != Some(&b'{')
        {
            let mut depth = 1usize;
            cursor += 1;
            while cursor < contents.len() && depth > 0 {
                match contents[cursor] {
                    b'{' => depth += 1,
                    b'}' => depth -= 1,
                    _ => {}
                }
                cursor += 1;
            }
            piece_start = cursor;
            continue;
        }
        if contents[cursor] != b'\\' {
            cursor += 1;
            continue;
        }
        let Some(&kind) = contents.get(cursor + 1) else {
            return None;
        };
        // `\N{...}` names a character; a bytes literal has no such escape.  The
        // brace here belongs to the escape, which is why the field skip above
        // runs only where no backslash precedes it.
        if kind == b'N' && !bytes_literal {
            if contents.get(cursor + 2) != Some(&b'{') {
                return Some(unicode_error(
                    cursor - piece_start,
                    cursor + 1 - piece_start,
                    r"malformed \N character escape",
                ));
            }
            let Some(close) = contents[cursor + 3..].iter().position(|byte| *byte == b'}') else {
                return Some(unicode_error(
                    cursor - piece_start,
                    contents.len().saturating_sub(1) - piece_start,
                    r"malformed \N character escape",
                ));
            };
            let close = cursor + 3 + close;
            let name = std::str::from_utf8(&contents[cursor + 3..close]).ok();
            if name
                .and_then(rustpython_unicode::lookup_character)
                .is_none()
            {
                return Some(unicode_error(
                    cursor - piece_start,
                    close - piece_start,
                    "unknown Unicode character name",
                ));
            }
            cursor = close + 1;
            continue;
        }
        // `\u` and `\U` are ordinary characters in a bytes literal too.
        let (width, form) = match kind {
            b'x' => (2, r"\xXX"),
            b'u' if !bytes_literal => (4, r"\uXXXX"),
            b'U' if !bytes_literal => (8, r"\UXXXXXXXX"),
            _ => {
                cursor += 2;
                continue;
            }
        };
        let digits_start = cursor + 2;
        let digits = contents[digits_start.min(contents.len())..]
            .iter()
            .take(width)
            .take_while(|byte| byte.is_ascii_hexdigit())
            .count();
        if digits < width {
            // `decode_bytes_with_escapes` reports its own failure, and names
            // only where the escape began.
            return Some(if bytes_literal {
                let position = cursor - piece_start;
                format!(r"(value error) invalid \x escape at position {position}")
            } else {
                unicode_error(
                    cursor - piece_start,
                    digits_start + digits - 1 - piece_start,
                    &format!("truncated {form} escape"),
                )
            });
        }
        let end = digits_start + width;
        if kind == b'U'
            && std::str::from_utf8(&contents[digits_start..end])
                .ok()
                .and_then(|text| u32::from_str_radix(text, 16).ok())
                .is_none_or(|value| value > 0x10_FFFF)
        {
            return Some(unicode_error(
                cursor - piece_start,
                end - 1 - piece_start,
                "illegal Unicode character",
            ));
        }
        cursor = end;
    }
    None
}

/// CPython 3.14 `Parser/python.gram` f-string replacement-field invalid
/// rules.  A `#` starts an ordinary tokenizer comment inside a field: on one
/// physical line it consumes the apparent closing brace, while a multiline
/// field containing only comments reaches the dedicated empty-expression
/// rule.  Ruff surfaces both through coarser f-string parser errors.
fn fstring_comment_diagnostic(message: &str, source: &str) -> Option<&'static str> {
    if !source.contains('#') {
        return None;
    }
    if message == "f-string: unterminated string" {
        return Some("'{' was never closed");
    }
    if source.contains("{)#") {
        Some("f-string: unmatched ')'")
    } else if source.contains('\n') && fstring_field_contains_only_comments(source) {
        Some("f-string: valid expression required before '}'")
    } else {
        None
    }
}

/// Whether the first replacement field has no token other than whitespace and
/// comments before its closing brace.  PyPy's f-string tokenizer enters the
/// ordinary expression tokenizer for the field; comments therefore disappear
/// before `python.gram:invalid_replacement_field` decides that it is empty.
fn fstring_field_contains_only_comments(source: &str) -> bool {
    let bytes = source.as_bytes();
    let Some(quote) = bytes.iter().enumerate().find_map(|(index, byte)| {
        if !matches!(*byte, b'\'' | b'"') {
            return None;
        }
        let mut prefix = index;
        while prefix > 0 && bytes[prefix - 1].is_ascii_alphabetic() {
            prefix -= 1;
        }
        bytes[prefix..index]
            .iter()
            .any(|byte| byte.eq_ignore_ascii_case(&b'f'))
            .then_some(index)
    }) else {
        return false;
    };
    let quote_byte = bytes[quote];
    let triple = bytes[quote..].starts_with(&[quote_byte, quote_byte, quote_byte]);
    let mut cursor = quote + if triple { 3 } else { 1 };
    loop {
        let Some(relative_open) = bytes[cursor..].iter().position(|byte| *byte == b'{') else {
            return false;
        };
        cursor += relative_open;
        if bytes.get(cursor + 1) == Some(&b'{') {
            cursor += 2;
        } else {
            cursor += 1;
            break;
        }
    }
    while cursor < bytes.len() {
        match bytes[cursor] {
            byte if byte.is_ascii_whitespace() => cursor += 1,
            b'#' => {
                while cursor < bytes.len() && bytes[cursor] != b'\n' {
                    cursor += 1;
                }
            }
            b'}' => return true,
            _ => return false,
        }
    }
    false
}

/// CPython's tokenizer keeps the opening-delimiter stack while lexing an
/// f-string replacement field.  Ruff sometimes lets its expression parser
/// replace that tokenizer error with `Expected ...` or a generic missing
/// brace, so recover the first mismatched closer and its exact source byte.
fn fstring_mismatched_delimiter(source: &str) -> Option<(String, usize)> {
    let bytes = source.as_bytes();
    let quote = bytes.iter().enumerate().find_map(|(index, byte)| {
        if !matches!(*byte, b'\'' | b'"') {
            return None;
        }
        let mut prefix = index;
        while prefix > 0 && bytes[prefix - 1].is_ascii_alphabetic() {
            prefix -= 1;
        }
        bytes[prefix..index]
            .iter()
            .any(|byte| byte.eq_ignore_ascii_case(&b'f'))
            .then_some(index)
    })?;
    let quote_byte = bytes[quote];
    let triple = bytes[quote..].starts_with(&[quote_byte, quote_byte, quote_byte]);
    let mut cursor = quote + if triple { 3 } else { 1 };
    while cursor < bytes.len() {
        if bytes[cursor] != b'{' || bytes.get(cursor + 1) == Some(&b'{') {
            cursor += 1;
            continue;
        }
        cursor += 1;
        let mut stack = Vec::new();
        while cursor < bytes.len() {
            match bytes[cursor] {
                b'\'' | b'"' => {
                    let inner_quote = bytes[cursor];
                    cursor += 1;
                    while cursor < bytes.len() && bytes[cursor] != inner_quote {
                        cursor += if bytes[cursor] == b'\\' { 2 } else { 1 };
                    }
                }
                opener @ (b'(' | b'[' | b'{') => stack.push(opener),
                closer @ (b')' | b']' | b'}') => {
                    let expected_open = match closer {
                        b')' => b'(',
                        b']' => b'[',
                        b'}' => b'{',
                        _ => unreachable!(),
                    };
                    if let Some(&opening) = stack.last() {
                        if opening != expected_open {
                            return Some((
                                format!(
                                    "closing parenthesis '{}' does not match opening parenthesis '{}'",
                                    closer as char, opening as char
                                ),
                                cursor,
                            ));
                        }
                        stack.pop();
                    } else if closer == b'}' {
                        break;
                    } else {
                        return Some((format!("f-string: unmatched '{}'", closer as char), cursor));
                    }
                }
                _ => {}
            }
            cursor += 1;
        }
        cursor += 1;
    }
    None
}

/// The empty replacement marker in a nested f-string.  Its recursive parser
/// fails before the outer field consumes the nested literal as an expression,
/// so it takes precedence over any delimiter the outer recovery later sees.
fn nested_empty_fstring_field_span(source: &str) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    for quote in 1..bytes.len() {
        if !matches!(bytes[quote], b'\'' | b'"') {
            continue;
        }
        let mut prefix = quote;
        while prefix > 0 && bytes[prefix - 1].is_ascii_alphabetic() {
            prefix -= 1;
        }
        if !bytes[prefix..quote]
            .iter()
            .any(|byte| byte.eq_ignore_ascii_case(&b'f'))
        {
            continue;
        }
        let triple = bytes[quote..].starts_with(&[bytes[quote], bytes[quote], bytes[quote]]);
        let mut cursor = quote + if triple { 3 } else { 1 };
        if bytes.get(cursor) != Some(&b'{') || bytes.get(cursor + 1) == Some(&b'{') {
            continue;
        }
        cursor += 1;
        while bytes.get(cursor).is_some_and(u8::is_ascii_whitespace) {
            cursor += 1;
        }
        if bytes.get(cursor) == Some(&b':') {
            return Some((cursor, cursor + 1));
        }
    }
    None
}

/// Locate an unparenthesized lambda inside an f-string field.  PyPy
/// `fstring_find_expr` sends the whole field expression through its recursive
/// eval parser, whose lambda-without-parentheses rule wins over the outer
/// f-string separator.  Ruff's recovered outer expression loses that choice.
#[derive(Clone, Copy)]
enum FstringLambdaDiagnostic {
    Unparenthesized((usize, usize)),
    InvalidExpression,
}

fn unparenthesized_fstring_lambda_span(source: &str) -> Option<FstringLambdaDiagnostic> {
    let bytes = source.as_bytes();
    let (start, end) = last_fstring_content_range(source)?;
    let mut cursor = start;
    let mut in_field = false;
    let mut field_start = start;
    let mut segment_start = start;
    let mut stack = Vec::new();
    while cursor < end {
        match bytes[cursor] {
            b'{' if !in_field && bytes.get(cursor + 1) == Some(&b'{') => cursor += 2,
            b'{' if !in_field => {
                in_field = true;
                cursor += 1;
                field_start = cursor;
                segment_start = cursor;
            }
            b'\'' | b'"' if in_field => {
                let quote = bytes[cursor];
                cursor += 1;
                while cursor < end && bytes[cursor] != quote {
                    cursor += if bytes[cursor] == b'\\' { 2 } else { 1 };
                }
                cursor += usize::from(cursor < end);
            }
            opener @ (b'(' | b'[' | b'{') if in_field => {
                stack.push(opener);
                cursor += 1;
            }
            b')' | b']' if in_field && !stack.is_empty() => {
                stack.pop();
                cursor += 1;
            }
            b'}' if in_field && !stack.is_empty() => {
                stack.pop();
                cursor += 1;
            }
            b'}' if in_field => {
                in_field = false;
                cursor += 1;
            }
            b',' if in_field && stack.is_empty() => {
                cursor += 1;
                segment_start = cursor;
            }
            b'l' if in_field
                && stack.is_empty()
                && bytes[cursor..].starts_with(b"lambda")
                && bytes
                    .get(cursor.wrapping_sub(1))
                    .is_none_or(|byte| !byte.is_ascii_alphanumeric() && *byte != b'_')
                && bytes
                    .get(cursor + b"lambda".len())
                    .is_none_or(|byte| !byte.is_ascii_alphanumeric() && *byte != b'_') =>
            {
                let starts_segment = bytes[segment_start..cursor]
                    .iter()
                    .all(u8::is_ascii_whitespace);
                let colon = bytes[cursor + b"lambda".len()..end]
                    .iter()
                    .position(|byte| *byte == b':')?
                    + cursor
                    + b"lambda".len();
                let span = (cursor, colon + 1);
                if starts_segment {
                    return Some(FstringLambdaDiagnostic::Unparenthesized(span));
                }
                // CPython's second f-string error pass treats a unary prefix
                // at the beginning of the whole field as an invalid field
                // expression.  A prefix after a comma, or a binary-expression
                // prefix, instead belongs to the ordinary delimiter recovery.
                let field_prefix = bytes[field_start..cursor].trim_ascii();
                if matches!(field_prefix, b"+" | b"-" | b"~" | b"not" | b"*" | b"**") {
                    return Some(FstringLambdaDiagnostic::InvalidExpression);
                }
                return None;
            }
            _ => cursor += 1,
        }
    }
    None
}

/// Find `$` where the tokenizer sees it as source rather than string/comment
/// contents.  This is used only to restore source-order precedence after a
/// later diagnostic-recovery pass has selected an earlier-looking message.
fn dollar_token_span(source: &str) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    let mut cursor = 0;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'#' => {
                while cursor < bytes.len() && bytes[cursor] != b'\n' {
                    cursor += 1;
                }
            }
            quote @ (b'\'' | b'"') => {
                let triple = bytes[cursor..].starts_with(&[quote, quote, quote]);
                cursor += if triple { 3 } else { 1 };
                while cursor < bytes.len() {
                    if bytes[cursor] == b'\\' {
                        cursor = (cursor + 2).min(bytes.len());
                    } else if triple && bytes[cursor..].starts_with(&[quote, quote, quote]) {
                        cursor += 3;
                        break;
                    } else if !triple && bytes[cursor] == quote {
                        cursor += 1;
                        break;
                    } else {
                        cursor += 1;
                    }
                }
            }
            b'$' => return Some((cursor, cursor + 1)),
            _ => cursor += 1,
        }
    }
    None
}

/// Whether the parser's raw byte lies on a physical line containing an
/// interpolated string token carrying `marker`.  CPython's tokenizer retains
/// the f/t prefix when it specializes unterminated-string diagnostics; Ruff's
/// unclosed-string error drops it.
fn unclosed_error_is_interpolated_string(source: &str, raw_index: usize, marker: u8) -> bool {
    let bytes = source.as_bytes();
    let raw_index = raw_index.min(bytes.len());
    let line_start = bytes[..raw_index]
        .iter()
        .rposition(|byte| *byte == b'\n')
        .map_or(0, |newline| newline + 1);
    let line_end = bytes[raw_index..]
        .iter()
        .position(|byte| *byte == b'\n')
        .map_or(bytes.len(), |newline| raw_index + newline);
    for quote in line_start..line_end {
        if !matches!(bytes[quote], b'\'' | b'"') {
            continue;
        }
        let mut prefix = quote;
        while prefix > line_start && bytes[prefix - 1].is_ascii_alphabetic() {
            prefix -= 1;
        }
        let token_head_end = quote
            + if bytes[quote..].starts_with(&[bytes[quote], bytes[quote], bytes[quote]]) {
                3
            } else {
                1
            };
        if bytes[prefix..quote]
            .iter()
            .any(|byte| byte.eq_ignore_ascii_case(&marker))
            && (prefix..=token_head_end).contains(&raw_index)
        {
            return true;
        }
    }
    false
}

fn unclosed_error_is_fstring(source: &str, raw_index: usize) -> bool {
    unclosed_error_is_interpolated_string(source, raw_index, b'f')
}

fn unclosed_error_is_tstring(source: &str, raw_index: usize) -> bool {
    unclosed_error_is_interpolated_string(source, raw_index, b't')
}

fn source_has_tstring(source: &str) -> bool {
    let mut lexer =
        crate::compile::parser::lexer::lex(source, crate::compile::parser::Mode::Module);
    loop {
        let kind = lexer.next_token();
        if matches!(kind, rustpython_compiler::TokenKind::TStringStart) {
            return true;
        }
        if kind.is_eof() {
            return false;
        }
    }
}

fn last_interpolated_string_content_range(source: &str, marker: u8) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    let mut cursor = 0;
    let mut last = None;
    while cursor < bytes.len() {
        if bytes[cursor] == b'#' {
            while cursor < bytes.len() && bytes[cursor] != b'\n' {
                cursor += 1;
            }
            continue;
        }
        if !matches!(bytes[cursor], b'\'' | b'"') {
            cursor += 1;
            continue;
        }
        let quote = cursor;
        let mut prefix = quote;
        while prefix > 0 && bytes[prefix - 1].is_ascii_alphabetic() {
            prefix -= 1;
        }
        let prefix_bytes = &bytes[prefix..quote];
        let is_interpolated = (prefix == 0
            || (!bytes[prefix - 1].is_ascii_alphanumeric() && bytes[prefix - 1] != b'_'))
            && ((prefix_bytes.len() == 1 && prefix_bytes[0].eq_ignore_ascii_case(&marker))
                || (prefix_bytes.len() == 2
                    && prefix_bytes
                        .iter()
                        .any(|byte| byte.eq_ignore_ascii_case(&marker))
                    && prefix_bytes
                        .iter()
                        .any(|byte| byte.eq_ignore_ascii_case(&b'r'))));
        let quote_byte = bytes[quote];
        let triple = bytes[quote..].starts_with(&[quote_byte, quote_byte, quote_byte]);
        let content_start = quote + if triple { 3 } else { 1 };
        cursor = content_start;
        let mut closed = false;
        while cursor < bytes.len() {
            if bytes[cursor] == b'\\' {
                cursor = (cursor + 2).min(bytes.len());
            } else if triple && bytes[cursor..].starts_with(&[quote_byte, quote_byte, quote_byte]) {
                closed = true;
                break;
            } else if !triple && bytes[cursor] == quote_byte {
                closed = true;
                break;
            } else {
                cursor += 1;
            }
        }
        if is_interpolated {
            last = Some((content_start, cursor));
        }
        if !closed {
            break;
        }
        cursor += if triple { 3 } else { 1 };
    }
    last
}

fn last_tstring_content_range(source: &str) -> Option<(usize, usize)> {
    last_interpolated_string_content_range(source, b't')
}

fn last_fstring_content_range(source: &str) -> Option<(usize, usize)> {
    last_interpolated_string_content_range(source, b'f')
}

fn tstring_blank_unclosed_field(source: &str) -> bool {
    let bytes = source.as_bytes();
    let Some((start, end)) = last_tstring_content_range(source) else {
        return false;
    };
    let Some(open) = bytes[start..end].iter().rposition(|byte| *byte == b'{') else {
        return false;
    };
    let open = start + open;
    bytes[open + 1..end].iter().all(u8::is_ascii_whitespace)
        && (open == start || bytes[open - 1] != b'{')
}

/// Inspect the outermost replacement field without attempting to reparse its
/// expression.  The parser has already established the diagnostic family;
/// this recovers only the invalid-rule token that Ruff's message discarded.
fn tstring_field_shape(source: &str) -> (bool, bool, bool) {
    let bytes = source.as_bytes();
    let Some((start, end)) = last_tstring_content_range(source) else {
        return (false, false, false);
    };
    let mut cursor = start;
    let mut in_field = false;
    let mut in_format = false;
    let mut stack = Vec::new();
    let mut top_level_semicolon = false;
    let mut nested_invalid_start = false;
    while cursor < end {
        match bytes[cursor] {
            b'{' if !in_field && bytes.get(cursor + 1) == Some(&b'{') => cursor += 2,
            b'{' if !in_field => {
                in_field = true;
                in_format = false;
                cursor += 1;
            }
            b'\'' | b'"' if in_field => {
                let quote = bytes[cursor];
                cursor += 1;
                while cursor < end && bytes[cursor] != quote {
                    cursor += if bytes[cursor] == b'\\' { 2 } else { 1 };
                }
                cursor += usize::from(cursor < end);
            }
            opener @ (b'(' | b'[' | b'{') if in_field && !in_format => {
                stack.push(opener);
                cursor += 1;
            }
            b')' | b']' if in_field && !in_format && !stack.is_empty() => {
                stack.pop();
                cursor += 1;
            }
            b'}' if in_field && !in_format && !stack.is_empty() => {
                stack.pop();
                cursor += 1;
            }
            b';' if in_field && !in_format && stack.is_empty() => {
                top_level_semicolon = true;
                cursor += 1;
            }
            b':' if in_field && !in_format && stack.is_empty() => {
                in_format = true;
                cursor += 1;
            }
            b'{' if in_field && in_format => {
                let mut next = cursor + 1;
                while next < end && bytes[next].is_ascii_whitespace() {
                    next += 1;
                }
                nested_invalid_start |= next < end
                    && matches!(
                        bytes[next],
                        b';' | b'=' | b'!' | b':' | b'}' | b',' | b'/' | b'%' | b'&' | b'|'
                    );
                cursor += 1;
            }
            b'}' if in_field => {
                in_field = false;
                in_format = false;
                cursor += 1;
            }
            _ => cursor += 1,
        }
    }
    (
        top_level_semicolon,
        in_field && in_format,
        nested_invalid_start,
    )
}

/// Diagnose a semicolon in the replacement field following a completed debug
/// field.  PyPy `fstring_find_expr` leaves the expression loop at the first
/// top-level field separator; `;` is not one, so the recursive expression
/// parser selects either its empty/invalid-start rule or the separator list.
/// Ruff instead reports the opening brace as merely missing its close.
fn fstring_debug_followup_diagnostic(source: &str) -> Option<&'static str> {
    let bytes = source.as_bytes();
    let (start, end) = last_fstring_content_range(source)?;
    let mut cursor = start;
    while cursor < end {
        if bytes[cursor] != b'{' {
            cursor += 1;
            continue;
        }
        if bytes.get(cursor + 1) == Some(&b'{') {
            cursor += 2;
            continue;
        }
        cursor += 1;
        let expression_start = cursor;
        let mut stack = Vec::new();
        let mut in_format_spec = false;
        while cursor < end {
            match bytes[cursor] {
                b'\'' | b'"' => {
                    let quote = bytes[cursor];
                    cursor += 1;
                    while cursor < end && bytes[cursor] != quote {
                        cursor += if bytes[cursor] == b'\\' { 2 } else { 1 };
                    }
                }
                opener @ (b'(' | b'[' | b'{') if !in_format_spec => stack.push(opener),
                b')' | b']' if !in_format_spec && !stack.is_empty() => {
                    stack.pop();
                }
                b'}' if !in_format_spec && !stack.is_empty() => {
                    stack.pop();
                }
                b':' if !in_format_spec && stack.is_empty() => in_format_spec = true,
                b';' if !in_format_spec && stack.is_empty() => {
                    let expression = source[expression_start..cursor].trim();
                    return Some(if matches!(expression, "" | "+" | "-" | "~") {
                        "f-string: expecting a valid expression after '{'"
                    } else {
                        "f-string: expecting '=', or '!', or ':', or '}'"
                    });
                }
                b'}' if stack.is_empty() => break,
                _ => {}
            }
            cursor += 1;
        }
        cursor += usize::from(cursor < end);
    }
    None
}

fn tstring_debug_missing_conversion(source: &str) -> bool {
    let bytes = source.as_bytes();
    let Some((start, end)) = last_tstring_content_range(source) else {
        return false;
    };
    for equals in start..end {
        if bytes[equals] != b'=' {
            continue;
        }
        let mut bang = equals + 1;
        while bang < end && bytes[bang].is_ascii_whitespace() {
            bang += 1;
        }
        if bytes.get(bang) != Some(&b'!') {
            continue;
        }
        let mut close = bang + 1;
        while close < end && bytes[close].is_ascii_whitespace() {
            close += 1;
        }
        if bytes.get(close) == Some(&b'}') {
            return true;
        }
    }
    false
}

/// CPython tokenizer state for an unclosed t-string replacement field.  An
/// open field which has not entered its format-specifier part reports the
/// unmatched `{`; after a top-level `:` the t-string itself is unterminated.
/// Doubled braces are literal text, and brackets inside the expression keep a
/// dict/slice colon from being mistaken for the format separator.
fn unclosed_tstring_replacement_field(source: &str) -> bool {
    let bytes = source.as_bytes();
    let Some((mut cursor, end)) = last_tstring_content_range(source) else {
        return false;
    };
    while cursor < end {
        if bytes[cursor] != b'{' {
            cursor += 1;
            continue;
        }
        if bytes.get(cursor + 1) == Some(&b'{') {
            cursor += 2;
            continue;
        }
        cursor += 1;
        let mut stack = Vec::new();
        let mut in_format_spec = false;
        while cursor < end {
            match bytes[cursor] {
                b'\'' | b'"' => {
                    let inner_quote = bytes[cursor];
                    cursor += 1;
                    while cursor < end && bytes[cursor] != inner_quote {
                        cursor += if bytes[cursor] == b'\\' { 2 } else { 1 };
                    }
                }
                opener @ (b'(' | b'[' | b'{') => stack.push(opener),
                b')' | b']' if !stack.is_empty() => {
                    stack.pop();
                }
                b'}' if !stack.is_empty() => {
                    stack.pop();
                }
                b'}' => return false,
                b':' if stack.is_empty() => in_format_spec = true,
                _ => {}
            }
            cursor += 1;
        }
        return !in_format_spec;
    }
    false
}

/// RustPython `vm_new.rs:new_syntax_error_maybe_incomplete` — select the
/// private Python 3.14 `_IncompleteInputError` subclass for parser failures
/// which end at an unfinished interactive input when
/// `PyCF_ALLOW_INCOMPLETE_INPUT` is set.  PyPy's compiler has the same
/// parser-level distinction through its `compile_command` path; pyre consumes
/// RustPython's parser, so keep its exact error-shape classification here.
///
/// `mode` is kept even when incomplete-input handling is disabled: CPython's
/// invalid-target reductions are part of the file/input grammar, while the
/// eval grammar rejects the same source with plain `invalid syntax`.
/// `PyPARSE_ALLOW_INCOMPLETE_INPUT` is likewise read by the parser selected by
/// that mode, and the three parsers do not stop at the same place.
fn compile_err_to_syntax_error_maybe_incomplete(
    e: crate::compile::CompileError,
    source: &str,
    mode: crate::compile::Mode,
    allow_incomplete: bool,
) -> crate::PyError {
    // Every location in `e` indexes the source the compiler was handed, which
    // `compile_source_with_opts` had already run through `universal_newline`.
    // Slice the same string here, or a `\r\n` input reports a line that still
    // carries its carriage return and a lone-`\r` one finds no line at all.
    let source = &*crate::compile::universal_newline(source);
    use rustpython_compiler::parser::{
        InterpolatedStringErrorType, LexicalErrorType, ParseErrorType,
    };

    // Parser locations are byte offsets, so index the source as bytes: a
    // non-ASCII character ahead of the quote would otherwise shift a
    // character-indexed lookup off the run being tested.  Quotes are ASCII,
    // so the byte comparison is exact.
    fn opens_triple_quote(source: &str, loc: usize) -> bool {
        let bytes = source.as_bytes();
        // The location names the literal, and a literal starts at its prefix:
        // `rb"""` opens its triple quote two bytes further on than `"""` does.
        // `tokenize.py StringPrefix` admits at most two prefix letters.
        let start = (loc..loc + 2)
            .take_while(|index| bytes.get(*index).is_some_and(u8::is_ascii_alphabetic))
            .last()
            .map_or(loc, |index| index + 1);
        bytes.get(start).is_some_and(|quote| {
            bytes.get(start + 1) == Some(quote) && bytes.get(start + 2) == Some(quote)
        })
    }

    // A single-quoted string that meets a newline is over -- that is where
    // `tok_get_normal_mode` reports `unterminated string literal` -- unless a
    // continuation took the newline, which carries the string onto the next
    // line. Reach the end of the source while it is still open and the
    // tokenizer stops at `E_EOFS` instead, which is more input wanted rather
    // than a bad program.
    //
    // So the string runs to the end only when every newline between its quote
    // and the end sits behind a continuation; the text after the final newline
    // has no newline to escape and is where the string is allowed to still be
    // open. A backslash escapes the character after it, so it is the parity of
    // the run ending a line that says whether that line's newline was taken.
    // `a = 'a`, `a = 'a\` and `a = 'a\\` all reach the end still open, while
    // `a = 'a` and `a = 'a\\` each followed by a newline meet it unescaped and
    // are errors -- which is how `codeop._maybe_compile`, retrying every
    // command with one newline appended, tells the two apart.
    fn ends_open_backslash_run(segment: &str) -> bool {
        segment.bytes().rev().take_while(|&b| b == b'\\').count() % 2 == 1
    }

    fn string_continues_to_eof(source: &str, loc: usize) -> bool {
        source.get(loc..).is_some_and(|tail| {
            let mut segments = tail.split('\n');
            segments.next_back();
            segments.all(ends_open_backslash_run)
        })
    }

    /// A triple-quoted literal left open wants more input under every parser.  A
    /// single-quoted one still open at the end of the source is reported as
    /// unterminated only by the block parser, which holds all the input there
    /// is; the interactive parser has another line to read and `eval`, wanting
    /// one expression, stops at the end of the input it was given, so for both
    /// the literal is unfinished.
    fn open_literal_wants_more_input(source: &str, loc: usize, mode: crate::compile::Mode) -> bool {
        opens_triple_quote(source, loc)
            || (!matches!(mode, crate::compile::Mode::Exec) && string_continues_to_eof(source, loc))
    }

    // A source holding nothing but blank lines and comments has no statement
    // to fail on, so the parser can only have run out of input: `eval` wants
    // an expression and the tokenizer reaches EOF still looking for one.
    fn holds_no_statement(source: &str) -> bool {
        source.lines().all(|line| {
            let line = line.trim_start();
            line.is_empty() || line.starts_with('#')
        })
    }

    // `_is_end_of_source`: the tokenizer state the incomplete-input flag is read
    // against.  `eval` parses one expression and stops at the first token that
    // cannot continue it, so its tokenizer reaches the end of the source only
    // when nothing earlier went wrong -- `x=[1,` fails at the `=`, three
    // characters before the bracket that is left open, and is a program that is
    // wrong where it stands however much more input follows it.
    //
    // `raw_location` is the parser's own range, which the CPython-shaped
    // diagnostic override does not rewrite, and it is the only place that first
    // failure survives: the override picks its message by scanning the whole
    // source, so an unfinished construct anywhere in it replaces the one the
    // parser actually stopped on.
    //
    // The block and interactive parsers stop at a statement boundary instead,
    // where an unfinished compound statement legitimately fails ahead of the
    // end -- `if 1:` wants an indented block the source has not reached -- so
    // the test is `eval`'s alone.
    fn parse_reached_end_of_source(e: &crate::compile::CompileError, source: &str) -> bool {
        match e {
            crate::compile::CompileError::Parse(error) => {
                error.raw_location.end().to_usize() >= source.len()
            }
            crate::compile::CompileError::Codegen(_) => false,
        }
    }

    // A source holding no statement is unfinished for whichever parser wanted
    // one, so the mode does not enter that arm.
    let incomplete = allow_incomplete
        && (holds_no_statement(source) || {
            let unfinished = match &e {
                crate::compile::CompileError::Parse(error) => match &error.error {
                    ParseErrorType::Lexical(LexicalErrorType::Eof) => true,
                    _ if error.is_unclosed_bracket => true,
                    ParseErrorType::Lexical(LexicalErrorType::FStringError(
                        InterpolatedStringErrorType::UnterminatedTripleQuotedString,
                    )) => true,
                    ParseErrorType::Lexical(LexicalErrorType::UnclosedStringError) => {
                        let loc = error.raw_location.start().to_usize();
                        open_literal_wants_more_input(source, loc, mode)
                    }
                    ParseErrorType::OtherError(message)
                        if message.starts_with("Expected an indented block after")
                            || message.starts_with("expected an indented block after") =>
                    {
                        // Byte offsets again: the span covers the blank run that
                        // should have held the indented block.
                        let bytes = source.as_bytes();
                        let from = error
                            .raw_location
                            .start()
                            .to_usize()
                            .saturating_add(1)
                            .min(bytes.len());
                        let to = error
                            .raw_location
                            .end()
                            .to_usize()
                            .saturating_add(1)
                            .min(bytes.len());
                        from <= to && bytes[from..to].iter().all(u8::is_ascii_whitespace)
                    }
                    // `codeop._maybe_compile` retries a failed command with one
                    // trailing newline.  The pinned RustPython parser reports the
                    // first unterminated triple quote as `UnclosedStringError`,
                    // but the newline retry as this `OtherError` shape.  CPython
                    // keeps both attempts incomplete; preserve RustPython's
                    // triple-quote test across that parser-shape variation.
                    // `unterminated_string_message` writes `triple-quoted` only
                    // for a literal opened with three quotes, so the message is
                    // itself the evidence and no position has to be read: such a
                    // literal runs to the end of the source by construction, which
                    // is `E_EOFS` -- more input wanted.  `raw_location` cannot
                    // answer it anyway, being ruff's own range rather than the one
                    // the CPython-shaped override reports; for `f"""` the two sit
                    // on different offsets.
                    ParseErrorType::OtherError(message)
                        if message.starts_with("unterminated triple-quoted ") =>
                    {
                        true
                    }
                    // The single-quoted spelling arrives the same way, and the
                    // generic arm below reads only whether the source ends on a
                    // newline -- which answers `a = 'a` but gets `a = 'a\` with one
                    // appended wrong, the one shape `codeop._maybe_compile` builds
                    // for every command it retries.
                    ParseErrorType::OtherError(message)
                        if message.starts_with("unterminated string literal") =>
                    {
                        let loc = error.raw_location.start().to_usize();
                        open_literal_wants_more_input(source, loc, mode)
                    }
                    // A closing bracket with no opener, or one that does not
                    // match the opener, is wrong where it stands rather than short
                    // of input: the tokenizer reports it away from `E_EOF`, so no
                    // continuation makes it parse.  `'x' was never closed` is the
                    // opposite case and `is_unclosed_bracket` answers it above.
                    ParseErrorType::OtherError(message)
                        if message.starts_with("unmatched ")
                            || message.starts_with("closing parenthesis ") =>
                    {
                        false
                    }
                    // Whatever else stopped the parse on the last token of a
                    // source carrying no trailing newline ran out of input
                    // rather than reading something wrong: the tokenizer sits
                    // at `E_EOF`, so a further line can still complete it.
                    // `exec` reads its source the way a file is read, with the
                    // missing newline supplied for it, so past the shapes above
                    // its failures are final -- only the `OtherError`
                    // spellings, the decorator and the line continuation among
                    // them, still want more input there.
                    error_type
                        if matches!(error_type, ParseErrorType::OtherError(_))
                            || !matches!(mode, crate::compile::Mode::Exec) =>
                    {
                        error.raw_location.end().to_usize() >= source.len()
                            && !source.ends_with('\n')
                    }
                    _ => false,
                },
                _ => false,
            };
            // `eval` reads the flag against a tokenizer that stopped where the
            // expression did, so a failure short of the end of the source is a
            // syntax error whatever the shape tests above say.
            unfinished
                && (!matches!(mode, crate::compile::Mode::Eval)
                    || parse_reached_end_of_source(&e, source))
        });

    // `syntax_error_subclass` can supply a replacement message, so it
    // runs before the located error is built.
    let subclass = syntax_error_subclass(&e, source);
    let mut msg = if let Some((_, Some(replacement))) = &subclass {
        replacement.clone()
    } else if let crate::compile::CompileError::Parse(parse_err) = &e {
        // astcompiler/codegen.py:3048-3051 reports duplicate call/class
        // keywords after parsing, using CPython 3.14's lower-case wording.
        // Ruff detects the same condition in its parser, so normalize only
        // that structured error rather than rewriting arbitrary messages.
        match &parse_err.error {
            ParseErrorType::OtherError(message)
                if let Some(name) = message
                    .strip_prefix("Duplicate keyword argument `")
                    .and_then(|rest| rest.strip_suffix('`')) =>
            {
                format!("keyword argument repeated: {name}")
            }
            ParseErrorType::Lexical(LexicalErrorType::FStringError(
                InterpolatedStringErrorType::SingleRbrace,
            )) => "f-string: single '}' is not allowed".to_owned(),
            ParseErrorType::Lexical(LexicalErrorType::FStringError(
                InterpolatedStringErrorType::UnclosedLbrace,
            )) => "f-string: expecting '}'".to_owned(),
            // The parser spells every unlexable character the same way. Split
            // it the way `pytokenizer.py:130-140` does — non-printable
            // characters name only their code point, printable ones are quoted
            // — with the hex uppercase and padded to at least four digits, so
            // an astral character widens instead of truncating.
            //
            // A printable ASCII character reports plain `invalid syntax`:
            // `test_syntax.py:1459` asserts that for `1 $ 2`, and keeps
            // `invalid character` for the non-ASCII case (`:2238`).
            ParseErrorType::Lexical(LexicalErrorType::UnrecognizedToken { tok }) => {
                let code = *tok as u32;
                if !rustpython_unicode::classify::is_printable(*tok) {
                    format!("invalid non-printable character U+{code:04X}")
                } else if tok.is_ascii() {
                    "invalid syntax".to_string()
                } else {
                    format!("invalid character '{tok}' (U+{code:04X})")
                }
            }
            // The generic parse failures.  CPython's grammar reports a
            // specific message only where an `invalid_*` rule matches and
            // spells `invalid syntax` for everything else, so ruff's own
            // wording for the same shapes is renamed rather than kept: two
            // statements sharing a line (`x = 1 y = 2`, `impor math`,
            // `asynch def f(): pass`), a statement that never started
            // (`x := 0`), and an unmet token expectation (`del x y`,
            // `for x im n:`).  The arms above stay ahead of these, and a later
            // one that recognizes a shape CPython does name keeps overwriting
            // the message the way the fstring and scope-conflict passes below
            // already do.
            //
            // `traceback._find_keyword_typos` also depends on this: it offers a
            // misspelled keyword only for a SyntaxError whose message is
            // exactly `invalid syntax`, and a keyword typo reaches the parser
            // as a name opening a second statement on the line.
            ParseErrorType::SimpleStatementsOnSameLine
            | ParseErrorType::SimpleAndCompoundStatementOnSameLine => "invalid syntax".to_owned(),
            // `invalid_colon` in the 3.14 grammar (`Parser/parser.c`) and
            // pypy3 both spell a missing suite-header colon as `expected
            // ':'`.  Other `Colon` expectations stay generic: `lambda x x`
            // and `{1 2}` are `invalid syntax` (the latter then rewritten
            // below to the forgot-a-comma form).
            ParseErrorType::ExpectedToken {
                expected: rustpython_compiler::ast::token::TokenKind::Colon,
                found,
            } if matches!(
                found,
                rustpython_compiler::ast::token::TokenKind::Newline
                    | rustpython_compiler::ast::token::TokenKind::NonLogicalNewline
                    | rustpython_compiler::ast::token::TokenKind::EndOfFile
                    | rustpython_compiler::ast::token::TokenKind::Indent
                    | rustpython_compiler::ast::token::TokenKind::Dedent
            ) && compound_suite_header_at(
                source,
                parse_err.raw_location.start().to_usize(),
            ) =>
            {
                "expected ':'".to_owned()
            }
            ParseErrorType::ExpectedToken { .. } => "invalid syntax".to_owned(),
            ParseErrorType::OtherError(message) if message == "Expected a statement" => {
                "invalid syntax".to_owned()
            }
            // `parser::parse_missing_identifier` uses this private parser
            // wording after a trailing attribute dot (`foo.`).  PyPy
            // `PythonParser._parse` and CPython 3.14's `primary` grammar rule
            // both expose the ordinary syntax diagnostic for that source, so
            // keep the normalization attached to the exact structured error
            // instead of rewriting arbitrary messages.
            ParseErrorType::OtherError(message) if message == "Expected an identifier" => {
                "invalid syntax".to_owned()
            }
            ParseErrorType::OtherError(message)
                if message.starts_with("Expected an identifier, but found a keyword ") =>
            {
                "invalid syntax".to_owned()
            }
            // Ruff capitalizes the bare `except *` rejection and reuses it for
            // `except* as e:`, which the grammar does not name at all.  The
            // `invalid_except_star_stmt` alternative matches only
            // `'except' '*' (NEWLINE | ':')` and spells the message lower-case
            // (`raise_syntax_error_known_location` there), which
            // `lib-python/3/test/test_syntax.py` asserts; every other shape the
            // one ruff message covers reports the plain diagnostic.
            ParseErrorType::OtherError(message)
                if message == "Expected one or more exception types" =>
            {
                if except_star_missing_types_at(source, parse_err.raw_location.start().to_usize()) {
                    "expected one or more exception types".to_owned()
                } else {
                    "invalid syntax".to_owned()
                }
            }
            // `ast.c` reports these three through `ast_error`, lower-case and
            // with `follows` where ruff writes `cannot follow`.
            ParseErrorType::PositionalAfterKeywordArgument => {
                "positional argument follows keyword argument".to_owned()
            }
            ParseErrorType::PositionalAfterKeywordUnpacking => {
                "positional argument follows keyword argument unpacking".to_owned()
            }
            ParseErrorType::InvalidArgumentUnpackingOrder => {
                "iterable argument unpacking follows keyword argument unpacking".to_owned()
            }
            // The grammar names this one where a call argument is a bare
            // comprehension: `f(x for x in y, 1)`, `sum(x for x in y, 2)`,
            // `foo(x, y for y in z, p)`.  A comprehension in a subscript is a
            // different rejection and reaches a different variant, which is why
            // renaming this one does not touch `a[x for x in y]`.
            ParseErrorType::UnparenthesizedGeneratorExpression => {
                "Generator expression must be parenthesized".to_owned()
            }
            // Ruff's parser capitalizes this semantic diagnostic.  The real
            // pypy3 oracle and CPython 3.14's `invalid_starred_expression`
            // grammar rule both expose the lower-case spelling for a starred
            // expression rejected while parsing (for example
            // ``((*x), y) = 1, 2``). Keep this structured parse arm distinct
            // from codegen's ``InvalidStarExpr``: CPython's in-tree
            // `test_unpack_ex` gives that other path the "can't use starred
            // expression here" spelling for shapes such as ``x = *a``.
            ParseErrorType::InvalidStarredExpressionUsage => {
                "cannot use starred expression here".to_owned()
            }
            // `tok_get_normal_mode` says what it found rather than what it
            // wanted: a backslash is a continuation only when the newline is
            // the next character, and anything else after it -- a space, a
            // comment -- ends the line there.  Running out of source instead is
            // a different rejection and keeps its own wording.
            ParseErrorType::Lexical(LexicalErrorType::LineContinuationError) => {
                "unexpected character after line continuation character".to_owned()
            }
            _ => e.to_string(),
        }
    } else {
        e.to_string()
    };
    // `eval_input` is `expressions NEWLINE* ENDMARKER`: there is no statement
    // rule for a keyword to open, and nothing may follow the expression.  The
    // parser's own account of the token it stopped on -- that a keyword stands
    // where an identifier belongs, or that the expression had already ended --
    // describes a grammar `eval` does not have, and the failure it reports is
    // the plain one.  This runs before the overrides below, so a literal that
    // named its own failure still keeps that message.
    if matches!(mode, crate::compile::Mode::Eval)
        && let crate::compile::CompileError::Parse(parse_error) = &e
        && match &parse_error.error {
            ParseErrorType::UnexpectedExpressionToken => true,
            ParseErrorType::OtherError(message) => {
                message.starts_with("Expected an identifier, but found a keyword ")
            }
            _ => false,
        }
    {
        msg = "invalid syntax".to_owned();
    }
    if msg.eq_ignore_ascii_case("Bytes literal cannot be mixed with non-bytes literals") {
        msg = if source_has_tstring(source) {
            "cannot mix t-string literals with string or bytes literals"
        } else {
            "cannot mix bytes and nonbytes literals"
        }
        .to_owned();
    }
    // Ruff 0.16 names the t-string mix with a leading capital.
    if msg
        .to_ascii_lowercase()
        .starts_with("cannot mix t-string literals with string or bytes literals")
    {
        msg = "cannot mix t-string literals with string or bytes literals".to_owned();
    }
    let raw_parse_start = match &e {
        crate::compile::CompileError::Parse(parse_error) => {
            Some(parse_error.raw_location.start().to_usize())
        }
        _ => None,
    };
    let late_dollar_span = if msg == "parameter without a default follows parameter with a default"
        && let Some((start, end)) = dollar_token_span(source)
        && crate::compile::parser::parse(
            &source[..start],
            crate::compile::parser::Mode::Module.into(),
        )
        .is_ok()
    {
        msg = "invalid syntax".to_owned();
        Some((start, end))
    } else {
        None
    };
    if msg == "invalid syntax"
        && let Some(raw_index) = raw_parse_start
        && source.as_bytes().get(raw_index) == Some(&b'$')
        && last_fstring_content_range(source)
            .is_some_and(|(start, end)| (start..end).contains(&raw_index))
    {
        msg = "f-string: expecting '=', or '!', or ':', or '}'".to_owned();
    }
    let lambda = if msg == "invalid syntax" {
        unparenthesized_fstring_lambda_span(source)
    } else {
        None
    };
    let lambda_span = match lambda {
        Some(FstringLambdaDiagnostic::Unparenthesized(span)) => Some(span),
        _ => None,
    };
    if lambda_span.is_some() {
        msg = "f-string: lambda expressions are not allowed without parentheses".to_owned();
    } else if matches!(lambda, Some(FstringLambdaDiagnostic::InvalidExpression)) {
        msg = "f-string: expecting a valid expression after '{'".to_owned();
    }
    // [3.14-spec] CPython's `invalid_conversion_character` grammar action
    // reports the complete Unicode identifier and its character-sized span.
    // PyPy `fstring_find_expr` performs the same conversion check after
    // consuming one character, but its 3.11 diagnostic does not name it.  Keep
    // that field-scanner ownership while adapting the observable to 3.14.
    let mut conversion_span = None;
    if matches!(
        msg.as_str(),
        "f-string: invalid conversion character" | "t-string: invalid conversion character"
    ) && let Some(start) = raw_parse_start
        && let Some(first) = source.get(start..).and_then(|tail| tail.chars().next())
        && !first.is_ascii()
        && rustpython_unicode::identifier::is_start(first)
    {
        let mut end = start + first.len_utf8();
        for character in source[end..].chars() {
            if !rustpython_unicode::identifier::is_continue(character) {
                break;
            }
            end += character.len_utf8();
        }
        let prefix = msg.split_once(':').map_or("f-string", |(prefix, _)| prefix);
        msg = format!(
            "{prefix}: invalid conversion character '{}': expected 's', 'r', or 'a'",
            &source[start..end]
        );
        conversion_span = Some((start, end));
    }
    let unterminated_fstring =
        raw_parse_start.is_some_and(|raw_index| unclosed_error_is_fstring(source, raw_index));
    let source_ends_in_tstring = last_tstring_content_range(source)
        .is_some_and(|(_, content_end)| content_end == source.len());
    let unterminated_tstring = raw_parse_start
        .is_some_and(|raw_index| unclosed_error_is_tstring(source, raw_index))
        || (msg.starts_with("unterminated ") && source_ends_in_tstring);
    if unterminated_fstring {
        if msg.starts_with("unterminated triple-quoted string literal") {
            msg = msg.replacen(
                "unterminated triple-quoted string literal",
                "unterminated triple-quoted f-string literal",
                1,
            );
        } else if msg.starts_with("unterminated string literal") {
            msg = msg.replacen(
                "unterminated string literal",
                "unterminated f-string literal",
                1,
            );
        }
    } else if unterminated_tstring {
        if msg.starts_with("unterminated string literal")
            && unclosed_tstring_replacement_field(source)
        {
            msg = "'{' was never closed".to_owned();
        } else if msg.starts_with("unterminated triple-quoted string literal") {
            msg = msg.replacen(
                "unterminated triple-quoted string literal",
                "unterminated triple-quoted t-string literal",
                1,
            );
        } else if msg.starts_with("unterminated string literal") {
            msg = msg.replacen(
                "unterminated string literal",
                "unterminated t-string literal",
                1,
            );
        }
    }
    let escape_error = string_escape_error(source).filter(|escape| {
        // Both the decode and the parse are failures of the same compile, and
        // the one reported is whichever comes first in the source. A literal
        // that sits after the parser's own error keeps that error, so
        // `1 +\nx = "\N"\n` still reports the incomplete expression on line 1.
        match &e {
            crate::compile::CompileError::Parse(parse_error) => {
                parse_error.raw_location.start().to_usize() >= escape.literal_start
            }
            _ => true,
        }
    });
    if let Some(escape) = &escape_error {
        msg = escape.message.clone();
    }
    if let Some(comment_error) = fstring_comment_diagnostic(&msg, source) {
        msg = comment_error.to_owned();
    }
    let nested_empty_field_span = nested_empty_fstring_field_span(source);
    if nested_empty_field_span.is_some() {
        msg = "f-string: valid expression required before ':'".to_owned();
    }
    let delimiter_error = nested_empty_field_span
        .is_none()
        .then(|| fstring_mismatched_delimiter(source))
        .flatten();
    if let Some((delimiter_message, _)) = &delimiter_error {
        msg = delimiter_message.clone();
    }
    if msg == "f-string: expecting `}`" {
        msg = "f-string: expecting '}'".to_owned();
    } else if msg == "t-string: expecting `}`" {
        msg = "t-string: expecting '}'".to_owned();
    } else if msg == "t-string: single `}` is not allowed" {
        msg = "t-string: single '}' is not allowed".to_owned();
    } else if msg == "f-string: expecting '}', or format specs" && source.contains(":{{") {
        msg = "f-string: expecting a valid expression after '{'".to_owned();
    }
    if msg == "f-string: expecting '}'"
        && let Some(diagnostic) = fstring_debug_followup_diagnostic(source)
    {
        msg = diagnostic.to_owned();
    }
    let (tstring_semicolon, tstring_unclosed_format, tstring_nested_invalid) =
        tstring_field_shape(source);
    if msg == "t-string: expecting a valid expression after '{'"
        && tstring_blank_unclosed_field(source)
    {
        msg = "t-string: expecting '}'".to_owned();
    } else if msg == "t-string: expecting '}'" && tstring_semicolon {
        msg = "t-string: expecting '=', or '!', or ':', or '}'".to_owned();
    } else if msg == "t-string: expecting '}'" && tstring_unclosed_format {
        msg = "t-string: expecting '}', or format specs".to_owned();
    } else if msg == "t-string: invalid conversion character"
        && tstring_debug_missing_conversion(source)
    {
        msg = "t-string: missing conversion character".to_owned();
    } else if msg == "invalid syntax" && tstring_nested_invalid {
        msg = "t-string: expecting a valid expression after '{'".to_owned();
    }
    if msg == "f-string: expecting a valid expression after '{'" {
        let bytes = source.as_bytes();
        let quote = bytes.iter().rposition(|byte| matches!(*byte, b'\'' | b'"'));
        if quote.is_some_and(|quote| bytes.get(quote.wrapping_sub(1)) == Some(&b'{')) {
            msg = "f-string: expecting '}'".to_owned();
        }
    }
    let literal_span = if msg == "bytes can only contain ASCII literal characters" {
        match &e {
            crate::compile::CompileError::Parse(parse_error) => {
                nonascii_bytes_literal_span(source, parse_error.raw_location.start().to_usize())
            }
            _ => None,
        }
    } else {
        None
    };
    let fstring_span = if literal_span.is_none() && msg.starts_with("f-string: expecting") {
        match &e {
            crate::compile::CompileError::Parse(parse_error) => {
                fstring_missing_comma_span(source, parse_error.raw_location.start().to_usize())
            }
            _ => None,
        }
    } else {
        None
    };
    if fstring_span.is_some() {
        msg = "invalid syntax. Perhaps you forgot a comma?".to_owned();
    }
    let scope_conflict = global_nonlocal_conflict_span(&e, source);
    if let Some((replacement, _, _)) = &scope_conflict {
        msg = replacement.clone();
    }
    let scope_span = scope_conflict.map(|(_, start, end)| (start, end));
    let generator_span = match &e {
        crate::compile::CompileError::Parse(parse_error)
            if matches!(
                &parse_error.error,
                ParseErrorType::UnparenthesizedGeneratorExpression
            ) =>
        {
            binary_call_generator_error_span(source)
        }
        _ => None,
    };
    if generator_span.is_some() {
        msg = "invalid syntax".to_owned();
    }
    // An unparenthesized `yield` where the grammar has no expression
    // alternative for it (`return yield 42`) matches no rule, so the parser's
    // generic error names the `yield` token itself.
    let yield_span = match &e {
        crate::compile::CompileError::Parse(parse_error)
            if msg == "Yield expression cannot be used here" =>
        {
            let start = parse_error.raw_location.start().to_usize();
            source
                .get(start..)
                .is_some_and(|rest| rest.starts_with("yield"))
                .then_some((start, start + "yield".len()))
        }
        _ => None,
    };
    if yield_span.is_some() {
        msg = "invalid syntax".to_owned();
    }
    // `invalid_assignment` is a grammar alternative, reached only by a
    // statement whose tokens lexed and parsed.  A literal whose own content is
    // wrong -- a bad escape, a byte outside ASCII, a replacement field that
    // does not parse -- fails before any alternative gets to name the target,
    // and so does a generator expression the call left unparenthesized.  Each
    // of those has already claimed `msg` above, wherever in the statement it
    // sits: `b'\xe4' = 1` reports the byte and `f() = '\N{'` the escape in the
    // value, not the target either way.
    let literal_content_error = escape_error.is_some()
        || delimiter_error.is_some()
        || literal_span.is_some()
        || fstring_span.is_some()
        || msg.starts_with("f-string: ")
        || msg.starts_with("t-string: ")
        || matches!(
            &e,
            crate::compile::CompileError::Parse(parse_error)
                if matches!(
                    parse_error.error,
                    ParseErrorType::UnparenthesizedGeneratorExpression
                )
        );
    let assignment_error = (!literal_content_error)
        .then(|| assignment_target_error(&e, source, mode))
        .flatten();
    if let Some((replacement, _, _)) = &assignment_error {
        msg = replacement.clone();
    }
    let assignment_span = assignment_error.map(|(_, start, end)| (start, end));
    let keyword_generator_span = (msg == "invalid syntax")
        .then(|| keyword_generator_assignment_span(source))
        .flatten()
        .filter(|(start, _)| raw_parse_start.is_none_or(|error_start| *start <= error_start));
    if keyword_generator_span.is_some() {
        msg = "invalid syntax. Maybe you meant '==' or ':=' instead of '='?".to_owned();
    }
    let prefix_error = match &e {
        crate::compile::CompileError::Parse(parse_error) => {
            let raw_index = parse_error.raw_location.start().to_usize();
            // A fatal tokenizer error means no later token exists.  Ruff still
            // leaves the remaining source available to this diagnostic pass,
            // so bound the recovery walk at the error it actually reported.
            // Grammar errors are different: CPython tokenizes the whole input
            // before parsing it, and a later incompatible prefix can therefore
            // precede an earlier assignment error.
            let tokenizer_stopped = parse_error.is_unclosed_bracket
                || matches!(
                    &parse_error.error,
                    ParseErrorType::Lexical(_)
                        | ParseErrorType::FStringError(_)
                        | ParseErrorType::TStringError(_)
                )
                || matches!(
                    &parse_error.error,
                    ParseErrorType::OtherError(message)
                        if message.starts_with("unmatched ")
                            || message.starts_with("closing parenthesis ")
                )
                // Ruff recovers some malformed number tokens into an
                // `OtherError` parser shape, but the CPython-shaped message
                // above has already identified the tokenizer failure.
                || matches!(
                    msg.as_str(),
                    "invalid decimal literal"
                        | "invalid hexadecimal literal"
                        | "invalid octal literal"
                        | "invalid binary literal"
                );
            incompatible_string_prefix_error(
                source,
                raw_index,
                tokenizer_stopped.then_some(raw_index),
            )
        }
        _ => None,
    };
    if let Some((replacement, _, _)) = &prefix_error {
        msg = replacement.clone();
    }
    let prefix_span = prefix_error.map(|(_, start, end)| (start, end));
    let delimiter_span = delimiter_error.map(|(_, index)| (index, index));
    // Only where the decoder's complaint is still the one being reported: a
    // literal can carry both a bad escape and one of the errors above, and
    // that one names its own span.
    let escape_span = escape_error
        .filter(|escape| escape.message == msg)
        .map(|escape| escape.span);
    let leading_indent_span = leading_unexpected_indent_span(source);
    // The overrides above assign `msg` in sequence, so the last one to fire is
    // the message being reported; after the tokenizer's leading-indentation
    // correction, this chain reads that precedence backwards so the span and
    // message name the same construct. Both halves of a pair can fire together:
    // an incompatible string prefix in an assignment target reaches the prefix
    // scan and the shape test, and `bu'x' = 1` is why the prefix span wins.
    let diagnostic_span = leading_indent_span
        .or(escape_span)
        .or(literal_span)
        .or(nested_empty_field_span)
        .or(conversion_span)
        .or(prefix_span)
        .or(keyword_generator_span)
        .or(assignment_span)
        .or(fstring_span)
        .or(scope_span)
        .or(lambda_span)
        .or(late_dollar_span)
        .or(generator_span)
        .or(yield_span)
        .or(delimiter_span);
    let ((lineno, byte_offset), diagnostic_end) = if let Some((start, end)) = diagnostic_span {
        (
            source_byte_location(source, start),
            Some(source_byte_location(source, end)),
        )
    } else {
        (e.python_location(), None)
    };
    // A parser diagnostic arrives already counted in characters, and a
    // compiler/symtable one retains the UTF-8 byte columns used by AST
    // locations (for example `return "ä"` ends at offset 12, not 11).  Neither
    // is converted here.  A span located above is a byte index into `source`
    // whichever kind produced it, so only that one is.
    let parser_error = matches!(&e, crate::compile::CompileError::Parse(_));
    let offset = if parser_error && diagnostic_span.is_some() {
        syntax_error_character_offset(source, lineno, byte_offset)
    } else {
        byte_offset
    };
    let mut error = if lineno == 0 {
        crate::PyError::syntax_error(msg)
    } else {
        let parser_end = diagnostic_end.or_else(|| e.python_end_location());
        let (end_lineno, end_byte_offset) = parser_end
            .or_else(|| codegen_statement_end(&e, source, lineno, byte_offset))
            .unwrap_or((lineno, byte_offset));
        let end_offset = if parser_error && diagnostic_end.is_some() {
            syntax_error_character_offset(source, end_lineno, end_byte_offset)
        } else {
            end_byte_offset
        };
        let filename = e.source_path().to_string();
        // Parser errors own their source text directly, keeping the trailing
        // newline like `e.text`.  Later compiler failures omit it for the
        // synthetic ``<string>`` input, while file compilation keeps the
        // decoded source line for the top-level error printer.
        let text = if unterminated_fstring {
            source.lines().nth(lineno - 1)
        } else if matches!(&e, crate::compile::CompileError::Parse(_)) || filename != "<string>" {
            source.split_inclusive('\n').nth(lineno - 1)
        } else {
            None
        };
        crate::PyError::syntax_error_located(
            msg,
            rustpython_wtf8::Wtf8::new(filename.as_str()),
            lineno as i64,
            offset as i64,
            end_lineno as i64,
            end_offset as i64,
            text,
        )
    };
    if incomplete {
        let w_error = error.to_exc_object();
        let w_type = lookup_exc_class("_IncompleteInputError")
            .expect("_IncompleteInputError must be installed before compile()");
        unsafe {
            (*(w_error as *mut pyre_object::PyObject)).w_class = w_type;
            return crate::PyError::from_exc_object(w_error);
        }
    }
    // An incomplete input has returned already; the indentation subclass
    // is the remaining retag.
    if let Some((name, _)) = subclass {
        error.retag_exception_class(name);
    }
    // `pegen.c _PyPegen_set_syntax_error_metadata` hangs the parser's own view
    // of the failure on the exception -- the start of the last statement it
    // finished, and the whole source -- and `traceback._find_keyword_typos`
    // re-tokenizes that slice to offer a misspelled keyword.  Only the parser
    // records it; a codegen SyntaxError carries none, and the incomplete-input
    // retag has returned above without one, as upstream's does.
    //
    // pyre always parses from a string, so the source is the one in hand.  The
    // statement start is parser state the ruff error does not carry, and `0` is
    // what the parser itself records until a statement finishes -- what all but
    // two of `TestKeywordTypoSuggestions.TYPO_CASES` are given, the other two
    // getting `1`, which the helper floors to the same slice index as `0`.
    // Where a statement has finished the constant widens that slice rather than
    // narrowing it, so the helper's own 1024-character ceiling turns the
    // suggestion off earlier on a long file, and it keeps the line numbers the
    // helper reports absolute instead of relative to the slice.
    if parser_error {
        stamp_parser_syntax_metadata(&mut error, source);
    }
    error
}

/// Which of `tokenizer.c tok_get_normal_mode`'s two indentation rejections a
/// line hits first.
enum IndentFault {
    /// `TabError`: the line's indentation measures differently with tabs
    /// expanded to 8 columns than with tabs counted as 1, so which block it
    /// belongs to depends on the tab width.
    TabsAndSpaces,
    /// `IndentationError`: a dedent that lands between two enclosing levels.
    UnmatchedDedent,
}

/// The first real token starts an indented top-level logical line.
///
/// [3.14-spec] CPython's tokenizer rejects this before its parser sees the
/// expression. Ruff can instead continue to an unclosed bracket or a generic
/// expression error, so recover the tokenizer's earlier position. PyPy uses
/// the same token-first shape normally, although after an explicit line
/// continuation its parser can report the later unclosed delimiter instead.
/// A continuation-only physical line contributes no token and is skipped, as
/// in `ASTHelpers_Test.test_literal_eval_syntax_errors`.
fn leading_unexpected_indent_span(source: &str) -> Option<(usize, usize)> {
    let mut line_start = 0usize;
    for line in source.split_inclusive('\n') {
        let bytes = line.as_bytes();
        let mut indent = 0usize;
        let mut has_effective_indent = false;
        while indent < bytes.len() && matches!(bytes[indent], b' ' | b'\t' | b'\x0c') {
            // CPython `tok_get_normal_mode` resets both indentation columns
            // at a formfeed. Whitespace before it therefore cannot make the
            // first logical line indented; whitespace after it still can.
            has_effective_indent = if bytes[indent] == b'\x0c' {
                false
            } else {
                true
            };
            indent += 1;
        }
        let content = line[indent..].trim_end_matches(['\r', '\n']);
        if content.is_empty() || content.starts_with('#') || content == "\\" {
            line_start += line.len();
            continue;
        }
        return has_effective_indent.then(|| {
            let index = line_start + indent - 1;
            (index, index)
        });
    }
    None
}

/// The first indentation the tokenizer would reject, and why.
///
/// `tokenizer.c tok_get_normal_mode` keeps two indent stacks — `indstack`
/// measured with tabs expanded to the next multiple of 8, `altindstack` with
/// each tab counted as 1 — and compares the incoming line against both. Equal,
/// deeper and shallower each have an `altcol` companion check, and it is the
/// disagreement between the two measures that is `TabError`; a dedent matching
/// no `indstack` entry is the plain indentation error.
///
/// A file-wide census cannot stand in for this. Tabs in one block and spaces in
/// another is legal as long as no single comparison disagrees, so counting both
/// characters anywhere in the source retags an unrelated failure.
///
/// Answers `None` for anything this cannot decide from lines alone — an
/// unterminated string, or a line still inside brackets when the source runs
/// out — because the tokenizer processes indentation only outside both, and
/// `TabError` should be claimed only on positive evidence.
fn first_indent_fault(source: &str) -> Option<IndentFault> {
    let mut indstack = vec![0usize];
    let mut altindstack = vec![0usize];
    let mut depth = 0usize;
    let mut in_triple: Option<u8> = None;
    for line in source.lines() {
        let bytes = line.as_bytes();
        // Only a logical line's first physical line carries indentation; a
        // continuation inside brackets or a triple-quoted string does not.
        let measures = (depth == 0 && in_triple.is_none()).then(|| {
            let mut col = 0usize;
            let mut altcol = 0usize;
            let mut i = 0;
            while i < bytes.len() {
                match bytes[i] {
                    b' ' => {
                        col += 1;
                        altcol += 1;
                    }
                    b'\t' => {
                        col = col / 8 * 8 + 8;
                        altcol += 1;
                    }
                    _ => break,
                }
                i += 1;
            }
            (col, altcol, i)
        });
        scan_line_nesting(bytes, &mut depth, &mut in_triple)?;
        let Some((col, altcol, indent_len)) = measures else {
            continue;
        };
        // `tok->blankline`: a blank or comment-only line is not indentation.
        match bytes.get(indent_len) {
            None | Some(b'#') | Some(b'\r') => continue,
            _ => {}
        }
        let (top, alttop) = (
            indstack[indstack.len() - 1],
            altindstack[altindstack.len() - 1],
        );
        if col == top {
            if altcol != alttop {
                return Some(IndentFault::TabsAndSpaces);
            }
        } else if col > top {
            if altcol <= alttop {
                return Some(IndentFault::TabsAndSpaces);
            }
            indstack.push(col);
            altindstack.push(altcol);
        } else {
            while indstack.len() > 1 && col < indstack[indstack.len() - 1] {
                indstack.pop();
                altindstack.pop();
            }
            if col != indstack[indstack.len() - 1] {
                return Some(IndentFault::UnmatchedDedent);
            }
            if altcol != altindstack[altindstack.len() - 1] {
                return Some(IndentFault::TabsAndSpaces);
            }
        }
    }
    None
}

/// Advance `depth` (bracket nesting) and `in_triple` (the open triple quote's
/// character) across one physical line, skipping what a quote or a `#` hides.
/// `None` when the line ends inside a single-quoted string that is not a
/// continuation, which means this scan has lost track.
fn scan_line_nesting(bytes: &[u8], depth: &mut usize, in_triple: &mut Option<u8>) -> Option<()> {
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if let Some(quote) = *in_triple {
            if c == b'\\' {
                i += 2;
                continue;
            }
            if c == quote && bytes[i + 1..].starts_with(&[quote, quote]) {
                *in_triple = None;
                i += 3;
                continue;
            }
            i += 1;
            continue;
        }
        match c {
            b'#' => return Some(()),
            b'(' | b'[' | b'{' => *depth += 1,
            b')' | b']' | b'}' => *depth = depth.saturating_sub(1),
            b'"' | b'\'' => {
                if bytes[i + 1..].starts_with(&[c, c]) {
                    *in_triple = Some(c);
                    i += 3;
                    continue;
                }
                // A single-quoted string closes on this line or the source is
                // malformed in a way this scan cannot follow.
                let mut j = i + 1;
                loop {
                    match bytes.get(j) {
                        None => return None,
                        Some(b'\\') => j += 2,
                        Some(&b) if b == c => break,
                        Some(_) => j += 1,
                    }
                }
                i = j + 1;
                continue;
            }
            _ => {}
        }
        i += 1;
    }
    Some(())
}

/// Whether `loc` sits after a compound suite header that is missing its `:`.
///
/// The 3.14 `invalid_colon` rule names `try`/`if`/`def`/…, not every
/// colon the parser can demand (`lambda`, dict displays).  A parenthesized
/// `if`/`def` header can place `loc` on the newline after `)`, so the
/// keyword is found by walking back through balanced brackets.
fn compound_suite_header_at(source: &str, loc: usize) -> bool {
    let loc = loc.min(source.len());
    let bytes = source.as_bytes();
    let mut i = loc;
    let mut depth = 0i32;
    while i > 0 {
        i -= 1;
        match bytes[i] {
            b')' | b']' | b'}' => depth += 1,
            b'(' | b'[' | b'{' if depth > 0 => depth -= 1,
            b'\n' if depth == 0 => {
                i += 1;
                break;
            }
            _ => {}
        }
    }
    let mut rest = source[i..loc].trim_start();
    if let Some(after) = rest.strip_prefix("async") {
        if after.starts_with(|c: char| c.is_whitespace()) {
            rest = after.trim_start();
        }
    }
    const HEADERS: &[&str] = &[
        "try", "if", "elif", "else", "for", "while", "with", "class", "def", "except", "finally",
        "match", "case",
    ];
    HEADERS.iter().any(|kw| {
        rest.starts_with(kw)
            && !rest
                .as_bytes()
                .get(kw.len())
                .is_some_and(|b| b.is_ascii_alphanumeric() || *b == b'_')
    })
}

/// Whether the `except *` clause on `loc`'s line names no exception type at
/// all, which is the only shape `invalid_except_star_stmt` matches:
/// `'except' '*' (NEWLINE | ':')`, with end-of-source standing in for the
/// newline.  A comment before that newline is not a token, so it does not
/// change the answer.
fn except_star_missing_types_at(source: &str, loc: usize) -> bool {
    let loc = loc.min(source.len());
    let bytes = source.as_bytes();
    let mut i = loc;
    while i > 0 {
        i -= 1;
        if bytes[i] == b'\n' {
            i += 1;
            break;
        }
    }
    let Some(after_except) = source[i..].trim_start().strip_prefix("except") else {
        return false;
    };
    let Some(after_star) = after_except.trim_start().strip_prefix('*') else {
        return false;
    };
    let rest = after_star.trim_start_matches([' ', '\t']);
    let rest = match rest.split_once('#') {
        Some((before, _)) if before.is_empty() => "",
        _ => rest,
    };
    rest.is_empty() || rest.starts_with([':', '\n', '\r'])
}

/// The `SyntaxError` subclass a compile failure belongs to.  3.14 raises
/// `IndentationError` for every indentation-shaped tokenizer failure,
/// `TabError` when that failure comes from mixing tabs and spaces, and plain
/// `SyntaxError` for the rest.
fn syntax_error_subclass(
    e: &crate::compile::CompileError,
    source: &str,
) -> Option<(&'static str, Option<String>)> {
    use rustpython_compiler::parser::{LexicalErrorType, ParseErrorType};
    let crate::compile::CompileError::Parse(parse_err) = e else {
        return None;
    };
    // Every indentation-shaped failure is one of the two the tokenizer
    // distinguishes, and only the source says which — the parser reports a
    // single column, having already collapsed the two measures.  `TabError`
    // carries the tokenizer's own message rather than the parser's, which
    // describes the shape it saw instead of the tab/space clash behind it.
    let indentation = |plain: Option<&'static str>| match first_indent_fault(source) {
        Some(IndentFault::TabsAndSpaces) => (
            "TabError",
            Some("inconsistent use of tabs and spaces in indentation".to_owned()),
        ),
        _ => ("IndentationError", plain.map(str::to_owned)),
    };
    if leading_unexpected_indent_span(source).is_some() {
        return Some(indentation(Some("unexpected indent")));
    }
    match &parse_err.error {
        ParseErrorType::OtherError(msg)
            if (msg.starts_with("Missing parentheses in call to 'print'")
                || msg.starts_with("Missing parentheses in call to 'exec'"))
                && matches!(first_indent_fault(source), Some(IndentFault::TabsAndSpaces)) =>
        {
            Some((
                "TabError",
                Some("inconsistent use of tabs and spaces in indentation".to_owned()),
            ))
        }
        // The parser spells this one "Unexpected indentation"; the tokenizer
        // raises `unexpected indent`.  The dedent message below already reads
        // as the tokenizer writes it, so it keeps the parser's.
        ParseErrorType::UnexpectedIndentation => Some(indentation(Some("unexpected indent"))),
        ParseErrorType::Lexical(LexicalErrorType::IndentationError) => Some(indentation(None)),
        // `pegen`'s "expected an indented block after <clause> on line N",
        // which the compiler reconstructs as a plain message.
        ParseErrorType::OtherError(msg) if msg.starts_with("expected an indented block") => {
            Some(("IndentationError", Some(msg.clone())))
        }
        // `python.gram:invalid_if_stmt` checks `NEWLINE !INDENT` before an
        // invalid expression on the following line.  RustPython's diagnostic
        // normalization currently chooses its Python-2 `print` hint first;
        // restore the grammar's priority when the source has no suite indent.
        ParseErrorType::OtherError(msg)
            if msg.starts_with("Missing parentheses in call to 'print'") =>
        {
            let lineno = parse_err.location.line.get();
            let current = source.split_inclusive('\n').nth(lineno.checked_sub(1)?)?;
            let (header_index, header) = source
                .split_inclusive('\n')
                .take(lineno.checked_sub(1)?)
                .enumerate()
                .filter(|(_, line)| {
                    let line = line.trim();
                    !line.is_empty() && !line.starts_with('#')
                })
                .last()?;
            let indent_width = |line: &str| {
                line.as_bytes()
                    .iter()
                    .take_while(|byte| matches!(byte, b' ' | b'\t' | b'\x0c'))
                    .count()
            };
            let header_text = header.trim();
            if indent_width(current) <= indent_width(header)
                && header_text.starts_with("if ")
                && header_text.ends_with(':')
            {
                Some((
                    "IndentationError",
                    Some(format!(
                        "expected an indented block after 'if' statement on line {}",
                        header_index + 1
                    )),
                ))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// CPython attaches the complete top-level ``return`` statement range to the
/// compiler-stage "outside function" error.  RustPython's codegen error keeps
/// only its start location, although the parsed statement still has the exact
/// byte range.  Recover that range before materialising `SyntaxError`.
fn codegen_statement_end(
    error: &crate::compile::CompileError,
    source: &str,
    lineno: usize,
    offset: usize,
) -> Option<(usize, usize)> {
    let crate::compile::CompileError::Codegen(codegen) = error else {
        return None;
    };
    if !matches!(
        codegen.error,
        crate::compile::codegen::error::CodegenErrorType::InvalidReturn
    ) {
        return None;
    }
    let line_start = source
        .split_inclusive('\n')
        .take(lineno.saturating_sub(1))
        .map(str::len)
        .sum::<usize>();
    let start = line_start.checked_add(offset.saturating_sub(1))?;
    let parsed = crate::compile::parser::parse_module(source).ok()?;
    let end = parsed
        .syntax()
        .body
        .iter()
        .find(|stmt| stmt.range().start().to_usize() == start)?
        .range()
        .end()
        .to_usize();
    let end_line_start = source[..end].rfind('\n').map_or(0, |index| index + 1);
    let end_lineno = source[..end].bytes().filter(|byte| *byte == b'\n').count() + 1;
    Some((end_lineno, end - end_line_start + 1))
}

/// The `consts.py` compilation flag bits.
///
/// Declaring each once mints the table
/// `every_compile_flag_is_the_bit_consts_gives_it` walks: a flag `consts.py`
/// also declares is held to the value it gives, one it does not is held to
/// being absent, and the two that deliberately differ are named there with
/// what `consts.py` says.
macro_rules! compile_flags {
    ($($(#[$doc:meta])* $name:ident = $value:expr,)*) => {
        $($(#[$doc])* const $name: i64 = $value;)*

        #[cfg(test)]
        const ALL_PYCF_FLAGS: &[(&str, i64)] = &[$((stringify!($name), $value),)*];
    };
}

compile_flags! {
    PYCF_ONLY_AST = 0x0400,
    PYCF_DONT_IMPLY_DEDENT = 0x0200,
    PYCF_SOURCE_IS_UTF8 = 0x0100,
    PYCF_IGNORE_COOKIE = 0x0800,
    /// `Include/cpython/compile.h` numbers this one `0x1000`, and `_ast`
    /// publishes it, so the value is observable.  `consts.py` moved it out to
    /// `0x40000000` because it kept `PyCF_ASYNC_HACKS` on `0x1000`; that flag
    /// is gone from 3.14 and the bit is free.
    PYCF_TYPE_COMMENTS = 0x1000,
    PYCF_ALLOW_TOP_LEVEL_AWAIT = 0x2000,
    PYCF_ALLOW_INCOMPLETE_INPUT = 0x4000,
    /// 3.13 added this one, so `consts.py` does not carry it.
    PYCF_OPTIMIZED_AST = 0x8000 | PYCF_ONLY_AST,
    PYCF_ACCEPT_NULL_BYTES = 0x1000_0000,
}

/// `future.py` `allowed_flags` — the union of the `__future__`
/// `compiler_flag` bits (`CO_FUTURE_DIVISION` … `CO_FUTURE_ANNOTATIONS`),
/// i.e. the flags `getcodeflags` masks out of a caller's `co_flags`.
const COMPILER_FLAGS: i64 = 0x01FE_0000;

/// `pyopcode.py:source_as_str` — turn text or one readable `PyBUF_SIMPLE`
/// export into compiler input.  The export remains acquired while its bytes
/// are copied and is released before decoding can raise.
fn source_as_str(
    source: PyObjectRef,
    funcname: &str,
    what: &str,
    filename: &rustpython_wtf8::Wtf8,
    flags: &mut i64,
) -> Result<String, crate::PyError> {
    // pyopcode.py source_as_str: encode() / buffer_w collect, and
    // gct_fv_gc_malloc reloads `w_source`. The native path has to pin it.
    let _source_roots = pyre_object::gc_roots::push_roots();
    let source_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(source);
    let source = pyre_object::gc_roots::shadow_stack_get(source_slot);
    let text_source = unsafe { pyre_object::is_str(source) };
    let bytes = unsafe {
        if text_source {
            // A text source is encoded strictly and coding-cookie detection is
            // disabled, matching PyPy's unicode branch.
            *flags |= PYCF_IGNORE_COOKIE;
            crate::type_methods::encode_object(
                pyre_object::gc_roots::shadow_stack_get(source_slot),
                "utf-8",
                "strict",
            )?
        } else if pyre_object::bytesobject::is_bytes(pyre_object::gc_roots::shadow_stack_get(
            source_slot,
        )) {
            pyre_object::bytesobject::bytes_like_data(pyre_object::gc_roots::shadow_stack_get(
                source_slot,
            ))
            .to_vec()
        } else {
            let buffer = match crate::baseobjspace::simple_buffer_bytes(
                pyre_object::gc_roots::shadow_stack_get(source_slot),
            ) {
                Ok(Some(buffer)) => buffer,
                Ok(None) => {
                    return Err(crate::PyError::type_error(format!(
                        "{funcname}() arg 1 must be a {what} object"
                    )));
                }
                Err(error) if error.kind == crate::PyErrorKind::TypeError => {
                    return Err(crate::PyError::type_error(format!(
                        "{funcname}() arg 1 must be a {what} object"
                    )));
                }
                Err(error) => return Err(error),
            };
            let bytes = buffer.as_bytes().to_vec();
            buffer.release();
            bytes
        }
    };

    // `source_as_str` applies this after its three branches, so it covers a
    // text, a bytes and a buffer source alike, and its diagnostic is
    // deliberately unlocated.  The located wording belongs to
    // `pyparse.PegParser.parse_source`, which only a source file reaches.
    if *flags & PYCF_ACCEPT_NULL_BYTES == 0 && bytes.contains(&0) {
        return Err(crate::PyError::syntax_error(
            "source code string cannot contain null bytes",
        ));
    }
    if text_source {
        return Ok(String::from_utf8(bytes).expect("strict utf-8 encode yields valid utf-8"));
    }
    crate::compile::decode_source_bytes(&bytes, filename, *flags & PYCF_IGNORE_COOKIE != 0)
}

pub(crate) fn replace_compile_syntax_error_filename(
    mut error: crate::PyError,
    filename: &str,
    filename_bytes: Option<&[u8]>,
) -> crate::PyError {
    if error.kind == crate::PyErrorKind::SyntaxError {
        let _roots = pyre_object::gc_roots::push_roots();
        let mut error = error;
        let slot = error.pin(&_roots);
        let w_filename =
            crate::gateway::fsdecode_filename_bytes(filename_bytes.unwrap_or(filename.as_bytes()));
        error.reload(&_roots, slot);
        error.replace_syntax_error_filename(w_filename);
        return error;
    }
    error
}

fn builtin_compile(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `compile(source, filename, mode, flags=0, dont_inherit=False,
    // optimize=-1, *, _feature_version=-1)`: the three required parameters and
    // flags/dont_inherit/optimize are positional-or-keyword; _feature_version
    // is keyword-only.  PyCF_ONLY_AST follows PyPy's compile_to_ast boundary.
    let (pos, kwargs) = split_builtin_kwargs(args);
    let source = bind_pos_or_kw(pos, kwargs, 0, "source", "compile", 1)?.ok_or_else(|| {
        crate::PyError::type_error("compile() missing required argument 'source' (pos 1)")
    })?;
    let filename_obj =
        bind_pos_or_kw(pos, kwargs, 1, "filename", "compile", 2)?.ok_or_else(|| {
            crate::PyError::type_error("compile() missing required argument 'filename' (pos 2)")
        })?;
    let mode_obj = bind_pos_or_kw(pos, kwargs, 2, "mode", "compile", 3)?.ok_or_else(|| {
        crate::PyError::type_error("compile() missing required argument 'mode' (pos 3)")
    })?;
    // Every declared slot binds before the unrecognized keywords are
    // reported, so a call missing a required argument names that argument.
    kwarg_reject_unknown(
        kwargs,
        &[
            "source",
            "filename",
            "mode",
            "flags",
            "dont_inherit",
            "optimize",
            "_feature_version",
        ],
        "compile",
    )?;
    // compiling.py compile: `space.isinstance_w(w_source, W_AST)` and
    // `source_as_str` run after fsencode / gettypeobject / encode, all of
    // which collect. `w_source` is a gateway local; gct_fv_gc_malloc reloads
    // it. The native path imports `_ast` for the same type probe, which is
    // another collection, so pin source / filename / mode from here.
    let n_pos = pos.len();
    let _compile_roots = pyre_object::gc_roots::push_roots();
    let compile_base = pyre_object::gc_roots::publish_roots(&[
        source,
        filename_obj,
        mode_obj,
        kwargs.unwrap_or(pyre_object::PY_NULL),
    ]);
    let pos_base = pyre_object::gc_roots::publish_roots(pos);
    pyre_object::gc_roots::normalize_roots(compile_base, 4 + n_pos);
    let reload = |i: usize| pyre_object::gc_roots::shadow_stack_get(compile_base + i);
    let mut pos_buf = vec![pyre_object::PY_NULL; n_pos];
    let kwargs = || {
        let w = reload(3);
        if w.is_null() { None } else { Some(w) }
    };
    // `compiling.py:12-13 unwrap_spec(filename='fsencode', mode='text')`.
    let filename_bytes = crate::gateway::fsencode_bytes_w(reload(1))?;
    // The code object spells its filename as `newfilename` does
    // (`objspace.py:438`), i.e. the filesystem decode of these bytes. Take that
    // decode here, where the caller that supplied the bytes is still on the
    // stack: under `surrogatepass` a byte that begins no UTF-8 sequence has no
    // spelling, and reporting it at the first `co_filename` read instead would
    // blame whoever came to look at the code object.
    crate::gateway::fsdecode_filename_checked(&filename_bytes)?;
    let filename_text = crate::gateway::fsdecode_filename_wtf8(&filename_bytes);
    let (filename, filename_bytes) = crate::pycode::split_code_filename_bytes(filename_bytes, None);
    let mode = crate::baseobjspace::text_w(reload(2))?;
    // flags / optimize are positional-or-keyword ints.
    pyre_object::gc_roots::shadow_stack_copy_range(pos_base, &mut pos_buf);
    let mut flags = match bind_pos_or_kw(&pos_buf, kwargs(), 3, "flags", "compile", 4)? {
        Some(v) => crate::baseobjspace::gateway_int_w(v)?,
        None => 0,
    };
    pyre_object::gc_roots::shadow_stack_copy_range(pos_base, &mut pos_buf);
    let dont_inherit = match bind_pos_or_kw(&pos_buf, kwargs(), 4, "dont_inherit", "compile", 5)? {
        // [3.14-spec] PyPy's unwrap_spec still requires an integer here, but
        // CPython `builtin_compile_impl` accepts any truth-testable object.
        // `test_compile_filename_refleak` makes the difference observable with
        // a __bool__ that raises ValueError.  The surrounding flag merge and
        // compiler ownership remain PyPy's `compiling.py:compile` path.
        Some(v) => crate::baseobjspace::is_true(v)?,
        None => false,
    };
    pyre_object::gc_roots::shadow_stack_copy_range(pos_base, &mut pos_buf);
    let mut optimize = match bind_pos_or_kw(&pos_buf, kwargs(), 5, "optimize", "compile", 6)? {
        Some(v) => crate::baseobjspace::gateway_int_w(v)?,
        None => -1,
    };
    // PyPy `PythonAstCompiler.compile_to_ast` passes this keyword-only value
    // through `CompileInfo.feature_version` to the parser.
    let feature_version = match kwarg_get(kwargs(), "_feature_version") {
        Some(value) => {
            let value = crate::baseobjspace::gateway_int_w(value)?;
            i64::from(i32::try_from(value).map_err(|_| {
                crate::PyError::overflow_error("Python int too large to convert to C int")
            })?)
        }
        None => -1,
    };

    // Any bit outside the recognised compilation-flag set is rejected.
    let recognized = COMPILER_FLAGS
        | PYCF_ONLY_AST
        | PYCF_DONT_IMPLY_DEDENT
        | PYCF_SOURCE_IS_UTF8
        | PYCF_ACCEPT_NULL_BYTES
        | PYCF_TYPE_COMMENTS
        | PYCF_ALLOW_TOP_LEVEL_AWAIT
        | PYCF_ALLOW_INCOMPLETE_INPUT
        | PYCF_OPTIMIZED_AST
        | PYCF_IGNORE_COOKIE;
    if flags & !recognized != 0 {
        return Err(crate::PyError::value_error("compile(): unrecognised flags"));
    }

    // dont_inherit=0 folds in the caller's __future__ flags
    // (getcodeflags: `co_flags & compiler_flags`).
    if !dont_inherit {
        let caller_frame = crate::eval::CURRENT_FRAME.with(|current| current.get());
        if !caller_frame.is_null() {
            let ec = crate::call::getexecutioncontext();
            if !ec.is_null() {
                let top = unsafe { (*ec).gettopframe_nohidden() };
                if !top.is_null() {
                    let caller_flags = unsafe { (*top).getcode().flags.bits() } as i64;
                    flags |= caller_flags & COMPILER_FLAGS;
                }
            }
        }
    }

    let only_ast = flags & PYCF_ONLY_AST != 0;
    let func_type_mode = mode == "func_type";
    if func_type_mode && !only_ast {
        return Err(crate::PyError::value_error(
            "compile() mode 'func_type' requires flag PyCF_ONLY_AST",
        ));
    }
    let mode = match mode {
        "exec" => crate::compile::Mode::Exec,
        "eval" => crate::compile::Mode::Eval,
        "single" => crate::compile::Mode::Single,
        // PyPy `compiling.py` admits this start rule only at the public AST
        // boundary.  Ruff's codegen Mode has no corresponding bytecode mode;
        // the ONLY_AST branch below dispatches before this placeholder can
        // reach either parser or code generation.
        "func_type" => crate::compile::Mode::Eval,
        _ => {
            return Err(crate::PyError::new(
                crate::PyErrorKind::ValueError,
                if only_ast {
                    "compile() mode must be 'exec', 'eval', 'single' or 'func_type'"
                } else {
                    "compile() mode must be 'exec', 'eval' or 'single'"
                },
            ));
        }
    };

    if !(-1..=2).contains(&optimize) {
        return Err(crate::PyError::value_error(
            "compile(): invalid optimize value",
        ));
    }
    if optimize == -1 {
        // pycompiler.py `compile_ast`: -1 resolves to sys.flags.optimize.
        optimize = i64::from(crate::importing::optimize_flag());
    }

    // PyPy checks the public AST boundary before source_as_str so AST
    // subclasses are compiled as trees rather than probed for a buffer.
    let ast_module = crate::importing::importhook(
        rustpython_wtf8::Wtf8::new("_ast"),
        PY_NULL,
        PY_NULL,
        0,
        crate::call::take_last_exec_ctx(),
    )?;
    let ast_mod_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ast_module);
    let ast_type = crate::baseobjspace::getattr_str(
        pyre_object::gc_roots::shadow_stack_get(ast_mod_slot),
        "AST",
    )?;
    let ast_type_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ast_type);
    let source_is_ast = unsafe {
        crate::baseobjspace::isinstance_w(
            reload(0),
            pyre_object::gc_roots::shadow_stack_get(ast_type_slot),
        )
    };
    let source_str = if source_is_ast {
        None
    } else {
        Some(
            source_as_str(
                reload(0),
                "compile",
                "string, bytes or AST",
                &filename_text,
                &mut flags,
            )
            .map_err(|error| {
                replace_compile_syntax_error_filename(error, &filename, filename_bytes.as_deref())
            })?,
        )
    };

    // Assemble CompileOpts: the __future__ feature bits, the two PyCF_*
    // bits the codegen honours, and the optimisation level.
    let opts = crate::compile::CompileOpts {
        optimize: optimize as u8,
        debug_ranges: crate::importing::code_debug_ranges_flag(),
        int_max_str_digits: crate::module::sys::state::int_max_str_digits().max(0) as usize,
        allow_top_level_await: flags & PYCF_ALLOW_TOP_LEVEL_AWAIT != 0,
        dont_imply_dedent: flags & PYCF_DONT_IMPLY_DEDENT != 0,
        future_features: crate::CodeFlags::from_bits_truncate((flags & COMPILER_FLAGS) as u32),
        ..Default::default()
    };
    if only_ast && let Some(source) = source_str.as_deref() {
        // PyPy's tokenizer calls `misc.syntax_warning` while it is building
        // an app-visible AST.  The ordinary code path runs both scans inside
        // `compile_with_codegen_warnings`; ONLY_AST has no codegen boundary,
        // so keep the tokenizer order explicitly here.
        crate::syntax_warnings::emit_tokenizer_syntax_warnings(source, &filename_text)?;
        crate::syntax_warnings::emit_escape_warnings(source, &filename_text)?;
    }
    if flags & PYCF_ONLY_AST != 0 {
        // CPython 3.14 bltinmodule.c:847 / pythonrun.c:1524:
        // plain ONLY_AST runs syntax-only preprocessing; OPTIMIZED_AST
        // includes ONLY_AST and enables constant folding.
        let syntax_check_only = flags & PYCF_OPTIMIZED_AST == PYCF_ONLY_AST;
        // Kept for the incomplete-input retry below, which the tree builder's
        // own `opts` has been moved into by then.
        let retry_opts = opts.clone();
        let result = if func_type_mode && source_is_ast {
            // PyPy `compiling.py` returns an AST input unchanged for
            // ONLY_AST, including FunctionType.  At the pinned CPython 3.14.6,
            // `PyAst_CheckMode` asserts because this path supplies func_type's
            // mode 3 to its 0..=2 table, so there is no successful 3.14
            // observable that displaces the PyPy owner path.
            Ok(reload(0))
        } else if func_type_mode {
            crate::module::_ast::convert::parse_func_type_to_object(
                source_str
                    .as_deref()
                    .expect("non-AST func_type source has decoded text"),
                feature_version,
            )
        } else if source_is_ast {
            // [3.14-spec] CPython `_PyAST_obj2mod` validates the root for the
            // requested mode and `_PyAST_mod2obj` publishes a fresh tree even
            // for plain ONLY_AST.  PyPy `compile_to_ast` returns its input
            // object unchanged; the observable 3.14 copy/TypeError wins here.
            crate::module::_ast::convert::preprocess_object_to_object(
                reload(0),
                "",
                mode,
                opts,
                syntax_check_only,
            )
        } else {
            crate::module::_ast::convert::parse_to_object_with_opts(
                source_str
                    .as_deref()
                    .expect("non-AST source has decoded text"),
                mode,
                opts,
                syntax_check_only,
                flags & PYCF_TYPE_COMMENTS != 0,
                feature_version,
            )
        };
        return result.map_err(|error| {
            // `PyCF_ALLOW_INCOMPLETE_INPUT` is a parser flag upstream
            // (`PyPARSE_ALLOW_INCOMPLETE_INPUT`, read by `_PyPegen_run_parser`),
            // so asking for a tree answers `_IncompleteInputError` exactly where
            // asking for code does.  That is the request
            // `traceback._find_keyword_typos` makes of every keyword it offers:
            // it accepts a candidate whose source compiles *or* is incomplete,
            // and a suite header left open by the slice it cut is the ordinary
            // outcome -- so a plain SyntaxError here rejects every suggestion
            // whose statement spans more than the failing line.
            //
            // The tree builder reports a parse failure without the structure
            // that decision reads, so the source goes through the compiling
            // parser to get it; that parse stops at the same failure and never
            // reaches code generation, and it runs only for a source that has
            // already failed under the flag -- which is `codeop` and that
            // helper, nothing else.
            if !func_type_mode
                && flags & PYCF_ALLOW_INCOMPLETE_INPUT != 0
                && let Some(text) = source_str.as_deref()
                && let Err(structured) =
                    crate::compile::compile_source_with_opts(text, mode, &filename, retry_opts)
            {
                return replace_compile_syntax_error_filename(
                    compile_err_to_syntax_error_maybe_incomplete(structured, text, mode, true),
                    &filename,
                    filename_bytes.as_deref(),
                );
            }
            replace_compile_syntax_error_filename(error, &filename, filename_bytes.as_deref())
        });
    }
    let code = if let Some(source) = source_str.as_deref() {
        crate::syntax_warnings::compile_with_codegen_warnings(source, mode, &filename_text, opts)
            .map_err(|error| match error {
                crate::syntax_warnings::SourceCompileError::Compile(error) => {
                    compile_err_to_syntax_error_maybe_incomplete(
                        error,
                        source,
                        mode,
                        flags & PYCF_ALLOW_INCOMPLETE_INPUT != 0,
                    )
                }
                crate::syntax_warnings::SourceCompileError::Warning(error) => error,
            })
    } else {
        crate::module::_ast::convert::compile_object(
            reload(0),
            &filename,
            &filename_text,
            mode,
            opts,
        )
    }
    .map_err(|error| {
        replace_compile_syntax_error_filename(error, &filename, filename_bytes.as_deref())
    })?;
    let result = crate::box_code_object(code);
    unsafe { crate::pycode::set_compilation_unit_filename_bytes(result, filename_bytes) };
    Ok(result)
}

/// `exec(source_or_code, globals=None, locals=None)` — PyPy:
/// pyopcode.py builtin_exec.
///
/// Compiles `source` if necessary, then runs the resulting code object in
/// the supplied namespaces.  When the namespaces are dicts, pyre converts
/// them into `DictStorage`s before invocation and copies the post-run
/// namespace contents back so that callers see the new bindings.
pub(crate) fn builtin_exec(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `exec(source, /, globals=None, locals=None, *, closure=None)`: source is
    // positional-only; globals/locals are positional-or-keyword; `closure` is
    // keyword-only.  `closure` supplies the cell objects that bind a code
    // object's free variables (bltinmodule.c builtin_exec_impl); a None
    // closure normalises to "absent" (PY_NULL).
    let (pos, kwargs) = split_builtin_kwargs(args);
    // The positional-only `source` is bound before the unrecognized keywords
    // are reported, so a keywords-only call is reported against `source`.
    if pos.is_empty() {
        return Err(crate::PyError::type_error(
            "exec() takes at least 1 positional argument (0 given)",
        ));
    }
    if pos.len() > 3 {
        // A fourth positional is refused for landing on the keyword-only
        // `closure`; past that the count exceeds the four parameters the
        // signature has at all, and the total is what gets reported.
        let message = if pos.len() == 4 {
            "exec() takes at most 3 positional arguments (4 given)".to_string()
        } else {
            format!("exec() takes at most 4 arguments ({} given)", pos.len())
        };
        return Err(crate::PyError::type_error(message));
    }
    kwarg_reject_unknown(kwargs, &["globals", "locals", "closure"], "exec")?;
    let source = pos[0];
    let globals_arg =
        bind_pos_or_kw(pos, kwargs, 1, "globals", "exec", 2)?.unwrap_or(pyre_object::PY_NULL);
    let locals_arg =
        bind_pos_or_kw(pos, kwargs, 2, "locals", "exec", 3)?.unwrap_or(pyre_object::PY_NULL);
    // `if closure is None: closure = NULL` — treat None as unset.
    let closure = match kwarg_get(kwargs, "closure") {
        Some(c) if !unsafe { pyre_object::is_none(c) } => c,
        _ => pyre_object::PY_NULL,
    };
    exec_or_eval(source, globals_arg, locals_arg, false, closure)
}

/// `eval(source_or_code, globals=None, locals=None)` — same plumbing as
/// exec but returns the value of the expression.
fn builtin_eval(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // `eval(source, /, globals=None, locals=None)`: source is positional-only;
    // globals/locals are positional-or-keyword.
    let (pos, kwargs) = split_builtin_kwargs(args);
    // The positional-only `source` is bound before the unrecognized keywords
    // are reported, so a keywords-only call is reported against `source`.
    if pos.is_empty() {
        return Err(crate::PyError::type_error(
            "eval() takes at least 1 positional argument (0 given)",
        ));
    }
    if pos.len() > 3 {
        return Err(crate::PyError::type_error(format!(
            "eval() takes at most 3 arguments ({} given)",
            pos.len()
        )));
    }
    kwarg_reject_unknown(kwargs, &["globals", "locals"], "eval")?;
    let source = pos[0];
    let globals_arg =
        bind_pos_or_kw(pos, kwargs, 1, "globals", "eval", 2)?.unwrap_or(pyre_object::PY_NULL);
    let locals_arg =
        bind_pos_or_kw(pos, kwargs, 2, "locals", "eval", 3)?.unwrap_or(pyre_object::PY_NULL);
    // eval() has no closure parameter — pass "absent".
    exec_or_eval(source, globals_arg, locals_arg, true, pyre_object::PY_NULL)
}

pub fn exec_or_eval(
    source: PyObjectRef,
    globals_arg: PyObjectRef,
    locals_arg: PyObjectRef,
    is_eval: bool,
    closure: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    // compiling.py eval: `compiler.compile` collects, then
    // `space.contains_w(w_globals, "__builtins__")` reads the same locals.
    // gct_fv_gc_malloc reloads `w_prog` / `w_globals` / `w_locals`; pin them
    // (and the closure) for the native path before source_as_str / compile.
    let _ns_roots = pyre_object::gc_roots::push_roots();
    let ns_base = pyre_object::gc_roots::pin_roots(&[source, globals_arg, locals_arg, closure]);
    let reload_ns = |i: usize| pyre_object::gc_roots::shadow_stack_get(ns_base + i);
    // Resolve a runnable code object: accept a precompiled W_Code or
    // compile a str on the fly.  `source_is_code` records whether the
    // original argument was already a code object (vs a compiled str /
    // bytes) — the closure validation below branches on it.
    let (code_obj_ref, source_is_code) = unsafe {
        if !reload_ns(0).is_null() && crate::is_code(reload_ns(0)) {
            (reload_ns(0), true)
        } else {
            let mut flags = PYCF_SOURCE_IS_UTF8;
            let mut source = source_as_str(
                reload_ns(0),
                if is_eval { "eval" } else { "exec" },
                "string, bytes or code",
                rustpython_wtf8::Wtf8::new("<string>"),
                &mut flags,
            )?;
            if is_eval {
                // compiling.py:eval compiles `source.lstrip(' \t')`.
                source = source.trim_start_matches([' ', '\t']).to_owned();
            }
            let mode = if is_eval {
                crate::compile::Mode::Eval
            } else {
                crate::compile::Mode::Exec
            };
            let code = crate::syntax_warnings::compile_with_codegen_warnings(
                &source,
                mode,
                rustpython_wtf8::Wtf8::new("<string>"),
                crate::compile::CompileOpts {
                    optimize: crate::importing::optimize_flag(),
                    debug_ranges: crate::importing::code_debug_ranges_flag(),
                    int_max_str_digits: crate::module::sys::state::int_max_str_digits().max(0)
                        as usize,
                    ..Default::default()
                },
            )
            .map_err(|error| match error {
                crate::syntax_warnings::SourceCompileError::Compile(error) => {
                    compile_err_to_syntax_error_maybe_incomplete(error, &source, mode, false)
                }
                crate::syntax_warnings::SourceCompileError::Warning(error) => error,
            })?;
            (crate::box_code_object(code), false)
        }
    };
    // A compiled source has just been boxed, and this local is its only
    // referrer: the wrapper is `try_gc_alloc_stable`, so it does not move, but
    // it is swept like any other unreferenced object.  Everything below runs
    // Python -- the `__getitem__` probes on the namespace arguments, and then
    // `ensure_*_builtins` through the globals mapping's `setdefault` (exec) or
    // `__setitem__` (eval) -- and the frame is built from this word at the very
    // end, so a collection in between leaves `createframe_obj` handing a reused
    // block to `w_code_frame_stores_global`'s write barrier.  `code_ptr` below
    // is a host allocation the destructor leaves standing, so only the wrapper
    // needs the root.
    let _code_roots = pyre_object::gc_roots::push_roots();
    let code_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(code_obj_ref);
    let raw_code = unsafe {
        crate::w_code_get_ptr(
            pyre_object::gc_roots::shadow_stack_get(code_slot) as pyre_object::PyObjectRef
        ) as *const crate::CodeObject
    };
    let globals_arg = reload_ns(1);
    let locals_arg = reload_ns(2);
    let closure = reload_ns(3);

    // pypy/interpreter/eval.py Code.exec_code keeps w_globals and
    // w_locals as separate dict references — STORE_GLOBAL writes to
    // w_globals and STORE_NAME writes to w_locals.  Pyre mirrors this by
    // building a fresh DictStorage per role and syncing each back to the
    // caller's dict on exit.  When `locals is globals` (module-level exec
    // / dataclasses), both sides reuse the same storage so semantics
    // collapse to PyPy's `space.createframe(self, w_globals)` followed by
    // a same-dict setdictscope.
    fn is_none_or_null(w_obj: PyObjectRef) -> bool {
        w_obj.is_null() || unsafe { pyre_object::is_none(w_obj) }
    }

    fn type_name_of(w_obj: PyObjectRef) -> String {
        // A tagged int immediate is an exact builtin int; skip the ob_type deref.
        if pyre_object::tagged_int::CAN_BE_TAGGED && pyre_object::tagged_int::is_tagged_int(w_obj) {
            return "int".to_string();
        }
        unsafe {
            match crate::typedef::r#type(w_obj) {
                Some(tp) => pyre_object::w_type_get_name(tp.as_ptr()).to_string(),
                None => (*(*w_obj).ob_type).name.to_string(),
            }
        }
    }

    fn is_dict_w(w_obj: PyObjectRef) -> bool {
        unsafe {
            let w_dict_type = crate::typedef::gettypeobject(&pyre_object::pyobject::DICT_TYPE);
            crate::baseobjspace::isinstance_w(w_obj, w_dict_type)
        }
    }

    /// `PyEval_GetBuiltins()` — the value `exec`/`eval` plant under
    /// `__builtins__` in a namespace that lacks it.  PyPy stores the picked
    /// `Module` (`compiling.py space.builtin`); 3.14 stores that module's
    /// *dict*, which is what `isinstance(__builtins__, dict)` inside
    /// `exec(src, {})` observes.
    fn planted_builtins(w_builtin: pyre_object::PyObjectRef) -> pyre_object::PyObjectRef {
        if !w_builtin.is_null() && unsafe { pyre_object::is_module(w_builtin) } {
            return unsafe { pyre_object::w_module_get_w_dict(w_builtin) };
        }
        w_builtin
    }

    fn ensure_eval_builtins(
        w_globals: pyre_object::PyObjectRef,
        exec_ctx: *const crate::PyExecutionContext,
    ) -> Result<(), crate::PyError> {
        // pypy/module/__builtin__/compiling.py eval:
        //
        //   if not space.contains_w(w_globals, space.newtext("__builtins__")):
        //       space.setitem_str(w_globals, "__builtins__", space.builtin)
        //
        // This is intentionally NOT pyopcode.py's `setdefault`
        // call-method path; dict-subclass `setdefault` overrides do
        // not fire for eval() in PyPy.  Dispatch on the dict object so
        // the str-keyed write fans into the storage proxy.
        let w_builtin = if !exec_ctx.is_null() {
            planted_builtins(unsafe { (*exec_ctx).get_builtin() })
        } else {
            pyre_object::PY_NULL
        };
        if w_builtin.is_null() || w_globals.is_null() {
            return Ok(());
        }
        let _roots = pyre_object::gc_roots::push_roots();
        let base = pyre_object::gc_roots::pin_roots(&[w_globals, w_builtin]);
        let key_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::unicodeobject::intern_str_value(
            "__builtins__",
        ));
        let w_globals = || pyre_object::gc_roots::shadow_stack_get(base);
        let w_builtin = || pyre_object::gc_roots::shadow_stack_get(base + 1);
        let key = || pyre_object::gc_roots::shadow_stack_get(key_slot);
        if !crate::baseobjspace::contains(w_globals(), key())? {
            crate::baseobjspace::setitem(w_globals(), key(), w_builtin())?;
        }
        Ok(())
    }

    fn ensure_exec_builtins(
        w_globals: pyre_object::PyObjectRef,
        caller_frame: *const crate::PyFrame,
        exec_ctx: *const crate::PyExecutionContext,
    ) -> Result<(), crate::PyError> {
        // pypy/interpreter/pyopcode.py:773-774
        //   space.call_method(w_globals, 'setdefault',
        //                     '__builtins__', self.get_builtin())
        // — `self` is the caller frame, so `get_builtin()` returns the
        // builtin picked at caller-frame creation (`pyframe.py`),
        // not the EC's default.  When the caller frame's picked builtin
        // is unavailable (e.g. exec called from outside any frame), fall
        // through to the EC default.  The receiver is the ORIGINAL
        // `w_globals` object so a dict-subclass `setdefault` override
        // fires.
        let w_builtin = if !caller_frame.is_null() {
            planted_builtins(unsafe { (*caller_frame).get_builtin() })
        } else if !exec_ctx.is_null() {
            planted_builtins(unsafe { (*exec_ctx).get_builtin() })
        } else {
            pyre_object::PY_NULL
        };
        if w_builtin.is_null() || w_globals.is_null() {
            return Ok(());
        }
        let _roots = pyre_object::gc_roots::push_roots();
        let base = pyre_object::gc_roots::pin_roots(&[w_globals, w_builtin]);
        let key_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::unicodeobject::intern_str_value(
            "__builtins__",
        ));
        let setdefault = crate::baseobjspace::getattr_str(
            pyre_object::gc_roots::shadow_stack_get(base),
            "setdefault",
        )?;
        crate::call_and_check(
            setdefault,
            &[
                pyre_object::gc_roots::shadow_stack_get(key_slot),
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            ],
        )?;
        Ok(())
    }

    // pypy/interpreter/pyopcode.py ensure_ns —
    //   globals: not None ⇒ isinstance_w(w_dict) else TypeError
    //   locals : not None ⇒ space.lookup(__getitem__) is not None
    //                       else TypeError "must be a mapping or None"
    if !is_none_or_null(globals_arg) && !is_dict_w(globals_arg) {
        // `builtin_eval_impl` splits on `PyMapping_Check`, so a mapping that
        // is merely not a dict is told how to pass it as the locals instead;
        // `builtin_exec_impl` names the type it got.
        let message = if is_eval {
            if unsafe { crate::baseobjspace::lookup(globals_arg, "__getitem__").is_some() } {
                "globals must be a real dict; try eval(expr, {}, mapping)".to_string()
            } else {
                "globals must be a dict".to_string()
            }
        } else {
            format!(
                "exec() globals must be a dict, not {}",
                type_name_of(globals_arg)
            )
        };
        return Err(crate::PyError::type_error(message));
    }
    if !is_none_or_null(locals_arg)
        && unsafe { crate::baseobjspace::lookup(locals_arg, "__getitem__").is_none() }
    {
        let message = if is_eval {
            "locals must be a mapping".to_string()
        } else {
            format!(
                "locals must be a mapping or None, not {}",
                type_name_of(locals_arg)
            )
        };
        return Err(crate::PyError::type_error(message));
    }

    // bltinmodule.c builtin_exec_impl — validate the closure against the
    // resolved code object (after the globals/locals type checks), then build
    // an `outer_func` carrying the cells so `initialize_frame_scopes` binds
    // them as the code's free variables (the same path a nested function call
    // takes via `function.__closure__`).  `closure` is already normalised so
    // PY_NULL means "absent".
    //
    // eval() takes no closure parameter; the eval-side error for a code
    // object that carries free variables comes from initialize_frame_scopes
    // (pyframe.py "directly executed code object may not contain free
    // variables") when createframe runs below with no outer_func.
    // `inject_closure` records that a validated closure must be bound into the
    // frame; the `outer_func` carrier is built just before createframe so it
    // needs no GC rooting across the namespace-setup allocations below.
    let mut inject_closure = false;
    if !is_eval {
        if source_is_code {
            let num_free = unsafe { (&*raw_code).freevars.len() };
            if num_free == 0 {
                // A code object without free variables accepts no closure.
                if !closure.is_null() {
                    return Err(crate::PyError::type_error(
                        "cannot use a closure with this code object",
                    ));
                }
            } else {
                // The closure must be an exact tuple of `num_free` cells.
                let closure_ok = !closure.is_null()
                    && unsafe { pyre_object::is_tuple(closure) }
                    && unsafe { pyre_object::w_tuple_len(closure) } == num_free
                    && (0..num_free).all(|i| unsafe {
                        pyre_object::w_tuple_getitem(closure, i as i64)
                            .is_some_and(|cell| pyre_object::is_cell(cell))
                    });
                if !closure_ok {
                    return Err(crate::PyError::type_error(format!(
                        "code object requires a closure of exactly length {num_free}"
                    )));
                }
                inject_closure = true;
            }
        } else if !closure.is_null() {
            // A str/bytes source is compiled fresh (no free variables), so a
            // closure is meaningless here.
            return Err(crate::PyError::type_error(
                "closure can only be used when source is a code object",
            ));
        }
    }

    let caller_frame = crate::eval::CURRENT_FRAME.with(|current| current.get());
    // The caller's frame is read once here and consulted again after
    // `ensure_*_builtins` (a dict subclass's `setdefault` / `__setitem__`),
    // after the frame object and function are built, and after the builtin
    // module is picked -- every one of which can collect.  A frame a compiled
    // trace built moves there, so it is re-read out of the anchor at each.
    let caller_anchor = unsafe { crate::eval::FrameAnchor::from_raw(caller_frame) };
    let exec_ctx = crate::call::getexecutioncontext();

    // pyopcode.py ensure_ns — the globals object is the
    // user-supplied dict, else the caller frame's globals, else a fresh
    // empty dict (`exec(src)` outside any frame, PyPy `newdict('module')`).
    // Whether the caller supplied each namespace is settled here, ahead of
    // anything that can collect: it is a property of the arguments and not of
    // the addresses they hold, which the plant below can change.
    let globals_supplied = !is_none_or_null(globals_arg);
    let w_globals = if globals_supplied {
        globals_arg
    } else if !caller_frame.is_null() {
        unsafe { (*caller_frame).get_w_globals() }
    } else {
        pyre_object::w_dict_new()
    };
    // The namespace mappings this function hands to the new frame are dicts,
    // which the nursery relocates, and the `exec(src)` snapshot below has no
    // referrer at all until `setdictscope` stores it.  `ensure_*_builtins`, the
    // frame construction and `pick_builtin_obj_checked` each dispatch through a
    // dict subclass and can collect, so all three are published here and read
    // back at the site that consumes them.  Every pin is taken before
    // `_closure_root` opens: a slot claimed after that scope would be truncated
    // away by its drop.
    let ns_roots = pyre_object::gc_roots::push_roots();
    // `locals_arg` is what `setdictscope` binds far below, and the plant on the
    // next lines runs user Python: a dict-subclass `setdefault` /
    // `__contains__` / `__setitem__` can collect, and the nursery relocates the
    // caller's mapping.  The caller's own reference is forwarded, so its dict
    // keeps reading correctly while this local copy is left naming the vacated
    // block; the frame then runs against a stale mapping and every LOAD_NAME /
    // STORE_NAME through it faults on a header that no longer describes a dict.
    // Publish it here beside `w_globals` and read it back where it is consumed.
    //
    // The two identity questions are answered here for the same reason: asked
    // after the move, `std::ptr::eq` would compare a forwarded pointer against
    // a stale one and report two objects where there is one.
    //
    // Dict and non-dict mapping arms share the `setdictscope` path — for exact
    // dict locals this matches the `code.exec_code(space, w_globals, w_locals)`
    // chain in pyopcode.py `exec_`, which feeds `space.setitem(w_locals, name,
    // value)` to STORE_NAME.  Pyre's earlier `is_dict_w` arm built a
    // storage copy and drained it back through a `Vec<String>` snapshot to
    // mirror DELETE_GLOBAL while preserving alias mutations; routing through
    // `setdictscope` retires the copy + snapshot entirely.
    let locals_is_absent = is_none_or_null(locals_arg);
    let globals_is_absent = is_none_or_null(globals_arg);
    let locals_is_globals =
        !locals_is_absent && !globals_is_absent && std::ptr::eq(locals_arg, globals_arg);
    let separate_locals = !locals_is_absent && !locals_is_globals;
    // Every namespace word is published before ensure_* and the caller-locals
    // snapshot. Later reads use these slots.
    let w_globals_slot = ns_roots.publish(&[w_globals]);
    let _globals_arg_slot = ns_roots.publish(&[globals_arg]);
    let locals_arg_slot = ns_roots.publish(&[locals_arg]);
    let locals_object_slot = separate_locals.then_some(locals_arg_slot);
    // The validated closure is the caller's tuple, and it is consumed last of
    // all -- after `ensure_*_builtins`, the two namespace pins and the
    // snapshot allocation.  It goes on the same scope as they do rather than
    // on `_closure_root`, which opens after those calls have already run.
    let closure_slot = ns_roots.publish(&[closure]);
    ns_roots.normalize(
        ns_roots.base(),
        pyre_object::gc_roots::shadow_stack_len() - ns_roots.base(),
    );
    // pyopcode.py:773-774 `space.call_method(w_globals, 'setdefault', ...)`
    // (exec) and compiling.py:109-110 `space.setitem_str(w_globals, ...)`
    // (eval) dispatch on the ORIGINAL `w_globals` object so a dict-subclass
    // `setdefault` / `__contains__` / `__setitem__` override fires.
    if is_eval {
        ensure_eval_builtins(
            pyre_object::gc_roots::shadow_stack_get(w_globals_slot),
            exec_ctx,
        )?;
    } else {
        ensure_exec_builtins(
            pyre_object::gc_roots::shadow_stack_get(w_globals_slot),
            caller_anchor.live(),
            exec_ctx,
        )?;
    }
    // pypy/interpreter/pyopcode.py:771-776 — `code.exec_code(space,
    // w_globals, w_locals, outer_func)` runs the frame on the
    // user-supplied dict directly.  Pyre routes locals through
    // `frame.setdictscope(w_locals)` so STORE_NAME / LOAD_NAME /
    // DELETE_NAME dispatch via `space.setitem` / `space.getitem` /
    // `space.delitem` on the live mapping (dict subclass `__getitem__`
    // overrides win, alias mutations are visible immediately, and
    // there is no entry/exit storage copy + drain pair).  Both exact
    // dicts and arbitrary `__getitem__`-bearing mappings now share
    // this path.
    //
    // pypy/interpreter/pyopcode.py ensure_ns — when the caller
    // omits both globals and locals, exec falls back to caller globals
    // (already wired above) AND caller `getdictscope()`.  When the
    // caller omits ONLY locals, locals collapse to globals (PyPy
    // `pyopcode.py`), which the existing same-storage shape
    // below covers via the `is_none_or_null(locals_arg)` skip.
    //
    // Resolve the implicit caller-locals only when globals_arg is also
    // None: that's the `exec(src)` shape where PyPy hands the caller's
    // live local mapping in via `frame.getdictscope()`.  When
    // globals_arg is supplied but locals_arg is None, PyPy collapses
    // locals=globals and pyre's existing same-dict path handles it.
    let mut implicit_caller_locals: pyre_object::PyObjectRef = std::ptr::null_mut();
    let caller_frame = caller_anchor.live();
    if globals_is_absent && locals_is_absent && !caller_frame.is_null() {
        // The caller's locals as `locals()` reports them: its real namespace
        // for a module or class frame, an independent snapshot for an
        // optimized one.  The snapshot is what keeps `exec("y = 1")` inside a
        // function from adding `y` to that function's locals.
        implicit_caller_locals = unsafe { (*caller_frame).frame_locals_snapshot()? };
    }
    let implicit_locals_slot = if !implicit_caller_locals.is_null() {
        let slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = ns_roots.pin_root(implicit_caller_locals);
        Some(slot)
    } else {
        None
    };

    // function.py Function.__init__ — build the closure carrier for
    // `exec(code, ..., closure=...)`.  A `Function` whose `__closure__` is the
    // validated cell tuple; createframe reads it back through
    // `function_get_closure` and injects each cell into the frame's freevar
    // slots (the same path a nested function call takes).  Its globals are
    // never read (initialize_frame_scopes only consults the closure), so a
    // PY_NULL globals carrier suffices.  Built here — after the namespace
    // setup allocations — and pinned so the intervening createframe allocation
    // cannot reclaim it before its cells are copied into the frame.
    let _closure_root = pyre_object::gc_roots::push_roots();
    let outer_func = if inject_closure {
        let name = unsafe { (&*raw_code).obj_name.clone() };
        let f = crate::function::function_new_with_closure(
            pyre_object::gc_roots::shadow_stack_get(code_slot) as *const (),
            name,
            pyre_object::PY_NULL,
            pyre_object::gc_roots::shadow_stack_get(closure_slot),
        );
        let f = pyre_object::gc_roots::pin_root(f);
        let w_name = unsafe {
            crate::pycode::w_code_name_obj(pyre_object::gc_roots::shadow_stack_get(code_slot))
        };
        if !w_name.is_null() {
            unsafe { crate::function::function_set_name_obj(f, w_name) };
        }
        Some(f)
    } else {
        None
    };
    // eval.py Code.exec_code → space.createframe(...) + frame.run().
    // For eval() with a code object that carries freevars, `outer_func` is
    // None so createframe surfaces pyframe.py's TypeError "directly
    // executed code object may not contain free variables" — exec()'s
    // closure-mismatch TypeError was already raised above.
    let mut frame = match crate::createframe_obj(
        pyre_object::gc_roots::shadow_stack_get(code_slot) as *const (),
        pyre_object::gc_roots::shadow_stack_get(w_globals_slot),
        exec_ctx,
        outer_func,
    ) {
        Ok(frame) => frame,
        Err(err) => {
            let _ = raw_code;
            return Err(err);
        }
    };
    // Python 3.14 always selects the builtin namespace supplied through an
    // explicit exec/eval globals dict.  PyPy expresses the same selection as
    // `space.builtin.pick_builtin(w_globals)` when
    // `objspace.honor__builtins__` is enabled.  Keep Pyre's global PyPy
    // configuration unchanged, but apply that exact selection to the frame
    // constructed by this exec/eval path.
    //
    // `moduledef.py:95-100` has a common-case identity exit when the globals
    // entry is already `space.builtin`.  Preserve that shape as an
    // allocation-free exact-dict probe: imported modules overwhelmingly carry
    // this entry, and must not enter the general mapping dispatch again.
    let current_globals = frame.get_w_globals();
    let keeps_existing_builtin = unsafe {
        pyre_object::is_dict(current_globals)
            && pyre_object::w_dict_getitem_str(current_globals, "__builtins__")
                .is_some_and(|w_builtin| std::ptr::eq(w_builtin, frame.w_builtin))
    };
    if !keeps_existing_builtin {
        // `pick_builtin_obj_checked` can invoke a dict-subclass `__getitem__`
        // and therefore allocate or collect.  The new frame is not current
        // yet, so expose it as a temporary GC root while selecting and storing
        // its builtin Module.
        let _frame_roots = pyre_object::gc_roots::push_roots();
        let _ = pyre_object::gc_roots::pin_root(frame.as_mut_ptr() as pyre_object::PyObjectRef);
        let current_globals = frame.get_w_globals();
        frame.w_builtin = crate::baseobjspace::pick_builtin_obj_checked(current_globals, exec_ctx)?;
    }
    frame.fix_array_ptrs();
    // eval.py:32 frame.setdictscope(w_locals, ...) — only when locals
    // were separately supplied.  Without this call, initialize_frame_scopes'
    // module-code arm has already bound w_locals = w_globals, matching
    // PyPy's `exec(src, g)` (and `exec(src, g, l)` where `l is g`).
    if let Some(slot) = locals_object_slot {
        frame.setdictscope(pyre_object::gc_roots::shadow_stack_get(slot))?;
    } else if let Some(implicit_locals_slot) = implicit_locals_slot {
        // pyopcode.py:2015 — `exec(src)` with no globals/locals uses
        // the caller's `getdictscope()` as locals.  Skip when the
        // resolved object is the caller's globals (module-level exec
        // collapses to locals=globals — same-dict shape kept by the
        // module-frame's initialize_frame_scopes binding).
        let implicit_caller_locals = pyre_object::gc_roots::shadow_stack_get(implicit_locals_slot);
        let caller_globals_obj = unsafe { (*caller_anchor.live()).get_w_globals() };
        let same_as_globals = !caller_globals_obj.is_null()
            && std::ptr::eq(implicit_caller_locals, caller_globals_obj);
        if !same_as_globals {
            frame.setdictscope(implicit_caller_locals)?;
        }
    }
    // run_with_jit rather than execute_frame so that
    // `eval(compile("(x for x in [])", ..., 'eval'))` of generator-flagged
    // code returns the wrapped generator object instead of executing the
    // body inline, and so the exec'd body reaches the JIT portal (a hot loop
    // inside exec()'d source warms into a trace like any function would).
    // STORE_GLOBAL / DELETE_GLOBAL writes during the run land on the
    // storage proxy and back-mirror to the dict object, so the user dict
    // and the frame's globals stay one and the same throughout the run
    // (pyopcode.py parity — no entry/exit drain needed).
    let result = frame.run_with_jit();

    let _ = raw_code; // keep raw_code alive until after exec for safety.
    match result {
        Ok(v) if is_eval => Ok(v),
        Ok(_) => Ok(pyre_object::w_none()),
        Err(e) => Err(e),
    }
}

fn builtin_globals(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if !args.is_empty() {
        return Err(crate::PyError::type_error("globals() takes no arguments"));
    }
    crate::eval::CURRENT_FRAME.with(|current| {
        let frame = current.get();
        if frame.is_null() {
            return Err(crate::PyError::runtime_error(
                "globals() requires an active frame",
            ));
        }
        // `pypy/module/__builtin__/interp_inspect.py:5 globals_w` →
        // `caller.get_w_globals_storage()` returns the dict directly without
        // wrapping.  PyPy keeps a single dict per module so subsequent
        // `globals()` / `frame.f_globals` / `f.__globals__` /
        // `module.__dict__` accesses on the same module share one
        // identity. Pyre returns the frame's globals dict object directly.
        // Returning a fresh wrapper per call would silently
        // diverged on `globals() is module.__dict__`.
        let dict = unsafe { (*frame).get_w_globals() };
        if dict.is_null() {
            return Err(crate::PyError::runtime_error(
                "globals() requires an active frame",
            ));
        }
        Ok(dict)
    })
}

/// The frame whose locals `locals()` / `vars()` / `dir()` report on
/// (`interp_inspect.py locals` — `ec.gettopframe_nohidden()`).
///
/// `gettopframe_nohidden` forces the VREF on its first line and then only
/// follows `f_backref` and tests `hide()`; it runs no per-frame `force_frame`.
/// That vref force is NOT sufficient here, measured: in a compiled `FOR_ITER`
/// loop `locals()` reported `a = 2082, i = 1041` where the frame held
/// `10000 / 5000`.  `getdictscope` reads `locals_cells_stack_w` directly, and an
/// unforced virtualizable holds the values the frame last wrote out — so the
/// mapping comes back with correct KEYS (those come from the code object) and
/// STALE values, which no key-only check can see.  Hence the explicit force
/// below.  Reading `CURRENT_FRAME` instead would skip the vref force too.
fn topframe_for_locals() -> *mut crate::PyFrame {
    let ec = crate::call::getexecutioncontext() as *mut crate::PyExecutionContext;
    if ec.is_null() {
        return std::ptr::null_mut();
    }
    let frame = unsafe { (*ec).gettopframe_nohidden() };
    // The force materializes the fastlocals through a backend hook whose callee
    // this crate cannot follow, so it is judged as able to collect.
    let anchor = unsafe { crate::eval::FrameAnchor::from_raw(frame) };
    // Spelled as the marker, not as a direct `force_frame_before_locals_read`.
    // Both bodies are the same call, but only this name is what
    // `jtransform.py rewrite_op_jit_force_virtualizable` deletes, and this
    // graph now HAS a jitcode: `__majit_wrap_builtin_locals` puts `locals`
    // in the `BuiltinCode.func` family, so the codewriter looks inside here.
    // A direct force would survive into the traced copy and force a
    // virtualizable the trace is meanwhile keeping symbolic; the residual
    // copy still runs the body and still forces.
    crate::executioncontext::jit_force_virtualizable(frame);
    anchor.live()
}

fn builtin_locals(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if !args.is_empty() {
        return Err(crate::PyError::type_error("locals() takes no arguments"));
    }
    // `frame_locals_snapshot` (`_PyEval_GetFrameLocals`) hands an optimized
    // frame an independent copy, so a snapshot neither tracks later stores nor
    // writes back — `x = 1; d = locals(); x = 2; d["x"]` still reads `1`, and
    // `locals() is locals()` is false.  Module and class frames keep returning
    // their real namespace, so `locals() is globals()` still holds at module
    // scope and a non-dict exec/eval mapping is still the live object written
    // through its `__setitem__`.
    let frame = topframe_for_locals();
    if frame.is_null() {
        return Err(crate::PyError::runtime_error(
            "locals() requires an active frame",
        ));
    }
    let frame_mut = unsafe { &mut *frame };
    frame_mut.frame_locals_snapshot()
}

/// `BuiltinCode.func` PBC member for `locals`.
///
/// Builtins installed by hand must publish one, or
/// `CallControl::compute_builtin_wrapper_indirect_graphs` leaves the builtin
/// out of the family, `get_jitcode` is never called for its body, and the
/// walker declines the CALL with `no jitcode for address` — measured on
/// `locals_proxy_extra_key_hot`, where `locals` was one of three such names.
///
/// Unlike `__majit_wrap_builtin_len` this adds no JIT-shaped body.
///
/// So what this buys is reach, not a descent: the chain below is codewritten,
/// which is what lets `rewrite_op_jit_force_virtualizable` delete the force in
/// `topframe_for_locals`, and `try_walker_specialize_builtin_locals` remains
/// the mechanism that makes `locals()` cheap.
pub fn __majit_wrap_builtin_locals(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_locals(args)
}

crate::builtin_wrapper_descriptor!(
    __majit_wrap_builtin_locals_target,
    __majit_wrap_builtin_locals
);

fn builtin_vars(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "vars() takes no keyword arguments",
        ));
    }
    if args.is_empty() {
        return builtin_locals(args);
    }
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "vars expected at most 1 argument, got {}",
            args.len()
        )));
    }
    // app_inspect.py:21-24 — the attribute lookup itself decides whether the
    // argument qualifies, so anything carrying a `__dict__` descriptor answers,
    // including exceptions.  Only AttributeError becomes the TypeError.
    let dict = match crate::baseobjspace::getattr_str(args[0], "__dict__") {
        Ok(dict) => dict,
        Err(error) if error.kind == crate::PyErrorKind::AttributeError => {
            return Err(crate::PyError::type_error(
                "vars() argument must have __dict__ attribute",
            ));
        }
        Err(error) => return Err(error),
    };
    if dict.is_null() {
        return Err(crate::PyError::type_error(
            "vars() argument must have __dict__ attribute",
        ));
    }
    Ok(dict)
}

/// The `dir()` accumulator: the dict `merge_class_dict` merges into.
///
/// Names are collected as the key objects they are, whatever their type —
/// filtering non-strings out here is what would keep `dir()` from raising the
/// `TypeError` its final sort owes for a class namespace holding one.  The
/// dict is what dedups them, and it is reached through a shadow-stack slot
/// because a store hashes its key (arbitrary Python for a non-string one) and
/// may grow the accumulator.
fn dir_names_new() -> usize {
    let names = pyre_object::w_dict_new();
    let names_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(names);
    names_slot
}

/// `PyDict_Update(dict, classdict)` — add every key `keys` yields.
fn dir_names_update(names_slot: usize, keys: Vec<PyObjectRef>) {
    let _roots = pyre_object::gc_roots::push_roots();
    let keys_slot = pyre_object::gc_roots::pin_roots(&keys);
    for index in 0..keys.len() {
        let key = pyre_object::gc_roots::shadow_stack_get(keys_slot + index);
        let names = pyre_object::gc_roots::shadow_stack_get(names_slot);
        unsafe { pyre_object::w_dict_store(names, key, pyre_object::w_none()) };
    }
}

/// `PyDict_Keys(dict)` — the collected names in first-seen order.  `dir()`
/// sorts them afterwards; `object.__dir__` / `type.__dir__` hand them back as
/// they stand.
fn dir_names_list(names_slot: usize) -> PyObjectRef {
    let _roots = pyre_object::gc_roots::push_roots();
    let names = pyre_object::gc_roots::shadow_stack_get(names_slot);
    let collected: Vec<PyObjectRef> = unsafe { pyre_object::w_dict_items(names) }
        .into_iter()
        .map(|(key, _)| key)
        .collect();
    let keys_slot = pyre_object::gc_roots::pin_roots(&collected);
    let keys = (0..collected.len())
        .map(|index| pyre_object::gc_roots::shadow_stack_get(keys_slot + index))
        .collect();
    w_list_new(keys)
}

/// util.py `_classdir` / `merge_class_dict` — union `getattr(klass,
/// '__dict__')`'s keys with, recursively, `_classdir(base)` for each base in
/// `getattr(klass, '__bases__')`.  Both attributes are read through the
/// attribute protocol so a metaclass that customizes `__dict__`/`__bases__`
/// access participates.
unsafe fn classdir_into(w_cls: PyObjectRef, names_slot: usize) -> Result<(), crate::PyError> {
    unsafe { classdir_recurse(w_cls, names_slot) }
}

unsafe fn classdir_recurse(w_cls: PyObjectRef, names_slot: usize) -> Result<(), crate::PyError> {
    // The class and its bases are read across calls that run Python, so the
    // receiver is published rather than carried in a Rust local.
    let _roots = pyre_object::gc_roots::push_roots();
    let cls_slot = pyre_object::gc_roots::shadow_stack_len();
    let w_cls = pyre_object::gc_roots::pin_root(w_cls);
    // getattr(klass, '__dict__', None): names.update(ns).  This is deliberately
    // iterable-driven, not dict-only: app-level PyPy accepts any iterable here.
    match crate::baseobjspace::getattr_str(w_cls, "__dict__") {
        Ok(w_ns) if !w_ns.is_null() && !unsafe { pyre_object::is_none(w_ns) } => {
            dir_names_update(names_slot, collect_iterable(w_ns)?);
        }
        Ok(_) => {}
        Err(e) if e.kind == crate::PyErrorKind::AttributeError => {}
        Err(e) => return Err(e),
    }

    // getattr(klass, '__bases__', None): for base in bases.
    let w_cls = pyre_object::gc_roots::shadow_stack_get(cls_slot);
    match crate::baseobjspace::getattr_str(w_cls, "__bases__") {
        Ok(bases) if !bases.is_null() && !unsafe { pyre_object::is_none(bases) } => {
            let bases = collect_iterable(bases)?;
            let _base_roots = pyre_object::gc_roots::push_roots();
            let bases_slot = pyre_object::gc_roots::pin_roots(&bases);
            for index in 0..bases.len() {
                let base = pyre_object::gc_roots::shadow_stack_get(bases_slot + index);
                unsafe { classdir_recurse(base, names_slot) }?;
            }
        }
        Ok(_) => {}
        Err(e) if e.kind == crate::PyErrorKind::AttributeError => {}
        Err(e) => return Err(e),
    }
    Ok(())
}

/// util.py `_objectdir` / objectobject.py `descr__dir__`.
///
/// Return the generic object's own dict keys together with the recursive
/// class namespace.  `dir(obj)` sorts the result after invoking this special
/// method; `object.__dir__(obj)` itself only promises a list.
pub(crate) fn object_dir_default(obj: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    // Both `getdict` calls can run Python. The receiver is reloaded from
    // this slot around each of them.
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let names_slot = dir_names_new();
    unsafe {
        let mut w_dict =
            crate::baseobjspace::getdict(pyre_object::gc_roots::shadow_stack_get(obj_slot))?;
        // `method.__dir__` forwards the underlying function's instance
        // dictionary as well as the method type's attributes.  The bound
        // method wrapper itself has no writable dict field.
        if w_dict.is_null()
            && pyre_object::function::is_method(pyre_object::gc_roots::shadow_stack_get(obj_slot))
        {
            let func = pyre_object::function::w_method_get_func(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
            );
            if !func.is_null() {
                w_dict = crate::baseobjspace::getdict(func)?;
            }
        }
        if !w_dict.is_null() && pyre_object::is_dict(w_dict) {
            dir_names_update(
                names_slot,
                pyre_object::w_dict_items(w_dict)
                    .into_iter()
                    .map(|(key, _)| key)
                    .collect(),
            );
        }
        if let Some(w_type) =
            crate::typedef::r#type(pyre_object::gc_roots::shadow_stack_get(obj_slot))
            && pyre_object::is_type(w_type.as_ptr())
        {
            classdir_into(w_type.as_ptr(), names_slot)?;
        }
    }
    Ok(dir_names_list(names_slot))
}

/// util.py `_classdir` / typeobject.py:1234 `descr__dir__`.
///
/// Unlike [`object_dir_default`], a type receiver contributes its own class
/// namespace and recursively the namespaces of its bases; its metaclass is
/// not part of the result.  Keep this as the direct `type.__dir__` target so
/// installing that descriptor does not make `dir()` redispatch recursively.
pub(crate) fn type_dir_default(w_type: PyObjectRef) -> Result<PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let names_slot = dir_names_new();
    unsafe { classdir_into(w_type, names_slot) }?;
    Ok(dir_names_list(names_slot))
}

/// The tail of no-argument `dir()`: a locals mapping's sorted key set.
///
/// Split out of [`builtin_dir`] so the JIT fold that models `fast2locals`
/// in the trace finishes through this exact code — the modelled mapping and
/// the interpreted one are then sorted, and their keys enumerated, by one
/// implementation that cannot drift.
fn dir_names_from_locals_mapping(
    w_locals_dict: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    // `_dir_locals` reads the key set through `PyMapping_Keys(locals)`,
    // so a locals mapping that overrides `keys()` (`eval(src, {}, A())`
    // with `A(dict)`) is honoured; only an exact dict takes the
    // `PyDict_Keys` fast path that iterates the storage directly.
    let w_keys = if unsafe {
        pyre_object::pyobject::is_exact_type(w_locals_dict, &pyre_object::pyobject::DICT_TYPE)
    } {
        w_locals_dict
    } else {
        let keys_meth = crate::baseobjspace::getattr_str(w_locals_dict, "keys")?;
        crate::call_and_check(keys_meth, &[])?
    };
    let keys_iter = crate::baseobjspace::iter(w_keys)?;
    let keys = collect_iterable(keys_iter)?;
    builtin_sorted(&[w_list_new(keys)])
}

/// Trace helper finishing the modelled no-argument `dir()`: sort the key set
/// of the mapping the modelled `fast2locals` expansion just built.
///
/// Takes the mapping, never a `PyFrame` — that is what keeps `force_frame`
/// unreachable from the emitted call, so nothing on the folded path arms
/// `force_virtualizable_if_necessary`.  Declared non-forcing and
/// `CannotRaise`: the input is always the exact dict the fold allocated, so
/// the key enumeration takes the storage fast path and the sort compares
/// `str` keys only.  An error is nevertheless reported as `PY_NULL` rather
/// than published, and the caller side-exits on it, so the residual `dir()`
/// re-runs and raises from the interpreter.
pub extern "C" fn jit_dir_names_from_locals(mapping: PyObjectRef) -> PyObjectRef {
    let _roots = pyre_object::gc_roots::push_roots();
    let mapping_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(mapping);
    let mapping = pyre_object::gc_roots::shadow_stack_get(mapping_slot);
    match dir_names_from_locals_mapping(mapping) {
        Ok(names) => names,
        Err(_) => pyre_object::PY_NULL,
    }
}

/// `dir([obj])` — PyPy: pypy/module/__builtin__/app_inspect.py dir
///
/// Without argument: names in the current local scope (not supported).
/// With argument: sorted list of attribute names from obj.__dict__ plus
/// type MRO. Modules expose their namespace via w_module_get_namespace.
pub(crate) fn builtin_dir(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "dir() takes no keyword arguments",
        ));
    }
    if args.is_empty() {
        // `bltinmodule.c builtin_dir` — with no argument, list the names in
        // the caller's local scope: `sorted(frame.f_locals)`.  Resolve the
        // frame exactly as `locals()` does, then return the mapping's sorted
        // keys.  PEP 709 hidden comprehension locals are present in the frame
        // snapshot while active even though they are absent from a module or
        // class namespace, so `getdictscope` is not equivalent here.
        let frame = topframe_for_locals();
        if frame.is_null() {
            return Ok(w_list_new(vec![]));
        }
        let frame_mut = unsafe { &mut *frame };
        let w_locals_dict = frame_mut.frame_locals_snapshot()?;
        if w_locals_dict.is_null() {
            return Ok(w_list_new(vec![]));
        }
        return dir_names_from_locals_mapping(w_locals_dict);
    }
    if args.len() > 1 {
        return Err(crate::PyError::type_error(format!(
            "dir expected at most 1 argument, got {}",
            args.len()
        )));
    }
    let obj = args[0];
    // app_inspect.py — dir() is driven by the object's `__dir__`:
    // `lookup_special(obj, '__dir__')` then `sorted(result)`.  pyre's builtin
    // types do not register a default `__dir__` slot, so the manual
    // enumeration below stands in for the default object / type / module
    // `__dir__`; a `__dir__` found on the type here is a user override (or a
    // builtin such as traceback) and drives dir() directly.
    if let Some(w_type) = crate::typedef::r#type(obj)
        && let Some((owner, dir_meth)) =
            unsafe { crate::baseobjspace::lookup_where_pair(w_type.as_ptr(), "__dir__") }
    {
        // The default object.__dir__ is implemented by the manual generic
        // paths below.  Keep descending when it is merely inherited so
        // module.__dir__, type.__dir__, and their surrogate-preserving
        // namespace walkers retain their specialized behavior.  A real
        // override on any other owner is invoked directly, exactly as
        // app_inspect.py's lookup_special requires.
        if !std::ptr::eq(owner, crate::typedef::w_object()) {
            let result = unsafe {
                crate::baseobjspace::get_and_call_function(dir_meth, obj, w_type.as_ptr(), &[])
            }?;
            return builtin_sorted(&[result]);
        }
    }
    // `GenericAlias.__dir__` (`_pypy_generic_alias.py`) merges the alias's
    // own attribute names with `dir(__origin__)`.
    if unsafe { pyre_object::is_generic_alias(obj) } {
        return crate::_pypy_generic_alias::dir_list(obj);
    }
    let _roots = pyre_object::gc_roots::push_roots();
    // `finditem_str` and the instance `__dict__` / `__class__` reads run
    // Python. The receiver is reloaded from this slot after each of them.
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let names_slot = dir_names_new();
    unsafe {
        if pyre_object::is_module(pyre_object::gc_roots::shadow_stack_get(obj_slot)) {
            // Route through `w_module.w_dict` so dict-subclass-backed
            // Modules (`pypy/module/__builtin__/moduledef.py:102-103
            // Module(space, None, w_builtin)`) surface their entries
            // alongside storage-backed modules.  PyPy
            // `pypy/interpreter/module.py Module.getdict()` returns
            // the dict directly regardless of subclass; pyre branches
            // on the underlying shape:
            //   - exact `W_DictObject` → `w_dict_items` returns the
            //     storage-proxy union view in one call, keeping
            //     lone-surrogate global names.
            //   - dict subclass instance → iterate keys via the
            //     standard `iter()` protocol so the subclass's
            //     `__iter__` override participates (PyPy's
            //     `space.iter(w_dict)` would do the same).
            let w_dict =
                pyre_object::w_module_get_w_dict(pyre_object::gc_roots::shadow_stack_get(obj_slot));
            if !w_dict.is_null() {
                // module.py descr_module__dir__ — a `__dir__` stored in the
                // module's own dict drives dir() (called with no arguments);
                // otherwise the dict keys are listed. `finditem_str` may run
                // Python, so the dict is reloaded for the key walk after it.
                let dict_slot = pyre_object::gc_roots::shadow_stack_len();
                let _ = pyre_object::gc_roots::pin_root(w_dict);
                if let Some(mod_dir) = crate::baseobjspace::finditem_str(
                    pyre_object::gc_roots::shadow_stack_get(dict_slot),
                    "__dir__",
                )? && !mod_dir.is_null()
                {
                    let result = crate::call::call_function_impl_result(mod_dir, &[])?;
                    return builtin_sorted(&[result]);
                }
                let w_dict = pyre_object::gc_roots::shadow_stack_get(dict_slot);
                if pyre_object::is_dict(w_dict) {
                    dir_names_update(
                        names_slot,
                        pyre_object::w_dict_items(w_dict)
                            .into_iter()
                            .map(|(key, _)| key)
                            .collect(),
                    );
                } else if let Ok(keys_iter) = crate::baseobjspace::iter(w_dict)
                    && let Ok(keys) = crate::builtins::collect_iterable(keys_iter)
                {
                    dir_names_update(names_slot, keys);
                }
            }
        } else if pyre_object::is_type(pyre_object::gc_roots::shadow_stack_get(obj_slot)) {
            // util.py `_classdir` (`type.__dir__`, typeobject.py:1234) —
            // the class's `__dict__` keys unioned with `_classdir` of each
            // base, recursively.
            classdir_into(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                names_slot,
            )?;
        } else if pyre_object::is_instance(pyre_object::gc_roots::shadow_stack_get(obj_slot)) {
            // util.py `_objectdir` (`object.__dir__`) — use ordinary
            // `getattr(obj, '__dict__'/'__class__', None)`, not raw layout
            // fields.  A class may shadow either name with a slot/descriptor;
            // in particular an uninitialised `__class__` slot suppresses the
            // recursive class namespace while the live `__dict__` remains.
            let w_dict = match crate::baseobjspace::getattr_str(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                "__dict__",
            ) {
                Ok(w_dict) if pyre_object::is_dict(w_dict) => Some(w_dict),
                Ok(_) => None,
                Err(e) if e.kind == crate::PyErrorKind::AttributeError => None,
                Err(e) => return Err(e),
            };
            if let Some(w_dict) = w_dict {
                dir_names_update(
                    names_slot,
                    pyre_object::w_dict_items(w_dict)
                        .into_iter()
                        .map(|(key, _)| key)
                        .collect(),
                );
            }
            let w_class = match crate::baseobjspace::getattr_str(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                "__class__",
            ) {
                Ok(w_class) => Some(w_class),
                Err(e) if e.kind == crate::PyErrorKind::AttributeError => None,
                Err(e) => return Err(e),
            };
            if let Some(w_class) = w_class
                && pyre_object::is_type(w_class)
            {
                classdir_into(w_class, names_slot)?;
            }
        } else {
            // Fallback `_objectdir` (util.py) for builtin W_Root types
            // (Function, StaticMethod, PyTraceback, dict views, etc.).  Some
            // W_Root subclasses own a typed dictionary field even though
            // `is_instance()` is false, so use W_Root.getdict + _classdir
            // rather than assuming this whole branch has no instance dict.
            return builtin_sorted(&[object_dir_default(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
            )?]);
        }
    }
    // `_dir_object` sorts what `__dir__` returned, so a namespace holding a
    // key that does not order against a `str` raises from the comparison
    // rather than being filtered away.
    builtin_sorted(&[dir_names_list(names_slot)])
}

/// `operation.py id(space, w_object)` — `space.id`, then the
/// `builtins.id` audit event.
fn builtin_id(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "id() takes exactly one argument ({} given)",
            args.len()
        )));
    }
    // `space.id` (baseobjspace.py): a plain `int` yields its
    // value-derived `immutable_unique_id`; every other object falls back
    // to `compute_unique_id` (objectmodel.py), which incminimark
    // implements through `id_or_identityhash` (incminimark.py) so
    // nursery moves preserve it.  The address-valued function is a
    // different one — `current_object_addr_as_int`
    // (objectmodel.py), whose docstring exists to say the value
    // "can change over time for moving GCs".  A list and a dict header do
    // move, so answering with the raw pointer would give such an object two
    // different ids over its lifetime, and every structure keyed on `id()`
    // would lose track of it.
    let w_res = crate::baseobjspace::id(args[0]);
    // `operation.py space.audit("builtins.id", [w_res])`, emitted after the
    // id is computed so a hook sees the value the call is about to return.
    if crate::module::sys::vm::audit_hooks_armed() {
        // The event-name wrap and the hooks are both collection points, and the
        // result reaches them only as a copied pointer.  Root it across the
        // emit and read the answer back out of its slot.
        let _roots = pyre_object::gc_roots::push_roots();
        let res_slot = pyre_object::gc_roots::pin_roots(&[w_res]);
        // The pin normalizes, and its query is itself a safepoint, so `w_res`
        // is dead from here on: what the hooks are handed has to come out of
        // the slot, not out of the copy that named the object beforehand.
        let w_res = pyre_object::gc_roots::shadow_stack_get(res_slot);
        crate::module::sys::vm::audit("builtins.id", &[w_res])?;
        return Ok(pyre_object::gc_roots::shadow_stack_get(res_slot));
    }
    Ok(w_res)
}

/// `hash(obj)` — PyPy: `descroperation.py hash`.
///
/// CPython / PyPy raise `TypeError: unhashable type: 'X'` when the
/// object's class lacks a non-None `__hash__` slot.  Built-in
/// mutable containers (dict, list, set, bytearray) explicitly set
/// `__hash__ = None` (`dictmultiobject.py`, `listobject.py`,
/// `setobject.py`).  `try_hash_value` is the Result-bearing variant
/// used by both `hash()` and dict key gates: it rejects known
/// unhashables, recurses through tuple/frozenset contents, and
/// propagates user `__hash__` errors.
pub(crate) fn builtin_hash(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "hash() takes exactly one argument ({} given)",
            args.len()
        )));
    }
    Ok(w_int_new(try_hash_value(args[0])?))
}

/// `hash_value` for an exact `str`, `long`, `bytes` or non-NaN `float`, the
/// scalars whose digest needs no `__hash__` lookup.  A `str` digest is
/// memoized through `w_str_set_hash`, which stores the value the next call
/// would recompute, so the leaf stays elidable.
#[majit_macros::elidable_cannot_raise]
pub fn hash_exact_scalar(w_obj: PyObjectRef) -> i64 {
    unsafe {
        if is_str(w_obj) {
            return str_hash_value(w_obj);
        }
        if is_long(w_obj) {
            return _hash_long(pyre_object::w_long_get_value(w_obj));
        }
        if is_float(w_obj) {
            return _hash_float(w_float_get_value(w_obj));
        }
        _hash_bytes(pyre_object::bytesobject::w_bytes_data(w_obj))
    }
}

#[majit_macros::dont_look_inside]
fn builtin_hash_slow(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_hash(args)
}

/// operation.py `hash` → `space.hash`.  An exact machine int (or bool)
/// computes `_hash_int` inline; an exact `str`, `long`, `bytes` or non-NaN
/// `float` answers through [`hash_exact_scalar`].  The type is pinned before
/// that call, so every other shape reaches `builtin_hash` without it.  A NaN
/// `float` is excluded because its identity hash allocates.
pub fn __majit_wrap_builtin_hash(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() == 1 {
        let w_obj = args[0];
        unsafe {
            if is_exact_builtin_instance(w_obj) {
                if is_int(w_obj) {
                    return Ok(w_int_new(_hash_int(w_int_get_value(w_obj))));
                }
                if is_str(w_obj)
                    || is_long(w_obj)
                    || pyre_object::is_bytes(w_obj)
                    || (is_float(w_obj) && !w_float_get_value(w_obj).is_nan())
                {
                    return Ok(w_int_new(hash_exact_scalar(w_obj)));
                }
            }
        }
    }
    builtin_hash_slow(args)
}

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_hash_target, __majit_wrap_builtin_hash);

/// `tupleobject.py W_AbstractTupleObject.descr_hash` — the hash a tuple has by
/// virtue of its contents, with no `__hash__` lookup on the receiver.
///
/// Separate from [`try_hash_value`] because the two answer different
/// questions.  `hash(x)` must honour whatever `type(x)` says, override
/// included; `tuple.__hash__(x)` names the base implementation, and running
/// the override there would return the subclass's answer for a call that
/// asked for the base's — and loop outright when the override calls back, as
/// the memoising `def __hash__(self, hash=tuple.__hash__)` idiom does.
pub(crate) fn tuple_structural_hash(mut obj: PyObjectRef) -> Result<i64, crate::PyError> {
    unsafe {
        // CPython 3.14 `tuple_hash`: a successful aggregate hash is
        // retained on the tuple.  Check before the recursive stack guard
        // so repeated dict probes do not touch the elements at all.
        if let Some(hash) = pyre_object::w_tuple_cached_hash(obj) {
            return Ok(hash);
        }
        // The element walk is the one recursive step here, and the scalar
        // fast path in `try_hash_value` no longer reaches the call protocol's
        // own guard, so a nest deep enough to exhaust the C stack has to be
        // caught on the way down.
        crate::stack_check::stack_check()?;
        if let Some(hash) = pyre_object::w_tuple_cached_hash(obj) {
            return Ok(hash);
        }
        // `W_TupleObject.descr_hash`: a cache miss takes
        // `_unroll_condition`, then `_descr_hash_unroll` or
        // `_descr_hash_jitdriver`, then the length mangle. Element
        // hashes are `space.hash_w` (`try_hash_value`). Either arm can
        // collect, so reload `obj` before writing the cache.
        let len = w_tuple_len(obj);
        let acc = if pyre_object::tupleobject::unroll_condition(obj) {
            pyre_object::with_roots!(obj => _descr_hash_unroll_w(obj))?
        } else {
            pyre_object::with_roots!(obj => _descr_hash_jitdriver_w(obj))?
        };
        let hash = tuple_hash_finish(acc, len);
        pyre_object::w_tuple_set_cached_hash(obj, hash);
        Ok(hash)
    }
}

/// `setobject.py W_FrozensetObject.descr_hash` — the frozenset counterpart of
/// [`tuple_structural_hash`], and separate for the same reason.
pub(crate) fn frozenset_structural_hash(obj: PyObjectRef) -> i64 {
    frozenset_hash_from_storage(obj)
}

pub fn try_hash_value(obj: PyObjectRef) -> Result<i64, crate::PyError> {
    if obj.is_null() {
        return Err(crate::PyError::type_error("hash() argument is null"));
    }
    // The scalar builtins are not subclassable in place: an *exact* instance
    // can only ever reach the `__hash__` these arms of `hash_value` already
    // compute, so the slot lookup and the call protocol below would just
    // route back here.  This is the digest every interpreter-level dict probe
    // needs, and it is on the path of every module / `sys.modules` /
    // namespace lookup — `UnicodeDictStrategy`'s upstream storage hashes its
    // unwrapped key the same way, without an app-level call.
    unsafe {
        for tp in [
            &pyre_object::STR_TYPE,
            &pyre_object::INT_TYPE,
            &pyre_object::BOOL_TYPE,
            &pyre_object::LONG_TYPE,
            &pyre_object::FLOAT_TYPE,
            &pyre_object::bytesobject::BYTES_TYPE,
        ] {
            if is_exact_type(obj, tp) {
                return Ok(hash_value(obj));
            }
        }
    }
    unsafe {
        // `frozenset` is hashable per setobject.py _hash_frozenset.
        // `dictmultiobject.py _is_set_like` — only the keys and items
        // views are set-like: they define `__eq__` and so are unhashable.  The
        // values view keeps `object.__hash__`.
        let unhashable_kind = pyre_object::is_dict(obj)
            || pyre_object::is_list(obj)
            || pyre_object::is_set(obj)
            || pyre_object::is_bytearray(obj)
            || pyre_object::dictmultiobject::is_dict_view_keys(obj)
            || pyre_object::dictmultiobject::is_dict_view_items(obj);
        if unhashable_kind {
            // The concrete builtin advertises `__hash__ = None`, but a user
            // subclass may replace that slot.  PyPy's normal special-method
            // lookup reaches the subclass entry before the inherited typedef
            // value (`descroperation.py:556-565`), so only reject the object
            // after giving a non-None override the call.
            if let Some(w_type) = crate::typedef::r#type(obj)
                && let Some(method) =
                    crate::baseobjspace::lookup_in_type(w_type.as_ptr(), "__hash__")
                && !pyre_object::is_none(method)
            {
                return hash_call_normalize(method, obj, w_type.as_ptr());
            }
            // The concrete kind decides that the object is unhashable; the
            // refusal names the receiver's own type, which for a subclass is
            // not the builtin base.
            return Err(unhashable_type_error(obj));
        }
        if pyre_object::sliceobject::is_slice(obj) {
            return slice_hash_value(obj);
        }
        if pyre_object::memoryview::is_w_memoryview(obj) {
            // `descr_hash` — released and writable views are unhashable; a
            // read-only view hashes its raw bytes, cached in `_hash`.
            return memoryview_hash_value(obj);
        }
        // A tuple/frozenset *subclass* can set `__hash__ = None` to become
        // unhashable, or override `__hash__` with its own method; the
        // structural fast paths below hash by contents and would ignore both.
        // For a non-exact receiver consult the `__hash__` slot: `None` raises,
        // a genuine override dispatches, and the inherited structural hash
        // falls through to the fast path.
        let is_tuple_recv = is_tuple(obj);
        let is_frozenset_recv = pyre_object::is_frozenset(obj);
        if ((is_tuple_recv && !is_exact_type(obj, &TUPLE_TYPE))
            || (is_frozenset_recv && !is_exact_type(obj, &pyre_object::setobject::FROZENSET_TYPE)))
            && let Some(w_type) = crate::typedef::r#type(obj)
            && let Some(method) = crate::baseobjspace::lookup_in_type(w_type.as_ptr(), "__hash__")
        {
            if pyre_object::is_none(method) {
                return Err(unhashable_type_error(obj));
            }
            let base = if is_tuple_recv {
                crate::typedef::gettypefor(&TUPLE_TYPE)
            } else {
                crate::typedef::gettypefor(&pyre_object::setobject::FROZENSET_TYPE)
            };
            let base_hash =
                base.and_then(|b| crate::baseobjspace::lookup_in_type(b.as_ptr(), "__hash__"));
            if Some(method) != base_hash {
                return hash_call_normalize(method, obj, w_type.as_ptr());
            }
        }
        if is_tuple(obj) {
            return tuple_structural_hash(obj);
        }
        if pyre_object::is_frozenset(obj) {
            return Ok(frozenset_hash_from_storage(obj));
        }
        if pyre_object::is_generic_alias(obj) {
            // GenericAlias.__hash__ (`_pypy_generic_alias.py`) —
            // `hash(self.__origin__) ^ hash(self.__args__)`.  Routed through
            // `try_hash_value` so an unhashable element in `__args__`
            // surfaces its TypeError instead of being swallowed.
            let origin = pyre_object::w_generic_alias_get_origin(obj);
            let args = pyre_object::w_generic_alias_get_args(obj);
            // `try_hash_value(origin)` may collect; `args` is a raw local read
            // afterward, so pin it across the first hash.
            let _roots = pyre_object::gc_roots::push_roots();
            let args_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(args);
            let origin_hash = try_hash_value(origin)?;
            let args_hash = try_hash_value(pyre_object::gc_roots::shadow_stack_get(args_slot))?;
            return Ok(origin_hash ^ args_hash);
        }
        if pyre_object::is_union(obj) {
            return crate::_pypy_generic_alias::union_hash_value(obj);
        }
        if pyre_object::is_instance(obj) {
            let w_type = pyre_object::w_instance_get_type(obj);
            if let Some(method) = crate::baseobjspace::lookup_in_type(w_type, "__hash__") {
                if pyre_object::is_none(method) {
                    return Err(unhashable_type_error(obj));
                }
                return hash_call_normalize(method, obj, w_type);
            }
        }
        // A type may declare itself unhashable via `__hash__ = None`
        // (a typed-payload `#[pyre_methods(unhashable)]` layout such as
        // `deque`); the `is_instance` arm above covers user classes, this
        // covers the builtin/typed-payload layouts before the identity-hash
        // fallback.
        if let Some(w_type) = crate::typedef::r#type(obj)
            && let Some(method) = crate::baseobjspace::lookup_in_type(w_type.as_ptr(), "__hash__")
        {
            if pyre_object::is_none(method) {
                return Err(unhashable_type_error(obj));
            }
            // A subclass may override `__hash__` (e.g. `class D(deque)`);
            // honor the override.  The inherited default `object.__hash__`
            // (identity) is left to the `hash_value` fallback below, which
            // computes the correct per-type builtin hash for the base
            // payload rather than a pointer identity.
            let default_hash =
                crate::baseobjspace::lookup_in_type(crate::typedef::w_object(), "__hash__");
            if default_hash != Some(method) {
                return hash_call_normalize(method, obj, w_type.as_ptr());
            }
        }
    }
    Ok(hash_value(obj))
}

/// CPython 3.14 `slice_hash`, the tuplehash-style three-lane mixer added
/// after the PyPy 3.11 source version. Component hash errors propagate.
fn slice_hash_value(obj: PyObjectRef) -> Result<i64, crate::PyError> {
    const PRIME1: u64 = 11_400_714_785_074_694_791;
    const PRIME2: u64 = 14_029_467_366_897_019_727;
    const PRIME5: u64 = 2_870_177_450_012_600_261;
    let parts = unsafe {
        [
            pyre_object::sliceobject::w_slice_get_start(obj),
            pyre_object::sliceobject::w_slice_get_stop(obj),
            pyre_object::sliceobject::w_slice_get_step(obj),
        ]
    };
    // `try_hash_value` runs each component's `__hash__`, which may collect; the
    // captured parts array holds raw locals, so pin them on the shadow stack.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::shadow_stack_len();
    for &part in parts.iter() {
        let _ = pyre_object::gc_roots::pin_root(part);
    }
    let mut acc = PRIME5;
    for j in 0..parts.len() {
        let lane = try_hash_value(pyre_object::gc_roots::shadow_stack_get(base + j))? as u64;
        acc = acc.wrapping_add(lane.wrapping_mul(PRIME2));
        acc = acc.rotate_left(31);
        acc = acc.wrapping_mul(PRIME1);
    }
    if acc == u64::MAX {
        acc = 1_546_275_796;
    }
    Ok(acc as i64)
}

/// Call a resolved `__hash__` method and normalize its result:
/// `descroperation.py:576-579` — accept `bool` / `int` / `long`, reject other
/// return types, and map a `-1` result to `-2`.
fn hash_call_normalize(
    method: PyObjectRef,
    obj: PyObjectRef,
    w_type: PyObjectRef,
) -> Result<i64, crate::PyError> {
    let r = unsafe { crate::baseobjspace::get_and_call_function(method, obj, w_type, &[]) }?;
    normalize_hash_digest(r)
}

/// The result arms of [`hash_call_normalize`], shared with the JIT's digest
/// residual: accept `bool`/`int`/`long`, reject other types, map `-1` to `-2`.
pub fn normalize_hash_digest(r: PyObjectRef) -> Result<i64, crate::PyError> {
    let h = unsafe {
        if is_bool(r) {
            pyre_object::w_bool_get_value(r) as i64
        } else if is_int(r) {
            w_int_get_value(r)
        } else if is_long(r) {
            _hash_long(pyre_object::w_long_get_value(r))
        } else {
            return Err(crate::PyError::type_error(
                "__hash__ method should return an integer",
            ));
        }
    };
    Ok(if h == -1 { -2 } else { h })
}

fn unhashable_type_error(obj: PyObjectRef) -> crate::PyError {
    let name = unsafe {
        match crate::typedef::r#type(obj) {
            Some(tp) => pyre_object::w_type_get_name(tp.as_ptr()).to_string(),
            None if !obj.is_null() => (*(*obj).ob_type).name.to_string(),
            None => "NULL".to_string(),
        }
    };
    crate::PyError::type_error(format!("unhashable type: '{}'", name))
}

/// `pypy/objspace/std/intobject.py` — `HASH_BITS = 61` (64-bit
/// host); `HASH_MODULUS = 2**HASH_BITS - 1`.  The Mersenne-prime
/// modulus is what makes pyre's `hash(42) == hash(42.0) ==
/// hash(2**100 + 42)`-class invariants hold: every per-type hash
/// reduces its input modulo the same `HASH_MODULUS`, so equal
/// numeric values land on the same residue.
const HASH_BITS: i64 = 61;
const HASH_MODULUS: u64 = (1u64 << HASH_BITS) - 1;
const HASH_INF: i64 = 314_159;
// tupleobject.py's 64-bit `r_ulonglong` xxHash constants.
const XXPRIME_1: u64 = 11_400_714_785_074_694_791;
const XXPRIME_2: u64 = 14_029_467_366_897_019_727;
const XXPRIME_5: u64 = 2_870_177_450_012_600_261;
// pypy/objspace/std/longobject.py imports rbigint.SHIFT, then defines
// `_HASH_SHIFT = SHIFT % HASH_BITS`.  RPython's flowspace receives both as
// already-folded host integers; mirror that graph shape inside this LLBC
// artefact because Charon keeps a cross-artefact const read opaque.
const RBIGINT_SHIFT: i64 = 63;
const HASH_SHIFT: i64 = RBIGINT_SHIFT % HASH_BITS;
const _: () = assert!(RBIGINT_SHIFT == majit_rlib::rbigint::SHIFT);
/// Numeric hash of a machine-word integer — the literal branch-free port of
/// `pypy/objspace/std/intobject.py::_hash_int`.  Keep the Mersenne reduction
/// in interpreter source: it is part of the translated RPython graph, not an
/// opaque Rust-library helper.  The unsigned multiply computes `abs(a)` even
/// for `i64::MIN`, the residue keeps the original sign, and the final subtract
/// maps the reserved `-1` hash to `-2`.
#[inline]
pub(crate) fn _hash_int(a: i64) -> i64 {
    let sign = 1 - ((a < 0) as i64 * 2);
    let mut x = (a as u64).wrapping_mul(sign as u64);
    x = (x & HASH_MODULUS) + (x >> HASH_BITS);
    x -= HASH_MODULUS * ((x >= HASH_MODULUS) as u64);
    let h = (x as i64) * sign;
    h - ((h == -1) as i64)
}

/// pypy/objspace/std/longobject.py `_hash_long`.
///
/// Reduce the 63-bit rbigint digits modulo the Mersenne prime
/// `2**61 - 1`, then apply the sign and the `-1 -> -2` sentinel rule.
#[inline]
#[majit_macros::elidable]
pub(crate) fn _hash_long(v: &BigInt) -> i64 {
    let mut i = v.numdigits();
    let mut x = 0_u64;
    while i > 0 {
        i -= 1;
        x = ((x << HASH_SHIFT) & HASH_MODULUS) + (x >> (HASH_BITS - HASH_SHIFT));
        x += v.udigit(i);
        if RBIGINT_SHIFT > HASH_BITS {
            x = (x & HASH_MODULUS) + (x >> HASH_BITS);
        }
        if x >= HASH_MODULUS {
            x -= HASH_MODULUS;
        }
    }
    let hash = (x as i64) * v.get_sign();
    hash - (hash == -1) as i64
}

/// Literal port of `pypy/objspace/std/floatobject.py::_hash_float`.
/// NaN identity hashing is handled by the wrapped-object caller, as in PyPy;
/// this helper receives finite values or infinities only.
#[inline]
#[majit_macros::elidable]
pub(crate) fn _hash_float(v: f64) -> i64 {
    if v.is_infinite() {
        return if v > 0.0 { HASH_INF } else { -HASH_INF };
    }

    let (mut m, mut e) = crate::typedef::float_frexp(v);
    let mut sign = 1_i64;
    if m < 0.0 {
        sign = -1;
        m = -m;
    }

    let mut x = 0_u64;
    while m != 0.0 {
        x = ((x << 28) & HASH_MODULUS) | (x >> (HASH_BITS - 28));
        m *= 268_435_456.0;
        e -= 28;
        let y = m as u64;
        m -= y as f64;
        x += y;
        if x >= HASH_MODULUS {
            x -= HASH_MODULUS;
        }
    }

    let hash_bits = HASH_BITS as i32;
    e = if e >= 0 {
        e % hash_bits
    } else {
        hash_bits - 1 - ((-1 - e) % hash_bits)
    };
    x = ((x << e) & HASH_MODULUS) | (x >> (hash_bits - e));

    let hash = (x as i64) * sign;
    hash - (hash == -1) as i64
}

/// One xxHash lane of `tupleobject.py` `descr_hash` (`xxrotate` is a
/// rotate-left by 31 on the 64-bit constants).
#[inline(always)]
fn tuple_hash_mix(acc: u64, lane: u64) -> u64 {
    let mut acc = acc.wrapping_add(lane.wrapping_mul(XXPRIME_2));
    acc = (acc << 31) | (acc >> 33);
    acc.wrapping_mul(XXPRIME_1)
}

/// `W_TupleObject.descr_hash` length mangle, after either hash arm.
#[inline(always)]
fn tuple_hash_finish(mut acc: u64, len: usize) -> i64 {
    acc = acc.wrapping_add((len as u64) ^ (XXPRIME_5 ^ 3_527_539));
    acc = acc.wrapping_add((acc == u64::MAX) as u64 * (1_546_275_796 + 1));
    acc as i64
}

/// Literal `tupleobject.py descr_hash` xxHash sequence fold over already
/// computed element hashes.
#[inline]
fn _hash_tuple_xx(items: &[i64]) -> i64 {
    let mut acc = XXPRIME_5;
    let mut i = 0_usize;
    while i < items.len() {
        acc = tuple_hash_mix(acc, items[i] as u64);
        i += 1;
    }
    tuple_hash_finish(acc, items.len())
}

/// `tupleobject.py hash_driver`.
///
/// `JitDriver(name='tuple.hash', greens=['w_type'], reds='auto')`.
/// Untranslated `JitDriver.jit_merge_point` does nothing. This receiver
/// is not a `jitdriver_receiver_roots` entry: `handle_jit_marker__jit_merge_point`
/// rejects a marker whose graph is not that driver's portal.
struct TupleHashJitDriver;

impl TupleHashJitDriver {
    #[inline(always)]
    fn jit_merge_point(&self, _w_type: PyObjectRef) {}
}

#[allow(non_upper_case_globals)]
const hash_driver: TupleHashJitDriver = TupleHashJitDriver;

/// `space.type(wrappeditems[0])`, the `hash_driver` green.
///
/// `Cls_ii` / `Cls_ff` keep the payload unboxed. Reading it back through
/// `w_tuple_getitem` would allocate a box only to ask for its type.
unsafe fn tuple_hash_w_type(obj: PyObjectRef) -> PyObjectRef {
    unsafe {
        let ob_type = (*obj).ob_type;
        let builtin = if std::ptr::eq(
            ob_type,
            &pyre_object::specialisedtupleobject::SPECIALISED_TUPLE_II_TYPE,
        ) {
            Some(&pyre_object::INT_TYPE)
        } else if std::ptr::eq(
            ob_type,
            &pyre_object::specialisedtupleobject::SPECIALISED_TUPLE_FF_TYPE,
        ) {
            Some(&pyre_object::FLOAT_TYPE)
        } else {
            None
        };
        if let Some(tp) = builtin {
            return crate::typedef::gettypefor(tp)
                .map(|p| p.as_ptr())
                .unwrap_or(pyre_object::PY_NULL);
        }
        let item = w_tuple_getitem(obj, 0).unwrap_or(pyre_object::PY_NULL);
        if item.is_null() {
            return pyre_object::PY_NULL;
        }
        crate::typedef::r#type(item)
            .map(|p| p.as_ptr())
            .unwrap_or(pyre_object::PY_NULL)
    }
}

/// `tupleobject.py _descr_hash_unroll` with `space.hash_w`.
///
/// The `hash_value` twin stays `unroll_safe`. This arm is the one
/// `descr_hash` runs, and `try_hash_value` is the element hash that can
/// raise.
unsafe fn _descr_hash_unroll_w(obj: PyObjectRef) -> Result<u64, crate::PyError> {
    unsafe {
        // `w_tuple_getitem` on `Cls_ii` / `Cls_ff` boxes the payload.
        // That allocation can move `obj`, so the tuple stays pinned and
        // every index reloads it.
        let _roots = pyre_object::gc_roots::push_roots();
        let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
        let len = w_tuple_len(pyre_object::gc_roots::shadow_stack_get(obj_slot));
        let mut acc = XXPRIME_5;
        let mut i = 0_usize;
        while i < len {
            let mut item =
                w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(obj_slot), i as i64)
                    .expect("tuple index below w_tuple_len is always present");
            let lane = pyre_object::with_roots!(item => try_hash_value(item))? as u64;
            acc = tuple_hash_mix(acc, lane);
            i += 1;
        }
        Ok(acc)
    }
}

/// `tupleobject.py _descr_hash_jitdriver`.
///
/// `w_type` is fixed from the first item, then every iteration hits
/// `hash_driver.jit_merge_point(w_type=w_type)` before `space.hash_w`.
unsafe fn _descr_hash_jitdriver_w(obj: PyObjectRef) -> Result<u64, crate::PyError> {
    unsafe {
        let len = w_tuple_len(obj);
        if len == 0 {
            return Ok(XXPRIME_5);
        }
        // `tuple_hash_w_type` reaches `w_tuple_getitem`, whose body boxes
        // an `_ii` / `_ff` payload. Reload `obj` before the element walk
        // pins both words for those boxes and for `try_hash_value`.
        let mut obj = obj;
        let w_type = pyre_object::with_roots!(obj => tuple_hash_w_type(obj));
        let _roots = pyre_object::gc_roots::push_roots();
        let base = pyre_object::gc_roots::pin_roots(&[obj, w_type]);
        let mut acc = XXPRIME_5;
        let mut i = 0_usize;
        while i < len {
            hash_driver.jit_merge_point(pyre_object::gc_roots::shadow_stack_get(base + 1));
            let mut item = w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(base), i as i64)
                .expect("tuple index below w_tuple_len is always present");
            let lane = pyre_object::with_roots!(item => try_hash_value(item))? as u64;
            acc = tuple_hash_mix(acc, lane);
            i += 1;
        }
        Ok(acc)
    }
}

/// Shared xxHash walk of `tupleobject.py` `_descr_hash_unroll` /
/// `_descr_hash_jitdriver` for `hash_value`. Expanded into each arm so
/// the unroll-safe graph contains the n-loop. `tuple_structural_hash`
/// does not use this macro: its long arm is `_descr_hash_jitdriver_w`,
/// which calls `hash_driver.jit_merge_point`.
macro_rules! hash_tuple_xx_storage {
    ($obj:ident) => {{
        let len = w_tuple_len($obj);
        let mut acc = XXPRIME_5;
        let mut i = 0_usize;
        while i < len {
            let item = w_tuple_getitem($obj, i as i64)
                .expect("tuple index below w_tuple_len is always present");
            let lane = pyre_object::with_roots!($obj => hash_value(item)) as u64;
            acc = tuple_hash_mix(acc, lane);
            i += 1;
        }
        tuple_hash_finish(acc, len)
    }};
}

/// `tupleobject.py _descr_hash_unroll` — `@jit.unroll_safe`.
#[majit_macros::unroll_safe]
unsafe fn _descr_hash_unroll(mut obj: PyObjectRef) -> i64 {
    hash_tuple_xx_storage!(obj)
}

/// `tupleobject.py _descr_hash_jitdriver`.
unsafe fn _descr_hash_jitdriver(mut obj: PyObjectRef) -> i64 {
    hash_tuple_xx_storage!(obj)
}

/// CPython/PyPy's deterministic seed expansion
/// (`Python/bootstrap_hash.c` / `rsiphash.py:lcg_urandom`).
fn hash_secret_from_seed(mut seed: u32) -> [u8; 16] {
    let mut secret = [0u8; 16];
    for byte in &mut secret {
        seed = seed.wrapping_mul(214013).wrapping_add(2531011);
        *byte = ((seed >> 16) & 0xff) as u8;
    }
    secret
}

/// Process-global CPython 3.14 hash secret.  RPython's `rsiphash.seed` is
/// likewise a single process-global owner initialized from `PYTHONHASHSEED`;
/// it is not interpreter-thread-local state.
static HASH_SECRET: std::sync::OnceLock<[u8; 16]> = std::sync::OnceLock::new();

/// How a `PYTHONHASHSEED` value that names no seed is reported.
pub const HASH_SEED_ERROR: &str =
    "PYTHONHASHSEED must be \"random\" or an integer in range [0; 4294967295]";

/// Fix the process-global hash secret from `PYTHONHASHSEED`, leaving it unset
/// for `"random"` or an absent value so the first digest samples a random one.
///
/// The variable is read through the host seam, so under sandbox the value comes
/// from the controller's environment rather than the child's cleared one.  A
/// value that names no seed yields [`HASH_SEED_ERROR`] instead of terminating:
/// the launcher owns the process lifetime, so reporting it is its call.
///
/// A digest taken before this runs pins a random secret and the variable is
/// ignored from then on, so the launcher calls it before anything hashes.
pub fn init_hash_secret_from_env() -> Result<(), &'static str> {
    let value = crate::host_seam::getenv(b"PYTHONHASHSEED")
        .ok()
        .flatten()
        .unwrap_or_default();
    if value.is_empty() || value.as_slice() == b"random" {
        // Force the getrandom backend (and its optional `/dev/urandom`
        // fallback) to run before a sandbox seccomp filter is installed.
        // Deferring to the first digest lets the fallback's `openat` land
        // after lockdown and kill the child with syscall 257.
        let _ = hash_secret();
        return Ok(());
    }
    let seed = std::str::from_utf8(&value)
        .ok()
        .and_then(|text| text.parse::<u32>().ok())
        .ok_or(HASH_SEED_ERROR)?;
    // `_build_key_from_seed` gives seed 0 the all-zero key rather than running
    // the expansion over it.
    let secret = if seed == 0 {
        [0; 16]
    } else {
        hash_secret_from_seed(seed)
    };
    let _ = HASH_SECRET.set(secret);
    Ok(())
}

fn hash_secret() -> &'static [u8; 16] {
    HASH_SECRET.get_or_init(|| {
        let mut secret = [0u8; 16];
        getrandom::fill(&mut secret)
            .expect("failed to get random numbers to initialize Python hash secret");
        secret
    })
}

/// CPython 3.14 `_Py_HashBytes`: empty input hashes to zero; every other byte
/// sequence uses SipHash-1-3 with the process-global 128-bit secret.
fn _hash_bytes_with_key(bytes: &[u8], secret: &[u8; 16]) -> i64 {
    if bytes.is_empty() {
        return 0;
    }
    use core::hash::Hasher;
    let mut hasher = siphasher::sip::SipHasher13::new_with_key(secret);
    hasher.write(bytes);
    let raw = hasher.finish() as i64;
    raw - ((raw == -1) as i64)
}

/// The `bytes` hash over a caller's buffer, which is what `Py_HashBuffer`
/// answers with.
#[allow(dead_code)]
pub(crate) fn hash_buffer(bytes: &[u8]) -> i64 {
    _hash_bytes(bytes)
}

#[inline]
fn _hash_bytes(bytes: &[u8]) -> i64 {
    _hash_bytes_with_key(bytes, hash_secret())
}

/// CPython 3.14 `unicode_hash`: hash the PEP 393 canonical code-unit storage,
/// selecting one-, two-, or four-byte native-endian units from the maximum
/// code point.  Pyre stores WTF-8, so materialize only this hash input.
fn _hash_unicode_with_key(wtf8: &rustpython_wtf8::Wtf8, secret: &[u8; 16]) -> i64 {
    // An all-ASCII string's PEP 393 canonical code-unit storage is its
    // one-byte-per-char form, byte-identical to the WTF-8 bytes, so hash those
    // directly instead of materializing a separate code-unit buffer. This is
    // the common case (identifiers, dict keys) and skips two Vec allocations.
    let storage = wtf8.as_bytes();
    // `CodePoints::size_hint` upper-bounds at the byte length. `collect()`
    // reserves that many `u32`s. A stale `Wtf8Buf` can report a length
    // above `isize::MAX`, and `Vec::with_capacity` then aborts the process
    // (`capacity overflow`) instead of hashing. Bound before `is_ascii`,
    // which would otherwise scan the corrupt slice.
    if storage.len() > isize::MAX as usize / 4 {
        return _hash_bytes_with_key(&[], secret);
    }
    if storage.is_ascii() {
        return _hash_bytes_with_key(storage, secret);
    }
    // Do not `collect`/`extend` the code-point iterator: its `size_hint`
    // upper bound is the byte length, and `Vec::extend` reserves that
    // hint. A stale `Wtf8Buf` makes the hint overflow even after the
    // length gate above. Push one code point at a time.
    let mut codepoints = Vec::new();
    for cp in wtf8.code_points() {
        codepoints.push(cp.to_u32());
    }
    let maxchar = codepoints.iter().copied().max().unwrap_or(0);
    let width = if maxchar <= 0xff {
        1
    } else if maxchar <= 0xffff {
        2
    } else {
        4
    };
    let mut bytes = Vec::new();
    if bytes
        .try_reserve(codepoints.len().saturating_mul(width))
        .is_err()
    {
        return _hash_bytes_with_key(&[], secret);
    }
    if maxchar <= 0xff {
        bytes.extend(codepoints.into_iter().map(|cp| cp as u8));
    } else if maxchar <= 0xffff {
        for cp in codepoints {
            bytes.extend_from_slice(&(cp as u16).to_ne_bytes());
        }
    } else {
        for cp in codepoints {
            bytes.extend_from_slice(&cp.to_ne_bytes());
        }
    }
    _hash_bytes_with_key(&bytes, secret)
}

#[inline]
fn _hash_unicode(wtf8: &rustpython_wtf8::Wtf8) -> i64 {
    _hash_unicode_with_key(wtf8, hash_secret())
}

/// `space.hash_w` digest for a `str` computed directly from its WTF-8 bytes
/// — the value [`hash_value`] returns for a str key — exposed for the
/// `dict_eq_hook::HASH_STR_HOOK` trampoline so str-keyed dict GET probes hash
/// without a `W_UnicodeObject`.
#[inline]
pub fn hash_str_bytes(bytes: &[u8]) -> i64 {
    // ASCII fast path (see `_hash_unicode_with_key`): the storage bytes are the
    // canonical hash input, so hash them without validating/constructing a Wtf8.
    if bytes.len() > isize::MAX as usize / 4 {
        return _hash_bytes(&[]);
    }
    if bytes.is_ascii() {
        return _hash_bytes(bytes);
    }
    let wtf8 = rustpython_wtf8::Wtf8::from_bytes(bytes).expect("str storage is valid WTF-8");
    _hash_unicode(wtf8)
}

/// Literal `setobject.py W_FrozensetObject.descr_hash` order-independent
/// XOR-fold.  The caller has already computed each element's hash into
/// `items`; `u64` is RPython's `r_uint` on pyre's supported 64-bit target.
#[inline]
fn _hash_frozenset(items: &[i64]) -> i64 {
    let multi = 1_822_399_083_u64
        .wrapping_add(1_822_399_083)
        .wrapping_add(1);
    let mut hash = 1_927_868_237_u64.wrapping_mul(items.len() as u64 + 1);
    for &h in items {
        let h = h as u64;
        let value = (h ^ (h << 16) ^ 89_869_747).wrapping_mul(multi);
        hash ^= value;
    }
    hash ^= (hash >> 11) ^ (hash >> 25);
    hash = hash.wrapping_mul(69_069).wrapping_add(907_133_923);
    let hash = hash as i64;
    if hash == -1 { 590_923_713 } else { hash }
}

/// CPython 3.14 consumes the digests cached in the set table and caches the
/// aggregate on the frozenset. This is observably newer than PyPy 3.11's
/// first `descr_hash` walk: an element's `__hash__` runs only on insertion,
/// never again for `hash(frozenset)`.
fn frozenset_hash_from_storage(obj: PyObjectRef) -> i64 {
    unsafe {
        if let Some(hash) = pyre_object::w_frozenset_cached_hash(obj) {
            return hash;
        }
        let hashes = pyre_object::w_set_stored_hashes(obj);
        let hash = _hash_frozenset(&hashes);
        pyre_object::w_frozenset_set_cached_hash(obj, hash);
        hash
    }
}

/// `W_UnicodeObject.descr_hash`: the memoized content digest.
///
/// # Safety
/// `obj` must be a live `str`.
unsafe fn str_hash_value(obj: PyObjectRef) -> i64 {
    unsafe {
        // CPython `unicode_hash` caches the PEP 393 content digest.
        let cached = pyre_object::w_str_get_hash(obj);
        if cached != 0 {
            return cached;
        }
        let wtf8 = pyre_object::w_str_get_wtf8(obj);
        let storage = wtf8.as_bytes();
        // Prefer the header `byte_len` when the `Wtf8Buf` length disagrees
        // (a swept value box can leave a huge `Vec` len on the dangling
        // pointer). A valid string has both counts equal.
        let declared = pyre_object::unicodeobject::w_str_byte_len(obj);
        let max_n = isize::MAX as usize / 4;
        // A live header with a swept value box reports a garbage
        // `Wtf8Buf` length. Do not slice or scan that buffer — the
        // prefix path SIGBUS'd on the unmapped page. Hash empty and
        // leave the missing GC edge as a separate defect.
        let hash = if declared == storage.len() && declared <= max_n {
            _hash_unicode(wtf8)
        } else {
            _hash_bytes(&[])
        };
        pyre_object::w_str_set_hash(obj, hash);
        hash
    }
}

/// `pypy/objspace/std/objspace.py StdObjSpace.hash` parity — share one
/// implementation across builtin `hash()`, dict / set lookup, and
/// tuple/frozenset content hashing.  Dispatches to PyPy's per-type
/// hash helpers (`_hash_int`/`_hash_long`/`_hash_float`/
/// `_hash_tuple_xx`/`_hash_frozenset`), so:
///
/// - `hash(42) == hash(42.0) == hash(2**100 + 42)` (Mersenne mod)
/// - `hash((1, 2)) == hash((1, 2))` regardless of allocation identity
/// - `hash(frozenset(...))` is deterministic and order-independent
///
/// CPython 3.14's `_Py_HashBytes` uses SipHash-1-3 and returns zero for empty
/// input. Strings hash their PEP 393 canonical code-unit representation rather
/// than pyre's internal WTF-8 bytes, keeping all seeded values bit-identical.
pub fn hash_value(mut obj: PyObjectRef) -> i64 {
    unsafe {
        // `is_int` is true for a bool (`BOOL_TYPE`), so test `is_bool` first.
        if is_bool(obj) {
            return if pyre_object::w_bool_get_value(obj) {
                1
            } else {
                0
            };
        }
        if is_int(obj) {
            return _hash_int(w_int_get_value(obj));
        }
        if is_long(obj) {
            return _hash_long(pyre_object::w_long_get_value(obj));
        }
        if is_float(obj) {
            let value = pyre_object::w_float_get_value(obj);
            return if value.is_nan() {
                crate::typedef::default_identity_hash_value(obj)
            } else {
                _hash_float(value)
            };
        }
        if pyre_object::is_complex(obj) {
            return crate::objspace::descroperation::complex_hash(
                obj,
                pyre_object::w_complex_get_real(obj),
                pyre_object::w_complex_get_imag(obj),
            );
        }
        if is_str(obj) {
            return str_hash_value(obj);
        }
        // CPython `bytes_hash` — the same `_Py_HashBytes` primitive, over the
        // bytes payload itself (bytearray is mutable / unhashable).
        if pyre_object::is_bytes(obj) {
            return _hash_bytes(pyre_object::bytesobject::w_bytes_data(obj));
        }
        // `memoryobject.py descr_hash` — `compute_hash(self.view.as_str())`;
        // a released or writable view is unhashable, so this infallible
        // hasher only digests a live read-only view and otherwise falls
        // through to the unhashable tail (the fallible `try_hash_value`
        // raises the proper ValueError).
        if pyre_object::memoryview::is_w_memoryview(obj)
            && memoryview_check_released(obj).is_ok()
            && pyre_object::memoryview::w_memoryview_readonly(obj)
        {
            return _hash_bytes(&memoryview_gather_bytes(obj));
        }
        if pyre_object::is_none(obj) {
            // CPython 3.12+ `Objects/object.c:none_hash`; introduced by
            // gh-99541 so singleton hashes are reproducible across processes.
            // PyPy inherits identity hashing here, so this is an intentional
            // CPython 3.14 surface delta rather than a PyPy semantic port.
            return 0xFCA8_6420;
        }
        if is_tuple(obj) {
            // 3.14 `tuple_hash` cache on the object; the walk itself is
            // PyPy's `_unroll_condition` fork (`_descr_hash_unroll` vs
            // `_descr_hash_jitdriver`).
            if let Some(hash) = pyre_object::w_tuple_cached_hash(obj) {
                return hash;
            }
            let hash = if pyre_object::tupleobject::unroll_condition(obj) {
                pyre_object::with_roots!(obj => _descr_hash_unroll(obj))
            } else {
                pyre_object::with_roots!(obj => _descr_hash_jitdriver(obj))
            };
            pyre_object::w_tuple_set_cached_hash(obj, hash);
            return hash;
        }
        if pyre_object::is_frozenset(obj) {
            return frozenset_hash_from_storage(obj);
        }
        if pyre_object::is_w_range(obj) {
            // `descr_hash` — `hash((length, start|None, step|None))` so two
            // ranges denoting the same sequence hash equally.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(obj);
            let w_len =
                pyre_object::w_range_length(pyre_object::gc_roots::shadow_stack_get(obj_slot));
            let (start, _stop, step) =
                pyre_object::w_range_fields(pyre_object::gc_roots::shadow_stack_get(obj_slot));
            // `range_obj_to_bigint` of a machine int collects; the length and
            // the fields are pinned before it.
            let field_base = pyre_object::gc_roots::pin_roots(&[w_len, start, step]);
            let len_b = pyre_object::range_obj_to_bigint(pyre_object::gc_roots::shadow_stack_get(
                field_base,
            ));
            let none = w_none();
            let none_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(none);
            let none = || pyre_object::gc_roots::shadow_stack_get(none_slot);
            let (a, b) = if len_b.int_eq(0) {
                (none(), none())
            } else if len_b.int_eq(1) {
                (
                    pyre_object::gc_roots::shadow_stack_get(field_base + 1),
                    none(),
                )
            } else {
                (
                    pyre_object::gc_roots::shadow_stack_get(field_base + 1),
                    pyre_object::gc_roots::shadow_stack_get(field_base + 2),
                )
            };
            let tup = pyre_object::w_tuple_new(vec![
                pyre_object::gc_roots::shadow_stack_get(field_base),
                a,
                b,
            ]);
            return hash_value(tup);
        }
        if pyre_object::is_generic_alias(obj) {
            // GenericAlias.__hash__ (`_pypy_generic_alias.py`) —
            // `hash(self.__origin__) ^ hash(self.__args__)`.  Resolved
            // here because `hash_w` does not consult a typedef `__hash__`
            // for builtin W_Roots.
            let origin = pyre_object::w_generic_alias_get_origin(obj);
            let mut args = pyre_object::w_generic_alias_get_args(obj);
            let origin_hash = pyre_object::with_roots!(args => hash_value(origin));
            return origin_hash ^ hash_value(args);
        }
        if pyre_object::is_union(obj) {
            // Strict callers take the Result-bearing arm above.  The
            // callback-only infallible path reads the already-built hashable
            // partition and never repartitions against mutable hash slots.
            return hash_value(pyre_object::w_union_get_hashable_args(obj));
        }
        if pyre_object::is_instance(obj) {
            let w_type = pyre_object::w_instance_get_type(obj);
            if let Some(method) = crate::baseobjspace::lookup_in_type(w_type, "__hash__") {
                // `hash_value` is the infallible callback arm, so a failed or
                // non-int `__hash__` falls through and reads `obj` again for
                // the identity hash.  `framework.py get_livevars_for_roots`
                // restores that livevar after `space.call_function`; native
                // Rust needs the same pop-roots writeback explicitly.
                let r = pyre_object::with_roots!(obj => crate::call_function(method, &[obj]));
                if !r.is_null() && is_int(r) {
                    return w_int_get_value(r);
                }
            }
        }
        crate::typedef::default_identity_hash_value(obj)
    }
}

/// `ord(c)` — PyPy: operation.py ord (dispatches to space.ord);
/// `unicodeobject.py:155-160` raises TypeError on multi-char strings.
pub(crate) fn builtin_ord(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(
            "ord() takes exactly one argument",
        ));
    }
    let obj = args[0];
    unsafe {
        if is_str(obj) {
            // Read the code point through the WTF-8 view so a lone-surrogate
            // single-character string yields its ordinal (0xD800-0xDFFF).
            let count = w_str_len(obj);
            if count != 1 {
                return Err(crate::PyError::type_error(format!(
                    "ord() expected a character, but string of length {count} found"
                )));
            }
            let cp = w_str_get_wtf8(obj).code_points().next().unwrap();
            return Ok(w_int_new(cp.to_u32() as i64));
        }
        // bytesobject.py:473 names bytes "bytes"; bytearrayobject.py:213
        // names bytearray "string".
        if pyre_object::bytesobject::is_bytes_like(obj) {
            let data = pyre_object::bytesobject::bytes_like_data(obj);
            if data.len() != 1 {
                let noun = if pyre_object::bytesobject::is_bytes(obj) {
                    "bytes"
                } else {
                    "string"
                };
                return Err(crate::PyError::type_error(format!(
                    "ord() expected a character, but {noun} of length {} found",
                    data.len()
                )));
            }
            return Ok(w_int_new(data[0] as i64));
        }
    }
    Err(crate::PyError::type_error(format!(
        "ord() expected string of length 1, but {} found",
        crate::baseobjspace::object_functionstr_type_name(obj)
    )))
}

/// `ord` on an exact one-code-point `str`: the code point, or -1.
#[majit_macros::elidable_cannot_raise]
pub fn ord_exact_str_char(w_obj: PyObjectRef) -> i64 {
    unsafe {
        if !(is_exact_builtin_instance(w_obj) && is_str(w_obj)) || w_str_len(w_obj) != 1 {
            return -1;
        }
        w_str_get_wtf8(w_obj)
            .code_points()
            .next()
            .map_or(-1, |cp| cp.to_u32() as i64)
    }
}

#[majit_macros::dont_look_inside]
fn builtin_ord_slow(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_ord(args)
}

/// operation.py `ord` → `space.ord`.  An exact one-code-point `str` answers
/// through [`ord_exact_str_char`]; every other shape runs `builtin_ord`.
pub fn __majit_wrap_builtin_ord(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() == 1 {
        let code_point = ord_exact_str_char(args[0]);
        if code_point >= 0 {
            return Ok(w_int_new(code_point));
        }
    }
    builtin_ord_slow(args)
}

crate::builtin_wrapper_descriptor!(__majit_wrap_builtin_ord_target, __majit_wrap_builtin_ord);

/// `chr(i)` — PyPy: operation.py chr
fn builtin_chr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "chr() takes exactly one argument ({} given)",
            args.len()
        )));
    }
    // Python 3.14 `builtin_chr` uses the index protocol: `__int__` alone is
    // insufficient, floats are rejected, and an arbitrarily large int reaches
    // the range check rather than overflowing a host machine word.  This is
    // the target-version difference from PyPy's `@unwrap_spec(code=int)`.
    let val = RBigIntGcRoot::new(index_to_bigint(args[0])?);
    // Compare through `int_*` so the bound is not a collecting `fromint`.
    if val.int_lt(0) || val.int_gt(0x10ffff) {
        return Err(crate::PyError::value_error(
            "chr() arg not in range(0x110000)",
        ));
    }
    let val = val
        .to_u32()
        .expect("chr range check guarantees a value fitting u32");
    let cp = match char::from_u32(val) {
        Some(c) => CodePoint::from(c),
        // Surrogate code points (0xD800-0xDFFF) are valid chr() arguments and
        // produce a lone-surrogate string; char::from_u32 rejects them, so
        // build the string through a WTF-8 code point instead.
        None => CodePoint::from_u32(val).expect("val is in 0..=0x10ffff per the range check above"),
    };
    let mut one = Wtf8Buf::new();
    one.push(cp);
    Ok(pyre_object::w_str_from_wtf8_managed(one))
}

/// `filter(function or None, iterable)` — `functional.py
/// W_Filter___new__`.  A lazy iterator: `function == None` keeps truthy
/// items, otherwise `function(item)` is the predicate.
pub(crate) fn builtin_filter(
    args: &[PyObjectRef],
    w_subtype: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "filter() takes no keyword arguments",
        ));
    }
    if args.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "filter expected 2 arguments, got {}",
            args.len()
        )));
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let subtype_slot = pyre_object::gc_roots::pin_roots(&[w_subtype]);
    let predicate_slot = pyre_object::gc_roots::pin_roots(&[args[0], args[1]]);
    let iterable_slot = predicate_slot + 1;
    let func = unsafe { pyre_object::gc_roots::shadow_stack_get(predicate_slot) };
    // `functional.py:921-924` — a None predicate is stored as PY_NULL.
    let w_predicate = if unsafe { pyre_object::is_none(func) } {
        pyre_object::PY_NULL
    } else {
        func
    };
    // `functional.py self.w_iterable = space.iter(w_iterable)`.
    let w_iterable = crate::baseobjspace::iter(unsafe {
        pyre_object::gc_roots::shadow_stack_get(iterable_slot)
    })?;
    let _ = pyre_object::gc_roots::pin_root(w_iterable);
    let iterator_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    Ok(pyre_object::functional::w_filter_new(
        if w_predicate.is_null() {
            pyre_object::PY_NULL
        } else {
            unsafe { pyre_object::gc_roots::shadow_stack_get(predicate_slot) }
        },
        unsafe { pyre_object::gc_roots::shadow_stack_get(iterator_slot) },
        pyre_object::gc_roots::shadow_stack_get(subtype_slot),
    ))
}

/// `map(func, *iterables, strict=False)` — `functional.py:888-902
/// W_Map___new__` plus the CPython 3.14 `strict` keyword.  A lazy iterator:
/// each `next()` pulls one item per iterable and calls `func(*items)`.
pub(crate) fn builtin_map(
    args: &[PyObjectRef],
    w_subtype: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    kwarg_reject_unknown(kwargs, &["strict"], "map")?;
    if args.len() < 2 {
        return Err(crate::PyError::type_error(
            "map() must have at least two arguments.",
        ));
    }

    // PyPy's `args_w` and `build_iterators_from_args` keep every argument live
    // while `space.iter` and the Python 3.14 `strict` truth conversion execute.
    let _roots = pyre_object::gc_roots::push_roots();
    let subtype_slot = pyre_object::gc_roots::pin_roots(&[w_subtype]);
    let args_base = pyre_object::gc_roots::publish_roots(args);
    let w_strict = kwarg_get(kwargs, "strict");
    let strict_slot = w_strict.map(|value| pyre_object::gc_roots::publish_roots(&[value]));
    pyre_object::gc_roots::normalize_roots(
        args_base,
        args.len() + usize::from(strict_slot.is_some()),
    );
    let strict = strict_slot
        .map(|slot| {
            crate::baseobjspace::is_true(unsafe { pyre_object::gc_roots::shadow_stack_get(slot) })
        })
        .transpose()?
        .unwrap_or(false);

    // `functional.py build_iterators_from_args` — `iter()` each input.
    let mut iter_slots = Vec::with_capacity(args.len() - 1);
    for index in 1..args.len() {
        let w_iter = crate::baseobjspace::iter(unsafe {
            pyre_object::gc_roots::shadow_stack_get(args_base + index)
        })?;
        let _ = pyre_object::gc_roots::pin_root(w_iter);
        iter_slots.push(pyre_object::gc_roots::shadow_stack_len() - 1);
    }
    let w_iterators = pyre_object::w_list_new(
        iter_slots
            .into_iter()
            .map(|slot| unsafe { pyre_object::gc_roots::shadow_stack_get(slot) })
            .collect(),
    );
    let _ = pyre_object::gc_roots::pin_root(w_iterators);
    let iterators_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    Ok(pyre_object::functional::w_map_new(
        unsafe { pyre_object::gc_roots::shadow_stack_get(args_base) },
        unsafe { pyre_object::gc_roots::shadow_stack_get(iterators_slot) },
        strict,
        pyre_object::gc_roots::shadow_stack_get(subtype_slot),
    ))
}

/// `zip(*iterables, strict=False)` — `functional.py W_Zip___new__`.
/// A lazy iterator: each `next()` pulls one item per iterable into a tuple,
/// stopping at the shortest (an empty `zip()` stops immediately); `strict`
/// raises `ValueError` on a length mismatch.
pub(crate) fn builtin_zip(
    args: &[PyObjectRef],
    w_subtype: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    // Pyre's flat builtin ABI surfaces kwargs as a trailing dict; strip it
    // before the positional walk and look up `strict` from it.
    let (args, kwargs) = split_builtin_kwargs(args);
    // `zip_new` parses its keywords with `PyArg_ParseTupleAndKeywords(empty,
    // kwds, "|$p:zip", ...)`, so the keyword *count* is checked against the
    // single `strict` slot before any name is looked at.
    clinic_arity("zip", 0, real_kwarg_count(kwargs), 0, 0, 1)?;
    kwarg_reject_unknown(kwargs, &["strict"], "zip")?;
    let _roots = pyre_object::gc_roots::push_roots();
    let subtype_slot = pyre_object::gc_roots::pin_roots(&[w_subtype]);
    let args_base = pyre_object::gc_roots::publish_roots(args);
    let strict_slot =
        kwarg_get(kwargs, "strict").map(|value| pyre_object::gc_roots::publish_roots(&[value]));
    pyre_object::gc_roots::normalize_roots(
        args_base,
        args.len() + usize::from(strict_slot.is_some()),
    );
    let strict = strict_slot
        .map(|slot| {
            crate::baseobjspace::is_true(unsafe { pyre_object::gc_roots::shadow_stack_get(slot) })
        })
        .transpose()?
        .unwrap_or(false);
    // `functional.py build_iterators_from_args` — `iter()` each input.
    let mut iter_slots = Vec::with_capacity(args.len());
    for index in 0..args.len() {
        let w_iter = crate::baseobjspace::iter(unsafe {
            pyre_object::gc_roots::shadow_stack_get(args_base + index)
        })?;
        let _ = pyre_object::gc_roots::pin_root(w_iter);
        iter_slots.push(pyre_object::gc_roots::shadow_stack_len() - 1);
    }
    let w_iterators = pyre_object::w_list_new(
        iter_slots
            .into_iter()
            .map(|slot| unsafe { pyre_object::gc_roots::shadow_stack_get(slot) })
            .collect(),
    );
    let _ = pyre_object::gc_roots::pin_root(w_iterators);
    let iterators_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    Ok(pyre_object::functional::w_zip_new(
        unsafe { pyre_object::gc_roots::shadow_stack_get(iterators_slot) },
        strict,
        pyre_object::gc_roots::shadow_stack_get(subtype_slot),
    ))
}

/// kwarg surface is also strict: anything other than `start=` is a
/// TypeError per the gateway's parsed signature.
// `pypy/module/__builtin__/functional.py W_Enumerate.descr___new__`
// line-by-line port — constructs the lazy `W_Enumerate` iterator,
// resolving `start` via `space.index_w` (with overflow promotion to a
// bigint slot) and capturing either the source iterator or the
// source list directly when `start == 0 + isinstance(it, list)`.
pub(crate) fn builtin_enumerate(
    args: &[PyObjectRef],
    w_subtype: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    if positional.len() > 2 {
        return Err(crate::PyError::type_error(format!(
            "enumerate() takes at most 2 arguments ({} given)",
            positional.len()
        )));
    }
    // `iterable` and `start` are the only accepted keywords; an unknown one is
    // reported with the vectorcall-style "invalid keyword argument" message.
    if let Some(dict) = kwargs {
        for (key, _) in unsafe { pyre_object::w_dict_str_entries_wtf8(dict) }.iter() {
            let k = key.as_str().unwrap_or("");
            if k == "__pyre_kw__" || k == "iterable" || k == "start" {
                continue;
            }
            return Err(crate::PyError::type_error(format!(
                "'{key}' is an invalid keyword argument for enumerate()"
            )));
        }
    }
    // `iterable` is positional-or-keyword; once filled positionally a stray
    // `iterable=` keyword is rejected as invalid rather than "multiple values".
    let source = if !positional.is_empty() {
        if kwarg_get(kwargs, "iterable").is_some() {
            return Err(crate::PyError::type_error(
                "'iterable' is an invalid keyword argument for enumerate()",
            ));
        }
        positional[0]
    } else if let Some(iterable) = kwarg_get(kwargs, "iterable") {
        iterable
    } else {
        return Err(crate::PyError::type_error(
            "enumerate() missing required argument 'iterable'",
        ));
    };
    let start_obj = if positional.len() > 1 {
        Some(positional[1])
    } else {
        kwarg_get(kwargs, "start")
    };
    // The constructor can execute user `__index__` and allocate. Keep both
    // arguments in the shadow stack exactly as the translated RPython locals
    // remain GC-visible across `space.index` / `space.iter`.
    let _roots = pyre_object::gc_roots::push_roots();
    let subtype_slot = pyre_object::gc_roots::pin_roots(&[w_subtype]);
    let _ = pyre_object::gc_roots::pin_root(source);
    let source_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    let raw_start = start_obj.unwrap_or(pyre_object::PY_NULL);
    let raw_start = pyre_object::gc_roots::pin_root(raw_start);
    let raw_start_slot = pyre_object::gc_roots::shadow_stack_len() - 1;

    // `functional.py descr___new__` — `space.index(w_start)` then
    // `space.int_w(w_start)`; ONLY OverflowError activates the bigint slot.
    // This preserves an arbitrary-precision start object verbatim, while a
    // machine-sized int/long/bool stays in the unboxed `index` fast path.
    let (start, w_start) = if raw_start.is_null() {
        (0, pyre_object::PY_NULL)
    } else {
        let indexed = crate::baseobjspace::space_index(unsafe {
            pyre_object::gc_roots::shadow_stack_get(raw_start_slot)
        })?;
        let indexed = pyre_object::gc_roots::pin_root(indexed);
        let indexed_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
        match crate::baseobjspace::int_w(indexed) {
            Ok(value) => (value, pyre_object::PY_NULL),
            Err(e) if e.kind == crate::PyErrorKind::OverflowError => (-1, unsafe {
                pyre_object::gc_roots::shadow_stack_get(indexed_slot)
            }),
            Err(e) => return Err(e),
        }
    };
    let w_start = pyre_object::gc_roots::pin_root(w_start);
    let w_start_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    // `functional.py:268-271` — `if start == 0 and type(w_iterable) is
    // W_ListObject: w_iter = w_iterable` (skip space.iter for the
    // common list-source case so __next__ can `getitem(index)`
    // directly).  Otherwise call `space.iter(w_iterable)`.
    let source = unsafe { pyre_object::gc_roots::shadow_stack_get(source_slot) };
    let w_iter_or_list =
        if start == 0 && w_start.is_null() && unsafe { pyre_object::is_exact_list(source) } {
            source
        } else {
            crate::baseobjspace::iter(source)?
        };
    Ok(pyre_object::functional::w_enumerate_new(
        w_iter_or_list,
        start,
        unsafe { pyre_object::gc_roots::shadow_stack_get(w_start_slot) },
        pyre_object::gc_roots::shadow_stack_get(subtype_slot),
    ))
}

/// `subclass_to_tag` for a `W_ReversedIterator` allocation. A foreign
/// iterator from `__reversed__` or range never reaches this helper.
fn reversed_user_subtype(subtype_slot: usize) -> Result<PyObjectRef, crate::PyError> {
    let cls = pyre_object::gc_roots::shadow_stack_get(subtype_slot);
    if crate::typedef::subclass_to_tag(cls, &pyre_object::functional::REVERSED_TYPE)?.is_none() {
        return Ok(pyre_object::PY_NULL);
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(subtype_slot))
}

/// `reversed()` — PyPy: functional.py W_ReversedIterator
pub(crate) fn builtin_reversed(
    args: &[PyObjectRef],
    w_subtype: PyObjectRef,
) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "reversed() takes no keyword arguments",
        ));
    }
    if args.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "reversed expected 1 argument, got {}",
            args.len()
        )));
    }
    // `descr___new__2` can execute `__reversed__`, `__len__`, or allocate an
    // iterator. The translated RPython argument remains a GC root throughout;
    // keep the Rust carrier in the shadow stack and reload at each call site.
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::pin_roots(&[args[0], w_subtype]);
    let subtype_slot = obj_slot + 1;
    let obj = unsafe { pyre_object::gc_roots::shadow_stack_get(obj_slot) };
    unsafe {
        // EXACT builtin list → `iterobject.py W_ReverseSeqIterObject` (the
        // Python 3.14-visible `list_reverseiterator`); tuple and the other
        // sequence fallbacks use `functional.py W_ReversedIterator`.
        // A subclass
        // shares the builtin `ob_type` but has its own `w_class`, so it falls
        // through to the `__reversed__` MRO lookup below — CPython honors a
        // subclass override (a non-overriding subclass inherits the builtin
        // `list.__reversed__`, which is the same lazy iterator).
        if pyre_object::is_exact_builtin_instance(obj) {
            if pyre_object::is_list(obj) {
                let n = isize::try_from(pyre_object::w_list_len(obj)).map_err(|_| {
                    crate::PyError::overflow_error("Python int too large to convert to C ssize_t")
                })?;
                return Ok(pyre_object::w_list_reverse_iter_new(
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    n - 1,
                ));
            }
            if pyre_object::is_tuple(obj) {
                let n = pyre_object::w_tuple_len(obj) as i64;
                let w_subtype = reversed_user_subtype(subtype_slot)?;
                return Ok(pyre_object::functional::w_reversed_new(
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    n - 1,
                    w_subtype,
                ));
            }
            // bytes / bytearray expose the sequence protocol at the C level but
            // not as `__getitem__` / `__len__` type slots, so they would miss
            // the `PySequence_Check` path below. `getitem` indexes them
            // (returning the int byte) for `W_ReversedIterator` to walk.
            if pyre_object::bytesobject::is_bytes(obj)
                || pyre_object::bytearrayobject::is_bytearray(obj)
            {
                let n = crate::baseobjspace::len_w(obj)?;
                let w_subtype = reversed_user_subtype(subtype_slot)?;
                return Ok(pyre_object::functional::w_reversed_new(
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    n - 1,
                    w_subtype,
                ));
            }
        }
        // range: functional.py W_Range.descr_reversed — reflect
        // the span and hand back a fresh reverse-walking iterator. (range is
        // not subclassable, so no override can apply.)
        if pyre_object::is_w_range(obj) {
            return Ok(pyre_object::w_range_reversed(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
            ));
        }
    }
    // `__reversed__` resolved through the type MRO (`functional.py:362-366`) —
    // honors a subclass override and the inherited builtin `list.__reversed__`,
    // and any user object defining `__reversed__`.
    let obj = unsafe { pyre_object::gc_roots::shadow_stack_get(obj_slot) };
    if let Some(tp) = crate::typedef::r#type(obj)
        && let Some(method) =
            unsafe { crate::baseobjspace::lookup_in_type(tp.as_ptr(), "__reversed__") }
    {
        // Python 3.14 `slot1` semantics: explicitly assigning None disables
        // the protocol and does not fall back to `__len__`/`__getitem__`.
        if unsafe { pyre_object::is_none(method) } {
            return Err(crate::PyError::type_error(format!(
                "'{}' object is not reversible",
                crate::baseobjspace::object_functionstr_type_name(obj)
            )));
        }
        let _ = pyre_object::gc_roots::pin_root(method);
        let method_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
        // Propagate a raised error from `__reversed__` instead of handing
        // back a null result.
        return unsafe {
            crate::baseobjspace::get_and_call_function(
                pyre_object::gc_roots::shadow_stack_get(method_slot),
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                tp.as_ptr(),
                &[],
            )
        };
    }
    // functional.py:351 — without `__reversed__`, require the sequence
    // protocol. `PySequence_Check` first (an object with `__getitem__`): a
    // non-sequence is "not reversible", while a sequence missing `__len__`
    // raises the regular "has no len()" from `len`.
    if let Some(tp) = crate::typedef::r#type(obj) {
        let has_getitem =
            unsafe { crate::baseobjspace::lookup_in_type(tp.as_ptr(), "__getitem__") }.is_some();
        if has_getitem {
            // `functional.py` — reverse lazily through `W_ReversedIterator`.
            let n = crate::baseobjspace::len_w(obj)?;
            let w_subtype = reversed_user_subtype(subtype_slot)?;
            return Ok(pyre_object::functional::w_reversed_new(
                unsafe { pyre_object::gc_roots::shadow_stack_get(obj_slot) },
                n - 1,
                w_subtype,
            ));
        }
    }
    Err(crate::PyError::type_error(format!(
        "'{}' object is not reversible",
        crate::baseobjspace::object_functionstr_type_name(obj)
    )))
}

/// Rewrite a user-function binding error for the published app-level
/// `sorted`; any other callable gets `err` back unchanged.
///
/// `builtin_sorted` unpacks exactly one positional itself
/// (`sorted expected 1 argument, got N`, before the iterable is touched)
/// and forwards every keyword to `list.sort`, which parses them only after
/// `list(iterable)` has consumed the iterable.  The app-level
/// `sorted(iterable, /, *, key=None, reverse=False)` rejects exactly those
/// calls, so the binding stays on the success path and only the error and
/// the iteration before it are produced here.
///
/// `positional[0]` is read only when exactly one positional was passed; the
/// binders raise every error such a call can hit before their first
/// allocation, so the word is still current.
#[cold]
#[inline(never)]
#[majit_macros::dont_look_inside]
pub(crate) fn applevel_binding_error(
    func: PyObjectRef,
    positional: &[PyObjectRef],
    kw_names: &[Wtf8Buf],
    mut err: crate::PyError,
) -> crate::PyError {
    if !crate::app_functional::is_published_sorted(func) {
        return err;
    }
    if positional.len() != 1 {
        return crate::PyError::type_error(format!(
            "sorted expected 1 argument, got {}",
            positional.len()
        ));
    }
    if clinic_keyword_only_error("sort", &["key", "reverse"], 0, kw_names).is_none() {
        return err;
    }
    let (listed, err) = {
        let _roots = pyre_object::gc_roots::push_roots();
        let mut err = err;
        let slot = err.pin(&_roots);
        let listed = builtin_list_ctor(&[positional[0]]);
        err.reload(&_roots, slot);
        (listed, err)
    };
    if let Err(iter_err) = listed {
        return iter_err;
    }
    clinic_keyword_only_error("sort", &["key", "reverse"], 0, kw_names).unwrap_or(err)
}

/// `pypy/module/__builtin__/functional.py:328-340 builtin_sorted`
/// parity:
///
/// ```python
/// @unwrap_spec(reverse=bool)
/// def sorted(space, w_iterable, w_key=None, reverse=False):
///     w_lst = space.call_function(space.w_list, w_iterable)
///     space.call_method(w_lst, "sort", w_key, space.newbool(reverse))
///     return w_lst
/// ```
///
/// PyPy's `sort` then calls into `listobject.py W_ListObject.descr_sort`
/// which dispatches keys through `space.lt`.  Pyre mirrors:
///   - exactly one positional iterable (extras → TypeError),
///   - kwargs limited to `{key, reverse}` (others → TypeError),
///   - per-comparison errors (e.g. user `__lt__` raises) propagate
///     instead of silently falling back to "treat as not less".
pub(crate) fn builtin_sorted(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    // `builtin_sorted` unpacks its one positional itself and leaves every
    // keyword to the `list.sort` it delegates to, so an unknown keyword is
    // reported by `sort`, not by `sorted`.
    if positional.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "sorted expected 1 argument, got {}",
            positional.len()
        )));
    }
    kwarg_reject_unknown(kwargs, &["key", "reverse"], "sort")?;
    let iterable = positional[0];
    let key_fn = kwarg_get(kwargs, "key").filter(|k| unsafe { !pyre_object::is_none(*k) });
    let has_key = key_fn.is_some();
    // `reverse=` runs a user `__bool__`, and building the list drains the
    // iterable's own Python, so the iterable and the key callable are pinned
    // before either and reloaded after, exactly as `list_method_sort` does.
    // `PY_NULL` stands in when no key was given, keeping the two roots
    // adjacent so one base covers both.
    let _roots = pyre_object::gc_roots::push_roots();
    let base =
        pyre_object::gc_roots::pin_roots(&[iterable, key_fn.unwrap_or(pyre_object::PY_NULL)]);
    let reverse = kwarg_get(kwargs, "reverse")
        .map(crate::baseobjspace::is_true)
        .transpose()?
        .unwrap_or(false);
    // `app_functional.py` `sorted` is `list(iterable)` followed by
    // `sorted_lst.sort(key=key, reverse=reverse)`, so the built list picks its
    // storage strategy first and the sort runs through the same body
    // `list.sort` uses.
    let w_list = builtin_list_ctor(&[pyre_object::gc_roots::shadow_stack_get(base)])?;
    let list_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_list);
    let key_fn = has_key.then(|| pyre_object::gc_roots::shadow_stack_get(base + 1));
    sort_list_in_place(list_slot, key_fn, reverse)?;
    Ok(pyre_object::gc_roots::shadow_stack_get(list_slot))
}

/// `listobject.py descr_sort` — the shared body of `list.sort` and
/// `sorted`.  `list_slot` is a shadow-stack slot holding the list, because a
/// key call or a comparison dunder can collect and move it.
///
/// Residual: `JitPolicy.look_inside_graph` refuses graphs that contain
/// loops (`self.sort(reverse)` / `sorter.sort()` / TimSort).  The gateway
/// unwrap in `typedef::__majit_wrap_list_descr_sort` is what a traced
/// CALL_KW descends.
///
/// Strategy sorts that do not call Python: range, unboxed numbers, bytes,
/// and ascii strings.  `false` means the list is object strategy (or
/// otherwise unsorted) and [`sort_list_in_place_obj`] still has to run.
///
/// The return is `bool`, not `Result`.  A `dont_look_inside` `Result`
/// helper's effect slot stays the most general one, and that call is
/// may-force, which a transparent builtin walk cannot record.
#[majit_macros::dont_look_inside_cannot_raise]
pub fn sort_list_without_key_native(list: PyObjectRef, reverse: bool) -> bool {
    unsafe {
        if pyre_object::listobject::w_list_sort_range(list, reverse) {
            return true;
        }
        if pyre_object::listobject::w_list_sort_int_or_float(list, reverse) {
            return true;
        }
        pyre_object::listobject::w_list_sort_strings(list, reverse)
    }
}

/// `list` / `key` / `reverse` stay the runtime boxes; `is_true(reverse)`
/// and the shadow-stack pin run here so the unwrap graph has no effect
/// before this call.
#[majit_macros::dont_look_inside]
pub fn sort_list_in_place_obj(
    list: PyObjectRef,
    key: PyObjectRef,
    reverse_obj: PyObjectRef,
) -> Result<(), crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let list_slot = pyre_object::gc_roots::pin_roots(&[list, key, reverse_obj]);
    let reverse = {
        let reverse_obj = pyre_object::gc_roots::shadow_stack_get(list_slot + 2);
        if reverse_obj.is_null() {
            false
        } else {
            crate::baseobjspace::is_true(reverse_obj)?
        }
    };
    let key_arg = pyre_object::gc_roots::shadow_stack_get(list_slot + 1);
    let key_fn = if key_arg.is_null() || unsafe { pyre_object::is_none(key_arg) } {
        None
    } else {
        Some(key_arg)
    };
    sort_list_in_place(list_slot, key_fn, reverse)
}

#[majit_macros::dont_look_inside]
pub fn sort_list_in_place(
    list_slot: usize,
    key_fn: Option<PyObjectRef>,
    reverse: bool,
) -> Result<(), crate::PyError> {
    // `descr_sort` sorts through the strategy's own `sort` whenever the list
    // is not object-strategy and no key was given: the storage is already
    // unwrapped, so there is no boxing, no comparison dunder, and no need to
    // empty the receiver first — no user code can run to observe it.
    if key_fn.is_none() {
        let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
        unsafe {
            if pyre_object::listobject::w_list_sort_range(list, reverse) {
                return Ok(());
            }
            let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
            if let Some((items, len)) = pyre_object::listobject::w_list_int_items_raw(list) {
                sort_scalars(std::slice::from_raw_parts_mut(items, len), reverse)?;
                return Ok(());
            }
            if let Some((items, len)) = pyre_object::listobject::w_list_float_items_raw(list) {
                sort_scalars(std::slice::from_raw_parts_mut(items, len), reverse)?;
                return Ok(());
            }
            if pyre_object::listobject::w_list_sort_int_or_float(list, reverse) {
                return Ok(());
            }
            if pyre_object::listobject::w_list_sort_strings(list, reverse) {
                return Ok(());
            }
        }
    }
    unsafe {
        // Hold the detached values in shadow-stack slots, not a bare Rust Vec,
        // while key and comparison calls can collect.  The receiver is empty
        // for the whole operation, so user code cannot alter this sorting
        // slice through the visible list.
        //
        // `descr_sort` snapshots via `getitems()` and holds that snapshot in
        // `sorter.list`.  Pin each getitem result before the next box, then
        // TimSort only moves integer indices.
        let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
        let saved_allocated = pyre_object::listobject::w_list_allocated(list);
        // Snapshot through getitem + pin, not a bare Vec: integer/float/range
        // strategies box each element (`getitems_copy`), and a Rust Vec of
        // those boxes is invisible to the collector.  `listsort.py` TimSort
        // plus `descr_sort`'s `sorter.list` are GC objects; the shadow stack
        // is the equivalent registered area, re-read after every `lt`.
        let saved_len = pyre_object::listobject::w_list_len(list);
        let _roots = pyre_object::gc_roots::push_roots();
        let item_base = pyre_object::gc_roots::shadow_stack_len();
        for i in 0..saved_len {
            let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
            let item = pyre_object::listobject::w_list_getitem(list, i as i64)
                .unwrap_or(pyre_object::PY_NULL);
            let _ = pyre_object::gc_roots::pin_root(item);
        }
        let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
        pyre_object::listobject::w_list_clear(list);
        // CPython 3.14 list_sort_impl detaches ob_item and marks `allocated`
        // as -1. Any resizing mutation replaces the sentinel with a normal
        // allocation, which is how the final modification check works.
        pyre_object::listobject::w_list_set_allocated(list, -1);

        let (order, sorted) = sort_rooted_items(item_base, saved_len, key_fn, reverse);
        let list = pyre_object::gc_roots::shadow_stack_get(list_slot);
        let mucked = pyre_object::listobject::w_list_allocated(list) != -1;

        // `descr_sort`'s `finally` puts the items back unconditionally,
        // discarding whatever the user stored into the receiver meanwhile.
        let restored = order
            .into_iter()
            .map(|index| pyre_object::gc_roots::shadow_stack_get(item_base + index))
            .collect();
        pyre_object::listobject::w_list_init_items(list, restored);
        pyre_object::listobject::w_list_set_allocated(list, saved_allocated);
        sorted?;
        if mucked {
            return Err(crate::PyError::new(
                crate::PyErrorKind::ValueError,
                "list modified during sort",
            ));
        }
    }
    Ok(())
}

/// `IntegerListStrategy.sort` (`listobject.py`) / `FloatListStrategy.sort`
/// (`:2067`) on the unwrapped storage.
///
/// `descr_sort`'s reverse handling — reverse, stable ascending sort, reverse
/// again — is kept here rather than the strategies' single trailing
/// `l.reverse()`: for `float` the difference is observable, since `-0.0` and
/// `0.0` compare equal but are distinct values whose relative order a stable
/// sort must preserve.
fn sort_scalars<T: Copy>(items: &mut [T], reverse: bool) -> Result<(), crate::PyError>
where
    ScalarLt: crate::listsort::SortLt<T>,
{
    if reverse {
        items.reverse();
    }
    crate::listsort::sort_with(items, &mut ScalarLt)?;
    if reverse {
        items.reverse();
    }
    Ok(())
}

/// `listobject.py IntSort.lt` / `:2434 FloatSort.lt` — a direct scalar
/// comparison, never a dunder.
struct ScalarLt;

impl crate::listsort::SortLt<i64> for ScalarLt {
    fn lt(&mut self, a: i64, b: i64) -> Result<bool, crate::PyError> {
        Ok(a < b)
    }
}

impl crate::listsort::SortLt<f64> for ScalarLt {
    fn lt(&mut self, a: f64, b: f64) -> Result<bool, crate::PyError> {
        Ok(a < b)
    }
}

/// Sort rooted item slots and return the resulting permutation.  All object
/// references that survive a Python call live in the shadow stack; the sort
/// itself only moves integer indices.
///
/// The permutation comes back even when a key call or a comparison raises,
/// because `descr_sort` puts `sorter.list` back from a `finally` — an
/// interrupted sort leaves the list holding its elements in whatever order the
/// merge had reached, not the order it started in.
pub(crate) fn sort_rooted_items(
    item_base: usize,
    item_len: usize,
    key_fn: Option<PyObjectRef>,
    reverse: bool,
) -> (Vec<usize>, Result<(), crate::PyError>) {
    let mut order: Vec<usize> = (0..item_len).collect();
    let _key_roots = pyre_object::gc_roots::push_roots();
    let key_base = pyre_object::gc_roots::shadow_stack_len();
    let key_fn_slot = key_fn.map(|key| {
        let _ = pyre_object::gc_roots::pin_root(key);
        key_base
    });
    let key_base = key_base + usize::from(key_fn_slot.is_some());
    if let Some(key_fn_slot) = key_fn_slot {
        for index in 0..item_len {
            // `_compute_keys_for_sorting` (listobject.py) runs before the
            // `reverse` flip, so a raising key leaves the input order.
            match crate::call::call_function_impl_result(
                pyre_object::gc_roots::shadow_stack_get(key_fn_slot),
                &[pyre_object::gc_roots::shadow_stack_get(item_base + index)],
            ) {
                Ok(key) => {
                    let _ = pyre_object::gc_roots::pin_root(key);
                }
                Err(err) => return (order, Err(err)),
            }
        }
    }

    // `descr_sort` reverses before and after a stable ascending sort for
    // `reverse=True`, so equal elements keep their original relative order (a
    // stable descending sort).  A single post-sort reverse would instead flip
    // ties.
    if reverse {
        order.reverse();
    }
    let base = if key_fn_slot.is_some() {
        key_base
    } else {
        item_base
    };
    let mut compare = sort_compare_for(base, item_len, key_fn_slot.is_some());
    let result = crate::listsort::sort_with(&mut order, &mut compare);
    // Second half of the reverse/ascending-sort/reverse pair `descr_sort` uses
    // for `reverse=True`, which runs on the raising
    // path too — an interrupted `reverse=True` sort must not leave the list in
    // the opposite orientation from the one it was handed.  `descr_sort` puts
    // this reverse inside its `try` and so skips it; `list_sort_impl` does not,
    // and that is the behaviour to match.
    if reverse {
        order.reverse();
    }
    (order, result)
}

/// The comparison primitive `listsort.py`'s TimSort drives, holding the
/// shadow-stack base of the values being compared (the keys under `key=`,
/// otherwise the items themselves).
///
/// `descr_sort` (`listobject.py`) resolves the sorter class from the
/// list's storage strategy, so an integer-strategy list sorts through
/// `IntSort` (`listobject.py`) and never dispatches a comparison dunder
/// at all; `FloatSort` (`:2434`) is the same for floats, and `SimpleSort`
/// (`:2423`) / `CustomKeySort` (`:2446`) are the generic `space.lt` path.
enum SortCompare {
    Int(usize),
    Float(usize),
    Str(usize),
    Generic(usize),
}

impl crate::listsort::SortLt<usize> for SortCompare {
    fn lt(&mut self, a: usize, b: usize) -> Result<bool, crate::PyError> {
        let (Self::Int(base) | Self::Float(base) | Self::Str(base) | Self::Generic(base)) = *self;
        let left = pyre_object::gc_roots::shadow_stack_get(base + a);
        let right = pyre_object::gc_roots::shadow_stack_get(base + b);
        // Each arm is what `compare_slot` reaches for that exact pair, taken
        // directly: `int_lt`'s `int_value`, `float_lt`'s unwrapped `<`, and the
        // WTF-8 byte order the str arm compares on.
        unsafe {
            match self {
                Self::Int(_) => {
                    // IntegerListStrategy / IntSort only unwraps a machine
                    // word.  A W_LongObject that slipped past is_plain_int1
                    // has a *mut BigInt where W_IntObject keeps intval;
                    // comparing those words orders by payload address.
                    if pyre_object::is_long(left) || pyre_object::is_long(right) {
                        let result = crate::baseobjspace::compare(
                            left,
                            right,
                            crate::baseobjspace::CompareOp::Lt,
                        )?;
                        crate::baseobjspace::is_true(result)
                    } else {
                        Ok(crate::objspace::descroperation::int_value(left)
                            < crate::objspace::descroperation::int_value(right))
                    }
                }
                Self::Float(_) => Ok(
                    pyre_object::w_float_get_value(left) < pyre_object::w_float_get_value(right)
                ),
                Self::Str(_) => {
                    Ok(w_str_get_wtf8(left).as_bytes() < w_str_get_wtf8(right).as_bytes())
                }
                Self::Generic(_) => {
                    let result = crate::baseobjspace::compare(
                        left,
                        right,
                        crate::baseobjspace::CompareOp::Lt,
                    )?;
                    crate::baseobjspace::is_true(result)
                }
            }
        }
    }
}

/// Pick the sorter the way `descr_sort` picks it from the list's strategy.
///
/// pyre's list stores plain object references with no strategy to read, so the
/// same decision is one pass over the values.  What makes the specialization
/// equivalent is that a subclass carrying its own `__lt__` must fail the test
/// and take the generic path, exactly as it would keep an object-strategy list
/// upstream — so the test has to be `is_exact_type` (pyobject.rs), which
/// compares the instance's `w_class` against the builtin's type object and so
/// rejects a subclass, which retags `w_class` to its own.  `is_int` / `is_str`
/// / `is_float` are NOT usable here ON THEIR OWN: they are `py_type_check`, an
/// `ob_type` layout test a subclass instance also passes because it shares the
/// builtin vtable.  The int arm needs both tests, which is what
/// `is_plain_int1` is -- the exact-class test alone would let a bigint into a
/// comparator that reads a machine word.  A `key=` sort is `CustomKeySort`,
/// generic upstream as well.
fn sort_compare_for(base: usize, len: usize, keyed: bool) -> SortCompare {
    if keyed {
        return SortCompare::Generic(base);
    }
    let (mut all_int, mut all_float, mut all_str) = (true, true, true);
    for index in 0..len {
        let item = pyre_object::gc_roots::shadow_stack_get(base + index);
        unsafe {
            // `bool` is admitted alongside `int` because it cannot be
            // subclassed, so it can never carry an overriding `__lt__`, and
            // `int_value` reads it the same way.
            // `is_exact_type` answers on `w_class`, and a bigint's is wired
            // to `int`'s so that `type(x) is int` holds for one -- so it alone
            // admits a `W_LongObject`, whose `*mut BigInt` sits where
            // `W_IntObject` keeps `intval`, and the `Int` arm's `int_value`
            // would order the list by payload address.  `is_plain_int1` is the
            // strategy's own `is_correct_type`, which carries both halves;
            // using it here is what makes this scan the strategy decision it
            // stands in for.
            all_int &= pyre_object::listobject::is_plain_int1(item)
                || pyre_object::is_exact_type(item, &pyre_object::BOOL_TYPE);
            all_float &= pyre_object::is_exact_type(item, &pyre_object::FLOAT_TYPE);
            all_str &= pyre_object::is_exact_type(item, &pyre_object::STR_TYPE);
        }
        if !(all_int || all_float || all_str) {
            return SortCompare::Generic(base);
        }
    }
    if all_int {
        SortCompare::Int(base)
    } else if all_float {
        SortCompare::Float(base)
    } else if all_str {
        SortCompare::Str(base)
    } else {
        SortCompare::Generic(base)
    }
}

/// `any(iterable)` — PyPy: operation.py any
/// `any(iterable)` — PyPy: baseobjspace.py any_w
pub fn builtin_any_fn(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    builtin_any(args)
}
fn builtin_any(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (positional, kwargs) = split_builtin_kwargs(args);
    if has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(
            "any() takes no keyword arguments",
        ));
    }
    if positional.len() != 1 {
        return Err(crate::PyError::type_error(format!(
            "any() takes exactly one argument ({} given)",
            positional.len()
        )));
    }
    // `iter` and every `next` run arbitrary Python. Pin the iterable, the
    // iterator, and a dict view's backing dict for the whole walk, and reload
    // the iterator from its slot before each call: a moving minor collection
    // relocates it behind a plain Rust local. The shape `collect_iterator` uses.
    let _roots = pyre_object::gc_roots::push_roots();
    let iterable_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(positional[0]);
    let it = crate::baseobjspace::iter(pyre_object::gc_roots::shadow_stack_get(iterable_slot))?;
    let iterator_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(it);
    // The pin queries the collector, so the slot — not this local — is what
    // holds the forwarded iterator once it returns.
    let it = pyre_object::gc_roots::shadow_stack_get(iterator_slot);
    if unsafe { pyre_object::dictmultiobject::is_dict_view_iterator(it) } {
        let w_dict = unsafe { pyre_object::dictmultiobject::w_dict_view_iterator_get_dict(it) };
        let _ = pyre_object::gc_roots::pin_root(w_dict);
    }
    loop {
        let it_now = pyre_object::gc_roots::shadow_stack_get(iterator_slot);
        match crate::baseobjspace::next(it_now) {
            Ok(item) if crate::baseobjspace::is_true(item)? => return Ok(w_bool_from(true)),
            Ok(_) => {}
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    return Ok(w_bool_from(false));
                } else {
                    return Err(e);
                }
            }
        }
    }
}

/// `all(iterable)` — PyPy: operation.py all
/// `all(iterable)` — PyPy: baseobjspace.py all_w
/// Shared file wrapper type — plain instance with hasdict so that
/// open() can attach `__file_data__` / `__file_pos__` / `__file_mode__`
/// as instance attributes, matching the PyPy FileIO/TextIOWrapper
/// duck-typing surface without a dedicated W_FileObject.
pub fn file_wrapper_type() -> PyObjectRef {
    // A Python type is process-global, exactly as PyPy's W_TypeObject is.
    // Storing it in TLS would manufacture one incompatible TextIOWrapper type
    // per host thread and break cross-thread isinstance/type identity.
    static FILE_WRAPPER_TYPE: pyre_object::gc_roots::RootedOnceRef =
        pyre_object::gc_roots::RootedOnceRef::new();
    FILE_WRAPPER_TYPE.get_or_init(|| {
        let tp = crate::typedef::make_builtin_type("_io.TextIOWrapper", init_file_wrapper_type);
        // CPython 3.14 Modules/_io/_iomodule.c:ADD_TYPE creates the immutable
        // TextIOWrapper heap spec.  This legacy wrapper accessor must publish
        // the same owner as `_io::interp_textio::type_object`.
        crate::typedef::mark_cpython_heap_type(tp, true);
        unsafe { pyre_object::typeobject::w_type_set_hasdict(tp, true) };
        tp
    })
}

/// PyPy: pypy/module/_io/interp_iobase.py W_IOBase.
pub(crate) fn init_file_wrapper_type(ns: PyObjectRef) {
    // The producer's own root slot tracks its copy of the namespace, not this
    // by-value parameter, so the word is pinned again here for the run of
    // allocating insertions below.
    let _roots = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ns);
    type_ns_store(
        ns_slot,
        "read",
        make_builtin_function("read", file_method_read),
    );
    type_ns_store(
        ns_slot,
        "readline",
        make_builtin_function("readline", file_method_readline),
    );
    type_ns_store(
        ns_slot,
        "readlines",
        make_builtin_function("readlines", file_method_readlines),
    );
    type_ns_store(
        ns_slot,
        "write",
        make_builtin_function_with_arity("write", file_method_write, 2),
    );
    type_ns_store(
        ns_slot,
        "writelines",
        make_builtin_function_with_arity("writelines", crate::module::_io::iobase_writelines, 2),
    );
    type_ns_store(
        ns_slot,
        "close",
        make_builtin_function_with_arity("close", file_method_close, 1),
    );
    type_ns_store(
        ns_slot,
        "flush",
        make_builtin_function_with_arity("flush", file_method_flush, 1),
    );
    type_ns_store(
        ns_slot,
        "__enter__",
        make_builtin_function_with_arity("__enter__", |args| Ok(args[0]), 1),
    );
    type_ns_store(
        ns_slot,
        "__exit__",
        make_builtin_function("__exit__", |args| {
            // Call close on exit.
            file_method_close(&args[..1])?;
            Ok(w_none())
        }),
    );
    type_ns_store(
        ns_slot,
        "__iter__",
        make_builtin_function_with_arity(
            "__iter__",
            |args| {
                let mut self_obj = args[0];
                pyre_object::with_roots!(self_obj => file_check_closed(self_obj))?;
                Ok(self_obj)
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "__next__",
        make_builtin_function_with_arity(
            "__next__",
            |args| {
                let line = file_method_readline(args)?;
                unsafe {
                    let s = pyre_object::w_str_get_wtf8(line);
                    if s.is_empty() {
                        return Err(crate::PyError::stop_iteration());
                    }
                }
                Ok(line)
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "fileno",
        make_builtin_function_with_arity(
            "fileno",
            |args| {
                let mut self_obj = args[0];
                pyre_object::with_roots!(self_obj => file_check_closed(self_obj))?;
                match file_get_fd(self_obj) {
                    Some(fd) => Ok(w_int_new(fd as i64)),
                    None => Err(crate::PyError::os_error(
                        "fileno() on a file without a descriptor",
                    )),
                }
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "readable",
        make_builtin_function_with_arity(
            "readable",
            |args| {
                let mut self_obj = args[0];
                pyre_object::with_roots!(self_obj => file_check_closed(self_obj))?;
                if let Some(fileio) = crate::module::_io::W_FileIO::from_obj(self_obj) {
                    return Ok(w_bool_from(fileio.readable()));
                }
                let mode = crate::baseobjspace::getattr_str(self_obj, "__file_mode__")
                    .ok()
                    .and_then(|m| {
                        unsafe { crate::baseobjspace::str_utf8_w(m) }
                            .ok()
                            .map(str::to_string)
                    })
                    .unwrap_or_default();
                Ok(w_bool_from(mode.contains('r') || mode.contains('+')))
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "writable",
        make_builtin_function_with_arity(
            "writable",
            |args| {
                let mut self_obj = args[0];
                pyre_object::with_roots!(self_obj => file_check_closed(self_obj))?;
                if let Some(fileio) = crate::module::_io::W_FileIO::from_obj(self_obj) {
                    return Ok(w_bool_from(fileio.writable()));
                }
                let mode = crate::baseobjspace::getattr_str(self_obj, "__file_mode__")
                    .ok()
                    .and_then(|m| {
                        unsafe { crate::baseobjspace::str_utf8_w(m) }
                            .ok()
                            .map(str::to_string)
                    })
                    .unwrap_or_default();
                Ok(w_bool_from(
                    mode.contains('w')
                        || mode.contains('a')
                        || mode.contains('x')
                        || mode.contains('+'),
                ))
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "seekable",
        make_builtin_function_with_arity("seekable", file_method_seekable, 1),
    );
    type_ns_store(
        ns_slot,
        "seek",
        make_builtin_function("seek", |args| {
            if args.len() < 2 || args.len() > 3 {
                return Err(crate::PyError::type_error(format!(
                    "seek() takes from 1 to 2 arguments ({} given)",
                    args.len().saturating_sub(1)
                )));
            }
            let _roots = pyre_object::gc_roots::push_roots();
            let file_slot = pyre_object::gc_roots::pin_roots(args);
            file_check_closed(pyre_object::gc_roots::shadow_stack_get(file_slot))?;
            // interp_fileio.py:267-275
            // `@unwrap_spec(pos=r_longlong, whence=int)`: both operands
            // go through Python's integer/index conversion before the
            // host lseek.  Reading their object payloads unchecked made a
            // float such as 0.0 look like offset zero instead of raising
            // TypeError (test_io.IOTest.write_ops).
            let offset = crate::builtins::space_index_w(pyre_object::gc_roots::shadow_stack_get(
                file_slot + 1,
            ))?;
            let whence = if args.len() >= 3 {
                crate::baseobjspace::index_c_int_w(pyre_object::gc_roots::shadow_stack_get(
                    file_slot + 2,
                ))?
            } else {
                0
            };
            // CPython 3.14 TextIOWrapper only permits the opaque-cookie
            // forms for current/end-relative seeks; FileIO remains free
            // to use ordinary non-zero offsets.
            let file = || pyre_object::gc_roots::shadow_stack_get(file_slot);
            if !file_is_binary(file()) && offset != 0 {
                // POSIX/Python's public SEEK_CUR and SEEK_END values are
                // 1 and 2.  Keep this semantic validation target-neutral;
                // wasm libc intentionally does not expose lseek constants.
                if whence == 1 {
                    return Err(crate::module::_io::unsupported(
                        "can't do nonzero cur-relative seeks",
                    ));
                }
                if whence == 2 {
                    return Err(crate::module::_io::unsupported(
                        "can't do nonzero end-relative seeks",
                    ));
                }
            }
            if let Some(fd) = file_get_fd(file()) {
                #[cfg(all(feature = "host_env", not(target_arch = "wasm32")))]
                {
                    #[cfg(not(feature = "sandbox"))]
                    let pos = {
                        let pos = crt_lseek(fd, offset, whence);
                        if pos < 0 {
                            return Err(fd_errno_err(crt_errno()));
                        }
                        pos
                    };
                    #[cfg(feature = "sandbox")]
                    let pos = crate::host_seam::ops::lseek(fd, offset, whence)
                        .map_err(|e| crate::host_seam::seam_os_err(e, ""))?;
                    return Ok(w_int_new(pos as i64));
                }
                #[cfg(all(feature = "host_env", target_arch = "wasm32"))]
                {
                    return Ok(w_int_new(wasm_fd::fd_lseek(fd, offset, whence)?));
                }
                #[cfg(not(feature = "host_env"))]
                {
                    let _ = (fd, offset, whence);
                    return Err(crate::PyError::not_implemented(
                        "fd seek requires host_env feature",
                    ));
                }
            }
            let origin = match whence {
                0 => 0,
                1 => file_get_pos(file()) as i64,
                2 => file_get_data(file()).len() as i64,
                _ => return Err(crate::PyError::value_error("invalid whence")),
            };
            let pos = origin
                .checked_add(offset)
                .filter(|pos| *pos >= 0)
                .ok_or_else(|| crate::PyError::value_error("negative seek position"))?;
            file_set_pos(file(), pos as usize);
            Ok(w_int_new(pos))
        }),
    );
    type_ns_store(
        ns_slot,
        "tell",
        make_builtin_function_with_arity(
            "tell",
            |args| {
                let mut self_obj = args[0];
                pyre_object::with_roots!(self_obj => file_check_closed(self_obj))?;
                if let Some(fd) = pyre_object::with_roots!(self_obj => file_get_fd(self_obj)) {
                    #[cfg(all(feature = "host_env", not(target_arch = "wasm32")))]
                    {
                        #[cfg(not(feature = "sandbox"))]
                        let pos = {
                            let pos = crt_lseek(fd, 0, libc::SEEK_CUR);
                            if pos < 0 {
                                return Err(fd_errno_err(crt_errno()));
                            }
                            pos
                        };
                        #[cfg(feature = "sandbox")]
                        let pos = crate::host_seam::ops::lseek(fd, 0, libc::SEEK_CUR)
                            .map_err(|e| crate::host_seam::seam_os_err(e, ""))?;
                        return Ok(w_int_new(pos as i64));
                    }
                    #[cfg(all(feature = "host_env", target_arch = "wasm32"))]
                    {
                        // A zero-offset current-relative seek reports the
                        // position without moving it.
                        return Ok(w_int_new(wasm_fd::fd_lseek(fd, 0, 1)?));
                    }
                    #[cfg(not(feature = "host_env"))]
                    {
                        let _ = fd;
                    }
                }
                if let Ok(pos) = crate::baseobjspace::getattr_str(self_obj, "__file_pos__") {
                    Ok(pos)
                } else {
                    Ok(w_int_new(0))
                }
            },
            1,
        ),
    );
    type_ns_store(
        ns_slot,
        "isatty",
        make_builtin_function_with_arity("isatty", file_method_isatty, 1),
    );
}

/// PyPy `W_FileIO.typedef` — raw-stream methods override the shared
/// TextIOWrapper-shaped helpers installed by [`init_file_wrapper_type`].
/// Keeping this as a separate initializer mirrors FileIO's distinct typedef
/// instead of teaching the text wrapper about raw-only operations.
pub(crate) fn init_fileio_type(ns: PyObjectRef) {
    // The producer's own root slot tracks its copy of the namespace, not this
    // by-value parameter, so the word is pinned again here for the run of
    // allocating insertions below.
    let _roots = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(ns);
    // The table carries the code pointer and arity, not the built function:
    // building all six up front would leave the early ones in a Rust array the
    // collector does not walk while the later ones allocate.
    for (name, f, arity) in [
        (
            "read",
            fileio_method_read as crate::gateway::BuiltinCodeFn,
            None,
        ),
        ("readinto", fileio_method_readinto, Some(2u16)),
        ("readall", fileio_method_readall, Some(1)),
        ("write", fileio_method_write, Some(2)),
        ("truncate", fileio_method_truncate, None),
        ("_isatty_open_only", fileio_method_isatty_open_only, Some(1)),
    ] {
        let function = match arity {
            Some(arity) => make_builtin_function_with_arity(name, f, arity),
            None => make_builtin_function(name, f),
        };
        type_ns_store(ns_slot, name, function);
    }
    for (name, getter, doc) in [
        (
            "closed",
            fileio_get_closed as crate::gateway::BuiltinCodeFn,
            Some("True if the file is closed"),
        ),
        (
            "closefd",
            fileio_get_closefd as crate::gateway::BuiltinCodeFn,
            Some("True if the file descriptor will be closed"),
        ),
        (
            "mode",
            fileio_get_mode as crate::gateway::BuiltinCodeFn,
            Some("String giving the file mode"),
        ),
        (
            "_blksize",
            fileio_get_blksize as crate::gateway::BuiltinCodeFn,
            None,
        ),
    ] {
        let getter = make_builtin_function_with_arity(name, getter, 2);
        let getter_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(getter);
        let descriptor = match doc {
            Some(doc) => crate::typedef::make_getset_property_named_doc(
                pyre_object::gc_roots::shadow_stack_get(getter_slot),
                pyre_object::PY_NULL,
                pyre_object::PY_NULL,
                doc,
                name,
            ),
            None => crate::typedef::make_getset_descriptor_named(
                pyre_object::gc_roots::shadow_stack_get(getter_slot),
                name,
            ),
        };
        type_ns_store(ns_slot, name, descriptor);
    }
    // interp_fileio.py `interp_member_w('w_name', cls=W_FileIO)`: get, set,
    // and delete the typed `w_name` field. A null field is AttributeError,
    // and delete stores null so `repr_w` switches to the fd form.
    let name_getter = make_builtin_function_with_arity("name", fileio_get_name, 2);
    let getter_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(name_getter);
    let name_setter = make_builtin_function_with_arity("name", fileio_set_name, 3);
    let setter_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(name_setter);
    let name_deleter = make_builtin_function_with_arity("name", fileio_del_name, 2);
    let deleter_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(name_deleter);
    type_ns_store(
        ns_slot,
        "name",
        crate::typedef::make_getset_property_named(
            pyre_object::gc_roots::shadow_stack_get(getter_slot),
            pyre_object::gc_roots::shadow_stack_get(setter_slot),
            pyre_object::gc_roots::shadow_stack_get(deleter_slot),
            "name",
        ),
    );
    type_ns_store(
        ns_slot,
        "__repr__",
        make_builtin_function_with_arity("__repr__", fileio_method_repr, 1),
    );
    type_ns_store(
        ns_slot,
        "_dealloc_warn",
        make_builtin_function_with_arity("_dealloc_warn", fileio_method_dealloc_warn, 2),
    );
}

fn fileio_method_dealloc_warn(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let n_args = args.len();
    if n_args == 0 {
        return Err(crate::PyError::type_error("_dealloc_warn() requires self"));
    }
    let arg_roots = pyre_object::gc_roots::push_roots();
    let arg_base = arg_roots.pin_roots(args);
    let mut self_obj = arg_roots.get(arg_base);
    if !pyre_object::with_roots!(self_obj => file_is_closed(self_obj))
        && pyre_object::with_roots!(self_obj => file_closefd(self_obj))
        && pyre_object::with_roots!(self_obj => file_get_fd(self_obj)).is_some()
    {
        let source_obj = if n_args > 1 {
            arg_roots.get(arg_base + 1)
        } else {
            self_obj
        };
        let _roots = pyre_object::gc_roots::push_roots();
        let source = crate::module::_warnings::pin_root_slot(source_obj);
        let repr = unsafe {
            crate::display::py_repr_wtf8(pyre_object::gc_roots::shadow_stack_get(source))?
        };
        crate::warn::warn_category_source(
            &format!("unclosed file {}", repr.to_string_lossy()),
            "ResourceWarning",
            1,
            pyre_object::gc_roots::shadow_stack_get(source),
        )?;
    }
    Ok(w_none())
}

fn fileio_get_slot(args: &[PyObjectRef], storage: &str) -> Result<PyObjectRef, crate::PyError> {
    let self_obj = args
        .get(1)
        .copied()
        .ok_or_else(|| crate::PyError::type_error("descriptor requires an instance"))?;
    crate::baseobjspace::getattr_str(self_obj, storage)
}

